                select pm2.nocm ,to_char(pm2.tgllahir,'dd-mm-yyyy') as tgllahir,age(pm2.tgllahir) as umur ,jm.jeniskelamin ,pm2.namapasien ,pm3.namalengkap, rm.namaruangan ruangantujuan, to_char(s.tglresep ,'dd-mm-yyyy HH:MM:ss') as tglorder,pm3.nosip, kp.kelompokpasien, ra.namaruangan ruanganasal, pm2.alergi,
                aa.jenis || ' - ' || aa.noantri as noantri
                from strukresep_t s
                inner join antrianpasiendiperiksa_t at2 on at2.norec = s.pasienfk 
                inner join pasiendaftar_t pt on pt.norec = at2.noregistrasifk 
                inner join pasien_m pm2 on pm2.id = pt.nocmfk 
                inner join jeniskelamin_m jm on jm.id = pm2.objectjeniskelaminfk
                inner join pegawai_m pm3 on pm3.id = s.penulisresepfk 
                inner join ruangan_m rm on rm.id = s.ruanganfk 
                left join ruangan_m ra on ra.id = at2.objectruanganasalfk 
                left join kelompokpasien_m AS kp ON kp.id = pt.objectkelompokpasienlastfk
                left join antrianapotik_t as aa on aa.noresep = s.noresep
                where s.norec = '$norec'

            "))->first();
            $details = \DB::select(DB::raw("
                SELECT x.* FROM (select distinct row_number()over(partition by pt.rke, pm.namaproduk ORDER BY pt.rke asc)as no, pt.jeniskemasanfk, jr.jenisracikan, pt.rke,pt.dosis, pt.jumlah , pt.aturanpakai , pm.namaproduk, pm.kekuatan, pt.keteranganpakai,
                op.keteranganpakai as catatandokter, op.satuandosis
                from pelayananpasien_t pt
                inner join produk_m pm on pm.id = pt.produkfk
                left join jenisracikan_m jr on jr.id = pt.jenisobatfk
                inner join strukresep_t as sr on sr.norec = pt.strukresepfk
                left join strukorder_t as so on so.norec = sr.orderfk
                left join orderpelayanan_t as op on op.strukorderfk = so.norec and op.rke = pt.rke 
                where strukresepfk = '$norec'
                and pt.isobat = true
                order by pt.rke asc, pt.keteranganpakai asc)as x where x.no = 1
            "));
        }else{
            echo 'Data Tidak ada ';
            return;
        }

        $skrining = collect(DB::select("
            select s.noresep, st.rpenulis, st.rtanggalresep, st.rklinis, st.rmr, st.rpasien,
            st.rtanggallahir,
            st.rberatbedan,
            st.rdokter,
            st.rruang,
            st.rstatusjamin,
            st.robat,
            st.rkekuatan,
            st.rjumlahobat, st.ketskrining, st.ridentitasdokter,st.rcarabayar,st.rruanganresep, st.rnamaobat, st.rstabilitas, st.raturan, st.ralergi, st.rinteraksi, st.rvariasi, st.rbeban, st.rdatawaktu 
            from strukresep_t s
            left join skriningfarmasi_t st on st.norec_apd = s.norec
            where s.norec = '$norec'
        "))->first();

        $ks_obat = collect(DB::select("
            select s.noresep, 
            st.penyiapanidentitas, st.penyiapannamaobat, st.penyiapanjumlahdosis, st.penyiapanrute, st.penyiapanwaktufrekuensi,
            st.penyiapanketidentitas, st.penyiapanketnamaobat, st.penyiapanketjumlahdosis, st.penyiapanketrute, st.penyiapanketwaktufrekuensi, st.penelaahpenyiapan,
            st.peracikanidentitas, st.peracikannamaobat, st.peracikanjumlahdosis, st.peracikanrute, st.peracikanwaktufrekuensi,
            st.peracikanketidentitas, st.peracikanketnamaobat, st.peracikanketjumlahdosis, st.peracikanketrute, st.peracikanketwaktufrekuensi, st.penelaahperacikan,
            st.pelabelanidentitas, st.pelabelannamaobat, st.pelabelanjumlahdosis, st.pelabelanrute, st.pelabelanwaktufrekuensi,
            st.pelabelanketidentitas, st.pelabelanketnamaobat, st.pelabelanketjumlahdosis, st.pelabelanketrute, st.pelabelanketwaktufrekuensi, st.penelaahpelabelan,
            st.diserahkanidentitas, st.diserahlahnamaobat, st.diserahanjumlahdosis, st.diserahanrute, st.diserahanwaktufrekuensi,
            st.diserahlanketidentitas, st.diserahlanketnamaobat, st.diserahlanketjumlahdosis, st.diserahlanketrute, st.diserahlanketwaktufrekuensi, st.penelaahdiserahkan
            from strukresep_t s
            left join skriningfarmasi_t st on st.norec_apd = s.norec
            where s.norec = '$norec'
        "))->first();
    //    dd($details);
        $pageWidth = 550;
        //var_dump($skrining);

        // return $r['norec'];
        $cetakkin = $r['cetakkin'];
        return view('report.apotik.resepdokterrev',
            compact('raw', 'pageWidth','r','details','profile', 'skrining', 'ks_obat','cetakkin'));
    }

    public function cetakDetailOrder(Request $r) {
        $idProfile = (int)$r['kodeprofile'];
        $noorder = $r['noorder'];

        $dataAsalProduk = \DB::table('asalproduk_m as ap')
            ->select('ap.id','ap.asalproduk')
            ->get();
        $dataSigna = \DB::table('stigma as st')
            ->select('st.id','st.name')
            ->get();

        $dataStruk = \DB::table('strukorder_t as so')
            ->leftJOIN('pegawai_m as pg','pg.id','=','so.objectpegawaiorderfk')
            ->leftJOIN('ruangan_m as ru','ru.id','=','so.objectruangantujuanfk')
            ->select('so.noorder','pg.id as pgid','pg.namalengkap','ru.id','ru.namaruangan','so.tglorder')
            ->where('so.kdprofile', 30);

        
            $dataStruk = $dataStruk->where('so.noorder','=', $r['noorder']);
        $dataStruk = $dataStruk->first();

        $data = \DB::table('strukorder_t as so')
            ->JOIN('orderpelayanan_t as op','op.strukorderfk','=','so.norec')
            ->JOIN('ruangan_m as ru','ru.id','=','so.objectruangantujuanfk')
            ->leftJOIN('jeniskemasan_m as jk','jk.id','=','op.jeniskemasanfk')
            ->leftJOIN('routefarmasi as rt','rt.id','=','op.routefk')
            ->JOIN('produk_m as pr','pr.id','=','op.objectprodukfk')
            ->leftJOIN('rm_sediaan_m as sdn','sdn.id','=','pr.objectsediaanfk')
