            ->leftJOIN('satuanresep_m as sn','sn.id','=','op.satuanresepfk')
            ->leftJOIN('jenisracikan_m as jr','jr.id','=','op.jenisobatfk')
            ->select('op.satuandosis','jr.id as ssid', 'so.noorder','op.hargasatuan','op.qtystokcurrent','so.objectruangantujuanfk','ru.namaruangan',
                'op.rke','op.jeniskemasanfk','jk.id as jkid','jk.jeniskemasan','op.aturanpakai','op.routefk','rt.name as namaroute',
                'op.objectprodukfk','pr.namaproduk','op.hasilkonversi',
                'op.objectsatuanstandarfk','jr.jenisracikan as satuanstandar','op.satuanviewfk','ss2.satuanstandar as ssview',
                'op.qtyproduk','op.hargadiscount','op.hasilkonversi','op.qtystokcurrent','op.dosis','op.jenisobatfk',
                'op.hargasatuan','op.hargadiscount','pr.kekuatan','sdn.name as sediaan','op.ispagi','op.issiang','op.ismalam',
                'op.issore','op.keteranganpakai','op.keteranganpakai as catatandokter','op.satuanresepfk','sn.satuanresep','op.tglkadaluarsa','so.isreseppulang', 
                DB::raw("
                CASE
                WHEN op.jumlahracikan <> NULL AND op.jeniskemasanfk = 1 THEN
                op.jumlahracikan 
                WHEN op.jumlahracikan is NULL 
                AND op.jeniskemasanfk = 2 THEN
                null ELSE op.qtyproduk::float * ( pr.kekuatan::float / op.dosis::float ) 
                END AS jumlahracikan"))
            ->where('so.kdprofile', 30)
            ->orderBy('op.rke', 'asc');
            $data = $data->where('so.noorder','=', $r['noorder']);
        $data = $data->get();

        $orderPelayanan=[];
        $i = 0;
        // $noordertapistruk = null;
        // if(!empty($dataStruk)){
        //     $noordertapistruk = $dataStruk->id;
        // }
        $dataStok = DB::select(DB::raw("select sk.norec,spd.objectprodukfk, sk.tglstruk,spd.objectasalprodukfk,
                            spd.harganetto2 as hargajual,spd.harganetto2 as harganetto,spd.hargadiscount,
                    cast(sum(spd.qtyproduk) as float) as qtyproduk,spd.objectruanganfk
                    from stokprodukdetail_t as spd
                    inner JOIN strukpelayanan_t as sk on sk.norec=spd.nostrukterimafk
                    where spd.kdprofile = 30 and spd.objectruanganfk =:ruanganid
                    group by sk.norec,spd.objectprodukfk, sk.tglstruk,spd.objectasalprodukfk,
                            spd.harganetto2,spd.hargadiscount,
                    spd.objectruanganfk
                    order By sk.tglstruk"),
            array(
                'ruanganid' =>$dataStruk->id
            )
        );

        $hargajual=0;
        $harganetto=0;
        $nostrukterimafk='';
        $asalprodukfk=0;
        $asalproduk='';
        $jmlstok=0;
        $hargasatuan=0;
        $hargadiscount=0;
        $total=0;
        $aturanpakaifk=0;
        $rke='0';
        $dataTarifAdminResep = \DB::table('settingdatafixed_m as rt')
            ->select('rt.namafield','rt.nilaifield')
            ->where('rt.statusenabled',true)
            ->where('rt.namafield','tarifadminresep')
            ->orderBy('rt.id')
            ->get();
        foreach ($data as $item){
            $i = $i+1;
            $hargajual=0;
            $harganetto=0;
            $jmlstok=0;
            $hargasatuan=0;
            $hargadiscount=0;
            $total=0;



            $tarifadminjasa = $dataTarifAdminResep[0]->nilaifield;
            $tarifjasa =0;
            $qty20 =0;
            if ($item->jkid == 2){
                $tarifjasa = $tarifadminjasa;//800;
            }
            if ($item->jkid == 1){
                if ($rke != $item->rke) {
                    if ($item->qtyproduk > 20) {
                        $qty20 = number_format($item->qtyproduk / 20, 0);
                        if ($item->qtyproduk % 20 == 0) {
                            $qty20 = $qty20;
                        } else {
                            $qty20 = $qty20 + 1;
                        }

//                        $tarifjasa = 800 * $qty20;
                        $tarifjasa = $tarifadminjasa * $qty20;
                    }else{
//                        $tarifjasa = 800;
                        $tarifjasa = $tarifadminjasa ;
                    }
                    $rke = $item->rke;
                }
            }
            $hargajual =round($item->hargasatuan,0);
            $hargasatuan =round($item->hargasatuan,0);
            $harganetto =round( $item->hargadiscount,0);

            foreach ($dataStok as $item2){
                if ($item2->objectprodukfk == $item->objectprodukfk){
                    if ($item2->qtyproduk > $item->qtyproduk*$item->hasilkonversi){
//                        $hargajual =round($item2->hargajual+(($item2->hargajual*25)/100),0);
//                        $harganetto =round( $item2->harganetto+(($item2->harganetto*25)/100),0);//$item2->harganetto;



                        $nostrukterimafk = $item2->norec;
                        $asalprodukfk = $item2->objectasalprodukfk;
//                        $asalproduk = $item2->objectasalprodukfk;
                        $jmlstok = $item2->qtyproduk;
//                        $hargasatuan = $harganetto;//$item2->harganetto;
                        $hargadiscount = $item2->hargadiscount;
                        $total = (((float)ceil($item->qtyproduk) * ((float)$hargasatuan-(float)$hargadiscount))*$item->hasilkonversi) + $tarifjasa;
                        break;
                    }
                }
            }
            foreach ($dataAsalProduk as $item3){
                if ($asalprodukfk == $item3->id){
                    $asalproduk = $item3->asalproduk;
                }
            }
            foreach ($dataSigna as $item4){
                if ($item->aturanpakai == $item4->id){
                    $aturanpakaifk = $item4->id;
                }
            }
            if((float)$item->dosis == 0){
                $item->dosis = 1;
            }
            // return $this->respond($item->qtyproduk);
            
            $orderPelayanan[] = array(
                'no' => $i,
                'noregistrasifk' => '',
                'tglregistrasi' => '',
                'generik' => null,
                'hargajual' => $hargajual,
                'jenisobatfk' => $item->jenisobatfk,
                'kelasfk' => '',
                'stock' => $jmlstok,
                'harganetto' => $harganetto,
                'nostrukterimafk' => $nostrukterimafk,
                'ruanganfk' => $item->objectruangantujuanfk,
                'rke' => $item->rke,
                'jeniskemasanfk' => $item->jeniskemasanfk,
                'jeniskemasan' => $item->jeniskemasan,
                'aturanpakaifk' => $aturanpakaifk,
                'aturanpakai' => $item->aturanpakai,
                'routefk' => $item->routefk,
                'route' => $item->namaroute,
                'asalprodukfk' => $asalprodukfk,
                'asalproduk' => $asalproduk,
                'produkfk' => $item->objectprodukfk,
                'namaproduk' => $item->namaproduk,
                'nilaikonversi' => $item->hasilkonversi,
                'satuanstandarfk' => $item->ssid,//objectsatuanstandarfk,
                'satuanstandar' => $item->satuanstandar,//satuanstandar,
                'satuanviewfk' => $item->satuanviewfk,
                'satuanview' => $item->ssview,
                'jmlstok' => $item->qtystokcurrent,
                'jumlah' => ceil($item->qtyproduk),
                'jumlahobat' => $item->qtyproduk,
                'jumlahracikan' => $item->jumlahracikan,
                'dosis' => $item->dosis,
                'kekuatan' => $item->kekuatan,
                'hargasatuan' => $hargasatuan,
                'hargadiscount' => $hargadiscount,
                'total' => $total,
                'sediaan' => $item->sediaan,
                'jmldosis' => (String)$item->qtyproduk/$item->dosis . '/' . (String)$item->dosis,
//                'jmldosis' => (String)$item->qtyproduk,
                'jasa' => $tarifjasa,
                'ispagi' => $item->ispagi,
                'issiang' =>  $item->issiang,
                'ismalam' =>  $item->ismalam,
                'issore' =>  $item->issore,
                "catatandokter"=>$item->catatandokter,
                "keterangan"=>null,
                'satuanresepfk' =>  $item->satuanresepfk,
                "satuanresep"=>$item->satuanresep,
                "tglkadaluarsa"=>$item->tglkadaluarsa,
                "isreseppulang" => $item->isreseppulang,
                "satuandosis" => $item->satuandosis,
            );
        }
        $noorder = $r['noorder'];
        $raw = collect(DB::select("
            select pm2.nocm ,to_char(pm2.tgllahir,'dd-mm-yyyy') as tgllahir,age(pm2.tgllahir) as umur ,jm.jeniskelamin ,pm2.namapasien ,pm3.namalengkap, rm.namaruangan ruanganasal, ra.namaruangan ruangantujuan, pm2.alergi, 
            to_char(st.tglorder,'dd-mm-yyyy HH24:MI:ss') as tglorder,pm3.nosip, kp.kelompokpasien 
            from strukorder_t st
            inner join pasien_m pm2 on pm2.id = st.nocmfk
            inner join jeniskelamin_m jm on jm.id = pm2.objectjeniskelaminfk
            inner join pegawai_m pm3 on pm3.id = st.objectpegawaiorderfk
            inner join ruangan_m rm on rm.id = st.objectruanganfk 
            inner join ruangan_m ra on ra.id = st.objectruangantujuanfk 
            inner join pasiendaftar_t AS pd ON pd.norec = st.noregistrasifk
            left join kelompokpasien_m AS kp ON kp.id = pd.objectkelompokpasienlastfk
            where st.noorder = '$noorder'
        "))->first();
        return view('report.apotik.detailorder', compact('orderPelayanan', 'noorder','raw'));
    }

    public function cetakAntrianKiosk(Request $request) {
        $kdProfile = (int)$request['kdprofile'];
        $norec = $request['norec'];
        $TglAwal =  date('Y-m-d '). '00:00';
        $TglAkhir = date('Y-m-d '). '23:59';
        $tglAyeuna = date('Y-m-d H:i:s');
        $profile = collect(DB::select
            ("
                select * from profile_m where statusenabled=true limit 1
            "))->first();

        $antrian = DB::table('antrianpasienregistrasi_t AS apr')
                    ->leftJoin('ruangan_m AS ru','ru.id','=','apr.objectruanganfk')
                    ->select(DB::raw("apr.*,CASE WHEN ru.namaruangan IS NULL 
                                        THEN '' ELSE ru.namaruangan END AS namaruangan"))
                    ->where('apr.norec','=',$norec)
                    ->first();

        $str = $antrian->jenis;
        $jmlAntrian = DB::table('antrianpasienregistrasi_t')
            ->select(DB::raw("count(noantrian) as jmlantri"))
            ->where('statuspanggil','=',0)
            ->whereBetween('tanggalreservasi',[$TglAwal, $TglAkhir])
            ->where('jenis','=',$str)
            ->first();

        $noAntrian = $antrian->noantrian;
        $strJenis = $antrian->jenis;
        $jenis = "";
        if ($strJenis == "A"){
            $jenis = "UMUM";
        }elseif ($strJenis == "B"){
            $jenis = "BPJS";
        }
        if (strlen($antrian->noantrian) == 1){
            $noAntrian = "00" . $antrian->noantrian;
        }else{
            $noAntrian = "0" . $antrian->noantrian;
        }
        $pageWidth = 250;
        $dataReport = array(
            'namaprofile' => $profile->namalengkap,
            'alamat' => $profile->alamatlengkap,
            'jenis' => $jenis,
            'noantrian' => $strJenis . "-" . $noAntrian,
            'jmlantrian' => $jmlAntrian->jmlantri,
            'pageWidth'  => 365,
            'tanggal'  => $tglAyeuna,
        );

//        $pdf = PDF::loadView('report.pendaftaran.antrian', array(
//                'dataReport' => $dataReport,
//        ));
//        return $pdf->stream();

        return view('report.pendaftaran.antrian',
            compact('dataReport', 'pageWidth','profile'));
//        return view('','$result');
    }
    public function cetakAntrianFarmKiosk(Request $request) {
        $noreg = $request['noreg'];
        $noresep = $request['noresep'];
        $noorder = $request['noorder'];

        $tglAyeuna = date('Y-m-d H:i:s');

        $profile = collect(DB::select
            ("
                select * from profile_m where statusenabled=true limit 1
            "))->first();

        if ((int)$profile->id == 30) {
            $kdProfile = (int)$profile->id;
        } else {
            $kdProfile = 30;
        }

        if (empty($noresep)){
            if (!empty($noreg)) {
                $cekPasien = DB::table('pasiendaftar_t as pt')
                    ->join('pasien_m as pm', 'pm.id', '=', 'pt.nocmfk')
                    ->leftJoin('ruangan_m as rm', 'rm.id', '=', 'pt.objectruanganlastfk')
                    ->where(function ($q) use ($noreg) {
                        $q->where('pt.noregistrasi', $noreg)
                          ->orWhere('pm.nocm', $noreg);
                    })
                    ->where('pt.statusenabled', true)
                    ->select('rm.objectdepartemenfk')
                    ->orderBy('pt.tglregistrasi', 'desc')
                    ->first();

                if (!empty($cekPasien) && (int)$cekPasien->objectdepartemenfk == 16) {
                    return "Pasien Rawat Inap tidak perlu melakukan check-in farmasi melalui kiosk, silakan hubungi petugas farmasi untuk informasi lebih lanjut.";
                }
            }
            $data = DB::table('antrianapotik_t as at')
            ->join('pasiendaftar_t as pt', 'pt.norec', '=', 'at.noregistrasifk')
            ->join('pasien_m as pm', 'pm.id', '=', 'pt.nocmfk')
            ->leftJoin('jeniskelamin_m as jk', 'jk.id', '=', 'pm.objectjeniskelaminfk')
            ->join('strukorder_t as st', 'st.noorder', '=', 'at.noorder')
            ->join('ruangan_m as rm', 'rm.id', '=', 'st.objectruanganfk')
            ->join('kelompokpasien_m as km', 'km.id', '=', 'pt.objectkelompokpasienlastfk')
            ->leftJoin('alamat_m as alm', 'alm.nocmfk', '=', 'pm.id')
            ->where(function ($q) use ($noreg, $noorder) {
                if (!empty($noorder)) {
                    $q->where('at.noorder', $noorder);
                } else {
                    $q->where(function ($q2) use ($noreg) {
                        $q2->where('pt.noregistrasi', $noreg)
                        ->orWhere('pm.nocm', $noreg);
                    });
                }
            })
            ->where('pt.statusenabled', true)
            ->where('st.statusenabled', true)
            ->where('at.statusenabled', true)
            ->where('st.statusorder', 0)
            // ->whereIn('st.statusorder', [0, 1, 2, 3])
            ->whereRaw('rm.objectdepartemenfk != 16')
            ->orderBy('pt.tglregistrasi', 'desc')
            ->orderBy('st.tglorder', 'desc')
            ->orderBy('at.noantri', 'desc')
            ->select([
                DB::raw("at.jenis || ' - ' || at.noantri as noantri"),
                'pm.namapasien',
                'st.noorder',
                'pm.nocm',
                'pt.noregistrasi',
                'rm.namaruangan',
                'km.kelompokpasien',
                'pt.tglregistrasi',
                'at.tglresep',
                'at.jenis',
                'jk.jeniskelamin',
                DB::raw("DATE(pm.tgllahir) as tgllahir"),
                'alm.alamatlengkap'
            ])

            ->first();

            // generate antrian apotik
            if(empty($data)){
                $cekOrder = DB::table('strukorder_t as st')
                ->join('pasiendaftar_t as pt', 'pt.norec', '=', 'st.noregistrasifk')
                ->join('pasien_m as pm', 'pm.id', '=', 'pt.nocmfk')
                ->join('ruangan_m as rm', 'rm.id', '=', 'st.objectruanganfk')
                ->where(function ($query) use ($noreg, $noorder) {
                        if (!empty($noorder)) {
                            $query->where('st.noorder', $noorder);
                        } else {
                            $query->where('pt.noregistrasi', $noreg)
                                ->orWhere('pm.nocm', $noreg);
                        }
                })
                ->where('pt.statusenabled', true)
                ->where('st.statusenabled', true)
                ->where('st.statusorder', 0)
                // ->whereIn('st.statusorder', [0, 1, 2, 3])
                ->whereRaw('rm.objectdepartemenfk != 16')
                ->orderBy('pt.tglregistrasi', 'desc')
                ->orderBy('st.tglorder', 'desc')
                ->selectRaw("
                    st.norec as norec_so,
                    st.noorder,
                    pm.namapasien,
                    pm.nocm,
                    pt.norec as norec_pd
                ")
                ->first();

                if (!empty($cekOrder->noorder)) {
                    $detOrder = DB::table('orderpelayanan_t as op')
                        ->where('op.strukorderfk', $cekOrder->norec_so)
                        ->where('op.statusenabled', true)
                        ->select('op.jeniskemasanfk')
                        ->get();

                    $hasRacikan = false;
                    foreach ($detOrder as $cek) {
                        if ($cek->jeniskemasanfk == 1) {
                            $hasRacikan = true;
                            break;
                        }
                    }
                    $racikanORnonracikan = $hasRacikan ? 'R' : 'N';
                    \DB::transaction(function () use (
                        &$noAntriApotik,
                        $racikanORnonracikan,
                        $kdProfile,
                        $cekOrder
                    ) {
                        $last = \DB::table('antrianapotik_t')
                            ->where('jenis', $racikanORnonracikan)
                            ->whereRaw('DATE(tglresep) = CURRENT_DATE')
                            ->orderBy('noantri', 'desc')
                            ->lockForUpdate()
                            ->first();

                        $countAntrian = $last ? ((int)$last->noantri + 1) : 1;

                        $noAntriApotik = str_pad($countAntrian, 4, "0", STR_PAD_LEFT);

                        $newAA = new AntrianApotik();
                        $newAA->norec = $newAA->generateNewId();
                        $newAA->kdprofile = $kdProfile;
                        $newAA->statusenabled = true;
                        $newAA->noantri = $noAntriApotik;
                        $newAA->keterangan = $cekOrder->namapasien;
                        $newAA->noregistrasifk = $cekOrder->norec_pd;
                        $newAA->jenis = $racikanORnonracikan;
                        $newAA->tglresep = date('Y-m-d H:i:s');
                        $newAA->noorder = $cekOrder->noorder;
                        $newAA->source = 'KIOS-K';
                        // $newAA->status = '6';
                        $newAA->save();
                    });
                    
                    

                    $data = DB::table('antrianapotik_t as at')
                    ->join('pasiendaftar_t as pt', 'pt.norec', '=', 'at.noregistrasifk')
                    ->join('pasien_m as pm', 'pm.id', '=', 'pt.nocmfk')
                    ->leftJoin('jeniskelamin_m as jk', 'jk.id', '=', 'pm.objectjeniskelaminfk')
                    ->join('strukorder_t as st', 'st.noorder', '=', 'at.noorder')
                    ->join('ruangan_m as rm', 'rm.id', '=', 'st.objectruanganfk')
                    ->join('kelompokpasien_m as km', 'km.id', '=', 'pt.objectkelompokpasienlastfk')
                    ->leftJoin('alamat_m as alm', 'alm.nocmfk', '=', 'pm.id')
                    ->where(function ($q) use ($noreg, $noorder) {
                        if (!empty($noorder)) {
                            $q->where('at.noorder', $noorder);
                        } else {
                            $q->where(function ($q2) use ($noreg) {
                                $q2->where('pt.noregistrasi', $noreg)
                                ->orWhere('pm.nocm', $noreg);
                            });
                        }
                    })
                    ->where('pt.statusenabled', true)
                    ->where('st.statusenabled', true)
                    ->where('at.statusenabled', true)
                    ->where('st.statusorder', 0)
                    // ->whereIn('st.statusorder', [0, 1, 2, 3])
                    ->whereRaw('rm.objectdepartemenfk != 16')
                    ->orderBy('pt.tglregistrasi', 'desc')
                    ->orderBy('st.tglorder', 'desc')
                    ->orderBy('at.noantri', 'desc')
                    ->select([
                        DB::raw("at.jenis || ' - ' || at.noantri as noantri"),
                        'pm.namapasien',
                        'st.noorder',
                        'pm.nocm',
                        'pt.noregistrasi',
                        'rm.namaruangan',
                        'km.kelompokpasien',
                        'pt.tglregistrasi',
                        'at.tglresep',
                        'at.jenis',
                        'jk.jeniskelamin',
                        DB::raw("DATE(pm.tgllahir) as tgllahir"),
                        'alm.alamatlengkap'
                    ])

                    ->first();
                }
            }
        } else {
            $data = DB::table('antrianapotik_t as at')
                ->join('strukresep_t as st', 'at.noresep', '=', 'st.noresep')
                ->join('antrianpasiendiperiksa_t as apd', 'apd.norec', '=', 'st.pasienfk')
                ->join('pasiendaftar_t as pt', 'pt.norec', '=', 'apd.noregistrasifk')
                ->join('pasien_m as pm', 'pm.id', '=', 'pt.nocmfk')
                ->leftJoin('jeniskelamin_m as jk', 'jk.id', '=', 'pm.objectjeniskelaminfk')
                ->join('ruangan_m as rm', 'rm.id', '=', 'st.ruanganfk')
                ->join('kelompokpasien_m as km', 'km.id', '=', 'pt.objectkelompokpasienlastfk')
                ->leftJoin('alamat_m as alm', 'alm.nocmfk', '=', 'pm.id')
                ->where('at.noresep', $noresep)
                ->where('st.statusenabled', true)
                ->where('pt.statusenabled', true)
                ->where('at.statusenabled', true)
                ->whereRaw('rm.objectdepartemenfk != 16')
                ->orderBy('at.tglresep', 'desc')
                ->selectRaw("
                    at.jenis || ' - ' || at.noantri as noantri, 
                    pm.namapasien, 
                    st.noresep as noorder,
                    pm.nocm, 
                    pt.noregistrasi, 
