        $pageWidth = 950;
        $data = \DB::table('sdm_pesertadidik_t as sdmp')->where('sdmp.noregistrasifk',$norec)
        ->where('sdmp.kdprofile',$kdProfile)
        ->join('sdm_penelitianeksternal_t as sdm','sdm.norec','=','sdmp.noregistrasifk')
