    public function CetakKeuanganPerRekening(Request $request){
        $tahun = $request['tahun'];

        $qtahun  = '';
        $qtahunka  = '';
        if (isset($request['tahun']) && $request['tahun'] != "" && $request['tahun'] != "undefined") {
            $qtahun =  " and extract(year from sr.tglrealisasi) =  '" . $request['tahun']."'";
            $qtahunka =  " and ka.tahun =  '" . $request['tahun']."'";
        }

        $qasalproduk  = '';
        if (isset($request['asalproduk']) && $request['asalproduk'] != "" && $request['asalproduk'] != "undefined") {
            $qasalproduk =  " and kb.objectasalprodukfk =  " . $request['asalproduk'];
        }

        // $data = DB::select(DB::raw("select ma.kodemataanggaran, ma.namamataanggaran, sum(kb.subtotal) jumlahanggaran,
        // x.totalbelanja jumlahspj, y.jumlah jumlahpanjar,
        // x.totalbelanja + y.jumlah as subtotal, round(cast(((x.totalbelanja + y.jumlah)/sum(kb.subtotal))*100 as numeric), 2) as persentase,  
        // sum(kb.subtotal) - (x.totalbelanja + y.jumlah) sisaanggaran
        // from mataanggaran_m ma
        // inner join keteranganbelanja_t kb on ma.id=kb.objectmataanggaranfk
        // INNER JOIN kegiatananggaran_m ka on ka.id=kb.objectkegiatanfk
		// 		inner join (
		// 			select ma.kodemataanggaran, ma.namamataanggaran, sum(sr.totalbelanja) totalbelanja
		// 			from mataanggaran_m ma
		// 			inner join strukrealisasi_t sr on ma.id=sr.objectmataanggaranfk
		// 			where sr.kdprofile = 30 and sr.statusenabled = true
		// 			and sr.status = 'Sudah Diverifikasi'
        //             $qtahun
		// 			group by ma.kodemataanggaran, ma.namamataanggaran
		// 		) as x on x.kodemataanggaran = ma.kodemataanggaran
		// 		inner join (
		// 			select kodemataanggaran, namamataanggaran, sum(jumlah) jumlah
		// 			from(
		// 				select ma.kodemataanggaran, ma.namamataanggaran, pj.jumlah panjar, coalesce(sum(sr.totalbelanja),0) totalbelanja,  coalesce(pj.jumlah - coalesce(sum(sr.totalbelanja),0), 0) as jumlah
		// 				from mataanggaran_m ma
		// 				left join panjar_t pj on ma.id=pj.objectmataanggaranfk and pj.kdprofile = 30 and pj.statusenabled = true
		// 				left join strukrealisasi_t sr on sr.objectpanjarfk = pj.norec and sr.kdprofile = 30 and sr.statusenabled = true
		// 				and sr.status = 'Sudah Diverifikasi'
        //                 $qtahun
		// 				group by ma.kodemataanggaran, ma.namamataanggaran, pj.jumlah
		// 			) as s group by kodemataanggaran, namamataanggaran
		// 		) as y on y.kodemataanggaran = ma.kodemataanggaran
        // where ma.kdprofile = 30 and ma.statusenabled = true
        // and kb.kdprofile = 30 and kb.statusenabled = true
        // and ka.kdprofile = 30 and ka.statusenabled = true
        // $qasalproduk
        // $qtahunka
        // group by ma.kodemataanggaran, ma.namamataanggaran, x.totalbelanja, y.jumlah
        // "));

        $settingrba = DB::table('settinganggaran_t')
            ->where('statusenabled', true)
            ->where('kdprofile', 30)
            ->first();

        $data = DB::select(DB::raw("

            SELECT
                x.id, x.kodemataanggaran, x.namamataanggaran, 
                COALESCE(SUM(x.jumlahanggaran), 0) as jumlahanggaran, 
                COALESCE(SUM(x.jumlahpanjar), 0) - COALESCE(SUM(x.jumlahpanjarspj), 0) as jumlahpanjar, 
                COALESCE(SUM(x.jumlahspj), 0) as jumlahspj, 
                (COALESCE(SUM(x.jumlahpanjar), 0) - COALESCE(SUM(x.jumlahpanjarspj), 0)) + COALESCE(SUM(x.jumlahspj),0) as subtotal,
                ((COALESCE(SUM(x.jumlahpanjar), 0) - COALESCE(SUM(x.jumlahpanjarspj), 0)) + COALESCE(SUM(x.jumlahspj),0)) / COALESCE(SUM(x.jumlahanggaran), 0) * 100 as persentase,
                (COALESCE(SUM(x.jumlahanggaran), 0) - ((COALESCE(SUM(x.jumlahpanjar), 0) - COALESCE(SUM(x.jumlahpanjarspj), 0)) + COALESCE(SUM(x.jumlahspj),0))) as sisaanggaran
            FROM (
                
                --- anggaran
                SELECT
                    ma.id,
                    ma.kodemataanggaran,
                    ma.namamataanggaran,
                    COALESCE(SUM(kb.subtotal), 0) as jumlahanggaran,
                    0 as jumlahpanjar,
                    0 as jumlahspj,
                    0 as jumlahpanjarspj
                FROM keteranganbelanja_t kb 
                JOIN transaksianggaran2024_t ta ON ta.norec = kb.objecttransaksifk AND ta.statusenabled = TRUE
                JOIN kegiatananggaran2024_m ka ON ka.id = ta.objectkegiatanfk
                JOIN mataanggaran_m ma ON ma.id = kb.objectmataanggaranfk AND ma.statusenabled = TRUE
                JOIN asalproduk_m ap ON ap.id = kb.objectasalprodukfk AND ap.statusenabled = TRUE
                WHERE
                    kb.statusenabled = TRUE
                    -- opsi
                    AND ta.tahun = '".$request['tahun']."'
                    AND kb.objectasalprodukfk = ".$request['asalproduk']."
                    AND kb.objecttahapfk = ".$settingrba->objecttahapaktivfk."
                GROUP BY
                    ma.id,
                    ma.kodemataanggaran,
                    ma.namamataanggaran
                
                -- panjar	
                UNION
                
                SELECT
                    ma.id,
                    ma.kodemataanggaran,
                    ma.namamataanggaran,
                    0 as jumlahanggaran,
                    COALESCE(SUM(pj.jumlah), 0) - COALESCE(SUM(pp.jumlahpengembalian), 0) as jumlahpanjar,
                    0 as jumlahspj,
                    0 as jumlahpanjarspj
                FROM panjar_t pj
                JOIN kegiatananggaran2024_m ka ON ka.id = pj.objectsubsubkegiatanfk
                JOIN mataanggaran_m ma ON ma.id = pj.objectmataanggaranfk AND ma.statusenabled = TRUE
                JOIN asalproduk_m ap ON ap.id = pj.objectasalprodukfk AND ap.statusenabled = TRUE
                LEFT JOIN pengembalianpanjar_t pp ON pp.objectpanjarfk = pj.norec AND pp.statusenabled = TRUE 
                WHERE
                    pj.statusenabled = TRUE
                    -- opsi
                    AND EXTRACT(YEAR FROM pj.tglpanjar) = '".$request['tahun']."'
                    AND pj.objectasalprodukfk = ".$request['asalproduk']."
                GROUP BY
                    ma.id,
                    ma.kodemataanggaran,
                    ma.namamataanggaran
                
                -- spj
                UNION 
                
                SELECT
                    ma.id,
                    ma.kodemataanggaran,
                    ma.namamataanggaran,
                    0 as jumlahanggaran,
                    0 as jumlahpanjar,
                    SUM(rd.subtotal) as jumlahspj,
                    0 as jumlahpanjarspj
                FROM strukrealisasi_t sr
                JOIN realisasidetail_t rd ON rd.strukrealisasifk = sr.norec AND rd.statusenabled = TRUE 
                JOIN keteranganbelanja_t kb ON kb.norec = rd.keteranganbelanjafk AND kb.statusenabled = TRUE
                JOIN transaksianggaran2024_t ta ON ta.norec = kb.objecttransaksifk AND ta.statusenabled = TRUE
                JOIN kegiatananggaran2024_m ka ON ka.id = ta.objectkegiatanfk AND ka.statusenabled = TRUE
                JOIN mataanggaran_m ma ON ma.id = sr.objectmataanggaranfk AND ma.statusenabled = TRUE
                JOIN asalproduk_m ap ON ap.id = sr.objectasalprodukfk AND ap.statusenabled = TRUE
                WHERE
                    sr.statusenabled = TRUE
                    AND sr.status ILIKE '%Sudah Diverifikasi%'
                    -- opsi
                    AND ta.tahun = '".$request['tahun']."'
                    AND sr.objectasalprodukfk = ".$request['asalproduk']."
                GROUP BY
                    ma.id,
                    ma.kodemataanggaran,
                    ma.namamataanggaran

                -- panjarspj
                UNION

                SELECT
                    ma.id,
                    ma.kodemataanggaran,
                    ma.namamataanggaran,
                    0 as jumlahanggaran,
                    0 as jumlahpanjar,
                    0 as jumlahspj,
                    COALESCE(SUM(sp.jumlahspj), 0) as jumlahpanjarspj
                FROM panjar_t pj
                JOIN kegiatananggaran2024_m ka ON ka.id = pj.objectsubsubkegiatanfk
                JOIN mataanggaran_m ma ON ma.id = pj.objectmataanggaranfk AND ma.statusenabled = TRUE
                JOIN asalproduk_m ap ON ap.id = pj.objectasalprodukfk AND ap.statusenabled = TRUE
                JOIN spjtopanjar_t sp ON sp.objectpanjarfk = pj.norec AND sp.statusenabled = TRUE 
                WHERE
                    pj.statusenabled = TRUE
                    -- opsi
                    AND EXTRACT(YEAR FROM pj.tglpanjar) = '".$request['tahun']."'
                    AND pj.objectasalprodukfk = ".$request['asalproduk']."
                GROUP BY
                    ma.id,
                    ma.kodemataanggaran,
                    ma.namamataanggaran
            ) as x
            GROUP BY
                x.id,
                x.kodemataanggaran,
                x.namamataanggaran
            ORDER BY
                SPLIT_PART(x.kodemataanggaran, '.', 1),
                SPLIT_PART(x.kodemataanggaran, '.', 2),
                SPLIT_PART(x.kodemataanggaran, '.', 3),
                case 
                        when SPLIT_PART(x.kodemataanggaran, '.', 5) = '' THEN cast(SPLIT_PART(x.kodemataanggaran, '.', 4) as INTEGER)
                        else cast(SPLIT_PART(x.kodemataanggaran, '.', 5) as INTEGER)
                END asc

        "));

        $pageWidth = 950;
        //return $this->respond($result);
        return view('report.keuangan.perrekening',compact('data', 'pageWidth', 'tahun'));
    }

    public function CetakRK(Request $request){
        $tahunjudul = $request['tahun'];
        $tanggalcetak = $this->tanggal_indonesia(date('Y-m-d',strtotime($request['tglcetak'])));

        $bulan = $request['bulan'];

        $periode = '';
        if($bulan == '01'){
            $periode = 'JANUARI';
        }
        else if($bulan == '02'){
            $periode = 'FEBRUARI';
        }
        else if($bulan == '03'){
            $periode = 'MARET';
        }
        else if($bulan == '04'){
            $periode = 'APRIL';
        }
        else if($bulan == '05'){
            $periode = 'MEI';
        }
        else if($bulan == '06'){
            $periode = 'JUNI';
        }
        else if($bulan == '07'){
            $periode = 'JULI';
        }
        else if($bulan == '08'){
            $periode = 'AGUSTUS';
        }
        else if($bulan == '09'){
            $periode = 'SEPTEMBER';
        }
        else if($bulan == '10'){
            $periode = 'OKTOBER';
        }
        else if($bulan == '11'){
            $periode = 'NOVEMBER';
        }
        else if($bulan == '12'){
            $periode = 'DESEMBER';
        }

        $lalu = DB::select(DB::raw("SELECT extract('month' from(date '$tahunjudul-$bulan-01' - interval '1 month')) as bulan;"));

