                        ma.ID AS idAng,
                        ka.kode,
                        ma.kodemataanggaran,
                        ma.namamataanggaran,
                        COALESCE ( SUM ( kb.subtotal ), 0 ) AS jumlahanggaran,
                        0 AS panjar,
                        0 AS spj_prev, 0 AS spj_current,
                        0 AS panjarspj 
