                        ma.ID AS idAng,
                        ka.kode,
                        ma.kodemataanggaran,
                        ma.namamataanggaran,
                        0 AS jumlahanggaran,
                        0 AS panjar,
                        COALESCE ( SUM ( rd.subtotal ), 0 ) AS spj,
