                        SELECT ID 
                        FROM
                            kegiatananggaran_m 
                        WHERE
                            kode = ( SELECT kode FROM kegiatananggaran_m WHERE ID = $subsubk AND statusenabled = TRUE AND kdprofile = 30 LIMIT 1 ) 
                            AND tahun = '$tahun'
                            AND statusenabled = TRUE 
                            AND kdprofile = 30 
                        ) 
                        AND ka.tahun = '$tahun'
                        AND P.statusenabled = TRUE 
                        AND P.kdprofile = 30 
                        AND ka.statusenabled = TRUE 
                        AND ka.kdprofile = 30 
                        AND ma.statusenabled = TRUE 
                        AND ma.kdprofile = 30 
                        $asalproduk_pj
                    GROUP BY
                        ma.ID,
                        ka.kode,
                        ma.kodemataanggaran,
                        ma.namamataanggaran
                        
                    UNION

                    SELECT
                        ma.ID AS idAng,
                        ka.kode,
                        ma.kodemataanggaran,
                        ma.namamataanggaran,
                        0 AS jumlahanggaran,
                        0 AS panjar, 
                        0 AS spj_prev, 0 AS spj_current,
                        COALESCE ( SUM ( sp.jumlahspj ), 0 ) AS panjarspj
                    FROM
                        panjar_t
                        P LEFT JOIN kegiatananggaran_m ka ON ka.ID = P.objectsubsubkegiatanfk
                        LEFT JOIN mataanggaran_m ma ON ma.ID = P.objectmataanggaranfk
                        LEFT JOIN pengembalianpanjar_t pp ON pp.objectpanjarfk = P.norec  AND pp.statusenabled = TRUE AND pp.kdprofile = 30
                        LEFT JOIN spjtopanjar_t sp ON sp.objectpanjarfk = P.norec AND sp.statusenabled = TRUE AND sp.kdprofile = 30 
                    WHERE
                        P.objectsubsubkegiatanfk IN (
                        SELECT ID 
                        FROM
                            kegiatananggaran_m 
                        WHERE
                            kode = ( SELECT kode FROM kegiatananggaran_m WHERE ID = $subsubk AND statusenabled = TRUE AND kdprofile = 30 LIMIT 1 ) 
                            AND tahun = '$tahun'
                            AND statusenabled = TRUE 
                            AND kdprofile = 30 
                        ) 
                        AND ka.tahun = '$tahun'
                        AND P.statusenabled = TRUE 
                        AND P.kdprofile = 30 
                        AND ka.statusenabled = TRUE 
                        AND ka.kdprofile = 30 
                        AND ma.statusenabled = TRUE 
                        AND ma.kdprofile = 30 
                        $asalproduk_pj
                    GROUP BY
                        ma.ID,
                        ka.kode,
                        ma.kodemataanggaran,
                        ma.namamataanggaran 

                    ) AS x 
                GROUP BY
                    kodemataanggaran,
                    namamataanggaran
                order by subkodepertama asc, subkodekedua asc, subkodeketiga asc, subkodekeempat asc, subkodekelima asc 

             "));


        $pageWidth = 950;
        //return $this->respond($result);
        $settingrba = DB::select(DB::raw("
        select pg.namalengkap, pg.nippns from settinganggaran_t sa
        inner join pegawai_m pg on pg.id = sa.objectkepalabludfk
        where sa.statusenabled = true
        "));
        return view('report.spj.cetakspjmonev',compact('data', 'pageWidth', 'tahun', 'subkegiatan', 'subsubkegiatan','settingrba'));
    }

    public function CetakKeuanganPerRekeningPermen(Request $request){
        $tahun = $request['tahun'];

        $qtahun  = '';
        $qtahunka  = '';
        if (isset($request['tahun']) && $request['tahun'] != "" && $request['tahun'] != "undefined") {
            $qtahun =  " and extract(year from sr.tglrealisasi) =  '" . $request['tahun']."'";
            $qtahunka =  " and ka.tahun =  '" . $request['tahun']."'";
        }

        $qasalproduk  = '';
        if (isset($request['asalproduk']) && $request['asalproduk'] != "" && $request['asalproduk'] != "undefined") {
            $qasalproduk =  " and kb.objectasalprodukfk =  " . $request['asalproduk'];
        }

        $data = DB::select(DB::raw("select map5.mataanggaranpermen as namamataanggaran, map2.kode || '.' ||  map3.kode || '.' ||  map4.kode || '.' || map5.kode as kodemataanggaran, sum(kb.subtotal) jumlahanggaran,
        x.totalbelanja jumlahspj, y.jumlah jumlahpanjar,
        x.totalbelanja + y.jumlah as subtotal, round(cast(((x.totalbelanja + y.jumlah)/sum(kb.subtotal))*100 as numeric), 2) as persentase,  
        sum(kb.subtotal) - (x.totalbelanja + y.jumlah) sisaanggaran
        from mataanggaran_m ma
        inner join keteranganbelanja_t kb on ma.id=kb.objectmataanggaranfk
        inner join mataanggaranpermen_m map5 on map5.id = ma.mataanggaranpermenfk and map5.div = 5
        inner join mataanggaranpermen_m map4 on map5.mataanggaranpermenfk = map4.id and map4.div = 4
        inner join mataanggaranpermen_m map3 on map4.mataanggaranpermenfk = map3.id and map3.div = 3
        inner join mataanggaranpermen_m map2 on map3.mataanggaranpermenfk = map2.id and map2.div = 2
        INNER JOIN kegiatananggaran_m ka on ka.id=kb.objectkegiatanfk
				inner join (
					select ma.kodemataanggaran, ma.namamataanggaran, sum(sr.totalbelanja) totalbelanja
					from mataanggaran_m ma
					inner join strukrealisasi_t sr on ma.id=sr.objectmataanggaranfk
					where sr.kdprofile = 30 and sr.statusenabled = true
					and sr.status = 'Sudah Diverifikasi'
                    $qtahun
					group by ma.kodemataanggaran, ma.namamataanggaran
				) as x on x.kodemataanggaran = ma.kodemataanggaran
				inner join (
					select kodemataanggaran, namamataanggaran, sum(jumlah) jumlah
					from(
						select ma.kodemataanggaran, ma.namamataanggaran, pj.jumlah panjar, coalesce(sum(sr.totalbelanja),0) totalbelanja,  coalesce(pj.jumlah - coalesce(sum(sr.totalbelanja),0), 0) as jumlah
						from mataanggaran_m ma
						left join panjar_t pj on ma.id=pj.objectmataanggaranfk and pj.kdprofile = 30 and pj.statusenabled = true
						left join strukrealisasi_t sr on sr.objectpanjarfk = pj.norec and sr.kdprofile = 30 and sr.statusenabled = true
						and sr.status = 'Sudah Diverifikasi'
                        $qtahun
						group by ma.kodemataanggaran, ma.namamataanggaran, pj.jumlah
					) as s group by kodemataanggaran, namamataanggaran
				) as y on y.kodemataanggaran = ma.kodemataanggaran
        where ma.kdprofile = 30 and ma.statusenabled = true
        and kb.kdprofile = 30 and kb.statusenabled = true
        and ka.kdprofile = 30 and ka.statusenabled = true
        $qasalproduk
        $qtahunka
        group by map5.mataanggaranpermen, map2.kode || '.' ||  map3.kode || '.' ||  map4.kode || '.' || map5.kode, x.totalbelanja, y.jumlah;
        "));

        $pageWidth = 950;
        //return $this->respond($result);
        return view('report.keuangan.perrekening',compact('data', 'pageWidth', 'tahun'));
    }

    public function CetakAngkasPenyerapan(Request $request){
        $tahunAnggaran = $request['tahunangkas'];

        $bulan = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
        $bawal = $bulan[(float)$request['bulanawal'] - 1];
        $bakhir = $bulan[(float)$request['bulanakhir'] -1]; 

        $qtahun  = '';
        $tahun = '';
        if (isset($request['tahunangkas']) && $request['tahunangkas'] != "" && $request['tahunangkas'] != "undefined") {
            $qtahun =  " and extract(year from sr.tglrealisasi) =  '" . $request['tahunangkas']."'";
            $tahun = "and ta.tahun = '".$request['tahunangkas']."'";
        }

        $qasalproduk  = '';
        $apanggaran = '';
        $apspj = '';
        if (isset($request['asalprodukangkas']) && $request['asalprodukangkas'] != "" && $request['asalprodukangkas'] != "undefined") {
            $qasalproduk =  " and kb.objectasalprodukfk =  " . $request['asalprodukangkas'];
            $apanggaran = "and kb.objectasalprodukfk = ".$request['asalprodukangkas'];
            $apspj = "and sr.objectasalprodukfk = ".$request['asalprodukangkas']; 
        }

        $bulanawal  = '';
        if (isset($request['bulanawal']) && $request['bulanawal'] != "" && $request['bulanawal'] != "undefined") {
            $bulanawal =  " and extract(month from sr.tglrealisasi) >= '" . $request['bulanawal']."'";
        }

        $bulanakhir  = '';
        if (isset($request['bulanakhir']) && $request['bulanakhir'] != "" && $request['bulanakhir'] != "undefined") {
            $bulanakhir =  " and extract(month from sr.tglrealisasi) <= '" . $request['bulanakhir']."'";
        }

        // $data = DB::select(DB::raw("select 'iya' as bold, nourut, kode, keterangan, sum(jumlahanggaran) jumlahanggaran, sum(jumlahspj) jumlahspj,
        // round(cast(sum(jumlahspj)/sum(jumlahanggaran)*100 as numeric), 2) as persentase
        // from(
        //     select RANK ( ) OVER ( order by ka.kode ) AS nourut, ka.kode, 
        //     ka.keterangan, sum(kb.subtotal) jumlahanggaran, x.totalbelanja jumlahspj,
        //     round(cast(x.totalbelanja/sum(kb.subtotal)*100 as numeric), 2) as persentase
        //     from mataanggaran_m ma
        //     inner join keteranganbelanja_t kb on ma.id=kb.objectmataanggaranfk
        //     INNER JOIN kegiatananggaran_m ka on ka.id=kb.objectkegiatanfk
        //     inner join (
        //         select ma.kodemataanggaran, ma.namamataanggaran, sum(sr.totalbelanja) totalbelanja
        //         from mataanggaran_m ma
        //         inner join strukrealisasi_t sr on ma.id=sr.objectmataanggaranfk
        //         where sr.kdprofile = 30 and sr.statusenabled = true
        //         and sr.status = 'Sudah Diverifikasi'
        //         $qtahun
        //         $bulanawal
        //         $bulanakhir
        //         group by ma.kodemataanggaran, ma.namamataanggaran
        //     ) as x on x.kodemataanggaran = ma.kodemataanggaran
        //     where ma.kdprofile = 30 and ma.statusenabled = true
        //     and kb.kdprofile = 30 and kb.statusenabled = true
        //     and ka.kdprofile = 30 and ka.statusenabled = true
        //     $qasalproduk
        //     group by ka.kode, ka.keterangan, x.totalbelanja
        // ) as y group by nourut, kode, keterangan
        
        // union all
        
        // select 'tidak' as bold, RANK ( ) OVER ( order by ka.kode ) AS nourut, ma.kodemataanggaran kode, 
        // ma.namamataanggaran keterangan, sum(kb.subtotal) jumlahanggaran, x.totalbelanja jumlahspj,
        // round(cast(x.totalbelanja/sum(kb.subtotal)*100 as numeric), 2) as persentase
        // from mataanggaran_m ma
        // inner join keteranganbelanja_t kb on ma.id=kb.objectmataanggaranfk
        // INNER JOIN kegiatananggaran_m ka on ka.id=kb.objectkegiatanfk
        // inner join (
        //     select ma.kodemataanggaran, ma.namamataanggaran, sum(sr.totalbelanja) totalbelanja
        //     from mataanggaran_m ma
        //     inner join strukrealisasi_t sr on ma.id=sr.objectmataanggaranfk
        //     where sr.kdprofile = 30 and sr.statusenabled = true
        //     and sr.status = 'Sudah Diverifikasi'
        //     $qtahun
        //     $bulanawal
        //     $bulanakhir
        //     group by ma.kodemataanggaran, ma.namamataanggaran
        // ) as x on x.kodemataanggaran = ma.kodemataanggaran
        // where ma.kdprofile = 30 and ma.statusenabled = true
        // and kb.kdprofile = 30 and kb.statusenabled = true
        // and ka.kdprofile = 30 and ka.statusenabled = true
        // $qasalproduk
        // group by ka.kode, ma.kodemataanggaran, ma.namamataanggaran, x.totalbelanja
        // order by nourut;"));

        $settingrba = DB::table('settinganggaran_t')
            ->where('statusenabled', true)
            ->where('kdprofile', 30)
            ->first();

        $data = DB::select(DB::raw("

            SELECT
                x.kode, x.keterangankegiatan,
                x.id, x.kodemataanggaran, x.namamataanggaran, 
                COALESCE(SUM(x.jumlahanggaran), 0) as jumlahanggaran,
                COALESCE(SUM(x.jumlahspj), 0) as jumlahspj
            FROM (
                
                --- anggaran
                SELECT
                    ka.kode,
                    reverse(split_part(reverse(MIN(ka.keterangan)), '-', 1)) as keterangankegiatan,
                    ma.id,
                    ma.kodemataanggaran,
                    ma.namamataanggaran,
                    COALESCE(SUM(CAST(akb.nilai as FLOAT)), 0) as jumlahanggaran,
                    0 as jumlahspj
                FROM keteranganbelanja_t kb 
                JOIN alokasiketeranganbelanja_t akb ON akb.keteranganbelanjafk = kb.norec AND akb.statusenabled = TRUE
                JOIN transaksianggaran2024_t ta ON ta.norec = kb.objecttransaksifk AND ta.statusenabled = TRUE
                JOIN kegiatananggaran2024_m ka ON ka.id = ta.objectkegiatanfk AND ka.statusenabled = TRUE
                JOIN mataanggaran_m ma ON ma.id = kb.objectmataanggaranfk AND ma.statusenabled = TRUE
                JOIN asalproduk_m ap ON ap.id = kb.objectasalprodukfk AND ap.statusenabled = TRUE
                WHERE
                    kb.statusenabled = TRUE
                    -- opsi
                    $tahun
                    $apanggaran
                    AND ta.objecttahapfk = ".$settingrba->objecttahapaktivfk."
                    AND akb.bulanint BETWEEN ".(float)$request['bulanawal']." AND ".(float)$request['bulanakhir']."
                GROUP BY
                    ka.kode,
                    ma.id,
                    ma.kodemataanggaran,
                    ma.namamataanggaran
                
                -- spj
                UNION 
                
                SELECT
                    ka.kode,
                    reverse(split_part(reverse(MIN(ka.keterangan)), '-', 1)) as keterangankegiatan,
                    ma.id,
                    ma.kodemataanggaran,
                    ma.namamataanggaran,
                    0 as jumlahanggaran,
                    SUM(rd.subtotal) as jumlahspj
                FROM strukrealisasi_t sr
                JOIN realisasidetail_t rd ON rd.strukrealisasifk = sr.norec AND rd.statusenabled = TRUE 
                JOIN keteranganbelanja_t kb ON kb.norec = rd.keteranganbelanjafk AND kb.statusenabled = TRUE
                JOIN transaksianggaran2024_t ta ON ta.norec = kb.objecttransaksifk AND ta.statusenabled = TRUE
                JOIN kegiatananggaran2024_m ka ON ka.id = ta.objectkegiatanfk AND ka.statusenabled = TRUE
                JOIN mataanggaran_m ma ON ma.id = sr.objectmataanggaranfk AND ma.statusenabled = TRUE
                JOIN asalproduk_m ap ON ap.id = sr.objectasalprodukfk AND ap.statusenabled = TRUE
                WHERE
                    sr.statusenabled = TRUE
                    AND sr.status ILIKE '%Sudah Diverifikasi%'
                    -- opsi
                    $tahun
                    $apspj
                    AND EXTRACT(MONTH FROM sr.tglrealisasi) BETWEEN ".(float)$request['bulanawal']." AND ".(float)$request['bulanakhir']."
                GROUP BY
                    ka.kode,
                    ma.id,
                    ma.kodemataanggaran,
                    ma.namamataanggaran
            ) as x
            GROUP BY
                x.kode,
                x.keterangankegiatan,
                x.id,
                x.kodemataanggaran,
                x.namamataanggaran
            ORDER BY
                CAST(SPLIT_PART(x.kode, '.', 2) AS INTEGER) ASC,
                CAST(SPLIT_PART(x.kode, '.', 3) AS INTEGER) ASC,
                CAST(SPLIT_PART(x.kode, '.', 4) AS INTEGER) ASC,
                CAST(SPLIT_PART(x.kode, '.', 5) AS INTEGER) ASC,
                CAST(SPLIT_PART(x.kode, '.', 6) AS INTEGER) ASC,
                CAST(SPLIT_PART(x.kode, '.', 7) AS INTEGER) ASC,
                SPLIT_PART(x.kodemataanggaran, '.', 1),
                SPLIT_PART(x.kodemataanggaran, '.', 2),
                SPLIT_PART(x.kodemataanggaran, '.', 3),
                case 
                    when SPLIT_PART(x.kodemataanggaran, '.', 5) = '' THEN cast(SPLIT_PART(x.kodemataanggaran, '.', 4) as INTEGER)
                    else cast(SPLIT_PART(x.kodemataanggaran, '.', 5) as INTEGER)
                END asc
        
        "));

        $pageWidth = 950;
        //return $this->respond($result);
        return view('report.keuangan.angkaspenyerapan',compact('data', 'pageWidth', 'tahunAnggaran', 'bawal', 'bakhir'));
    }

