                and coa1.namaaccount = 'ASET'
                group by coa1.id, ma.kodemataanggaran, ma.namamataanggaran, ka.tahun

                union all

                select coa1.id, '2.1.01.01.01.0001.001' as noaccount, 'JUMLAH KEWAJIBAN' namaaccount,
