                group by coa1.id, ma.kodemataanggaran, ma.namamataanggaran, ka.tahun

                union all

                select coa1.id, '3.1.01.01.01.0001.001' as noaccount, 'JUMLAH EKUITAS DANA' namaaccount,
                ma.kodemataanggaran, ma.namamataanggaran,
