        //     and dp0.kdprofile = 30 and dp0.statusenabled=true
        //     and ma.kdprofile = 30 and ma.statusenabled=true
        //     and sr.kdprofile = 30 and sr.statusenabled=true
        //     and extract(month from bku.tglbku) = '$bulan'
