        }

        // jika memilih bulan januari maka lihat anggaran
        // jika memeilih bulan setelah januari maka anggaran lihat sisa bulan sebelumnya
        $anggaran_awal = 0;
        $bulanlalu = 0;
        if((float)$request['bulan'] !== 1){

            // data bulan lalu
            $bku = DB::select(DB::raw("

                SELECT
                    bku.tglbku, bku.uraianbku, bku.nobku,
                    COALESCE(SUM(bku.pengeluaran), 0) as jumlahbku
                FROM strukrealisasi_t sr 
                JOIN realisasidetail_t rd ON rd.strukrealisasifk = sr.norec AND rd.statusenabled = TRUE
                JOIN bukukasumum_t bku ON bku.norec = sr.objectbkufk AND bku.statusenabled = TRUE
                JOIN kegiatananggaran_m ka ON ka.id = sr.objectkegiatanfk AND ka.statusenabled = TRUE
                JOIN mataanggaran_m ma ON ma.id = sr.objectmataanggaranfk AND ma.statusenabled = TRUE
                WHERE
                    sr.statusenabled = TRUE
                    AND ka.tahun = '".$request['tahun']."'
                    AND ka.kode = '".$dtsubsubkegiatan[0]->kode."'
                    AND ma.id = ".$request['idmataanggaran']."
                    AND extract(year from bku.tglbku) = ".$request['tahun']." 
                    and extract(month from bku.tglbku) < ".(float)$request['bulan']."
                    $apSPJ
                GROUP BY
                    bku.norec
                ORDER BY
                    bku.tglbku ASC
            "));

            foreach($bku as $row){
                $bulanlalu += $row->jumlahbku;
            }

            $anggaran_awal = $totalanggaran - $bulanlalu;

        }else{
            $anggaran_awal = $totalanggaran;
        }


        // $saldoakhir = 0;

        // foreach($data as $row){
        //     if($row->uraianbku == 'ANGGARAN'){
        //         $saldoakhir = $saldoakhir + $row->penerimaan - $row->pengeluaran;  
        //     } else{
        //         $saldoakhir = $saldoakhir - $row->pengeluaran;   
        //     }
        //     $row->saldoawal = $saldoakhir;
        // }

        $pageWidth = 950;
        //return $this->respond($result);
        return view('report.keuangan.cetakro',compact('data', 'pageWidth', 'tahunjudul', 'tanggalcetak', 'totalanggaran', 'anggaran_awal', 'dtsubsubkegiatan', 'rekening', 'bulanlalu'));
    }

    public function CetakBKUReal(Request $request){
        $tahunjudul = $request['tahunbku'];
        $tanggalcetak = $this->tanggal_indonesia(date('Y-m-d',strtotime($request['tglcetak'])));
        // $bawal = date('F', mktime(0, 0, 0, $request['bulanawal'], 10));
        // $bakhir = date('F', mktime(0, 0, 0, $request['bulanakhir'], 10));

        $bulan = $request['bulanbku'];


        if($bulan == '01'){
            $periode = 'JANUARI';
        }
        else if($bulan == '02'){
            $periode = 'FEBRUARI';
        }
        else if($bulan == '03'){
            $periode = 'MARET';
        }
        else if($bulan == '04'){
            $periode = 'APRIL';
        }
        else if($bulan == '05'){
            $periode = 'MEI';
        }
        else if($bulan == '06'){
            $periode = 'JUNI';
        }
        else if($bulan == '07'){
            $periode = 'JULI';
        }
        else if($bulan == '08'){
            $periode = 'AGUSTUS';
        }
        else if($bulan == '09'){
            $periode = 'SEPTEMBER';
        }
        else if($bulan == '10'){
            $periode = 'OKTOBER';
        }
        else if($bulan == '11'){
            $periode = 'NOVEMBER';
        }
        else if($bulan == '12'){
            $periode = 'DESEMBER';
        }

        $qtahun  = '';
        if (isset($request['tahunbku']) && $request['tahunbku'] != "" && $request['tahunbku'] != "undefined") {
            $qtahun =  " and extract(year from tglbku) =  '" . $request['tahunbku']."'";
        }

        $qbulan  = '';
        if (isset($request['bulanbku']) && $request['bulanbku'] != "" && $request['bulanbku'] != "undefined") {
            $qbulan =  " and extract(month from tglbku) =  '" . $request['bulanbku']."'";
        }

        $qbulanSaldo  = '';
        if (isset($request['bulanbku']) && $request['bulanbku'] != "" && $request['bulanbku'] != "undefined") {
            $qbulanSaldo =  " and extract(month from tglbku) <  '" . $request['bulanbku']."'";
        }

        // select 0 pph, 0 ppn, 0 nourut, '' objectmataanggaranfk, '' nobku, '' tgl, 'Saldo Awal Bulan' uraianbku, (saldo-penerimaan+pengeluaran) penerimaan, 0 pengeluaran, 0 saldoawal, '' nodokumen
        // order by tglbku asc limit 1

        $jumlahbkulalu = DB::select(DB::raw("
        select coalesce(sum(penerimaan),0) penerimaanLalu, coalesce(sum(pengeluaran),0) pengeluaranLalu, coalesce(sum(penerimaan),0)-coalesce(sum(pengeluaran),0) as saldoLalu
        from bukukasumum_t
        where kdprofile = 30
        and statusenabled = true
        $qbulanSaldo
        $qtahun"));

        $jumlahbkusekarang = DB::select(DB::raw("
        select coalesce(sum(penerimaan),0) penerimaanNow, coalesce(sum(pengeluaran),0) pengeluaranNow, coalesce(sum(penerimaan),0)-coalesce(sum(pengeluaran),0) as saldoNow
        from bukukasumum_t
        where kdprofile = 30
        and statusenabled = true
        $qbulan
        $qtahun"));

        $jumlahbkutotal = DB::select(DB::raw("
        select coalesce(sum(penerimaan),0) penerimaanTotal, coalesce(sum(pengeluaran),0) pengeluaranTotal, coalesce(sum(penerimaan),0)-coalesce(sum(pengeluaran),0) as saldoTotal
        from bukukasumum_t
        where kdprofile = 30
        and statusenabled = true
        $qtahun"));

        $data = DB::select(DB::raw("select * from(
            select 0 pph, 0 ppn, 0 nourut, '' objectmataanggaranfk, '' nobku, '' tgl, 'Saldo Awal Bulan' uraianbku, coalesce(sum(penerimaan)-sum(pengeluaran),0) penerimaan, 0 pengeluaran, 0 saldoawal, '' nodokumen, 0 objectjenisbuktifk, 'Saldo Awal Bulan' uraian
            from bukukasumum_t
            where kdprofile = 30
            and statusenabled = true
            $qbulanSaldo
            $qtahun
            ) as x
            
            union all
            
            
            select pph, ppn, nourut, objectmataanggaranfk, nobku, tgl, uraianbku, penerimaan, pengeluaran, saldoawal,
            case 
                when norealisasi is not null then norealisasi
                when nopengembalian is not null then nopengembalian
                WHEN nopanjar is not null  then nopanjar
                --WHEN nopanjar is not null  THEN (CASE WHEN nopengembalian IS NOT NULL THEN nopengembalian ELSE nopanjar END)
                when nospm is not null then nospm
                when nopemungutan is not null then nopemungutan
                when nopenyetoran is not null then nopenyetoran
                when nojasagiro is not null then nojasagiro
                when nosts is not null then nosts
            end as nodokumen, objectjenisbuktifk, 
			case 
                when norealisasi is not null AND deskripsi <> '' AND deskripsi is not null then concat(uraian,' : ',deskripsi)
                else uraianbku
            end as uraian
            from(
                select ROW_NUMBER ( ) OVER ( ORDER BY bku.nobku ) nourut, bku.objectmataanggaranfk, bku.nobku, 
                to_char(bku.tglbku::date, 'DD-MM-YYYY') tgl, bku.uraianbku, bku.penerimaan, 
                bku.pengeluaran, 0 saldoawal, sr.norealisasi, pj.nopanjar, spm.nospm,
                pp.nopajak nopemungutan, coalesce(pp.pph, 0) pph, coalesce(pp.ppn, 0) ppn, ppj.nopajak nopenyetoran, jg.nojasagiro, sk.nosts,pep.nopengembalian , objectjenisbuktifk, uraianbku uraian, sr.deskripsi 
                from bukukasumum_t bku
                left join strukrealisasi_t sr on sr.objectbkufk = bku.norec
                and sr.kdprofile = 30
                and sr.statusenabled = true
                left join panjar_t pj on pj.objectbkufk = bku.norec
                and pj.kdprofile = 30
                and pj.statusenabled = true
                left join spm_t spm on spm.objectbkufk = bku.norec
                and spm.kdprofile = 30
                and spm.statusenabled = true
                left join penyetoranpajak_t ppj on ppj.objectbkufk = bku.norec
                and ppj.kdprofile = 30
                and ppj.statusenabled = true
                left join pemungutanpajak_t pp on pp.objectbkufk = bku.norec
                and pp.kdprofile = 30
                and pp.statusenabled = true
                left join jasagiro_t jg on jg.objectbkufk = bku.norec
                and jg.kdprofile = 30
                and jg.statusenabled = true
                left join stskeuangan_t sk on sk.objectbkufk = bku.norec
                and sk.kdprofile = 30
                and sk.statusenabled = true
                left join pengembalianpanjar_t pep on pep.objectbkufk = bku.norec and pep.kdprofile = 30 and pep.statusenabled = true
                where bku.kdprofile = 30
                and bku.statusenabled = true 
                
                $qbulan
                $qtahun
            ) as x"));

        $saldoakhir = 0;

        foreach($data as $row){
            $saldoakhir = $saldoakhir + $row->penerimaan - $row->pengeluaran; 
            $row->saldoawal = $saldoakhir;
        }

        $pageWidth = 950;
        //return $this->respond($result);
        return view('report.keuangan.cetakbkureal',compact('data', 'pageWidth', 'tahunjudul', 'tanggalcetak', 'periode', 'jumlahbkulalu', 'jumlahbkusekarang', 'jumlahbkutotal'));
    }

    public function CetakBukuPajak(Request $request){
        $tahunjudul = $request['tahun'];
        $tanggalcetak = $this->tanggal_indonesia(date('Y-m-d',strtotime($request['tglcetak'])));
        $bulan = $request['bulan'];
        $sumberdana = $request['sumberdana'];

        $blalu = DB::select(DB::raw("SELECT extract('month' from(date '$tahunjudul-$bulan-01' - interval '1 month')) as bulan;"));

        $bulanlalu = $blalu[0]->bulan;

        $qtahun  = '';
        if (isset($request['tahun']) && $request['tahun'] != "" && $request['tahun'] != "undefined") {
            $qtahun =  " and extract(year from sr.tglrealisasi) =  '" . $request['tahun']."'";
        }

        $qbulan  = '';
        if (isset($request['bulan']) && $request['bulan'] != "" && $request['bulan'] != "undefined") {
            $qbulan =  " and extract(month from sr.tglrealisasi) =  '" . $request['bulan']."'";
        }

        $qasalproduk  = '';
        if (isset($request['sumberdana']) && $request['sumberdana'] != "" && $request['sumberdana'] != "undefined") {
            $qasalproduk =  " and ap.id =  " . $request['sumberdana'];
        }

        $data = DB::select(DB::raw("select ROW_NUMBER ( ) OVER ( ORDER BY norec ) nourut, norec, tglrealisasi, totalbelanja, namarekanan, npwp, alamatlengkap, billpph, billppn,
        idbillpph, idbillppn, ntpnpph, ntpnppn, ppn, pph21, pph22, pph23, pph26, pph4, pph
        from(

            select distinct sr.norec, sr.tglrealisasi::varchar, sr.totalbelanja, rk.namarekanan, rk.npwp, rk.alamatlengkap,
            'ID BILLING ' || jp.namaexternal billpph, 'ID BILLING PPN' billppn, pp.idbillpph, pp.idbillppn,
            pp.ntpnpph, pp.ntpnppn,
            ppn.ppn ppn,
            case when jp.id = 15 then pp.pph else null end as pph21,
            case when jp.id = 16 then pp.pph else null end as pph22,
            case when jp.id = 17 then pp.pph else null end as pph23,
            case when jp.id = 18 then pp.pph else null end as pph26,
            case when jp.id = 19 then pp.pph else null end as pph4,
            case when jp.id = 20 then pp.pph else null end as pph
            from strukrealisasi_t sr
            inner join pemungutanpajak_t pp on pp.objectspjfk = sr.norec
            left join jenispajak_m jp on jp.id = pp.objectjenispphfk
            and jp.statusenabled = true
            and jp.kdprofile = 30
            left join pemungutanpajak_t ppn on pp.idbillpph = ppn.idbillppn
            and pp.ntpnpph = ppn.ntpnppn
            and ppn.statusenabled = true
            and ppn.kdprofile = 30
            left join rekanan_m rk on rk.id = sr.rekananfk
            inner join kegiatananggaran_m as dp on dp.id = sr.objectkegiatanfk
            inner join keteranganbelanja_t as kb on kb.objectkegiatanfk = dp.id
            inner join asalproduk_m ap on ap.id = sr.objectasalprodukfk
            inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
            where sr.statusenabled = true
            and sr.kdprofile = 30
            and pp.statusenabled = true
            and pp.kdprofile = 30
            and pp.objectjenispphfk is not null
            and sr.status = 'Sudah Diverifikasi'
            $qbulan
            $qtahun
            $qasalproduk
            
            union all
            
            select distinct sr.norec, sr.tglrealisasi::varchar, sr.totalbelanja, rk.namarekanan, rk.npwp, rk.alamatlengkap,
            'ID BILLING ' || jp.namaexternal billpph, 'ID BILLING PPN' billppn, pj.idbillpph, pj.idbill idbillppn,
            pj.ntpnpph, pj.ntpn ntpnppn,
            pj.ppn ppn,
            case when jp.id = 15 then pj.pph else null end as pph21,
            case when jp.id = 16 then pj.pph else null end as pph22,
            case when jp.id = 17 then pj.pph else null end as pph23,
            case when jp.id = 18 then pj.pph else null end as pph26,
            case when jp.id = 19 then pj.pph else null end as pph4,
            case when jp.id = 20 then pj.pph else null end as pph
            from strukrealisasi_t sr
            inner join spjtopanjar_t spj on spj.objectspjfk = sr.norec
            inner join panjar_t pj on pj.norec = spj.objectpanjarfk
            inner join jenispajak_m jp on jp.id = pj.objectjenispphfk
            left join rekanan_m rk on rk.id = sr.rekananfk
            inner join asalproduk_m ap on ap.id = sr.objectasalprodukfk
            where sr.statusenabled = true
            and sr.kdprofile = 30
            and pj.statusenabled = true
            and pj.kdprofile = 30
            and sr.status = 'Sudah Diverifikasi'
            $qbulan
            $qtahun
            $qasalproduk
            
            union all
            
            select distinct sr.norec, sr.tglrealisasi::varchar, sr.totalbelanja, rk.namarekanan, rk.npwp, rk.alamatlengkap,
            'ID BILLING ' || jp.namaexternal billpph, 'ID BILLING PPN' billppn, pj.idbillpph2, '' idbillppn,
            pj.ntpnpph2, '' ntpnppn,
            0 ppn,
            case when jp.id = 15 then pj.pph2 else null end as pph21,
            case when jp.id = 16 then pj.pph2 else null end as pph22,
            case when jp.id = 17 then pj.pph2 else null end as pph23,
            case when jp.id = 18 then pj.pph2 else null end as pph26,
            case when jp.id = 19 then pj.pph2 else null end as pph4,
            case when jp.id = 20 then pj.pph2 else null end as pph
            from strukrealisasi_t sr
            inner join spjtopanjar_t spj on spj.objectspjfk = sr.norec
            inner join panjar_t pj on pj.norec = spj.objectpanjarfk
            inner join jenispajak_m jp on jp.id = pj.objectjenispphfk2
            left join rekanan_m rk on rk.id = sr.rekananfk
            inner join asalproduk_m ap on ap.id = sr.objectasalprodukfk
            where sr.statusenabled = true
            and sr.kdprofile = 30
            and pj.statusenabled = true
            and pj.kdprofile = 30
            and sr.status = 'Sudah Diverifikasi'
            $qbulan
            $qtahun
            $qasalproduk
        ) as x"));

        $lalu = DB::select(DB::raw("select coalesce(sum(ppn), 0) ppn, coalesce(sum(pph21), 0) pph21, coalesce(sum(pph22), 0) pph22, 
        coalesce(sum(pph23), 0) pph23, coalesce(sum(pph26), 0) pph26, coalesce(sum(pph4), 0) pph4, 
        coalesce(sum(pph), 0) pph
        from(
            select distinct sr.norec, sr.tglrealisasi::varchar, sr.totalbelanja, rk.namarekanan, rk.npwp, rk.alamatlengkap,
            'ID BILLING ' || jp.namaexternal billpph, 'ID BILLING PPN' billppn, pp.idbillpph, pp.idbillppn,
            pp.ntpnpph, pp.ntpnppn,
            ppn.ppn ppn,
            case when jp.id = 15 then pp.pph else null end as pph21,
            case when jp.id = 16 then pp.pph else null end as pph22,
            case when jp.id = 17 then pp.pph else null end as pph23,
            case when jp.id = 18 then pp.pph else null end as pph26,
            case when jp.id = 19 then pp.pph else null end as pph4,
            case when jp.id = 20 then pp.pph else null end as pph
            from strukrealisasi_t sr
            inner join pemungutanpajak_t pp on pp.objectspjfk = sr.norec
            left join jenispajak_m jp on jp.id = pp.objectjenispphfk
            and jp.statusenabled = true
            and jp.kdprofile = 30
            left join pemungutanpajak_t ppn on pp.idbillpph = ppn.idbillppn
            and pp.ntpnpph = ppn.ntpnppn
            and ppn.statusenabled = true
            and ppn.kdprofile = 30
            left join rekanan_m rk on rk.id = sr.rekananfk
            inner join kegiatananggaran_m as dp on dp.id = sr.objectkegiatanfk
            inner join keteranganbelanja_t as kb on kb.objectkegiatanfk = dp.id
            inner join asalproduk_m ap on ap.id = sr.objectasalprodukfk
            inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
            where sr.statusenabled = true
            and sr.kdprofile = 30
            and pp.statusenabled = true
            and pp.kdprofile = 30
            and pp.objectjenispphfk is not null
            and sr.status = 'Sudah Diverifikasi'
            and extract('month' from sr.tglrealisasi) = '01'
            $qtahun
            $qasalproduk
            
            union all
            
            select distinct sr.norec, sr.tglrealisasi::varchar, sr.totalbelanja, rk.namarekanan, rk.npwp, rk.alamatlengkap,
            'ID BILLING ' || jp.namaexternal billpph, 'ID BILLING PPN' billppn, pj.idbillpph, pj.idbill idbillppn,
            pj.ntpnpph, pj.ntpn ntpnppn,
            pj.ppn ppn,
            case when jp.id = 15 then pj.pph else null end as pph21,
            case when jp.id = 16 then pj.pph else null end as pph22,
            case when jp.id = 17 then pj.pph else null end as pph23,
            case when jp.id = 18 then pj.pph else null end as pph26,
            case when jp.id = 19 then pj.pph else null end as pph4,
            case when jp.id = 20 then pj.pph else null end as pph
            from strukrealisasi_t sr
            inner join spjtopanjar_t spj on spj.objectspjfk = sr.norec
            inner join panjar_t pj on pj.norec = spj.objectpanjarfk
            inner join jenispajak_m jp on jp.id = pj.objectjenispphfk
            left join rekanan_m rk on rk.id = sr.rekananfk
            inner join asalproduk_m ap on ap.id = sr.objectasalprodukfk
            where sr.statusenabled = true
            and sr.kdprofile = 30
            and pj.statusenabled = true
            and pj.kdprofile = 30
            and sr.status = 'Sudah Diverifikasi'
            and extract('month' from sr.tglrealisasi) = '01'
            $qtahun
            $qasalproduk
            
            union all
            
            select distinct sr.norec, sr.tglrealisasi::varchar, sr.totalbelanja, rk.namarekanan, rk.npwp, rk.alamatlengkap,
            'ID BILLING ' || jp.namaexternal billpph, 'ID BILLING PPN' billppn, pj.idbillpph2, '' idbillppn,
            pj.ntpnpph2, '' ntpnppn,
            0 ppn,
            case when jp.id = 15 then pj.pph2 else null end as pph21,
            case when jp.id = 16 then pj.pph2 else null end as pph22,
            case when jp.id = 17 then pj.pph2 else null end as pph23,
            case when jp.id = 18 then pj.pph2 else null end as pph26,
            case when jp.id = 19 then pj.pph2 else null end as pph4,
            case when jp.id = 20 then pj.pph2 else null end as pph
            from strukrealisasi_t sr
            inner join spjtopanjar_t spj on spj.objectspjfk = sr.norec
            inner join panjar_t pj on pj.norec = spj.objectpanjarfk
            inner join jenispajak_m jp on jp.id = pj.objectjenispphfk2
            left join rekanan_m rk on rk.id = sr.rekananfk
            inner join asalproduk_m ap on ap.id = sr.objectasalprodukfk
            where sr.statusenabled = true
            and sr.kdprofile = 30
            and pj.statusenabled = true
            and pj.kdprofile = 30
            and sr.status = 'Sudah Diverifikasi'
            and extract('month' from sr.tglrealisasi) = '01'
            $qtahun
            $qasalproduk
        ) as x"));

        $pageWidth = 950;
        //return $this->respond($result);
        return view('report.keuangan.cetakbukupajak',compact('data', 'pageWidth', 'lalu', 'sumberdana', 'tanggalcetak', 'bulan', 'tahunjudul'));
    }

