            $periode = 'DESEMBER';
        }

        $qtahun  = '';
        if (isset($request['tahun']) && $request['tahun'] != "" && $request['tahun'] != "undefined") {
            $qtahun =  " and extract(year from tglbku) =  '" . $request['tahun']."'";
        }

        $qbulan  = '';
        if (isset($request['bulan']) && $request['bulan'] != "" && $request['bulan'] != "undefined") {
            $qbulan =  " and extract(month from tglbku) =  '" . $request['bulan']."'";
        }

        $qsumberdana  = '';
        if (isset($request['sumberdana']) && $request['sumberdana'] != "" && $request['sumberdana'] != "undefined") {
            $qsumberdana =  " and ap.id = " . $request['sumberdana'];
        }

        $data = DB::select(DB::raw("select sum(bku.penerimaan) penerimaan, sum(bku.pengeluaran) pengeluaran
        from bukukasumum_t bku
        left join asalproduk_m ap on ap.id = bku.objectasalprodukfk
        where bku.kdprofile = 30
        and bku.statusenabled = true 
        $qsumberdana
        $qbulan
        $qtahun"));

        $akhirbulanini = DB::select(DB::raw("SELECT (date_trunc('month', '$tahunjudul-$bulan-01'::date) + interval '1 month' - interval '1 day')::date
        AS end_of_month"));

        $indakhirbulanini = $this->tanggal_indonesia(date('Y-m-d',strtotime($akhirbulanini[0]->end_of_month)));

        $akhirbulanlalu = DB::select(DB::raw("SELECT (date_trunc('month', '$tahunjudul-$bulan-01'::date) - interval '1 day')::date
        AS end_of_month_past;"));

        $indakhirbulanlalu = $this->tanggal_indonesia(date('Y-m-d',strtotime($akhirbulanlalu[0]->end_of_month_past)));
        
        $pageWidth = 950;
        //return $this->respond($result);
        return view('report.keuangan.penutupankas',compact('data', 'pageWidth', 'tahunjudul', 'tanggalcetak', 'periode', 'indakhirbulanlalu', 'indakhirbulanini'));
    }

    public function CetakBukuPanjar(Request $request){
        $tahunjudul = $request['tahunpanjar'];
        $tanggalcetak = $this->tanggal_indonesia(date('Y-m-d',strtotime($request['tglcetakpanjar'])));
        // $bawal = date('F', mktime(0, 0, 0, $request['bulanawal'], 10));
        // $bakhir = date('F', mktime(0, 0, 0, $request['bulanakhir'], 10));
        $settingrba = DB::select(DB::raw("
        select pg.namalengkap, pg.nippns from settinganggaran_t sa
        inner join pegawai_m pg on pg.id = sa.objectkepalabludfk
        where sa.statusenabled = true
        "));
        $bulan = $request['bulanpanjar'];


        if($bulan == '01'){
            $periode = 'JANUARI';
        }
        else if($bulan == '02'){
            $periode = 'FEBRUARI';
        }
        else if($bulan == '03'){
            $periode = 'MARET';
        }
        else if($bulan == '04'){
            $periode = 'APRIL';
        }
        else if($bulan == '05'){
            $periode = 'MEI';
        }
        else if($bulan == '06'){
            $periode = 'JUNI';
        }
        else if($bulan == '07'){
            $periode = 'JULI';
        }
        else if($bulan == '08'){
            $periode = 'AGUSTUS';
        }
        else if($bulan == '09'){
            $periode = 'SEPTEMBER';
        }
        else if($bulan == '10'){
            $periode = 'OKTOBER';
        }
        else if($bulan == '11'){
            $periode = 'NOVEMBER';
        }
        else if($bulan == '12'){
            $periode = 'DESEMBER';
        }

        $qtahun  = '';
        if (isset($request['tahunpanjar']) && $request['tahunpanjar'] != "" && $request['tahunpanjar'] != "undefined") {
            $qtahun =  " and extract(year from tglbku) = '" . $request['tahunpanjar']."'";
        }

        $qbulan  = '';
        if (isset($request['bulanpanjar']) && $request['bulanpanjar'] != "" && $request['bulanpanjar'] != "undefined") {
            $qbulan =  " and extract(month from tglbku) between '01' and  '" . $request['bulanpanjar']."'";
        }

        // select * from(
            //     select 0 nourut, '' nobku, '' tgl, 'Saldo Awal Bulan' uraianbku, (saldo-penerimaan+pengeluaran) penerimaan, 0 pengeluaran, 0 saldo
        //     from bukukasumum_t
        //     where kdprofile = 30
        //     and statusenabled = true
        //     $qbulan
        //     $qtahun
        //     and objectjenisbuktifk = 3
        //     order by tglbku asc limit 1
        // ) as x
    
        // union all
    
        // $data = DB::select(DB::raw("select * from(select ROW_NUMBER ( ) OVER ( ORDER BY bku.nobku ) nourut, bku.nobku, to_char(bku.tglbku::date, 'DD-MM-YYYY') tgl, bku.uraianbku, bku.penerimaan, bku.pengeluaran, 0 saldo
        // from bukukasumum_tx bku
        // where bku.kdprofile = 30
        // and bku.statusenabled = true
        // $qbulan
        // $qtahun
        // and bku.objectjenisbuktifk in (3,7)) as x ORDER BY nourut"));

        $data = DB::select(DB::raw("SELECT ROW_NUMBER
        ( ) OVER ( ORDER BY x.nobku ) nourut,
        x.nobku,
        x.tgl,
        x.uraianbku,
        x.penerimaan,
        x.pengeluaran,
        x.saldo 
    FROM
        (
        select 
            bku.nobku,
            to_char( bku.tglbku :: DATE, 'DD-MM-YYYY' ) tgl,
            bku.uraianbku,
            bku.penerimaan,
            bku.pengeluaran,
            0 saldo 
        FROM
            bukukasumum_t bku 
        WHERE
            bku.kdprofile = 30 
            AND bku.statusenabled = TRUE             
            $qbulan
            $qtahun
            AND bku.objectjenisbuktifk IN ( 3, 7 ) UNION
        SELECT
            bku.nobku,
            to_char( bku.tglbku :: DATE, 'DD-MM-YYYY' ) tgl,
            bku.uraianbku,
            spj.jumlahdibayarverif AS penerimaan,
            0 pengeluaran,
            0 saldo 
        FROM
            bukukasumum_t bku
            INNER JOIN strukrealisasi_t spj ON bku.norec = spj.objectbkufk
            INNER JOIN spjtopanjar_t stp ON spj.norec = stp.objectspjfk 
            where 
            bku.kdprofile = 30 
            AND bku.statusenabled = TRUE            
            $qbulan
            $qtahun
            AND bku.statusenabled = TRUE 
            AND spj.statusenabled = TRUE
            AND stp.statusenabled = TRUE 
        ) AS x 
    ORDER BY
        nourut"));

        $saldoakhir = 0;

        foreach($data as $row){
            $saldoakhir = $saldoakhir - $row->penerimaan + $row->pengeluaran; 
            $row->saldo = $saldoakhir;
        }

        //var_dump($data);

        // $result = array(
        //     'daftar' => $data,
        //     'message' => 'as@epic',
        // );

        // return $this->respond($result);

        $pageWidth = 950;
        //return $this->respond($result);
        return view('report.keuangan.cetakbukupanjar',compact('data', 'pageWidth', 'tahunjudul', 'tanggalcetak', 'periode','settingrba'));
    }

