                        inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
                        left join strukrealisasi_t sr on km.id = sr.objectkegiatanfk
                        and sr.kdprofile = 30 and sr.statusenabled = true
                        and sr.status = 'Sudah Diverifikasi'
