        INNER JOIN mataanggaran_m ma2 ON split_part( ma.kodemataanggaran, '.', 1 )||'.'||split_part( ma.kodemataanggaran, '.', 2 ) ||'.'||split_part( ma.kodemataanggaran, '.', 3 )= ma2.kodemataanggaran
