                    union all
        
                    select ta.id, ta.tahap, mat.kodemataanggaran, mat.namamataanggaran keterangan, sum(kb.subtotal) subtotal
                    from kegiatananggaran_m km
                    inner join kegiatananggaran_m kms on km.kode ilike kms.kode || '%' and kms.div = 3
