            inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
            inner join mataanggaran_m mat on ma.kodemataanggaran ilike mat.kodemataanggaran || '%'
            and 
            case 
                when mat.kodemataanggaran ilike 'I%' then char_length(mat.kodemataanggaran) = 5
                when mat.kodemataanggaran ilike 'II%' then char_length(mat.kodemataanggaran) = 4
                when mat.kodemataanggaran ilike 'III%' then char_length(mat.kodemataanggaran) = 5
            end
            inner join tahapanggaran_m ta on ta.id = kb.objecttahapfk 
            where km.kdprofile = 30 and km.statusenabled = true
            and kms.kdprofile = 30 and kms.statusenabled = true
            and kmss.kdprofile = 30 and kmss.statusenabled = true
            and ma.kdprofile = 30 and ma.statusenabled = true
            and mat.kdprofile = 30 and mat.statusenabled = true
            and kb.kdprofile = 30 and kb.statusenabled = true
            $qterhadap
                                                    and km.tahun = '$tahun'
                                                    and ma.id in(
                                                            select ma.id
                                                            from kegiatananggaran_m km
                                                            inner join kegiatananggaran_m kms on km.kode ilike kms.kode || '%' and kms.div = 3
                                                            left join kegiatananggaran_m kmss on km.kode ilike kmss.kode || '%' and kmss.div = 2
                                                            inner join keteranganbelanja_t kb on kb.objectkegiatanfk = km.id
                                                            inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
                                                            inner join mataanggaran_m mat on ma.kodemataanggaran ilike mat.kodemataanggaran || '%'
                                                            and 
                                                            case 
                                                                    when mat.kodemataanggaran ilike 'I%' then char_length(mat.kodemataanggaran) = 5
                                                                    when mat.kodemataanggaran ilike 'II%' then char_length(mat.kodemataanggaran) = 4
                                                                    when mat.kodemataanggaran ilike 'III%' then char_length(mat.kodemataanggaran) = 5
                                                            end
                                                            inner join tahapanggaran_m ta on ta.id = kb.objecttahapfk 
                                                            where km.kdprofile = 30 and km.statusenabled = true
                                                            and kms.kdprofile = 30 and kms.statusenabled = true
                                                            and kmss.kdprofile = 30 and kmss.statusenabled = true
                                                            and ma.kdprofile = 30 and ma.statusenabled = true
                                                            and mat.kdprofile = 30 and mat.statusenabled = true
                                                            and kb.kdprofile = 30 and kb.statusenabled = true
                                                            $qtahap
                                                            and km.tahun = '$tahun'
                                                            group by ma.id
                                                    )
            group by ta.id, ta.tahap, mat.kodemataanggaran, mat.namamataanggaran, kb.keteranganbelanja
        ) as x group by id, tahap, kodemataanggaran
        ) as y where y.kodemataanggaran not in('II', 'III') group by id, tahap, kodemataanggaran
                    ) as t on s.kodemataanggaran = t.kodemataanggaran
        )  as i"));

        $result = array(
            'data' => $sebelum,
            'message' => '@epic',
        );

        $pageWidth = 1200;
        return view('report.spj.cetakrekaptotalanggaransebelumsesudah',compact('sebelum','pageWidth', 'jumlah', 'itahap', 'tanggalcetak'));
    }

    public function CetakRBADetail(Request $request){
        $tahun = $request['tahun'];
        $tahap = $request['tahap'];
        $settingrba = DB::select(DB::raw("

        select sa.*, pg.reportdisplay as namalengkap, pg.nippns from settinganggaran_t sa

        inner join pegawai_m pg on pg.id = sa.objectkepalabludfk
        where sa.statusenabled = true
        "));
        $tanggalcetak = $this->tanggal_indonesia(date('Y-m-d',strtotime($request['tglcetak'])));

        $qtahap  = '';
        if (isset($request['tahap']) && $request['tahap'] != "" && $request['tahap'] != "undefined") {
            $qtahap =  ' and kb.objecttahapfk =  ' . $request['tahap'];
        }

        $itahap = DB::select(DB::raw("select id, tahap from tahapanggaran_m where id = $tahap"));

        $qsubsubkegiatan  = '';
        $subsubkegiatan  = '';
        if (isset($request['subsubkegiatan']) && $request['subsubkegiatan'] != "" && $request['subsubkegiatan'] != "undefined") {
            $qsubsubkegiatan =  ' and km.id =  ' . $request['subsubkegiatan'];
            $subsubkegiatan =  ' and dp.id =  ' . $request['subsubkegiatan'];
        }
        // edit split_part(dp.keterangan, '-', 2)
        $data = DB::select(DB::raw("select dp.tahun, dp.kode kodesubsubkegiatan, 
        dp.keterangan as keterangansubsubkegiatan,

        dp0.kode kodesubkegiatan, dp0.keterangan keterangansubkegiatan,
        dp3.kode kodekegiatan, dp3.keterangan keterangankegiatan,
        dp2.kode kodeprogram, dp2.keterangan keteranganprogram,
        dp1.kode kodeurusan, dp1.keterangan keteranganurusan, 
        dp.indikatormasuk, dp.indikatorkeluaran, dp.indikatorhasil, dp.targetmasuk, dp.targetkeluaran, dp.targethasil
        from kegiatananggaran_m as dp 
        inner join keteranganbelanja_t as kb on kb.objectkegiatanfk = dp.id 
        and kb.kdprofile = 30 and kb.statusenabled = true 
        inner join kegiatananggaran_m as dp3 on dp.kode ilike dp3.kode || '%' and dp3.div = 2
        and dp3.kdprofile = 30 and dp3.statusenabled = true 
        inner join kegiatananggaran_m as dp2 on dp3.kode ilike dp2.kode || '%' and dp2.div = 1
        and dp2.kdprofile = 30 and dp2.statusenabled = true 
        inner join kegiatananggaran_m as dp1 on dp2.kode ilike dp1.kode || '%' and dp1.div = 0
        and dp1.kdprofile = 30 and dp1.statusenabled = true 
        inner join kegiatananggaran_m as dp0 on dp.kode ilike dp0.kode || '%' and dp0.div = 3
        and dp0.kdprofile = 30 and dp0.statusenabled = true 
        where dp.tahun = '$tahun'
        $subsubkegiatan
        group by dp.tahun, dp.kode, dp.keterangan,
        dp0.kode, dp0.keterangan,
        dp3.kode, dp3.keterangan,
        dp2.kode, dp2.keterangan,
        dp1.kode, dp1.keterangan, 
        dp.indikatormasuk, dp.indikatorkeluaran, dp.indikatorhasil, dp.targetmasuk, dp.targetkeluaran, dp.targethasil"));     

        $sebelum = DB::select(DB::raw("
        select * from(select
        case 
            when kodemataanggaran = 'A' then 'I.A'
            when kodemataanggaran = 'B' then 'I.B'
        end as kodemataanggaran,
        case 
            when kodemataanggaran = 'A' then 'BIAYA PELAYANAN '
            when kodemataanggaran = 'B' then 'BIAYA UMUM DAN ADMINISTRASI'
        end as keterangan,
				id, tahap, jml, satuan, hargasatuan,
        case 
            when kodemataanggaran = 'A' then sum(subtotaljasalayanan)
            when kodemataanggaran = 'B' then sum(subtotaljasalayanan)
        end as subtotaljasalayanan,
		case 
            when kodemataanggaran = 'A' then sum(subtotalapbd)
            when kodemataanggaran = 'B' then sum(subtotalapbd)
        end as subtotalapbd,
        case 
        when kodemataanggaran ilike 'A' then sum(subtotaldak)
        when kodemataanggaran ilike 'B' then sum(subtotaldak)
        end as subtotaldak,			
        case 
        when kodemataanggaran ilike 'A' then sum(subtotaldanais)
        when kodemataanggaran ilike 'B' then sum(subtotaldanais)
        end as subtotaldanais,			
        case 
        when kodemataanggaran ilike 'A' then sum(subtotalsilpa)
        when kodemataanggaran ilike 'B' then sum(subtotalsilpa)
        end as subtotalsilpa, 

        2 as isRincian, 0 as len3, 0 as len4, 0 as nourut			

    from(
            select id, tahap, jml, satuan, hargasatuan,
            case 
                when kodemataanggaran ilike 'I.A.%' then 'A'
                when kodemataanggaran ilike 'I.B.%' then 'B'
            end as kodemataanggaran,
            case 
                when kodemataanggaran ilike 'I.A.%' then sum(subtotaljasalayanan)
                when kodemataanggaran ilike 'I.B.%' then sum(subtotaljasalayanan)
            end as subtotaljasalayanan,
						case 
                when kodemataanggaran ilike 'I.A.%' then sum(subtotalapbd)
                when kodemataanggaran ilike 'I.B.%' then sum(subtotalapbd)
            end as subtotalapbd,
            case 
            when kodemataanggaran ilike 'I.A.%' then sum(subtotaldak)
            when kodemataanggaran ilike 'I.B.%' then sum(subtotaldak)
            end as subtotaldak,			  
            case 
            when kodemataanggaran ilike 'I.A.%' then sum(subtotaldanais)
            when kodemataanggaran ilike 'I.B.%' then sum(subtotaldanais)
            end as subtotaldanais,			    
            case 
            when kodemataanggaran ilike 'I.A.%' then sum(subtotalsilpa)
            when kodemataanggaran ilike 'I.B.%' then sum(subtotalsilpa)
            end as subtotalsilpa,
            
            2 as isRincian, 0 as len3, 0 as len4, 0 as nourut
    
            from(
                        select ta.id, ta.tahap, mat.kodemataanggaran, mat.namamataanggaran, kb.keteranganbelanja, 0 jml, '' satuan, 0 hargasatuan, 
						case when ap.id = 18 then sum(kb.subtotal) else 0 end as subtotaljasalayanan,
						case when ap.id = 15 then sum(kb.subtotal) else 0 end as subtotalapbd,
						case when ap.id = 21 then sum(kb.subtotal) else 0 end as subtotaldak,
						case when ap.id = 2 then sum(kb.subtotal) else 0 end as subtotaldanais,
						case when ap.id = 4 then sum(kb.subtotal) else 0 end as subtotalsilpa,

                        2 as isRincian, 0 as len3, 0 as len4, 0 as nourut

                        from kegiatananggaran_m km
                        inner join kegiatananggaran_m kms on km.kode ilike kms.kode || '%' and kms.div = 3
                        left join kegiatananggaran_m kmss on km.kode ilike kmss.kode || '%' and kmss.div = 2
                        inner join keteranganbelanja_t kb on kb.objectkegiatanfk = km.id
                        inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
                        inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
                        inner join mataanggaran_m mat on ma.kodemataanggaran ilike mat.kodemataanggaran || '%'
                        and 
                        case 
                            when mat.kodemataanggaran ilike 'I%' then char_length(mat.kodemataanggaran) = 5
                            when mat.kodemataanggaran ilike 'II%' then char_length(mat.kodemataanggaran) = 4
                            when mat.kodemataanggaran ilike 'III%' then char_length(mat.kodemataanggaran) = 5
                        end
                        inner join tahapanggaran_m ta on ta.id = kb.objecttahapfk 
                        where km.kdprofile = 30 and km.statusenabled = true
                        and kms.kdprofile = 30 and kms.statusenabled = true
                        and kmss.kdprofile = 30 and kmss.statusenabled = true
                        and ma.kdprofile = 30 and ma.statusenabled = true
                        and mat.kdprofile = 30 and mat.statusenabled = true
                        and kb.kdprofile = 30 and kb.statusenabled = true
                        $qtahap
                        $qsubsubkegiatan
                        and km.tahun = '$tahun'
                        group by ap.id, ta.id, ta.tahap, mat.kodemataanggaran, mat.namamataanggaran, kb.keteranganbelanja
            ) as x group by id, tahap, jml, satuan, hargasatuan, kodemataanggaran
        ) as y where kodemataanggaran is not null 
        group by id, tahap, jml, satuan, hargasatuan, kodemataanggaran

        union all

        select kodemataanggaran, keterangan, id, tahap, jml, satuan, hargasatuan, sum(subtotaljasalayanan) subtotaljasalayanan,
				sum(subtotalapbd) subtotalapbd, sum(subtotaldak) subtotaldak, sum(subtotaldanais) subtotaldanais, sum(subtotalsilpa) subtotalsilpa, 
                
                3 as isRincian, LENGTH(split_part(kodemataanggaran, '.', 3)) len3, 0 as len4, 0 as nourut
				
                from(
					select mat.kodemataanggaran, mat.namamataanggaran keterangan,ta.id, ta.tahap, 0 jml, '' satuan, 0 hargasatuan, 
					case when ap.id = 18 then sum(kb.subtotal) else 0 end as subtotaljasalayanan,
                    case when ap.id = 15 then sum(kb.subtotal) else 0 end as subtotalapbd,
                    case when ap.id = 21 then sum(kb.subtotal) else 0 end as subtotaldak,
                    case when ap.id = 2 then sum(kb.subtotal) else 0 end as subtotaldanais,
                    case when ap.id = 4 then sum(kb.subtotal) else 0 end as subtotalsilpa,

                    3 as isRincian, LENGTH(split_part(mat.kodemataanggaran, '.', 3)) len3, 0 as len4, 0 as nourut

                    from kegiatananggaran_m km
					inner join kegiatananggaran_m kms on km.kode ilike kms.kode || '%' and kms.div = 3
					left join kegiatananggaran_m kmss on km.kode ilike kmss.kode || '%' and kmss.div = 2
					inner join keteranganbelanja_t kb on kb.objectkegiatanfk = km.id
					inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
					inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
					inner join mataanggaran_m mat on ma.kodemataanggaran ilike mat.kodemataanggaran || '%'
					and 
					case 
							when mat.kodemataanggaran ilike 'I%' then char_length(mat.kodemataanggaran) in(5,6)
							when mat.kodemataanggaran ilike 'II%' then char_length(mat.kodemataanggaran) in(6,7)
							when mat.kodemataanggaran ilike 'III%' then char_length(mat.kodemataanggaran) in(7,8)
					end
					inner join tahapanggaran_m ta on ta.id = kb.objecttahapfk 
					where km.kdprofile = 30 and km.statusenabled = true
					$qtahap
                    $qsubsubkegiatan
                    and km.tahun = '$tahun'
					and kms.kdprofile = 30 and kms.statusenabled = true
					and kmss.kdprofile = 30 and kmss.statusenabled = true
					and ma.kdprofile = 30 and ma.statusenabled = true
					and mat.kdprofile = 30 and mat.statusenabled = true
					and kb.kdprofile = 30 and kb.statusenabled = true
					group by ap.id, ta.id, ta.tahap, mat.kodemataanggaran, mat.namamataanggaran
				) as x group by kodemataanggaran, keterangan, id, tahap, jml, satuan, hargasatuan

        union all
				
				select kodemataanggaran, keterangan, id, tahap, jml, satuan, hargasatuan, sum(subtotaljasalayanan) subtotaljasalayanan,
				sum(subtotalapbd) subtotalapbd, sum(subtotaldak) subtotaldak, sum(subtotaldanais) subtotaldanais, sum(subtotalsilpa) subtotalsilpa, 
                
                1 as isRincian, 0 as len3, 0 as len4, 0 as nourut
				
                from(
					select mat.kodemataanggaran, mat.namamataanggaran keterangan, ta.id, ta.tahap, 0 jml, '' satuan, 0 hargasatuan, 
					case when ap.id = 18 then sum(kb.subtotal) else 0 end as subtotaljasalayanan,
                    case when ap.id = 15 then sum(kb.subtotal) else 0 end as subtotalapbd,
                    case when ap.id = 21 then sum(kb.subtotal) else 0 end as subtotaldak,
                    case when ap.id = 2 then sum(kb.subtotal) else 0 end as subtotaldanais,
                    case when ap.id = 4 then sum(kb.subtotal) else 0 end as subtotalsilpa,

                    1 as isRincian, 0 as len3, 0 as len4, 0 as nourut

                    from kegiatananggaran_m km
					inner join kegiatananggaran_m kms on km.kode ilike kms.kode || '%' and kms.div = 3
					left join kegiatananggaran_m kmss on km.kode ilike kmss.kode || '%' and kmss.div = 2
					inner join keteranganbelanja_t kb on kb.objectkegiatanfk = km.id
					inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
					inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
					inner join mataanggaran_m mat on ma.kodemataanggaran ilike mat.kodemataanggaran || '.' || '%'
					and 
					case 
							when mat.kodemataanggaran = 'I' then char_length(mat.kodemataanggaran) = 1
							when mat.kodemataanggaran = 'II' then char_length(mat.kodemataanggaran) = 2
							when mat.kodemataanggaran = 'III' then char_length(mat.kodemataanggaran) = 3
					end
					inner join tahapanggaran_m ta on ta.id = kb.objecttahapfk 
					where km.kdprofile = 30 and km.statusenabled = true
					$qtahap
                    $qsubsubkegiatan
                    and km.tahun = '$tahun'
					and kms.kdprofile = 30 and kms.statusenabled = true
					and kmss.kdprofile = 30 and kmss.statusenabled = true
					and ma.kdprofile = 30 and ma.statusenabled = true
					and mat.kdprofile = 30 and mat.statusenabled = true
					and kb.kdprofile = 30 and kb.statusenabled = true
					group by ap.id, ta.id, ta.tahap, mat.kodemataanggaran, mat.namamataanggaran
				) as x group by kodemataanggaran, keterangan, id, tahap, jml, satuan, hargasatuan

        union all
                
        SELECT zx.kodemataanggaran, zx.keterangan, zx.id, zx.tahap, zx.jml, zx.satuan, zx.hargasatuan, sum(zx.subtotaljasalayanan)as subtotaljasalayanan, sum(zx.subtotalapbd)as  subtotalapbd, sum(zx.subtotaldak)as subtotaldak, sum(zx.subtotaldanais)as subtotaldanais, sum(zx.subtotalsilpa)as subtotalsilpa,

        4 as isRincian, LENGTH(split_part(zx.kodemataanggaran, '.', 3)) len3, LENGTH(split_part(zx.kodemataanggaran, '.', 4)) len4, 0 as nourut

        FROM (
        select ma.kodemataanggaran, ma.namamataanggaran keterangan, ta.id, ta.tahap, 0 jml, '' satuan, 0 hargasatuan, 
				case when ap.id = 18 then sum(kb.subtotal) else 0 end as subtotaljasalayanan,
                case when ap.id = 15 then sum(kb.subtotal) else 0 end as subtotalapbd,
                case when ap.id = 21 then sum(kb.subtotal) else 0 end as subtotaldak,
                case when ap.id = 2 then sum(kb.subtotal) else 0 end as subtotaldanais,
                case when ap.id = 4 then sum(kb.subtotal) else 0 end as subtotalsilpa,

                4 as isRincian, LENGTH(split_part(ma.kodemataanggaran, '.', 3)) len3, LENGTH(split_part(ma.kodemataanggaran, '.', 4)) len4, 0 as nourut

from kegiatananggaran_m km
        inner join kegiatananggaran_m kms on km.kode ilike kms.kode || '%' and kms.div = 3
        left join kegiatananggaran_m kmss on km.kode ilike kmss.kode || '%' and kmss.div = 2
        inner join keteranganbelanja_t kb on kb.objectkegiatanfk = km.id
        inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
        inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
        inner join mataanggaran_m mat on ma.kodemataanggaran ilike mat.kodemataanggaran || '%'
        and 
        case 
            when mat.kodemataanggaran ilike 'I%' then char_length(mat.kodemataanggaran) = 5
            when mat.kodemataanggaran ilike 'II%' then char_length(mat.kodemataanggaran) = 4
            when mat.kodemataanggaran ilike 'III%' then char_length(mat.kodemataanggaran) = 5
        end
        inner join tahapanggaran_m ta on ta.id = kb.objecttahapfk 
        where km.kdprofile = 30 and km.statusenabled = true
        $qtahap
        $qsubsubkegiatan
        and km.tahun = '$tahun'
        and kms.kdprofile = 30 and kms.statusenabled = true
        and kmss.kdprofile = 30 and kmss.statusenabled = true
        and ma.kdprofile = 30 and ma.statusenabled = true
        and mat.kdprofile = 30 and mat.statusenabled = true
        and kb.kdprofile = 30 and kb.statusenabled = true
        group by ap.id, ta.id, ta.tahap, ma.kodemataanggaran, ma.namamataanggaran
            
)as zx
GROUP BY zx.kodemataanggaran, zx.keterangan, zx.id, zx.tahap, zx.jml, zx.satuan, zx.hargasatuan
				union ALL

				select ma.kodemataanggaran, kb.keteranganbelanja keterangan, ta.id, ta.tahap, kb.jml, kb.satuan, kb.hargasatuan,  
				case when ap.id = 18 then sum(kb.subtotal) else 0 end as subtotaljasalayanan,
                case when ap.id = 15 then sum(kb.subtotal) else 0 end as subtotalapbd,
                case when ap.id = 21 then sum(kb.subtotal) else 0 end as subtotaldak,
                case when ap.id = 2 then sum(kb.subtotal) else 0 end as subtotaldanais,
                case when ap.id = 4 then sum(kb.subtotal) else 0 end as subtotalsilpa,

                5 as isRincian, LENGTH(split_part(ma.kodemataanggaran, '.', 3)) len3, LENGTH(split_part(ma.kodemataanggaran, '.', 4)) len4, nourut

from kegiatananggaran_m km
        inner join kegiatananggaran_m kms on km.kode ilike kms.kode || '%' and kms.div = 3
        left join kegiatananggaran_m kmss on km.kode ilike kmss.kode || '%' and kmss.div = 2
        inner join keteranganbelanja_t kb on kb.objectkegiatanfk = km.id
        inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
        inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
        inner join mataanggaran_m mat on ma.kodemataanggaran ilike mat.kodemataanggaran || '%'
        and 
        case 
            when mat.kodemataanggaran ilike 'I%' then char_length(mat.kodemataanggaran) = 5
            when mat.kodemataanggaran ilike 'II%' then char_length(mat.kodemataanggaran) = 4
            when mat.kodemataanggaran ilike 'III%' then char_length(mat.kodemataanggaran) = 5
        end
        inner join tahapanggaran_m ta on ta.id = kb.objecttahapfk 
        where km.kdprofile = 30 and km.statusenabled = true
        $qtahap
        $qsubsubkegiatan
        and km.tahun = '$tahun'
        and kms.kdprofile = 30 and kms.statusenabled = true
        and kmss.kdprofile = 30 and kmss.statusenabled = true
        and ma.kdprofile = 30 and ma.statusenabled = true
        and mat.kdprofile = 30 and mat.statusenabled = true
        and kb.kdprofile = 30 and kb.statusenabled = true
        group by ap.id, ta.id, ta.tahap, kb.nourut, kb.jml, kb.satuan, kb.hargasatuan, kb.keteranganbelanja, ma.kodemataanggaran
        

		order by kodemataanggaran, jml, hargasatuan, satuan) as yyy
        order by split_part(yyy.kodemataanggaran, '.', 1),split_part(yyy.kodemataanggaran, '.', 2),len3,split_part(yyy.kodemataanggaran, '.', 3),len4,split_part(yyy.kodemataanggaran, '.', 4),CASE WHEN split_part(yyy.kodemataanggaran, '.', 5) <> '' THEN split_part(yyy.kodemataanggaran, '.', 5)::int ELSE 0 END
        , yyy.nourut, yyy.jml , yyy.hargasatuan, yyy.satuan
        "));

        $pageWidth = 950;
        return view('report.spj.cetakrbadetail',compact('sebelum','pageWidth', 'data', 'itahap', 'tanggalcetak','settingrba'));
    }

    public function CetakPendapatanPerubahan(Request $request){
        $tahun = $request['tahun'];
        $tanggalcetak = $this->tanggal_indonesia(date('Y-m-d',strtotime($request['tglcetak'])));    

        $qperubahan  = '';
        if (isset($request['perubahan']) && $request['perubahan'] != "" && $request['perubahan'] != "undefined" && $request['perubahan'] == 1) {
            $qperubahan =  ' and rp.isperubahan = true ';
        }
        if (isset($request['perubahan']) && $request['perubahan'] != "" && $request['perubahan'] != "undefined" && $request['perubahan'] == 2) {
            $qperubahan =  ' and rp.isperubahan = false ';
        }

        $data = DB::select(DB::raw("select 0 AS nourut, 'juga' bold, ap.namaexternal, 0 as jumlah, '' keterangan
        from asalproduk_m as ap 
        left join rincianpendapatan_t as rp on ap.id = rp.objectasalprodukfk
        and rp.kdprofile = 30
        and rp.statusenabled = true
        left join uraianpendapatan_m as up on up.id = rp.objecturaianpendapatanfk
        and up.kdprofile = 30
        and up.statusenabled = true
        where ap.kdprofile = 30
        and ap.statusenabled = true
        and rp.norec is null
    
        union all
    
        select RANK ( ) OVER ( order by ap.namaexternal ) AS nourut, 'iya' bold, ap.namaexternal, sum(rp.jumlahpendapatan) as jumlah, '' keterangan
        from rincianpendapatan_t as rp
        inner join asalproduk_m as ap on ap.id = rp.objectasalprodukfk
        inner join uraianpendapatan_m as up on up.id = rp.objecturaianpendapatanfk
        where rp.kdprofile = 30
        and rp.statusenabled = true
        and ap.kdprofile = 30
        and ap.statusenabled = true
        and up.kdprofile = 30
        and up.statusenabled = true
        and rp.tahun = '$tahun'
        $qperubahan
        group by ap.namaexternal
    
        union all
    
        select RANK ( ) OVER ( order by ap.namaexternal ) AS nourut, 'tidak' bold, rp.uraianpendapatan namaexternal, rp.jumlahpendapatan jumlah, rp.keterangan
        from rincianpendapatan_t as rp
        inner join asalproduk_m as ap on ap.id = rp.objectasalprodukfk
        inner join uraianpendapatan_m as up on up.id = rp.objecturaianpendapatanfk
        where rp.kdprofile = 30
        and rp.statusenabled = true
        and ap.kdprofile = 30
        and ap.statusenabled = true
        and up.kdprofile = 30
        and up.statusenabled = true
        and rp.tahun = '$tahun'
        $qperubahan
        order by nourut, bold"));     
        $settingrba = DB::select(DB::raw("
        select pg.namalengkap, pg.nippns from settinganggaran_t sa
        inner join pegawai_m pg on pg.id = sa.objectkepalabludfk
        where sa.statusenabled = true
        "));
        $pageWidth = 1200;
        return view('report.spj.cetakpendapatanperubahan',compact('pageWidth', 'data', 'tanggalcetak','settingrba'));
    }

    public function CetakRBADetailSebelumSesudah(Request $request)
    {
        $tahun = $request['tahun'];
        $kode = $request['kode'];
        $tanggalcetak = $this->tanggal_indonesia(date('Y-m-d',strtotime($request['tglcetak'])));        
        $settingrba = DB::select(DB::raw("
        select pg.namalengkap, pg.nippns from settinganggaran_t sa
        inner join pegawai_m pg on pg.id = sa.objectkepalabludfk
        where sa.statusenabled = true
        "));
        $dataterhadap = DB::select(DB::raw("
        SELECT DISTINCT ka.kode, ka.keterangan,ka.id, kb.objecttahapfk FROM keteranganbelanja_t kb 
        inner join kegiatananggaran_m ka on ka.id = kb.objectkegiatanfk
        where ka.tahun = '$tahun'  and ka.kode = '$kode' and kb.objecttahapfk = $request[terhadap] and ka.statusenabled = true and kb.statusenabled = true"));

        $qtahap  = '';
        if (isset($request['tahap']) && $request['tahap'] != "" && $request['tahap'] != "undefined") {
            $qtahap =  ' and kb.objecttahapfk =  ' . $request['tahap'];
        }

        $qterhadap  = '';
        if (isset($request['terhadap']) && $request['terhadap'] != "" && $request['terhadap'] != "undefined") {
            $qterhadap =  ' and kb.objecttahapfk =  ' . $request['terhadap'];
        }

        $qsubsubkegiatan  = '';
        $qsubsubkegiatansebelum  = '';
        $subsubkegiatansebelum  = '';
        $subsubkegiatan  = '';
        if (isset($request['subsubkegiatan']) && $request['subsubkegiatan'] != "" && $request['subsubkegiatan'] != "undefined") {
            $qsubsubkegiatan =  ' and km.id =  ' . $request['subsubkegiatan'];
            $qsubsubkegiatansebelum =  ' and km.id =  ' . $dataterhadap[0]->id;
            
            $subsubkegiatan =  ' and dp.id =  ' . $request['subsubkegiatan'];
            $subsubkegiatansebelum =  ' and dp.id =  ' . $dataterhadap[0]->id;
        }

        $qsama = '';
        if($request['terhadap'] == $request['tahap']){
            $qsama = 'and a.subtotaljasalayanan = b.subtotaljasalayanan
            and a.subtotalapbd = b.subtotalapbd
            and a.subtotaldak = b.subtotaldak
            and a.subtotaldanais = b.subtotaldanais
            and a.subtotalsilpa = b.subtotalsilpa
            and a.jml = b.jml
            and a.satuan = b.satuan
            and a.hargasatuan = b.hargasatuan';
        }
        

        $data = DB::select(DB::raw("select dp.tahun, dp.kode kodesubsubkegiatan, split_part(dp.keterangan, '-', 2) keterangansubsubkegiatan,

        dp0.kode kodesubkegiatan, dp0.keterangan keterangansubkegiatan,
        dp3.kode kodekegiatan, dp3.keterangan keterangankegiatan,
        dp2.kode kodeprogram, dp2.keterangan keteranganprogram,
        dp1.kode kodeurusan, dp1.keterangan keteranganurusan, 
        dp.indikatormasuk, dp.indikatorkeluaran, dp.indikatorhasil, dp.targetmasuk, dp.targetkeluaran, dp.targethasil
        from kegiatananggaran_m as dp 
        inner join keteranganbelanja_t as kb on kb.objectkegiatanfk = dp.id 
        and kb.kdprofile = 30 and kb.statusenabled = true 
        inner join kegiatananggaran_m as dp3 on dp.kode ilike dp3.kode || '%' and dp3.div = 2
        and dp3.kdprofile = 30 and dp3.statusenabled = true 
        inner join kegiatananggaran_m as dp2 on dp3.kode ilike dp2.kode || '%' and dp2.div = 1
        and dp2.kdprofile = 30 and dp2.statusenabled = true 
        inner join kegiatananggaran_m as dp1 on dp2.kode ilike dp1.kode || '%' and dp1.div = 0
        and dp1.kdprofile = 30 and dp1.statusenabled = true 
        inner join kegiatananggaran_m as dp0 on dp.kode ilike dp0.kode || '%' and dp0.div = 3
        and dp0.kdprofile = 30 and dp0.statusenabled = true 
        where dp.tahun = '$tahun'
        $subsubkegiatan
        group by dp.tahun, dp.kode, dp.keterangan,
        dp0.kode, dp0.keterangan,
        dp3.kode, dp3.keterangan,
        dp2.kode, dp2.keterangan,
        dp1.kode, dp1.keterangan, 
        dp.indikatormasuk, dp.indikatorkeluaran, dp.indikatorhasil, dp.targetmasuk, dp.targetkeluaran, dp.targethasil"));     

        $datasebelum = DB::select(DB::raw("select dp.tahun, dp.kode kodesubsubkegiatan, split_part(dp.keterangan, '-', 2) keterangansubsubkegiatan,

        dp0.kode kodesubkegiatan, dp0.keterangan keterangansubkegiatan,
        dp3.kode kodekegiatan, dp3.keterangan keterangankegiatan,
        dp2.kode kodeprogram, dp2.keterangan keteranganprogram,
        dp1.kode kodeurusan, dp1.keterangan keteranganurusan, 
        dp.indikatormasuk, dp.indikatorkeluaran, dp.indikatorhasil, dp.targetmasuk, dp.targetkeluaran, dp.targethasil
        from kegiatananggaran_m as dp 
        inner join keteranganbelanja_t as kb on kb.objectkegiatanfk = dp.id 
        and kb.kdprofile = 30 and kb.statusenabled = true 
        inner join kegiatananggaran_m as dp3 on dp.kode ilike dp3.kode || '%' and dp3.div = 2
        and dp3.kdprofile = 30 and dp3.statusenabled = true 
        inner join kegiatananggaran_m as dp2 on dp3.kode ilike dp2.kode || '%' and dp2.div = 1
        and dp2.kdprofile = 30 and dp2.statusenabled = true 
        inner join kegiatananggaran_m as dp1 on dp2.kode ilike dp1.kode || '%' and dp1.div = 0
        and dp1.kdprofile = 30 and dp1.statusenabled = true 
        inner join kegiatananggaran_m as dp0 on dp.kode ilike dp0.kode || '%' and dp0.div = 3
        and dp0.kdprofile = 30 and dp0.statusenabled = true 
        where dp.tahun = '$tahun'
        $subsubkegiatansebelum
        group by dp.tahun, dp.kode, dp.keterangan,
        dp0.kode, dp0.keterangan,
        dp3.kode, dp3.keterangan,
        dp2.kode, dp2.keterangan,
        dp1.kode, dp1.keterangan, 
        dp.indikatormasuk, dp.indikatorkeluaran, dp.indikatorhasil, dp.targetmasuk, dp.targetkeluaran, dp.targethasil"));     


        $sebelum = DB::select(DB::raw("
        select * from(select distinct a.*, b.jml jmlsetelah, b.satuan satuansetelah, b.hargasatuan hargasatuansetelah,
        b.subtotaljasalayanan subtotaljasalayanansetelah, b.subtotalapbd subtotalapbdsetelah, b.subtotaldak subtotaldaksetelah, b.subtotaldanais subtotaldanaissetelah, b.subtotalsilpa subtotalsilpasetelah FROM
        (

        select 
        case 
            when kodemataanggaran = 'A' then 'I.A'
            when kodemataanggaran = 'B' then 'I.B'
        end as kodemataanggaran,
        case 
            when kodemataanggaran = 'A' then 'BIAYA PELAYANAN '
            when kodemataanggaran = 'B' then 'BIAYA UMUM DAN ADMINISTRASI'
        end as keterangan,
                id, tahap, jml, satuan, hargasatuan,
        case 
            when kodemataanggaran = 'A' then sum(subtotaljasalayanan)
            when kodemataanggaran = 'B' then sum(subtotaljasalayanan)
        end as subtotaljasalayanan,
        case 
            when kodemataanggaran = 'A' then sum(subtotalapbd)
            when kodemataanggaran = 'B' then sum(subtotalapbd)
        end as subtotalapbd,

        case 
            when kodemataanggaran = 'A' then sum(subtotaldak)
            when kodemataanggaran = 'B' then sum(subtotaldak)
        end as subtotaldak,
        case 
            when kodemataanggaran = 'A' then sum(subtotaldanais)
            when kodemataanggaran = 'B' then sum(subtotaldanais)
        end as subtotaldanais,
        case 
            when kodemataanggaran = 'A' then sum(subtotalsilpa)
            when kodemataanggaran = 'B' then sum(subtotalsilpa)
        end as subtotalsilpa

        from(
            select id, tahap, jml, satuan, hargasatuan,
            case 
                when kodemataanggaran ilike 'I.A.%' then 'A'
                when kodemataanggaran ilike 'I.B.%' then 'B'
            end as kodemataanggaran,
            case 
                when kodemataanggaran ilike 'I.A.%' then sum(subtotaljasalayanan)
                when kodemataanggaran ilike 'I.B.%' then sum(subtotaljasalayanan)
            end as subtotaljasalayanan,
            case 
                when kodemataanggaran ilike 'I.A.%' then sum(subtotalapbd)
                when kodemataanggaran ilike 'I.B.%' then sum(subtotalapbd)
            end as subtotalapbd,

            case 
                when kodemataanggaran ilike 'I.A.%' then sum(subtotaldak)
                when kodemataanggaran ilike 'I.B.%' then sum(subtotaldak)
            end as subtotaldak,
            case 
                when kodemataanggaran ilike 'I.A.%' then sum(subtotaldanais)
                when kodemataanggaran ilike 'I.B.%' then sum(subtotaldanais)
            end as subtotaldanais,
            case 
                when kodemataanggaran ilike 'I.A.%' then sum(subtotalsilpa)
                when kodemataanggaran ilike 'I.B.%' then sum(subtotalsilpa)
            end as subtotalsilpa
            
            from(
                        select ta.id, ta.tahap, mat.kodemataanggaran, mat.namamataanggaran, kb.keteranganbelanja, 0 jml, '' satuan, 0 hargasatuan, 
                                                case when ap.id = 18 then sum(kb.subtotal) else 0 end as subtotaljasalayanan,

                                                case when ap.id = 15 then sum(kb.subtotal) else 0 end as subtotalapbd,
                                                case when ap.id = 21 then sum(kb.subtotal) else 0 end as subtotaldak,
                                                case when ap.id = 2 then sum(kb.subtotal) else 0 end as subtotaldanais,
                                                case when ap.id = 4 then sum(kb.subtotal) else 0 end as subtotalsilpa

                        from kegiatananggaran_m km
                        inner join kegiatananggaran_m kms on km.kode ilike kms.kode || '%' and kms.div = 3
                        left join kegiatananggaran_m kmss on km.kode ilike kmss.kode || '%' and kmss.div = 2
                        inner join keteranganbelanja_t kb on kb.objectkegiatanfk = km.id
                        inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
                        inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
                        inner join mataanggaran_m mat on ma.kodemataanggaran ilike mat.kodemataanggaran || '%'
                        and 
                        case 
                            when mat.kodemataanggaran ilike 'I%' then char_length(mat.kodemataanggaran) = 5
                            when mat.kodemataanggaran ilike 'II%' then char_length(mat.kodemataanggaran) = 4
                            when mat.kodemataanggaran ilike 'III%' then char_length(mat.kodemataanggaran) = 5
                        end
                        inner join tahapanggaran_m ta on ta.id = kb.objecttahapfk 
                        where km.kdprofile = 30 and km.statusenabled = true
                        and kms.kdprofile = 30 and kms.statusenabled = true
                        and kmss.kdprofile = 30 and kmss.statusenabled = true
                        and ma.kdprofile = 30 and ma.statusenabled = true
                        and mat.kdprofile = 30 and mat.statusenabled = true
                        and kb.kdprofile = 30 and kb.statusenabled = true
                        $qterhadap
                        $qsubsubkegiatansebelum
                        and km.tahun = '$tahun'
                        group by ap.id, ta.id, ta.tahap, mat.kodemataanggaran, mat.namamataanggaran, kb.keteranganbelanja
            ) as x group by id, tahap, jml, satuan, hargasatuan, kodemataanggaran
        ) as y where kodemataanggaran is not null 
        group by id, tahap, jml, satuan, hargasatuan, kodemataanggaran

        union all
                
                select kodemataanggaran, keterangan, id, tahap, jml, satuan, hargasatuan, sum(subtotaljasalayanan) subtotaljasalayanan,
                sum(subtotalapbd) subtotalapbd, sum(subtotaldak) subtotaldak, sum(subtotaldanais) subtotaldanais, sum(subtotalsilpa) subtotalsilpa
                from(
                    select mat.kodemataanggaran, mat.namamataanggaran keterangan,ta.id, ta.tahap, 0 jml, '' satuan, 0 hargasatuan, 
                    case when ap.id = 18 then sum(kb.subtotal) else 0 end as subtotaljasalayanan,

                                                case when ap.id = 15 then sum(kb.subtotal) else 0 end as subtotalapbd,
                                                case when ap.id = 21 then sum(kb.subtotal) else 0 end as subtotaldak,
                                                case when ap.id = 2 then sum(kb.subtotal) else 0 end as subtotaldanais,
                                                case when ap.id = 4 then sum(kb.subtotal) else 0 end as subtotalsilpa

                    from kegiatananggaran_m km
                    inner join kegiatananggaran_m kms on km.kode ilike kms.kode || '%' and kms.div = 3
                    left join kegiatananggaran_m kmss on km.kode ilike kmss.kode || '%' and kmss.div = 2
                    inner join keteranganbelanja_t kb on kb.objectkegiatanfk = km.id
                    inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
                    inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
                    inner join mataanggaran_m mat on ma.kodemataanggaran ilike mat.kodemataanggaran || '%'
                    and 
                    case 
                            when mat.kodemataanggaran ilike 'I%' then char_length(mat.kodemataanggaran) in(5,6)
                            when mat.kodemataanggaran ilike 'II%' then char_length(mat.kodemataanggaran) in(6,7)
                            when mat.kodemataanggaran ilike 'III%' then char_length(mat.kodemataanggaran) in(7,8)
                    end
                    inner join tahapanggaran_m ta on ta.id = kb.objecttahapfk 
                    where km.kdprofile = 30 and km.statusenabled = true
                    $qterhadap
                    $qsubsubkegiatansebelum
                    and km.tahun = '$tahun'
                    and kms.kdprofile = 30 and kms.statusenabled = true
                    and kmss.kdprofile = 30 and kmss.statusenabled = true
                    and ma.kdprofile = 30 and ma.statusenabled = true
                    and mat.kdprofile = 30 and mat.statusenabled = true
                    and kb.kdprofile = 30 and kb.statusenabled = true
                    group by ap.id, ta.id, ta.tahap, mat.kodemataanggaran, mat.namamataanggaran
                ) as x group by kodemataanggaran, keterangan, id, tahap, jml, satuan, hargasatuan

        union all
                
                select kodemataanggaran, keterangan, id, tahap, jml, satuan, hargasatuan, sum(subtotaljasalayanan) subtotaljasalayanan,
                sum(subtotalapbd) subtotalapbd, sum(subtotaldak) subtotaldak, sum(subtotaldanais) subtotaldanais, sum(subtotalsilpa) subtotalsilpa
                from(
                    select mat.kodemataanggaran, mat.namamataanggaran keterangan, ta.id, ta.tahap, 0 jml, '' satuan, 0 hargasatuan, 
                    case when ap.id = 18 then sum(kb.subtotal) else 0 end as subtotaljasalayanan,

                    case when ap.id = 15 then sum(kb.subtotal) else 0 end as subtotalapbd,
                    case when ap.id = 21 then sum(kb.subtotal) else 0 end as subtotaldak,
                    case when ap.id = 2 then sum(kb.subtotal) else 0 end as subtotaldanais,
                    case when ap.id = 4 then sum(kb.subtotal) else 0 end as subtotalsilpa

        from kegiatananggaran_m km
                    inner join kegiatananggaran_m kms on km.kode ilike kms.kode || '%' and kms.div = 3
                    left join kegiatananggaran_m kmss on km.kode ilike kmss.kode || '%' and kmss.div = 2
                    inner join keteranganbelanja_t kb on kb.objectkegiatanfk = km.id
                    inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
                    inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
                    inner join mataanggaran_m mat on ma.kodemataanggaran ilike mat.kodemataanggaran || '.' || '%'
                    and 
                    case 
                            when mat.kodemataanggaran = 'I' then char_length(mat.kodemataanggaran) = 1
                            when mat.kodemataanggaran = 'II' then char_length(mat.kodemataanggaran) = 2
                            when mat.kodemataanggaran = 'III' then char_length(mat.kodemataanggaran) = 3
                    end
                    inner join tahapanggaran_m ta on ta.id = kb.objecttahapfk 
                    where km.kdprofile = 30 and km.statusenabled = true
                    $qterhadap
                    $qsubsubkegiatansebelum
                    and km.tahun = '$tahun'
                    and kms.kdprofile = 30 and kms.statusenabled = true
                    and kmss.kdprofile = 30 and kmss.statusenabled = true
                    and ma.kdprofile = 30 and ma.statusenabled = true
                    and mat.kdprofile = 30 and mat.statusenabled = true
                    and kb.kdprofile = 30 and kb.statusenabled = true
                    group by ap.id, ta.id, ta.tahap, mat.kodemataanggaran, mat.namamataanggaran
                ) as x group by kodemataanggaran, keterangan, id, tahap, jml, satuan, hargasatuan

        union all

        select ma.kodemataanggaran, ma.namamataanggaran keterangan, ta.id, ta.tahap, 0 jml, '' satuan, 0 hargasatuan, 
                case when ap.id = 18 then sum(kb.subtotal) else 0 end as subtotaljasalayanan,

                case when ap.id = 15 then sum(kb.subtotal) else 0 end as subtotalapbd,
                case when ap.id = 21 then sum(kb.subtotal) else 0 end as subtotaldak,
                case when ap.id = 2 then sum(kb.subtotal) else 0 end as subtotaldanais,
                case when ap.id = 4 then sum(kb.subtotal) else 0 end as subtotalsilpa

        from kegiatananggaran_m km
        inner join kegiatananggaran_m kms on km.kode ilike kms.kode || '%' and kms.div = 3
        left join kegiatananggaran_m kmss on km.kode ilike kmss.kode || '%' and kmss.div = 2
        inner join keteranganbelanja_t kb on kb.objectkegiatanfk = km.id
        inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
        inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
        inner join mataanggaran_m mat on ma.kodemataanggaran ilike mat.kodemataanggaran || '%'
        and 
        case 
            when mat.kodemataanggaran ilike 'I%' then char_length(mat.kodemataanggaran) = 5
            when mat.kodemataanggaran ilike 'II%' then char_length(mat.kodemataanggaran) = 4
            when mat.kodemataanggaran ilike 'III%' then char_length(mat.kodemataanggaran) = 5
        end
        inner join tahapanggaran_m ta on ta.id = kb.objecttahapfk 
        where km.kdprofile = 30 and km.statusenabled = true
        $qterhadap
        $qsubsubkegiatansebelum
        and km.tahun = '$tahun'
        and kms.kdprofile = 30 and kms.statusenabled = true
        and kmss.kdprofile = 30 and kmss.statusenabled = true
        and ma.kdprofile = 30 and ma.statusenabled = true
        and mat.kdprofile = 30 and mat.statusenabled = true
        and kb.kdprofile = 30 and kb.statusenabled = true
        group by ap.id, ta.id, ta.tahap, ma.kodemataanggaran, ma.namamataanggaran

                union ALL

                select ma.kodemataanggaran, kb.keteranganbelanja keterangan, ta.id, ta.tahap, kb.jml, kb.satuan, kb.hargasatuan,  
                case when ap.id = 18 then sum(kb.subtotal) else 0 end as subtotaljasalayanan,

                                                case when ap.id = 15 then sum(kb.subtotal) else 0 end as subtotalapbd,
                                                case when ap.id = 21 then sum(kb.subtotal) else 0 end as subtotaldak,
                                                case when ap.id = 2 then sum(kb.subtotal) else 0 end as subtotaldanais,
                                                case when ap.id = 4 then sum(kb.subtotal) else 0 end as subtotalsilpa

        from kegiatananggaran_m km
        inner join kegiatananggaran_m kms on km.kode ilike kms.kode || '%' and kms.div = 3
        left join kegiatananggaran_m kmss on km.kode ilike kmss.kode || '%' and kmss.div = 2
        inner join keteranganbelanja_t kb on kb.objectkegiatanfk = km.id
        inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
        inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
        inner join mataanggaran_m mat on ma.kodemataanggaran ilike mat.kodemataanggaran || '%'
        and 
        case 
            when mat.kodemataanggaran ilike 'I%' then char_length(mat.kodemataanggaran) = 5
            when mat.kodemataanggaran ilike 'II%' then char_length(mat.kodemataanggaran) = 4
            when mat.kodemataanggaran ilike 'III%' then char_length(mat.kodemataanggaran) = 5
        end
        inner join tahapanggaran_m ta on ta.id = kb.objecttahapfk 
        where km.kdprofile = 30 and km.statusenabled = true
        $qterhadap
        $qsubsubkegiatansebelum
        and km.tahun = '$tahun'
        and kms.kdprofile = 30 and kms.statusenabled = true
        and kmss.kdprofile = 30 and kmss.statusenabled = true
        and ma.kdprofile = 30 and ma.statusenabled = true
        and mat.kdprofile = 30 and mat.statusenabled = true
        and kb.kdprofile = 30 and kb.statusenabled = true
        group by ap.id, ta.id, ta.tahap, kb.jml, kb.satuan, kb.hargasatuan, kb.keteranganbelanja, ma.kodemataanggaran
        

                order by kodemataanggaran, jml, hargasatuan, satuan


        ) as a
        inner join(


                -- b itu yg setelah
                select 
        case 
            when kodemataanggaran = 'A' then 'I.A'
            when kodemataanggaran = 'B' then 'I.B'
        end as kodemataanggaran,
        case 
            when kodemataanggaran = 'A' then 'BIAYA PELAYANAN '
            when kodemataanggaran = 'B' then 'BIAYA UMUM DAN ADMINISTRASI'
        end as keterangan,
                id, tahap, jml, satuan, hargasatuan,
        case 
            when kodemataanggaran = 'A' then sum(subtotaljasalayanan)
            when kodemataanggaran = 'B' then sum(subtotaljasalayanan)
        end as subtotaljasalayanan,
        case 
            when kodemataanggaran = 'A' then sum(subtotalapbd)
            when kodemataanggaran = 'B' then sum(subtotalapbd)
        end as subtotalapbd,

        case
            when kodemataanggaran = 'A' then sum(subtotaldak)
            when kodemataanggaran = 'B' then sum(subtotaldak)
        end as subtotaldak,
        case
            when kodemataanggaran = 'A' then sum(subtotaldanais)
            when kodemataanggaran = 'B' then sum(subtotaldanais)
        end as subtotaldanais,
        case
            when kodemataanggaran = 'A' then sum(subtotalsilpa)
            when kodemataanggaran = 'B' then sum(subtotalsilpa)
        end as subtotalsilpa

        from(
            select id, tahap, jml, satuan, hargasatuan,
            case 
                when kodemataanggaran ilike 'I.A.%' then 'A'
                when kodemataanggaran ilike 'I.B.%' then 'B'
            end as kodemataanggaran,
            case 
                when kodemataanggaran ilike 'I.A.%' then sum(subtotaljasalayanan)
                when kodemataanggaran ilike 'I.B.%' then sum(subtotaljasalayanan)
            end as subtotaljasalayanan,
            case 
                when kodemataanggaran ilike 'I.A.%' then sum(subtotalapbd)
                when kodemataanggaran ilike 'I.B.%' then sum(subtotalapbd)
            end as subtotalapbd,

            case 
                when kodemataanggaran ilike 'I.A.%' then sum(subtotaldak)
                when kodemataanggaran ilike 'I.B.%' then sum(subtotaldak)
            end as subtotaldak,
            case 
                when kodemataanggaran ilike 'I.A.%' then sum(subtotaldanais)
                when kodemataanggaran ilike 'I.B.%' then sum(subtotaldanais)
            end as subtotaldanais,
            case 
                when kodemataanggaran ilike 'I.A.%' then sum(subtotalsilpa)
                when kodemataanggaran ilike 'I.B.%' then sum(subtotalsilpa)
            end as subtotalsilpa
            
            from(
                        select ta.id, ta.tahap, mat.kodemataanggaran, mat.namamataanggaran, kb.keteranganbelanja, 0 jml, '' satuan, 0 hargasatuan, 
                                                case when ap.id = 18 then sum(kb.subtotal) else 0 end as subtotaljasalayanan,

                                                case when ap.id = 15 then sum(kb.subtotal) else 0 end as subtotalapbd,
                                                case when ap.id = 21 then sum(kb.subtotal) else 0 end as subtotaldak,
                                                case when ap.id = 2 then sum(kb.subtotal) else 0 end as subtotaldanais,
                                                case when ap.id = 4 then sum(kb.subtotal) else 0 end as subtotalsilpa

                        from kegiatananggaran_m km
                        inner join kegiatananggaran_m kms on km.kode ilike kms.kode || '%' and kms.div = 3
                        left join kegiatananggaran_m kmss on km.kode ilike kmss.kode || '%' and kmss.div = 2
                        inner join keteranganbelanja_t kb on kb.objectkegiatanfk = km.id
                        inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
                        inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
                        inner join mataanggaran_m mat on ma.kodemataanggaran ilike mat.kodemataanggaran || '%'
                        and 
                        case 
                            when mat.kodemataanggaran ilike 'I%' then char_length(mat.kodemataanggaran) = 5
                            when mat.kodemataanggaran ilike 'II%' then char_length(mat.kodemataanggaran) = 4
                            when mat.kodemataanggaran ilike 'III%' then char_length(mat.kodemataanggaran) = 5
                        end
                        inner join tahapanggaran_m ta on ta.id = kb.objecttahapfk 
                        where km.kdprofile = 30 and km.statusenabled = true
                        and kms.kdprofile = 30 and kms.statusenabled = true
                        and kmss.kdprofile = 30 and kmss.statusenabled = true
                        and ma.kdprofile = 30 and ma.statusenabled = true
                        and mat.kdprofile = 30 and mat.statusenabled = true
                        and kb.kdprofile = 30 and kb.statusenabled = true
                        $qtahap
                        $qsubsubkegiatan
                        and km.tahun = '$tahun'
                        group by ap.id, ta.id, ta.tahap, mat.kodemataanggaran, mat.namamataanggaran, kb.keteranganbelanja
            ) as x group by id, tahap, jml, satuan, hargasatuan, kodemataanggaran
        ) as y where kodemataanggaran is not null 
        group by id, tahap, jml, satuan, hargasatuan, kodemataanggaran

        union all
                
                select kodemataanggaran, keterangan, id, tahap, jml, satuan, hargasatuan, sum(subtotaljasalayanan) subtotaljasalayanan,
                sum(subtotalapbd) subtotalapbd, sum(subtotaldak) subtotaldak, sum(subtotaldanais) subtotaldanais, sum(subtotalsilpa) subtotalsilpa
                from(
                    select mat.kodemataanggaran, mat.namamataanggaran keterangan,ta.id, ta.tahap, 0 jml, '' satuan, 0 hargasatuan, 
                    case when ap.id = 18 then sum(kb.subtotal) else 0 end as subtotaljasalayanan,

                                                case when ap.id = 15 then sum(kb.subtotal) else 0 end as subtotalapbd,
                                                case when ap.id = 21 then sum(kb.subtotal) else 0 end as subtotaldak,
                                                case when ap.id = 2 then sum(kb.subtotal) else 0 end as subtotaldanais,
                                                case when ap.id = 4 then sum(kb.subtotal) else 0 end as subtotalsilpa

                    from kegiatananggaran_m km
                    inner join kegiatananggaran_m kms on km.kode ilike kms.kode || '%' and kms.div = 3
                    left join kegiatananggaran_m kmss on km.kode ilike kmss.kode || '%' and kmss.div = 2
                    inner join keteranganbelanja_t kb on kb.objectkegiatanfk = km.id
                    inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
                    inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
                    inner join mataanggaran_m mat on ma.kodemataanggaran ilike mat.kodemataanggaran || '%'
                    and 
                    case 
                            when mat.kodemataanggaran ilike 'I%' then char_length(mat.kodemataanggaran) in(5,6)
                            when mat.kodemataanggaran ilike 'II%' then char_length(mat.kodemataanggaran) in(6,7)
                            when mat.kodemataanggaran ilike 'III%' then char_length(mat.kodemataanggaran) in(7,8)
                    end
                    inner join tahapanggaran_m ta on ta.id = kb.objecttahapfk 
                    where km.kdprofile = 30 and km.statusenabled = true
                    $qtahap
                        $qsubsubkegiatan
                        and km.tahun = '$tahun'
                    and kms.kdprofile = 30 and kms.statusenabled = true
                    and kmss.kdprofile = 30 and kmss.statusenabled = true
                    and ma.kdprofile = 30 and ma.statusenabled = true
                    and mat.kdprofile = 30 and mat.statusenabled = true
                    and kb.kdprofile = 30 and kb.statusenabled = true
                    group by ap.id, ta.id, ta.tahap, mat.kodemataanggaran, mat.namamataanggaran
                ) as x group by kodemataanggaran, keterangan, id, tahap, jml, satuan, hargasatuan

        union all
                
                select kodemataanggaran, keterangan, id, tahap, jml, satuan, hargasatuan, sum(subtotaljasalayanan) subtotaljasalayanan,
                sum(subtotalapbd) subtotalapbd, sum(subtotaldak) subtotaldak, sum(subtotaldanais) subtotaldanais, sum(subtotalsilpa) subtotalsilpa
                from(
                    select mat.kodemataanggaran, mat.namamataanggaran keterangan, ta.id, ta.tahap, 0 jml, '' satuan, 0 hargasatuan, 
                    case when ap.id = 18 then sum(kb.subtotal) else 0 end as subtotaljasalayanan,

                    case when ap.id = 15 then sum(kb.subtotal) else 0 end as subtotalapbd,
                    case when ap.id = 21 then sum(kb.subtotal) else 0 end as subtotaldak,
                    case when ap.id = 2 then sum(kb.subtotal) else 0 end as subtotaldanais,
                    case when ap.id = 4 then sum(kb.subtotal) else 0 end as subtotalsilpa

        from kegiatananggaran_m km
                    inner join kegiatananggaran_m kms on km.kode ilike kms.kode || '%' and kms.div = 3
                    left join kegiatananggaran_m kmss on km.kode ilike kmss.kode || '%' and kmss.div = 2
                    inner join keteranganbelanja_t kb on kb.objectkegiatanfk = km.id
                    inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
                    inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
                    inner join mataanggaran_m mat on ma.kodemataanggaran ilike mat.kodemataanggaran || '.' || '%'
                    and 
                    case 
                            when mat.kodemataanggaran = 'I' then char_length(mat.kodemataanggaran) = 1
                            when mat.kodemataanggaran = 'II' then char_length(mat.kodemataanggaran) = 2
                            when mat.kodemataanggaran = 'III' then char_length(mat.kodemataanggaran) = 3
                    end
                    inner join tahapanggaran_m ta on ta.id = kb.objecttahapfk 
                    where km.kdprofile = 30 and km.statusenabled = true
                    $qtahap
                        $qsubsubkegiatan
                        and km.tahun = '$tahun'
                    and kms.kdprofile = 30 and kms.statusenabled = true
                    and kmss.kdprofile = 30 and kmss.statusenabled = true
                    and ma.kdprofile = 30 and ma.statusenabled = true
                    and mat.kdprofile = 30 and mat.statusenabled = true
                    and kb.kdprofile = 30 and kb.statusenabled = true
                    group by ap.id, ta.id, ta.tahap, mat.kodemataanggaran, mat.namamataanggaran
                ) as x group by kodemataanggaran, keterangan, id, tahap, jml, satuan, hargasatuan

        union all

        select ma.kodemataanggaran, ma.namamataanggaran keterangan, ta.id, ta.tahap, 0 jml, '' satuan, 0 hargasatuan, 
                case when ap.id = 18 then sum(kb.subtotal) else 0 end as subtotaljasalayanan,

                case when ap.id = 15 then sum(kb.subtotal) else 0 end as subtotalapbd,
                case when ap.id = 21 then sum(kb.subtotal) else 0 end as subtotaldak,
                case when ap.id = 2 then sum(kb.subtotal) else 0 end as subtotaldanais,
                case when ap.id = 4 then sum(kb.subtotal) else 0 end as subtotalsilpa

        from kegiatananggaran_m km
        inner join kegiatananggaran_m kms on km.kode ilike kms.kode || '%' and kms.div = 3
        left join kegiatananggaran_m kmss on km.kode ilike kmss.kode || '%' and kmss.div = 2
        inner join keteranganbelanja_t kb on kb.objectkegiatanfk = km.id
        inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
        inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
        inner join mataanggaran_m mat on ma.kodemataanggaran ilike mat.kodemataanggaran || '%'
        and 
        case 
            when mat.kodemataanggaran ilike 'I%' then char_length(mat.kodemataanggaran) = 5
            when mat.kodemataanggaran ilike 'II%' then char_length(mat.kodemataanggaran) = 4
            when mat.kodemataanggaran ilike 'III%' then char_length(mat.kodemataanggaran) = 5
        end
        inner join tahapanggaran_m ta on ta.id = kb.objecttahapfk 
        where km.kdprofile = 30 and km.statusenabled = true
        $qtahap
                        $qsubsubkegiatan
                        and km.tahun = '$tahun'
        and kms.kdprofile = 30 and kms.statusenabled = true
        and kmss.kdprofile = 30 and kmss.statusenabled = true
        and ma.kdprofile = 30 and ma.statusenabled = true
        and mat.kdprofile = 30 and mat.statusenabled = true
        and kb.kdprofile = 30 and kb.statusenabled = true
        group by ap.id, ta.id, ta.tahap, ma.kodemataanggaran, ma.namamataanggaran

                union ALL

                select ma.kodemataanggaran, kb.keteranganbelanja keterangan, ta.id, ta.tahap, kb.jml, kb.satuan, kb.hargasatuan,  
                case when ap.id = 18 then sum(kb.subtotal) else 0 end as subtotaljasalayanan,

                                                case when ap.id = 15 then sum(kb.subtotal) else 0 end as subtotalapbd,
                                                case when ap.id = 21 then sum(kb.subtotal) else 0 end as subtotaldak,
                                                case when ap.id = 2 then sum(kb.subtotal) else 0 end as subtotaldanais,
                                                case when ap.id = 4 then sum(kb.subtotal) else 0 end as subtotalsilpa                                                
        from kegiatananggaran_m km
        inner join kegiatananggaran_m kms on km.kode ilike kms.kode || '%' and kms.div = 3
        left join kegiatananggaran_m kmss on km.kode ilike kmss.kode || '%' and kmss.div = 2
        inner join keteranganbelanja_t kb on kb.objectkegiatanfk = km.id
        inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
        inner join mataanggaran_m ma on ma.id = kb.objectmataanggaranfk
        inner join mataanggaran_m mat on ma.kodemataanggaran ilike mat.kodemataanggaran || '%'
        and 
        case 
            when mat.kodemataanggaran ilike 'I%' then char_length(mat.kodemataanggaran) = 5
            when mat.kodemataanggaran ilike 'II%' then char_length(mat.kodemataanggaran) = 4
            when mat.kodemataanggaran ilike 'III%' then char_length(mat.kodemataanggaran) = 5
        end
        inner join tahapanggaran_m ta on ta.id = kb.objecttahapfk 
        where km.kdprofile = 30 and km.statusenabled = true
        $qtahap
                        $qsubsubkegiatan
                        and km.tahun = '$tahun'
        and kms.kdprofile = 30 and kms.statusenabled = true
        and kmss.kdprofile = 30 and kmss.statusenabled = true
        and ma.kdprofile = 30 and ma.statusenabled = true
        and mat.kdprofile = 30 and mat.statusenabled = true
        and kb.kdprofile = 30 and kb.statusenabled = true
        group by ap.id, ta.id, ta.tahap, kb.jml, kb.satuan, kb.hargasatuan, kb.keteranganbelanja, ma.kodemataanggaran
        

        order by kodemataanggaran, jml, hargasatuan, satuan

        ) as b on a.kodemataanggaran = b.kodemataanggaran and a.keterangan = b.keterangan
        $qsama) as yyy
        order by split_part(yyy.kodemataanggaran, '.', 1),split_part(yyy.kodemataanggaran, '.', 2),split_part(yyy.kodemataanggaran, '.', 3),split_part(yyy.kodemataanggaran, '.', 4),CASE WHEN split_part(yyy.kodemataanggaran, '.', 5) <> '' THEN split_part(yyy.kodemataanggaran, '.', 5)::int ELSE 0 END,
        yyy.kodemataanggaran, yyy.jml, yyy.hargasatuan, yyy.satuan
        "));

        $itahap = DB::select(DB::raw("select id, tahap from tahapanggaran_m where id = $request[tahap]"));
        $pageWidth = 950;
        return view('report.spj.cetakrbadetailsebelumsesudah',compact('sebelum','pageWidth', 'data', 'tanggalcetak','itahap','datasebelum','settingrba'));    
    }
    
    public function CetakSKNapza(Request $request)
    {   
        $norec = $request['emr'];
        $noemr = $request['noemr'];
        $kdProfile = (int) $request['kdprofile'];
        $emrfk = $request['emfk'];
        $data = DB::select(DB::raw("
            SELECT
                epd.emrdfk,
                epd.emrfk,
                ep.noemr,
                ed.TYPE,
                pa.namapasien,
                pa.tgllahir,
                pa.nohp,
                pa.nocm,
                ep.jeniskelamin,
                ep.umur,
                al.alamatlengkap,
                ep.noregistrasifk as noregistrasi,
                epd.value,ep.namaruangan,epd.tgl,
                pg.namalengkap as namadokter
            FROM
                emrpasien_t AS ep
                INNER JOIN emrpasiend_t AS epd ON ep.noemr = epd.emrpasienfk
                INNER JOIN emrd_t AS ed ON epd.emrdfk = ed.ID
                    INNER JOIN antrianpasiendiperiksa_t AS pd ON pd.norec = ep.norec_apd
                left JOIN pegawai_m AS pg ON pg.id = pd.objectpegawaifk
                left JOIN pasien_m as pa on ep.nocm =  pa.nocm
                left JOIN alamat_m as al on pa.id = al.nocmfk
            WHERE
                ep.norec = '".$request['emr']."'
                AND ep.kdprofile = ".$kdProfile." 
                AND epd.statusenabled = TRUE 
                and epd.emrfk = '".$request['emrfk']."'
            ORDER BY
                ed.nourut
        "));
        
        $profile = Profile::where('id',$request['kdprofile'])->first();

        foreach ($data as $z){
            if (isset($z->tgllahir) ||isset($z->tgl)){
                $z->tgllahir=$this->tanggal_indonesia(date('Y-m-d',strtotime($z->tgllahir)));
                $z->tgl=$this->tanggal_indonesia(date('Y-m-d',strtotime($z->tgl)));
            }
            
        }
        // $pageWidth = 950;

        $res['profile'] = Profile::where('id',$request['kdprofile'])->first();
        $res['d'] = $data;
        $item =[];   
        $item2 = [];
        
        foreach( $res['d'] as $items){
            if($items->type  ==  "textbox" ||$items->type  ==  "textarea"  ){
                $item[$items->emrdfk] =  $items->value;
            }
            if($items->type  ==  "datetime"){
                $item[$items->emrdfk] = $this->tanggal_indonesia(date('Y-m-d',strtotime( $items->value))) ;
            }
            if($items->type  ==  "time"){
                $item[$items->emrdfk] = date('H:i',strtotime( $items->value));
            }
            if($items->type  ==  "date"){
                $item[$items->emrdfk] = date('Y-m-d',strtotime( $items->value));
            }
            if($items->type  ==  "checkboxtextbox"){
                $item[$items->emrdfk] =  $items->value;
                $item2[$items->emrdfk] =  true;
            }
            if($items->type == "checkbox") {
                $chekedd = false;
                if ($items->value == '1') {
                    $chekedd = true;
                }
                $item[$items->emrdfk] = $chekedd;
            }
            if($items->type == "combobox") {
                $arr = explode('~',$items->value );
                $item[$items->emrdfk] = $arr[1];
            }
        }


        $pageWidth = 950;
        // $peg = null;
        
        $peg = DB::table('pegawai_m')
            ->where('id',$request['pegawaittd'])
            ->first();
        
        $dataSip = DB::table('masaberlakusipstr_t as mbs')
                ->select('pg.id as idpegawai', 'pg.nama', 'mbs.nosip')
                ->leftJoin('jenismasaberlakustrsip_m as jmb','jmb.id','=','mbs.jenismasaberlakufk')
                ->leftJoin('pegawai_m as pg','pg.id','=', 'mbs.pegawaifk')
                ->leftJoin('unitkerjapegawai_m as uk','uk.id','=','pg.objectunitkerjapegawaifk')
                ->leftJoin('unitkerjapegawai_m as uk2','uk2.id','=','mbs.subunitkerjafk')
                ->where('pg.statusenabled',true)
                ->where('mbs.kdprofile', $kdProfile)
                ->where('mbs.pegawaifk', $request['pegawaittd'])
                ->orderBy('mbs.berakhirstr','desc')
                ->first();
        
        // if(isset($request['isttd']) && $request['isttd'] == true){
        //     $peg = DB::table('pegawai_m')->where('id',$request['pegawaittd'])->first();
            
        // }
        
        // cari pdf yang sudah di ttd
        $cekPdf = DB::table('emr_bsre_t')
            ->where('statusenabled', true)
            ->where('noregistrasi', trim($data[0]->noregistrasi))
            ->where('nocm', $data[0]->nocm)
            ->where('nomoremr', $data[0]->noemr)
            ->where('status', true)
            ->where('emrfk', $data[0]->emrfk)
            ->get();

        if(count($cekPdf) > 0){
            $link = '/service/storage_path?path='.$cekPdf[0]->file.'&filename='.$cekPdf[0]->namafile.'&mimetype=application/pdf';
            return redirect($link);
        }

        $pdf = PDF::loadView(
            'report.EMR.suratketerangannapza-dom',
            array(
                'res' => $res,
                'pageWidth' => $pageWidth,
                'data' => $data,
                'profile' => $profile,
                'item'=> $item,
                'peg'=> $peg,
                'tte' => (isset($request['isttd']) && $request['isttd'] == true) ? 'true' : 'false',
                'sip' => $dataSip
            )
        );
        if(isset($request['isttd']) && $request['isttd'] == true){
            $objetoRequest = new \Illuminate\Http\Request();
            $objetoRequest ['emrfk'] = $request['emrfk'];
            $objetoRequest ['norec_emr'] = $request['emr'];
            $objetoRequest ['pegawaittd'] = $request['pegawaittd'];
            $objetoRequest ['nocm'] = $request['nocm'];
            $objetoRequest ['noregistrasi'] = $request['noregistrasi'];
            $objetoRequest ['norec_pd'] = $request['norec_pd'];
            $bsre = app('App\Http\Controllers\Bridging\BridgingBSREController')->pengajuanTTE($objetoRequest,true);
            if($bsre['status'] == 201){
                $content = $pdf->download()->getOriginalContent();
                \Storage::disk('local')->put( 'TTD_BSRE/' . $bsre['dokumen']->id . '/file' . '.pdf' , $content);
            }
          
            return $bsre;
        }

        return $pdf->stream();
        // return view('report.EMR.suratketerangannapza',compact('data','pageWidth', 'profile', 'item'));
    }

    public function CetakSKJiwa(Request $request)
    {
        $noemr = $request['noemr'];
        $kdProfile = (int) $request['kdprofile'];
        $emrfk = $request['emrfk'];
        $kodeAwalSurat = $this->settingDataFixed('KodeAwalSurat', $kdProfile);
        $kodeAkhirSurat = $this->settingDataFixed('KodeAkhirSurat', $kdProfile);
        $data = DB::select(DB::raw("
            SELECT
                epd.emrdfk,
                epd.emrfk,
                ep.noemr,
                ed.TYPE,
                pa.namapasien,
                pa.tgllahir,
                pa.nohp,
                pa.nocm,
                ep.jeniskelamin,
                ep.umur,
                al.alamatlengkap,
                ep.noregistrasifk as noregistrasi,
                epd.value,ep.namaruangan,epd.tgl,
                pg.namalengkap as namadokter
            FROM
                emrpasien_t AS ep
                INNER JOIN emrpasiend_t AS epd ON ep.noemr = epd.emrpasienfk
                INNER JOIN emrd_t AS ed ON epd.emrdfk = ed.ID
                    INNER JOIN antrianpasiendiperiksa_t AS pd ON pd.norec = ep.norec_apd
                left JOIN pegawai_m AS pg ON pg.id = pd.objectpegawaifk
                left JOIN pasien_m as pa on ep.nocm =  pa.nocm
                left JOIN alamat_m as al on pa.id = al.nocmfk
            WHERE
                ep.norec = '".$request['emr']."'
                AND ep.kdprofile = ".$kdProfile." 
                AND epd.statusenabled = TRUE 
                and epd.emrfk = '".$request['emrfk']."'
            ORDER BY
                ed.nourut
        
        "));

        $profile = Profile::where('id',$request['kdprofile'])->first();

        foreach ($data as $z){
            if (isset($z->tgllahir) ||isset($z->tgl)){
                $z->tgllahir=$this->tanggal_indonesia(date('Y-m-d',strtotime($z->tgllahir)));
                $z->tgl=$this->tanggal_indonesia(date('Y-m-d',strtotime($z->tgl)));
            }
            
        }

        $item = [];

        foreach($data as $items){
            if($items->type  ==  "textbox" ||$items->type  ==  "textarea"  ){
                $item[$items->emrdfk] =  $items->value;
            }
            if($items->type  ==  "datetime"){
                $item[$items->emrdfk] = $this->tanggal_indonesia(date('Y-m-d',strtotime( $items->value)));
            }
            if($items->type  ==  "time"){
                $item[$items->emrdfk] = date('H:i',strtotime( $items->value));
            }
            if($items->type  ==  "date"){
                $item[$items->emrdfk] = date('Y-m-d',strtotime( $items->value));
            }
            if($items->type  ==  "checkboxtextbox"){
                $item[$items->emrdfk] =  $items->value;
            }
            if($items->type == "checkbox") {
                $chekedd = false;
                if ($items->value == '1') {
                    $chekedd = true;
                }
                $item[$items->emrdfk] = $chekedd;
            }
            if($items->type == "combobox") {
                $arr = explode('~',$items->value );
                $item[$items->emrdfk] = $arr[1];
            }
        }

        // dd($item);

        $pageWidth = 950;

        $peg = DB::table('pegawai_m')
            ->where('id',$request['pegawaittd'])
            ->first();
        
        $dataSip = DB::table('masaberlakusipstr_t as mbs')
                ->select('pg.id as idpegawai', 'pg.nama', 'mbs.nosip')
                ->leftJoin('jenismasaberlakustrsip_m as jmb','jmb.id','=','mbs.jenismasaberlakufk')
                ->leftJoin('pegawai_m as pg','pg.id','=', 'mbs.pegawaifk')
                ->leftJoin('unitkerjapegawai_m as uk','uk.id','=','pg.objectunitkerjapegawaifk')
                ->leftJoin('unitkerjapegawai_m as uk2','uk2.id','=','mbs.subunitkerjafk')
                ->where('pg.statusenabled',true)
                ->where('mbs.kdprofile', $kdProfile)
                ->where('mbs.pegawaifk', $request['pegawaittd'])
                ->orderBy('mbs.berakhirstr','desc')
                ->first();

        // if(isset($request['isttd']) && $request['isttd'] == true){
        //     $peg = DB::table('pegawai_m')->where('id',$request['pegawaittd'])->first();
            
        // }

        $cekPdf = DB::table('emr_bsre_t')
            ->where('statusenabled', true)
            ->where('noregistrasi', trim($data[0]->noregistrasi))
            ->where('nocm', $data[0]->nocm)
            ->where('nomoremr', $data[0]->noemr)
            ->where('emrfk', $data[0]->emrfk)
            ->where('status', true)
            ->get();

        if(count($cekPdf) > 0){
            $link = '/service/storage_path?path='.$cekPdf[0]->file.'&filename='.$cekPdf[0]->namafile.'&mimetype=application/pdf';
            return redirect($link);
        }

        $pdf = PDF::loadView(
            'report.EMR.suratketerangankesehatanjiwa-dom',
            array(
                'pageWidth' => $pageWidth,
                'kodeawalsurat' => $kodeAwalSurat,
                'kodeakhirsurat' => $kodeAkhirSurat,
                'data' => $data,
                'profile' => $profile,
                'item' => $item,
                'tte' => (isset($request['isttd']) && $request['isttd'] == true) ? 'true' : 'false',
                'peg' => $peg,
                'sip' => $dataSip,
            )
        );

        if(isset($request['isttd']) && $request['isttd'] == true){
            $objetoRequest = new \Illuminate\Http\Request();
            $objetoRequest ['emrfk'] = $request['emrfk'];
            $objetoRequest ['norec_emr'] = $request['emr'];
            $objetoRequest ['pegawaittd'] = $request['pegawaittd'];
            $objetoRequest ['nocm'] = $request['nocm'];
            $objetoRequest ['noregistrasi'] = $request['noregistrasi'];
            $objetoRequest ['norec_pd'] = $request['norec_pd'];
            $bsre = app('App\Http\Controllers\Bridging\BridgingBSREController')->pengajuanTTE($objetoRequest,true);
            if($bsre['status'] == 201){
                $content = $pdf->download()->getOriginalContent();
                \Storage::disk('local')->put( 'TTD_BSRE/' . $bsre['dokumen']->id . '/file' . '.pdf' , $content);
            }
          
            return $bsre;
        }

        return $pdf->stream();
        // return view('report.EMR.suratketerangankesehatanjiwa',compact('data','pageWidth', 'profile', 'item'));
    }
    public function CetakHPPCFIT(Request $request)
