                        INNER JOIN emrpasiend_t epd ON ep.noemr = epd.emrpasienfk
                        INNER JOIN emrd_t ed ON ed.ID = epd.emrdfk 
                    WHERE ep.kdprofile = $kdProfile AND ep.statusenabled = TRUE 
                        AND ep.noemr ILIKE '$noemr' 
                        AND ed.statusenabled = TRUE 
