    public function CetakRekapSumberDanaAnggaranSebelum(Request $request)
    {
        $tahun = $request['tahun'];
        $tahap =  $request['tahap'];

        $settingrba = DB::select(DB::raw("select sa.*, pg.reportdisplay as namalengkap, pg.nippns from settinganggaran_t sa
        inner join pegawai_m pg on pg.id = sa.objectkepalabludfk
        where sa.statusenabled = true"));

        $tanggalcetak = $this->tanggal_indonesia(date('Y-m-d',strtotime($request['tglcetak'])));

        $qtahap  = '';
        if (isset($request['tahap']) && $request['tahap'] != "" && $request['tahap'] != "undefined") {
            $qtahap =  ' and kb.objecttahapfk =  ' . $request['tahap'];
        }

        $tahap = DB::select(DB::raw("select tahapanggaran_m.*,$tahun as thn from tahapanggaran_m where id = $tahap"));
        $tahapnow = $request['tahap'];
        $data = \DB::select(DB::raw("select a.kode, a.div, a.kode1 kode2,
        a.kegiatan,a.jasalayanan,a.apbd,a.dak,a.danais,a.silpa,a.total 
        from(
        
                select y.kegiatan, y.kode, y.kode1, y.div, sum(y.apbd) apbd, sum(y.jasalayanan) jasalayanan, sum(y.dak) dak, sum(y.danais) danais, sum(y.silpa) silpa,
                sum(y.apbd) + sum(y.jasalayanan) + sum(y.dak) + sum(y.danais) + sum(y.silpa) as total
                from(
                        select x.kegiatan, x.subkegiatan, x.kode, x.kode1, x.div,
                        case when x.id_asalproduk = 15 then x.subtotal else 0 end as apbd,
                        case when x.id_asalproduk = 18 then subtotal else 0 end as jasalayanan,

                        case when x.id_asalproduk = 21 then subtotal else 0 end as dak,
                        case when x.id_asalproduk = 2 then subtotal else 0 end as danais,
                        case when x.id_asalproduk = 4 then subtotal else 0 end as silpa

                        from(
                                select kmss.keterangan kegiatan, ap.id as id_asalproduk,kmss.kode, 0 kode1, kmss.div, kms.keterangan subkegiatan, sum(kb.subtotal) subtotal
                                from kegiatananggaran2024_m km
                                inner join kegiatananggaran2024_m kms on km.headfk = kms.id
                                inner join kegiatananggaran2024_m kmss on kms.headfk = kmss.id
                                inner join transaksianggaran2024_t ta ON ta.objectkegiatanfk = km.id AND ta.statusenabled = TRUE
                                inner join keteranganbelanja_t kb on kb.objecttransaksifk = ta.norec
                                inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
                                where km.kdprofile = 30 and km.statusenabled = true
                                and kms.kdprofile = 30 and kms.statusenabled = true
                                and kmss.kdprofile = 30 and kmss.statusenabled = true
                                and kb.kdprofile = 30 and kb.statusenabled = true
                                and ap.kdprofile = 30 and ap.statusenabled = true
                                and ta.tahun = '$tahun'
                                $qtahap
                                group by kms.keterangan, kmss.keterangan, kmss.kode, kmss.div, ap.id
                        ) as x group by x.kegiatan, x.subkegiatan, x.subtotal, x.kode, x.kode1, x.div, x.id_asalproduk
                ) as y group by kegiatan, kode, kode1, div
        
                union all
        
                select y.subkegiatan as kegiatan, y.kode, y.kode1, y.div, sum(y.apbd) apbd, sum(y.jasalayanan) jasalayanan, sum(y.dak) dak, sum(y.danais) danais, sum(y.silpa) silpa,
                sum(y.apbd) + sum(y.jasalayanan) + sum(y.dak) + sum(y.danais) + sum(y.silpa) as total
                from(
                        select x.kegiatan, x.subkegiatan, x.kode, kode1, x.div,
                        case when x.id_asalproduk = 15 then x.subtotal else 0 end as apbd,
                        case when x.id_asalproduk = 18 then subtotal else 0 end as jasalayanan,

                        case when x.id_asalproduk = 21 then subtotal else 0 end as dak,
                        case when x.id_asalproduk = 2 then subtotal else 0 end as danais,
                        case when x.id_asalproduk = 4 then subtotal else 0 end as silpa

                        from(
                                select kmss.keterangan kegiatan, kms.keterangan subkegiatan, kms.kode, 0 kode1, kms.div, ap.id as id_asalproduk,sum(kb.subtotal) subtotal
                                from kegiatananggaran2024_m km
                                inner join kegiatananggaran2024_m kms on km.headfk = kms.id
                                inner join kegiatananggaran2024_m kmss on kms.headfk = kmss.id
                                inner join transaksianggaran2024_t ta ON ta.objectkegiatanfk = km.id AND ta.statusenabled = TRUE
                                inner join keteranganbelanja_t kb on kb.objecttransaksifk = ta.norec
                                inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
                                where km.kdprofile = 30 and km.statusenabled = true
                                and kms.kdprofile = 30 and kms.statusenabled = true
                                and kmss.kdprofile = 30 and kmss.statusenabled = true
                                and kb.kdprofile = 30 and kb.statusenabled = true
                                and ap.kdprofile = 30 and ap.statusenabled = true
                                and ta.tahun = '$tahun'
                                $qtahap
                                group by kms.keterangan, kmss.keterangan, kms.kode, kms.div, ap.id
                        ) as x group by x.kegiatan, x.subkegiatan, x.subtotal, x.kode, x.kode1, x.div, x.id_asalproduk
                ) as y group by subkegiatan, kode, kode1, div
        
                union all
        
                select case when $tahapnow=1 then y.subkegiatan else REGEXP_REPLACE(y.subkegiatan, '^[0-9-]+', '') end as kegiatan, 
                y.kode, y.kode1, y.div, sum(y.apbd) apbd, sum(y.jasalayanan) jasalayanan, sum(y.dak) dak, sum(y.danais) danais, sum(y.silpa) silpa,
                sum(y.apbd) + sum(y.jasalayanan) + sum(y.dak) + sum(y.danais) + sum(y.silpa) as total
                from(
                        select x.kegiatan, x.subkegiatan, x.kode, x.kode1, x.div,
                        case when x.id_asalproduk = 15 then x.subtotal else 0 end as apbd,
                        case when x.id_asalproduk = 18 then subtotal else 0 end as jasalayanan,

                        case when x.id_asalproduk = 21 then subtotal else 0 end as dak,
                        case when x.id_asalproduk = 2 then subtotal else 0 end as danais,
                        case when x.id_asalproduk = 4 then subtotal else 0 end as silpa

                        from(
                                select km.keterangan kegiatan, km.keterangan subkegiatan,
                                km.kode as kode,
                                CAST(split_part(km.kode,'.',7) as int) as kode1,
                                km.div, ap.id as id_asalproduk,sum(kb.subtotal) subtotal
                                from kegiatananggaran2024_m km
                                inner join kegiatananggaran2024_m kms on km.headfk = kms.id
                                inner join kegiatananggaran2024_m kmss on kms.headfk = kmss.id
                                inner join transaksianggaran2024_t ta ON ta.objectkegiatanfk = km.id AND ta.statusenabled = TRUE
                                inner join keteranganbelanja_t kb on kb.objecttransaksifk = ta.norec
                                inner join asalproduk_m ap on ap.id = kb.objectasalprodukfk
                                where km.kdprofile = 30 and km.statusenabled = true
                                and kms.kdprofile = 30 and kms.statusenabled = true
                                and kmss.kdprofile = 30 and kmss.statusenabled = true
                                and kb.kdprofile = 30 and kb.statusenabled = true
                                and ap.kdprofile = 30 and ap.statusenabled = true
                                and ta.tahun = '$tahun'
                                $qtahap
                                group by km.keterangan, km.keterangan, km.kode, km.div, ap.id
                        ) as x group by x.kegiatan, x.subkegiatan, x.subtotal, x.kode, x.kode1, x.div, x.id_asalproduk
                ) as y group by subkegiatan, kode, kode1, div
        
        ) as a order by CAST(split_part(kode,'.',1) as int), CAST(split_part(kode,'.',2) as int), CAST(split_part(kode,'.',3) as int),
				CAST(split_part(kode,'.',4) as int),CAST(split_part(kode,'.',5) as int), div, kode2"));

        $grandtotal = collect(DB::select("
        SELECT SUM ( xx.jasalayanan ) AS jasapelayanan, SUM ( xx.apbd ) AS apbd, SUM ( xx.dak ) AS dak, SUM ( xx.danais ) AS danais, SUM ( xx.silpa ) AS silpa, SUM ( xx.total ) AS total  FROM ( SELECT A .kode, A.div,
                    CASE WHEN A.div = 2 THEN SUBSTR( A.kode, 9, 4 )  WHEN A.div = 3 THEN SUBSTR( A.kode, 14, 2 ) WHEN A.div = 4 THEN A.kode END AS kode,
                        A.kode1 kode2, A.kegiatan, A.jasalayanan, A.apbd, A.dak, A.danais, A.silpa, A.total  FROM ( SELECT y.kegiatan, y.kode, y.kode1, y.div, SUM ( y.apbd ) apbd,
                            SUM ( y.jasalayanan ) jasalayanan, SUM ( y.dak ) dak, SUM ( y.danais ) danais, SUM ( y.silpa ) silpa, SUM ( y.apbd ) + SUM ( y.jasalayanan ) + SUM ( y.dak ) + SUM ( y.danais ) + SUM ( y.silpa ) AS total  FROM ( SELECT x.kegiatan, x.subkegiatan,
                                x.kode, x.kode1, x.div,
                            CASE WHEN x.id_asalproduk = 15 THEN x.subtotal ELSE 0  END AS apbd,
                            CASE WHEN x.id_asalproduk = 18 THEN subtotal ELSE 0  END AS jasalayanan,

                            CASE WHEN x.id_asalproduk = 21 THEN subtotal ELSE 0  END AS dak, 
                            CASE WHEN x.id_asalproduk = 2 THEN subtotal ELSE 0  END AS danais, 
                            CASE WHEN x.id_asalproduk = 4 THEN subtotal ELSE 0  END AS silpa 

                            FROM ( SELECT kmss.keterangan kegiatan, ap.ID AS id_asalproduk, kmss.kode, 0 kode1, kmss.div, kms.keterangan subkegiatan,
                                    SUM ( kb.subtotal ) subtotal  FROM
                                    kegiatananggaran_m km
                                    inner join kegiatananggaran2024_m kms on km.headfk = kms.id
                                    inner join kegiatananggaran2024_m kmss on kms.headfk = kmss.id
                                    inner join transaksianggaran2024_t ta ON ta.objectkegiatanfk = km.id AND ta.statusenabled = TRUE
                                    inner join keteranganbelanja_t kb on kb.objecttransaksifk = ta.norec
                                    INNER JOIN asalproduk_m ap ON ap.ID = kb.objectasalprodukfk 
                                WHERE
                                    km.kdprofile = 30  AND km.statusenabled = TRUE 
                                    AND kms.kdprofile = 30 AND kms.statusenabled = TRUE 
                                    AND kmss.kdprofile = 30 AND kmss.statusenabled = TRUE 
                                    AND kb.kdprofile = 30 AND kb.statusenabled = TRUE 
                                    and ap.kdprofile = 30 and ap.statusenabled = true
                                    AND ta.tahun = '$tahun' 
                                    $qtahap
                                GROUP BY
                                    kms.keterangan,
                                    kmss.keterangan,
                                    kmss.kode,
                                    kmss.div,
                                    ap.ID 
                                ) AS x 
                            GROUP BY
                                x.kegiatan,
                                x.subkegiatan,
                                x.subtotal,
                                x.kode,
                                x.kode1,
                                x.div,
                                x.id_asalproduk 
                            ) AS y 
                        GROUP BY
                            kegiatan,
                            kode,
                            kode1,
                            div UNION ALL
                        SELECT
                            y.subkegiatan AS kegiatan,
                            y.kode,
                            y.kode1,
                            y.div,
                            SUM ( y.apbd ) apbd,
                            SUM ( y.jasalayanan ) jasalayanan,

                            SUM ( y.dak ) dak,
                            SUM ( y.danais ) danais,
                            SUM ( y.silpa ) silpa,

                            SUM ( y.apbd ) + SUM ( y.jasalayanan ) + SUM ( y.dak ) + SUM ( y.danais ) + SUM ( y.silpa ) AS total 
                        FROM
                            (
                            SELECT
                                x.kegiatan,
                                x.subkegiatan,
                                x.kode,
                                kode1,
                                x.div,
                            CASE
                                    
                                    WHEN x.id_asalproduk = 15 THEN
                                    x.subtotal ELSE 0 
                                END AS apbd,
                            CASE
                                    
                                    WHEN x.id_asalproduk = 18 THEN
                                    subtotal ELSE 0 
                                END AS jasalayanan, 

                            CASE                                   
                                WHEN x.id_asalproduk = 21 THEN
                                subtotal ELSE 0 
                            END AS dak, 
                            CASE                                    
                                WHEN x.id_asalproduk = 2 THEN
                                subtotal ELSE 0 
                            END AS danais, 
                            CASE                                    
                                WHEN x.id_asalproduk = 4 THEN
                                subtotal ELSE 0 
                            END AS silpa 

                        FROM
                                (
                                SELECT
                                    kmss.keterangan kegiatan,
                                    kms.keterangan subkegiatan,
                                    kms.kode,
                                    0 kode1,
                                    kms.div,
                                    ap.ID AS id_asalproduk,
                                    SUM ( kb.subtotal ) subtotal 
                                FROM
                                    kegiatananggaran_m km
                                    inner join kegiatananggaran2024_m kms on km.headfk = kms.id
                                    inner join kegiatananggaran2024_m kmss on kms.headfk = kmss.id
                                    inner join transaksianggaran2024_t ta ON ta.objectkegiatanfk = km.id
                                    inner join keteranganbelanja_t kb on kb.objecttransaksifk = ta.norec
                                    INNER JOIN asalproduk_m ap ON ap.ID = kb.objectasalprodukfk 
                                WHERE
                                    km.kdprofile = 30 AND km.statusenabled = TRUE 
                                    AND kms.kdprofile = 30 AND kms.statusenabled = TRUE 
                                    AND kmss.kdprofile = 30 AND kmss.statusenabled = TRUE 
                                    AND kb.kdprofile = 30 AND kb.statusenabled = TRUE 
                                    and ap.kdprofile = 30 and ap.statusenabled = true
                                    AND ta.tahun = '$tahun' 
                                    $qtahap
                                GROUP BY
                                    kms.keterangan,
                                    kmss.keterangan,
                                    kms.kode,
                                    kms.div,
                                    ap.ID 
                                ) AS x 
                            GROUP BY
                                x.kegiatan,
                                x.subkegiatan,
                                x.subtotal,
                                x.kode,
                                x.kode1,
                                x.div,
                                x.id_asalproduk 
                            ) AS y 
                        GROUP BY
                            subkegiatan,
                            kode,
                            kode1,
                            div UNION ALL
                        SELECT
                            y.subkegiatan AS kegiatan,
                            y.kode,
                            y.kode1,
                            y.div,
                            SUM ( y.apbd ) apbd,
                            SUM ( y.jasalayanan ) jasalayanan,

                            SUM ( y.dak ) dak,
                            SUM ( y.danais ) danais,
                            SUM ( y.silpa ) silpa,

                            SUM ( y.apbd ) + SUM ( y.jasalayanan ) + SUM ( y.dak ) + SUM ( y.danais ) + SUM ( y.silpa ) AS total 
                        FROM
                            (
                            SELECT
                                x.kegiatan,
                                x.subkegiatan,
                                x.kode,
                                x.kode1,
                                x.div,
                            CASE
                                    
                                    WHEN x.id_asalproduk = 15 THEN
                                    x.subtotal ELSE 0 
                                END AS apbd,
                            CASE
                                    
                                    WHEN x.id_asalproduk = 18 THEN
                                    subtotal ELSE 0 
                                END AS jasalayanan,
                                
                            CASE                                
                                WHEN x.id_asalproduk = 21 THEN
                                subtotal ELSE 0 
                            END AS dak, 
                            CASE                                
                                WHEN x.id_asalproduk = 2 THEN
                                subtotal ELSE 0 
                            END AS danais, 
                            CASE                                
                                WHEN x.id_asalproduk = 4 THEN
                                subtotal ELSE 0 
                            END AS silpa 
                            
                            FROM
                                (
                                SELECT
                                    km.keterangan kegiatan,
                                    km.keterangan subkegiatan,
                                CASE
                                        
                                        WHEN LENGTH ( km.kode ) = 17 THEN
                                        LEFT ( km.kode, - 1 ) 
                                        WHEN LENGTH ( km.kode ) = 18 THEN
                                        LEFT ( km.kode, - 2 ) 
                                    END AS kode,
                                CASE
                                        
                                        WHEN LENGTH ( km.kode ) = 17 THEN
                                        RIGHT ( km.kode, 1 ) :: INT 
                                        WHEN LENGTH ( km.kode ) = 18 THEN
                                        RIGHT ( km.kode, 2 ) :: INT 
                                    END AS kode1,
                                    km.div,
                                    ap.ID AS id_asalproduk,
                                    SUM ( kb.subtotal ) subtotal 
                                FROM
                                    kegiatananggaran_m km
                                    inner join kegiatananggaran2024_m kms on km.headfk = kms.id
                                    inner join kegiatananggaran2024_m kmss on kms.headfk = kmss.id
                                    inner join transaksianggaran2024_t ta ON ta.objectkegiatanfk = km.id AND ta.statusenabled = TRUE
                                    inner join keteranganbelanja_t kb on kb.objecttransaksifk = ta.norec
                                    INNER JOIN asalproduk_m ap ON ap.ID = kb.objectasalprodukfk 
                                WHERE
                                    km.kdprofile = 30 AND km.statusenabled = TRUE 
                                    AND kms.kdprofile = 30 AND kms.statusenabled = TRUE 
                                    AND kmss.kdprofile = 30 AND kmss.statusenabled = TRUE 
                                    AND kb.kdprofile = 30 AND kb.statusenabled = TRUE 
                                    and ap.kdprofile = 30 and ap.statusenabled = true
                                    AND ta.tahun = '$tahun' 
                                    $qtahap
                                GROUP BY
                                    km.keterangan,
                                    km.keterangan,
                                    km.kode,
                                    km.div,
                                    ap.ID 
                                ) AS x 
                            GROUP BY
                                x.kegiatan,
                                x.subkegiatan,
                                x.subtotal,
                                x.kode,
                                x.kode1,
                                x.div,
                                x.id_asalproduk 
                            ) AS y 
                        GROUP BY
                            subkegiatan,
                            kode,
                            kode1,
                            div 
                        ) AS A 
                    ORDER BY
                        A.kode,
                    kode1 
        ) AS xx"))->first();

        $pageWidth = 1200;
        return view('report.spj.cetakrekapanggaransumberdana', compact('data','grandtotal','pageWidth','tahap', 'tanggalcetak', 'settingrba'));
    }
    public function CetakRekapSumberDanaAnggaran(Request $request)
    {   
        $tahun = $request['tahun'];
        $tanggalcetak = $this->tanggal_indonesia(date('Y-m-d',strtotime($request['tglcetak'])));

        $qtahap  = '';
        if (isset($request['tahap']) && $request['tahap'] != "" && $request['tahap'] != "undefined") {
            $qtahap =  ' and kb.objecttahapfk =  ' . $request['tahap'];
        }

        $qterhadap  = '';
        if (isset($request['terhadap']) && $request['terhadap'] != "" && $request['terhadap'] != "undefined") {
            $qterhadap =  ' and kb.objecttahapfk =  ' . $request['terhadap'];
        }
        $sebelum = \DB::select(DB::raw("
        SELECT 
            COALESCE(j.kegiatan, K.kegiatan) AS kegiatan,
            COALESCE(j.kode, K.kode) AS kode,
            COALESCE(j.div, K.div) AS div,
            COALESCE(j.tahap, '') AS tahap,
            COALESCE(j.apbd, 0) AS apbd,
            COALESCE(j.jasalayanan, 0) AS jasalayanan,
            COALESCE(j.dak, 0) AS dak,
            COALESCE(j.danais, 0) AS danais,
            COALESCE(j.silpa, 0) AS silpa,
            COALESCE(j.total, 0) AS total,
            COALESCE(K.apbd, 0) AS kapbd,
            COALESCE(K.jasalayanan, 0) AS kjasalayanan,
            COALESCE(K.dak, 0) AS kdak,
            COALESCE(K.danais, 0) AS kdanais,
            COALESCE(K.silpa, 0) AS ksilpa,
            COALESCE(K.total, 0) AS ktotal,
            K.tahap AS tahapsesudah
        FROM
            (
            SELECT
                * 
            FROM
                (
                SELECT y.kegiatan, y.tahap, y.kode, y.div,
                    SUM ( y.apbd ) AS apbd, SUM ( y.jasalayanan ) AS jasalayanan,
                    SUM ( y.dak ) AS dak, SUM ( y.danais ) AS danais, SUM ( y.silpa ) AS silpa,
                    SUM ( y.apbd ) + SUM ( y.jasalayanan ) + SUM ( y.dak ) + SUM ( y.danais ) + SUM ( y.silpa ) AS total 
                FROM
                    (
                    SELECT x.kegiatan, x.subkegiatan, x.tahap, x.kode, x.div,
                    CASE WHEN x.id_asalproduk = 15 THEN x.subtotal ELSE 0 END AS apbd,
                    CASE WHEN x.id_asalproduk = 18 THEN x.subtotal ELSE 0 END AS jasalayanan,
                    CASE WHEN x.id_asalproduk = 21 THEN x.subtotal ELSE 0 END AS dak,
                    CASE WHEN x.id_asalproduk = 2  THEN x.subtotal ELSE 0 END AS danais,
                    CASE WHEN x.id_asalproduk = 4  THEN x.subtotal ELSE 0 END AS silpa
                    FROM
                        (
                        SELECT kmss.keterangan kegiatan, ap.ID AS id_asalproduk, kms.keterangan subkegiatan, kmss.kode, kmss.div, km.keterangan subsubkegiatan, ta.tahap, ta.ID, ap.asalproduk, SUM ( kb.subtotal ) subtotal 
                        FROM
                            kegiatananggaran2024_m km
                            inner join kegiatananggaran2024_m kms on km.headfk = kms.id
                            inner join kegiatananggaran2024_m kmss on kms.headfk = kmss.id
                            inner join transaksianggaran2024_t th ON th.objectkegiatanfk = km.id AND th.statusenabled = TRUE
                            inner join keteranganbelanja_t kb on kb.objecttransaksifk = th.norec 
                            INNER JOIN asalproduk_m ap ON ap.ID = kb.objectasalprodukfk
                            LEFT JOIN tahapanggaran_m ta ON ta.ID = kb.objecttahapfk 
                        WHERE
                            km.kdprofile = 30 
                            AND km.statusenabled = TRUE 
                            and kms.kdprofile = 30 and kms.statusenabled = true
                            and kmss.kdprofile = 30 and kmss.statusenabled = true
                            and kb.kdprofile = 30 and kb.statusenabled = true
                            $qterhadap
                            and th.tahun = '$request[tahun]'
                        GROUP BY kms.keterangan, kmss.keterangan, kmss.kode, ap.asalproduk, kmss.div, km.keterangan, ta.tahap, ta.ID, ap.ID 
                        ) AS x GROUP BY x.kegiatan, x.subkegiatan, x.tahap, x.asalproduk, x.subtotal, x.kode, x.div, x.id_asalproduk 
                    ) AS y GROUP BY y.kegiatan, y.tahap, y.kode, y.div UNION ALL
                SELECT y.subkegiatan, y.tahap, y.kode, y.div,
                    SUM ( y.apbd ) AS apbd, SUM ( y.jasalayanan ) AS jasalayanan,
                    SUM ( y.dak ) AS dak, SUM ( y.danais ) AS danais, SUM ( y.silpa ) AS silpa,
                    SUM ( y.apbd ) + SUM ( y.jasalayanan ) + SUM ( y.dak ) + SUM ( y.danais ) + SUM ( y.silpa ) AS total 
                FROM
                    (
                    SELECT x.kegiatan, x.subkegiatan, x.tahap, x.kode, x.div,
                    CASE WHEN x.id_asalproduk = 15 THEN x.subtotal ELSE 0 END AS apbd,
                    CASE WHEN x.id_asalproduk = 18 THEN x.subtotal ELSE 0 END AS jasalayanan,
