                        'rutepagi'=> $rutepagi,
                       
                        );
                    }
                    foreach ($datasiang as $ds) {
                            $obatsiang = $ds->namaproduk;
                            $aturansiang = $ds->aturan;
                            $satuansiang = $ds->satuan;
                            $rutesiang = $ds->rute;
                       
                        $detailobatsiang[] = array(
                        'v'=> '',
                        'obatsiang'=> $obatsiang,
                        'aturansiang'=> $aturansiang,
                        'satuansiang'=> $satuansiang,
                        'rutesiang'=> $rutesiang,
                       
                        );
                    }
                    $detailobat[] = array(
                        'obatmalam'=> $detailobatmalam,
                        'obatpagi'=> $detailobatpagi,
                        'obatsiang'=> $detailobatsiang,
                        'tglpagi'=> $dd->tglcetakpagi,
                        'tglsiang'=> $dd->tglcetaksiang,
                        'tglmalam'=> $dd->tglcetakmalam,
                        'waktumalam'=> 'MALAM',
                        'waktusiang'=> 'SIANG',
                        'waktupagi'=> 'PAGI',
                    );
                    $detailobatmalam = null;                
                    $detailobatpagi = null;                
                    $detailobatsiang = null;                
                }
                $detail = $detailobat;
                $obat=null;
            $pasien = \DB::select(DB::raw("SELECT ps.namapasien, ps.tgllahir::date, ps.nocm 
            FROM pasien_m ps where ps.statusenabled=true and ps.kdprofile = $request[kodeprofile] and ps.nocm = '$cm'"));
            foreach ($pasien as $ps) {
                $namapasien = $ps->namapasien;
                $tgllahir = $ps->tgllahir;
                $nocms = $ps->nocm;
            }
            $result[]= array(
                'namapasien'=>$namapasien,
                'tgllahir'=>$tgllahir,
                'nocm'=>$nocms,
                'details'=> $detail,
            );
            $i++;
        }
        $pageWidth = 1300;
        return view("report.apotik.cetak-tilik", compact('result','pageWidth'));
    }
    public function persetujuanUmum(Request $request)
    {
        $data = \DB::select(DB::raw("SELECT ps.saksipersetujuan, ps.pjpersetujuan, ps.kerahasiaan1,ps.kerahasiaan2,ps.kerahasiaan3,ps.kerahasiaan4,
        ps.privasi1,ps.privasi2,ps.privasi3,ps.privasi4,ps.ismengizinkan, pg.id, pg.namalengkap  
        from pasiendaftar_t pd 
        inner join pasien_m ps on ps.id = pd.nocmfk
        left join pegawai_m pg on pg.id = pd.objectpetugasinformasifk
        where pd.norec ilike '$request[norec_pd]' and pd.kdprofile = $request[kdprofile] and pd.statusenabled = true
        "));
        foreach($data as $d){
            $d->saksi = $request['saksi'];
            $d->penanggungjawab = $request['penanggungjawab'];
            $d->tglnow = $this->tanggal_indonesia(date('Y-m-d'));
            $d->waktu = date('H:i');
        }
        $pageWidth = 1300;
        return view("report.EMR.persetujuan-umum", compact('data','pageWidth'));
    }
    public function cetakSEPV2(Request $request) {
        $kdProfile = (int)$request['kdprofile'];
        $noregistrasi = $request['noregistrasi'];
        $tglAyeuna = date('Y-m-d H:i:s');

        $profile = collect(DB::select("
            select * from profile_m where id = $kdProfile limit 1
        "))->first();
        $datas = collect(DB::select("
            SELECT pd.norec AS norec_pd
            ,pa.nosep
            ,pa.tanggalsep
            ,pa.tglcreate
            ,pa.nokepesertaan || ' ( MR : ' || pi.nocm || ' )' as nokepesertaan
            ,pa.nokepesertaan as nobpjs
            ,pi.nocm
            ,pd.noregistrasi
            ,apdp.noantrian
            ,pa.norujukan
            ,ap.namapeserta
            ,ap.tgllahir
            ,jk.jeniskelamin
            ,pa.ppkrujukan
            ,rp.kdinternal AS namapolibpjs
            ,ap.jenispeserta
            ,ap.kdprovider
            ,ap.nmprovider
            ,pa.catatan
            ,kls.namakelas AS haknamakelas
	        ,ap.notelpmobile
	        ,pa.penjaminlaka
            ,pa.prolanisprb
            ,pa.namadjpjpmelayanni
            ,rp.objectdepartemenfk
            ,CASE WHEN rp.objectdepartemenfk = 18 THEN
            CASE WHEN pa.polirujukankode IS NULL THEN rp.namaruangan ELSE pa.polirujukannama END
            ELSE '-' END AS namaruangan
            ,CASE WHEN rp.objectdepartemenfk = 16 THEN 'R. Inap' ELSE'R. Jalan' END AS jenisrawat
            ,CASE WHEN pa.statuskunjungan = 1 THEN 'Konsultasi dokter (pertama)'
            WHEN pa.statuskunjungan = 2 THEN  'Kunjungan rujukan internal'
            WHEN pa.statuskunjungan = 3 THEN 'Kunjungan Kontrol (ulangan)'
            ELSE '' END AS kunjungan
            ,CASE WHEN pa.flagprocedure = '0' THEN 'Prosedur tidak berkelanjutan'
            WHEN pa.flagprocedure = '1' THEN 'Prosedur dan terapi berkelanjutan'
            END AS procedures
            ,CASE WHEN dg.kddiagnosa IS NULL THEN '-' ELSE dg.kddiagnosa END || '-' || ( CASE WHEN dg.namadiagnosa IS NULL THEN '-' ELSE dg.namadiagnosa END ) AS namadiagnosa
            ,CASE WHEN pa.cob = TRUE THEN 'Ya' ELSE '' END AS cob
            ,CASE WHEN rp.objectdepartemenfk = 16 THEN true ELSE false END AS isSPRI
            ,CASE WHEN rp.objectdepartemenfk = 16 THEN kls.namakelas ELSE '-' END AS namakelas
            ,CASE WHEN pa.penjaminlaka = '1' THEN 'Jasa Raharja PT' 
            WHEN pa.penjaminlaka = '2' THEN 'BPJS Ketenagakerjaan'
            WHEN pa.penjaminlaka = '3' THEN 'TASPEN PT'
            WHEN pa.penjaminlaka = '4' THEN 'ASABRI PT'
            ELSE '-' END AS penjaminlakalantas,
            CASE WHEN rp.objectdepartemenfk = 18 THEN pa.polirujukannama ELSE '-' END AS polirujukannama
            FROM pemakaianasuransi_t AS pa
            LEFT JOIN asuransipasien_m AS ap ON pa.objectasuransipasienfk = ap.id
            LEFT JOIN pasiendaftar_t AS pd ON pd.norec = pa.noregistrasifk
            LEFT JOIN antrianpasiendiperiksa_t AS apdp ON apdp.noregistrasifk = pd.norec
            LEFT JOIN pasien_m AS pi ON pi.id = pd.nocmfk
            LEFT JOIN jeniskelamin_m AS jk ON jk.id = pi.objectjeniskelaminfk
            LEFT JOIN ruangan_m AS rp ON rp.id = pd.objectruanganlastfk
            LEFT JOIN diagnosa_m AS dg ON pa.diagnosisfk = dg.id
            LEFT JOIN kelas_m AS kls ON kls.id = ap.objectkelasdijaminfk
            WHERE pd.noregistrasi = '". $noregistrasi ."'
            AND pa.nosep IS NOT NULL
        "))->first();
        if(empty($datas)) {
            echo '
                <script language="javascript">
                    window.alert("Data tidak ada.");
                    window.close()
                </script>
            ';
            die;
        }

        $suratJaminan = collect(DB::select("
            SELECT
            CASE WHEN ru.objectdepartemenfk = 18 THEN 'RAWAT JALAN'
            WHEN ru.objectdepartemenfk = 24 THEN 'GAWAT DARURAT'
            WHEN ru.objectdepartemenfk = 16 THEN 'RAWAT INAP' 
            ELSE dp.namadepartemen END AS instalasi
            ,pm.nocm
            ,pd.noregistrasi
            ,ru.namaruangan
            ,pm.namapasien
            ,pm.nobpjs || ' ( MR : ' || pm.nocm || ' )' as nobpjs
            ,pg.namalengkap AS dokter
            ,to_char(pd.tglregistrasi, 'DD/MM/YYYY' ) AS tglmasuk 
            FROM pasiendaftar_t AS pd
            LEFT JOIN ruangan_m AS ru ON ru.id = pd.objectruanganlastfk
            LEFT JOIN pegawai_m AS pg ON pg.id = pd.objectpegawaifk
		    INNER JOIN pasien_m AS pm ON pm.id = pd.nocmfk
            LEFT JOIN alamat_m AS alm ON alm.nocmfk = pm.id
            LEFT JOIN departemen_m AS dp ON dp.id = ru.objectdepartemenfk
            LEFT JOIN kelompokpasien_m AS kp ON kp.id = pd.objectkelompokpasienlastfk
		    LEFT JOIN rekanan_m AS rkn ON rkn.id = pd.objectrekananfk
            WHERE pd.noregistrasi = '". $noregistrasi ."'
        "))->first();
        $spri = collect(DB::select("
            SELECT to_char(tglrencanakontrol, 'dd Month yyyy') as tglrencana
            ,to_char(tglterbitkontrol, 'dd Month yyyy') as tglterbit
            ,* 
            FROM bpjsrencanakontrol_t 
            WHERE statusenabled = true and norec_pd = '". $datas->norec_pd ."'
        "))->first();

        // isi tanda tangan
        // $tulisanheader = "Dikeluarkan di RSUD H.A SULTHAN DG. RADJA, Kabupaten/Kota Bulukumba /r";
        $tulisanheader = "Dikeluarkan di RS JIWA GRHASIA. Jalan Kaliurang KM. 17, Pakem Sleman, Daerah Istimewa Yogyakarta, <br/>";
        $tulisanheader .= "Ditandatangani secara elektronik oleh /r";
        $tulisanfooter = "ID ". $datas->nobpjs ."/r";
        $tulisanfooter .= date_format(date_create($datas->tglcreate), 'Y-m-d');

        $ttdpasien = $tulisanheader . $datas->namapeserta . "/r" . $tulisanfooter;
        $ttddokter = $tulisanheader . $suratJaminan->dokter . "/r" . $tulisanfooter;
        $ttdrumahsakit = $tulisanheader . "RSUD H.A SULTHAN DG. RADJA /r" . $tulisanfooter;
        $pageWidth = 819;
        $dataReport = array(
            'namaprofile' => $profile->namalengkap,
            'alamat' => $profile->alamatlengkap,
            'tglAyeuna' => $tglAyeuna,
            'data' => $datas,
            'suratJaminan' => $suratJaminan,
            'spri' => $spri,
            'ttdpasien' => $ttdpasien,
            'ttddokter' => $ttddokter,
            'ttdrumahsakit' => $ttdrumahsakit,
        );

        return view('report.pendaftaran.sepV2',
            compact('dataReport', 'pageWidth','profile'));
    }
    public function ttdDigital($noregistrasi, $type)
    {
        $data = collect(DB::select("
            SELECT pd.norec as norec_pd
            ,pm.namapasien
            ,pm.nobpjs
            ,pg.namalengkap AS dokter
            ,to_char(pd.tglregistrasi, 'YYYY-MM-DD') AS tglmasuk
            FROM pasiendaftar_t AS pd
            LEFT JOIN pegawai_m AS pg ON pg.id = pd.objectpegawaifk
		    INNER JOIN pasien_m AS pm ON pm.id = pd.nocmfk
            WHERE pd.noregistrasi = '". $noregistrasi ."'
        "))->first();
        $spri = collect(DB::select("SELECT * FROM bpjsrencanakontrol_t 
        WHERE statusenabled = true and norec_pd = '". $data->norec_pd ."'"))->first();

        $tulisanheader = "Dikeluarkan di RS JIWA GRHASIA. Jalan Kaliurang KM. 17, Pakem Sleman, Daerah Istimewa Yogyakarta, <br/>";
        $tulisanheader .= "Ditandatangani secara elektronik oleh <br/>";
        $tulisanfooter = "ID ". $data->nobpjs ."<br/>". $data->tglmasuk;
        $ttddigital = "";
        switch ($type) {
            case 'pasien':
                $ttddigital = $tulisanheader . $data->namapasien . "<br/>" . $tulisanfooter;
                break;
            case 'dokter':
                $ttddigital = $tulisanheader . $data->dokter . "<br/>" . $tulisanfooter;
                break;
            case 'rs':
                $ttddigital = $tulisanheader . "RS JIWA GRHASIA<br/>" . $tulisanfooter;
                break;
            case 'spri':
                $ttddigital = $tulisanheader . $spri->namadokter . "<br/>" . $tulisanfooter;
                break;
        }
        return $ttddigital;
    }
    public function cetakResepDokterHarga(Request $r) {
        $kdProfile = (int)$r['kodeprofile'];
        $noorder = $r['noorder'];
        $norec = $r['norec'];
        $nocm = $r['nocm'];
        
        $profile = \DB::select(DB::raw("
                select * from profile_m where id = $kdProfile limit 1
            "));
        $raw = collect(DB::select("
            select pa.nosep, pm2.nocm ,to_char(pm2.tgllahir,'dd-mm-yyyy') as tgllahir,age(pm2.tgllahir) as umur ,jm.jeniskelamin ,pm2.namapasien ,pm3.namalengkap, rm.namaruangan ruanganasal, ra.namaruangan ruangantujuan, pm2.alergi, 
            to_char(st.tglorder,'dd-mm-yyyy HH24:MI:ss') as tglorder,pm3.nosip, kp.kelompokpasien 
            from strukorder_t st
            inner join pasien_m pm2 on pm2.id = st.nocmfk
            inner join jeniskelamin_m jm on jm.id = pm2.objectjeniskelaminfk
            inner join pegawai_m pm3 on pm3.id = st.objectpegawaiorderfk
            inner join ruangan_m rm on rm.id = st.objectruanganfk 
            inner join ruangan_m ra on ra.id = st.objectruangantujuanfk 
            inner join pasiendaftar_t AS pd ON pd.norec = st.noregistrasifk
            left join pemakaianasuransi_t pa on pa.noregistrasifk = pd.norec
            left join kelompokpasien_m AS kp ON kp.id = pd.objectkelompokpasienlastfk
            where st.noorder = '$noorder'
        "))->first();
        $detel = [];
        $details = \DB::select(DB::raw("
                SELECT x.* FROM (select distinct row_number()over(partition by pt.rke, pm.namaproduk ORDER BY pt.rke asc)as no, pt.jeniskemasanfk, jr.jenisracikan, pt.rke,pt.dosis, pt.jumlah , pt.aturanpakai , pm.namaproduk, pm.kekuatan, pt.keteranganpakai,
                op.keteranganpakai as catatandokter, op.satuandosis, pt.hargasatuan,(((CASE WHEN pt.hargajual IS NULL THEN	0 ELSE pt.hargajual END - CASE WHEN pt.hargadiscount IS NULL THEN
		        0 ELSE pt.hargadiscount END) * pt.jumlah) + CASE WHEN pt.jasa IS NULL THEN	0 ELSE	pt.jasa	END	) as harga
                from pelayananpasien_t pt
                inner join produk_m pm on pm.id = pt.produkfk
                inner join jenisracikan_m jr on jr.id = pt.jenisobatfk
                inner join strukresep_t as sr on sr.norec = pt.strukresepfk
                inner join strukorder_t as so on so.norec = sr.orderfk
                left join orderpelayanan_t as op on op.strukorderfk = so.norec and op.rke = pt.rke 
                where strukresepfk = '$norec'
                and pt.isobat = true
                order by pt.rke asc, pt.keteranganpakai asc)as x where x.no = 1
            "));
        if(!empty($raw)){

            // $raw->umur = $this->getAge($raw->tgllahir ,date('Y-m-d'));
        }else if (empty($raw)){

            $raw = collect(DB::select("
                select pa.nosep, pm2.nocm ,to_char(pm2.tgllahir,'dd-mm-yyyy') as tgllahir,age(pm2.tgllahir) as umur ,jm.jeniskelamin ,pm2.namapasien ,pm3.namalengkap, rm.namaruangan ruangantujuan, to_char(s.tglresep ,'dd-mm-yyyy HH:MM:ss') as tglorder,pm3.nosip, kp.kelompokpasien, ra.namaruangan ruanganasal, pm2.alergi
                from strukresep_t s
                inner join antrianpasiendiperiksa_t at2 on at2.norec = s.pasienfk 
                inner join pasiendaftar_t pt on pt.norec = at2.noregistrasifk 
                left join pemakaianasuransi_t pa on pa.noregistrasifk = pt.norec

                inner join pasien_m pm2 on pm2.id = pt.nocmfk 
                inner join jeniskelamin_m jm on jm.id = pm2.objectjeniskelaminfk
                inner join pegawai_m pm3 on pm3.id = s.penulisresepfk 
                inner join ruangan_m rm on rm.id = s.ruanganfk 
                left join ruangan_m ra on ra.id = at2.objectruanganasalfk 
                left join kelompokpasien_m AS kp ON kp.id = pt.objectkelompokpasienlastfk
                where s.norec = '$norec'

            "))->first();
            $details = \DB::select(DB::raw("
                SELECT x.* FROM (select distinct row_number()over(partition by pt.rke, pm.namaproduk ORDER BY pt.rke asc)as no, pt.jeniskemasanfk, jr.jenisracikan, pt.rke,pt.dosis, pt.jumlah , pt.aturanpakai , pm.namaproduk, pm.kekuatan, pt.keteranganpakai,
                op.keteranganpakai as catatandokter, op.satuandosis, pt.hargasatuan, (((CASE WHEN pt.hargajual IS NULL THEN	0 ELSE pt.hargajual END - CASE WHEN pt.hargadiscount IS NULL THEN
		        0 ELSE pt.hargadiscount END) * pt.jumlah) + CASE WHEN pt.jasa IS NULL THEN	0 ELSE	pt.jasa	END	) as harga
                from pelayananpasien_t pt
                inner join produk_m pm on pm.id = pt.produkfk
                inner join jenisracikan_m jr on jr.id = pt.jenisobatfk
                inner join strukresep_t as sr on sr.norec = pt.strukresepfk
                inner join strukorder_t as so on so.norec = sr.orderfk
                left join orderpelayanan_t as op on op.strukorderfk = so.norec and op.rke = pt.rke 
                where strukresepfk = '$norec'
                and pt.isobat = true
                order by pt.rke asc, pt.keteranganpakai asc)as x where x.no = 1
            "));
        }else{
            echo 'Data Tidak ada ';
            return;
        }

        $skrining = collect(DB::select("
            select s.noresep, st.rpenulis, st.rtanggalresep, st.rklinis, st.rmr, st.rpasien,
            st.rtanggallahir,
            st.rberatbedan,
            st.rdokter,
            st.rruang,
            st.rstatusjamin,
            st.robat,
            st.rkekuatan,
            st.rjumlahobat, st.ketskrining, st.ridentitasdokter,st.rcarabayar,st.rruanganresep, st.rnamaobat, st.rstabilitas, st.raturan, st.ralergi, st.rinteraksi, st.rvariasi, st.rbeban, st.rdatawaktu 
            from strukresep_t s
            left join skriningfarmasi_t st on st.norec_apd = s.norec
            where s.norec = '$norec'
        "))->first();
    //    dd($details);
        $pageWidth = 550;
        //var_dump($skrining);

        // return $r['norec'];
        $cetakkin = 1;
        return view('report.apotik.resepdokterharga',
            compact('raw', 'pageWidth','r','details','profile', 'skrining','cetakkin'));
    }

    public function cetakCM05(Request $request)
    {
        $norec = $request['emr'];
        $kdProfile = (int) $request['kdprofile'];
        $data = DB::select(DB::raw("
        SELECT
            epd.emrdfk,
            ep.noemr,
            ed.TYPE,
            pa.namapasien,
            pa.tgllahir,
            pa.nohp,
            pa.nocm,
            ep.jeniskelamin,
            ep.umur,
            al.alamatlengkap,
            ep.noregistrasifk as noregistrasi ,
            epd.value,ep.namaruangan,pg.namalengkap as namadokter
            --case when ed.TYPE = 'datetime' then TO_CHAR(TO_TIMESTAMP(epd.value, 'YYYY-MM-DD HH24:MI:SS'),'YYYY-MM-DD HH24:MI:SS') else epd.value end as value
        FROM
            emrpasien_t AS ep
            INNER JOIN emrpasiend_t AS epd ON ep.noemr = epd.emrpasienfk
            INNER JOIN emrd_t AS ed ON epd.emrdfk = ed.ID
            LEFT JOIN antrianpasiendiperiksa_t AS pd ON pd.norec = ep.norec_apd
            left JOIN pegawai_m AS pg ON pg.id = pd.objectpegawaifk
            left JOIN pasien_m as pa on ep.nocm =  pa.nocm
            left JOIN alamat_m as al on pa.id = al.nocmfk
        WHERE
            ep.norec = '$norec'
                AND ep.kdprofile = '$kdProfile' 
            AND epd.statusenabled = TRUE 
            and epd.emrfk = $request[emrfk]
        ORDER BY
            ed.nourut
            "
        ));
        if (count($data) == 0) {
            return 'Data EMR tidak ditemukan atau belum disimpan.';
        }
        foreach ($data as $z){
            if ($z->type=="datetime"){
                $z->value=date('Y-m-d H:i:s',strtotime($z->value));
            }
//            $z->value = nl2br( $z->value);
        }
        // foreach ($data as $z){
        //     if (isset($z->tgllahir) ||isset($z->tgl)){
        //         $z->tgllahir=$this->tanggal_indonesia(date('Y-m-d',strtotime($z->tgllahir)));
        //         $z->tgl=$this->tanggal_indonesia(date('Y-m-d',strtotime($z->tgl)));
        //     }
            
        // }
        $res['profile'] = Profile::where('id',$request['kdprofile'])->first();
        $res['d'] = $data;
        // return view('report.cppt-ranap-dom',compact('res','pageWidth', 'data'));
        // dd($res);
        $item =[];   
        $item2= [];      
        foreach( $res['d'] as $items){
                if($items->type  ==  "textbox" ||$items->type  ==  "textarea"  ){
                    $item[$items->emrdfk] =  $items->value;
        }
                if($items->type  ==  "datetime"){
                    $item[$items->emrdfk] = $this->tanggal_indonesia(date('Y-m-d',strtotime( $items->value))) ;
                }
                if($items->type  ==  "time"){
                    $item[$items->emrdfk] = date('H:i',strtotime( $items->value));
                }
                if($items->type  ==  "date"){
                    $item[$items->emrdfk] = date('Y-m-d',strtotime( $items->value));
                }
                if($items->type  ==  "checkboxtextbox"){
                    $item[$items->emrdfk] =  $items->value;
                    $item2[$items->emrdfk] =  true;
                }
                if($items->type == "checkbox") {
                    $chekedd = false;
                    if ($items->value == '1') {
                        $chekedd = true;
                    }
                    $item[$items->emrdfk] = $chekedd;
                }
                if($items->type == "combobox") {
                    $arr = explode('~',$items->value );
                    $item[$items->emrdfk] = $arr[1];
                }
        }
        $noemr = '';
        if (count($data) > 0) {
            $noemr = $data[0]->noemr;
        }
        $listFoto = [];
        if ($noemr != '') {
            $listFoto = DB::table('emrfoto_t')
                ->where('noemrpasienfk', $noemr)
                ->where('emrfk', $request['emrfk'])
                ->where('statusenabled', true)
                ->get();
        }
        $fotoMap = [];
        foreach ($listFoto as $f) {
            $fotoMap[$f->emrdfk] = $f->image;
        }

        $pageWidth = 950;
        $peg = null;    
        if(isset($request['isttd']) && $request['isttd'] == true){
            $peg = DB::table('pegawai_m')->where('id',$request['pegawaittd'])->first();
            
        }
        // dd($data, $item);

        // var_dump($data);
        $pdf = PDF::loadView(
            'report.EMR.cmrm05-dom',
            array(
                'res' => $res,
                'pageWidth' => $pageWidth,
                'data' => $data,
                'item'=> $item,
                'peg'=> $peg,
                'fotoMap' => $fotoMap
            )
        );
        if(isset($request['isttd']) && $request['isttd'] == true){
            $objetoRequest = new \Illuminate\Http\Request();
            $objetoRequest ['emrfk'] = $request['emrfk'];
            $objetoRequest ['norec_emr'] = $request['emr'];
            $objetoRequest ['pegawaittd'] = $request['pegawaittd'];
            $objetoRequest ['nocm'] = $request['nocm'];
            $objetoRequest ['noregistrasi'] = $request['noregistrasi'];
