        $pdf = PDF::loadView(
            'report.EMR.rujukan-edukasi-pasien-dengan-komorbid-sindrome-geriatri-low-intake',
            array(
                'res' => $res,
                'pageWidth' => $pageWidth,
                'data' => $data,
                'item'=> $item,
