    public function pengajuanTTE(Request $request)
    {
        $kdProfile = 30;

        DB::beginTransaction();

        try {


            $prof =  DB::table('profile_m')->where('statusenabled', true)->first();

            if(isset($request['tipe']) && $request['tipe'] == 'resumemedis'){
                $emr = ResumeMedis::where('norec', $request['norec_emr'])->first();
                $emr->noemr = $emr->koderesume;
            }else{
                $emr = EMRPasien::where('norec', $request['norec_emr'])->first();
                $emr->noemr = $emr->noemr;

            }

            $emrM =  DB::table('emr_t')->where('id', $request['emrfk'])->first();

            $pegawai = Pegawai::where('id', $request['pegawaittd'])->first();
            $cek =  EMR_BSRE::where('nomoremr', $emr->noemr)
                ->where('emrfk', $request['emrfk'])->first();

            if (empty($cek)) {
                $idOK = EMR_BSRE::max('id') + 1;

                $filename_res = 'TTD_BSRE/' . $idOK . '/file' . '.pdf';
                $emrDkmn = new EMR_BSRE();
                $emrDkmn->id =  $idOK;
                $emrDkmn->kdprofile = $kdProfile;
                $emrDkmn->statusenabled = true;
            } else {
                $emrDkmn = $cek;
                $filename_res = 'TTD_BSRE/' . $cek->id . '/file' . '.pdf';
                $idOK =  $cek->id;
            }

            $emrDkmn->noregistrasi = $request['noregistrasi'];
            $emrDkmn->nocm = $request['nocm'];
            $emrDkmn->norec_pd = $request['norec_pd'];
            $emrDkmn->tglemr = date('Y-m-d H:i:s');
            $emrDkmn->file = 'app/' . $filename_res;
            $emrDkmn->namafile =  $emrM->caption;
            $emrDkmn->deskripsi = '';
            $emrDkmn->nik_pegawai = $pegawai->noidentitas;
            $emrDkmn->namadokumen = $emrM->caption;
            $emrDkmn->pegawaifk = $request['pegawaittd'];
            $emrDkmn->nomoremr = $emr->noemr;
            $emrDkmn->linkQR = 'https://simrs-grhasia.jogjaprov.go.id/service/medifirst2000/verify-doc/' . $idOK;
            $emrDkmn->passphrase = null;
            $emrDkmn->tampilan = 'visible';
            $emrDkmn->page = 1;
            $emrDkmn->xAxis = $emrM->bsre_xaxis ? $emrM->bsre_xaxis : 625;
            $emrDkmn->yAxis = $emrM->bsre_yaxis ? $emrM->bsre_yaxis : 70;
            $emrDkmn->width = $emrM->bsre_width ? $emrM->bsre_width : 251.46;
            $emrDkmn->height = $emrM->bsre_height ? $emrM->bsre_height : 133.13;
            $emrDkmn->location = $prof->namalengkap;
            $emrDkmn->emrfk =  $request['emrfk'];
            $emrDkmn->status = false;
            $emrDkmn->save();


            $transStatus = 'true';
        } catch (\Exception $e) {
            $transStatus = 'false';
        }

        if ($transStatus == 'true') {
            $transMessage = 'Sukses';
            DB::commit();
            $result = array(
                "status" => 201,
                "message" => $transMessage,
                "dokumen" => $emrDkmn,
                "as" => 'inhuman',
            );
        } else {
            $transMessage = "Terjadi kesalahan";
            DB::rollBack();
            $result = array(
                "status" => 400,
                "message" => $transMessage,
                "e" => $e->getMessage() . ' ' . $e->getLine(),
                "as" => 'inhuman',
            );
        }
        return  $result;
    }
    function cetakCatatanKonselingNapza(Request $request) {
        $norec = $request['emr'];
        $kdProfile = (int) $request['kdprofile'];
        $data = DB::select(DB::raw("
        SELECT
            epd.emrdfk,
            ep.noemr,
            ed.TYPE,
            pa.namapasien,
            pa.tgllahir,
            pa.nohp,
            pa.nocm,
            ep.jeniskelamin,
            ep.umur,
            al.alamatlengkap,
            ep.noregistrasifk as noregistrasi ,
            epd.value,ep.namaruangan,pg.namalengkap as namadokter
            --case when ed.TYPE = 'datetime' then TO_CHAR(TO_TIMESTAMP(epd.value, 'YYYY-MM-DD HH24:MI:SS'),'YYYY-MM-DD HH24:MI:SS') else epd.value end as value
        FROM
            emrpasien_t AS ep
            INNER JOIN emrpasiend_t AS epd ON ep.noemr = epd.emrpasienfk
            INNER JOIN emrd_t AS ed ON epd.emrdfk = ed.ID
                INNER JOIN antrianpasiendiperiksa_t AS pd ON pd.norec = ep.norec_apd
            left JOIN pegawai_m AS pg ON pg.id = pd.objectpegawaifk
            left JOIN pasien_m as pa on ep.nocm =  pa.nocm
            left JOIN alamat_m as al on pa.id = al.nocmfk
        WHERE
            ep.norec = '$norec'
                AND ep.kdprofile = '$kdProfile' 
            AND epd.statusenabled = TRUE 
            and epd.emrfk = $request[emrfk]
        ORDER BY
            ed.nourut
            "
        ));
        foreach ($data as $z){
            if ($z->type=="datetime"){
                $z->value=date('Y-m-d H:i:s',strtotime($z->value));
            }
//            $z->value = nl2br( $z->value);
        }
        // foreach ($data as $z){
        //     if (isset($z->tgllahir) ||isset($z->tgl)){
        //         $z->tgllahir=$this->tanggal_indonesia(date('Y-m-d',strtotime($z->tgllahir)));
        //         $z->tgl=$this->tanggal_indonesia(date('Y-m-d',strtotime($z->tgl)));
        //     }
            
        // }
        $res['profile'] = Profile::where('id',$request['kdprofile'])->first();
        $res['d'] = $data;
        // return view('report.cppt-ranap-dom',compact('res','pageWidth', 'data'));
        // dd($res);
        $item =[];   
        $item2= [];      
        foreach( $res['d'] as $items){
                if($items->type  ==  "textbox" ||$items->type  ==  "textarea"  ){
                    $item[$items->emrdfk] =  $items->value;
        }
                if($items->type  ==  "datetime"){
                    $item[$items->emrdfk] = $this->tanggal_indonesia(date('Y-m-d',strtotime( $items->value))) ;
                }
                if($items->type  ==  "time"){
                    $item[$items->emrdfk] = date('H:i',strtotime( $items->value));
                }
                if($items->type  ==  "date"){
                    $item[$items->emrdfk] = date('Y-m-d',strtotime( $items->value));
                }
                if($items->type  ==  "checkboxtextbox"){
                    $item[$items->emrdfk] =  $items->value;
                    $item2[$items->emrdfk] =  true;
                }
                if($items->type == "checkbox") {
                    $chekedd = false;
                    if ($items->value == '1') {
                        $chekedd = true;
                    }
                    $item[$items->emrdfk] = $chekedd;
                }
                if($items->type == "combobox") {
                    $arr = explode('~',$items->value );
                    $item[$items->emrdfk] = $arr[1];
                }
        }
        $pageWidth = 950;
        $peg = null;    
        if(isset($request['isttd']) && $request['isttd'] == true){
            $peg = DB::table('pegawai_m')->where('id',$request['pegawaittd'])->first();
            
        }
        // dd($res);
        $pdf = PDF::loadView(
            'report.EMR.catatankonseling-dom',
            array(
                'res' => $res,
                'pageWidth' => $pageWidth,
                'data' => $data,
                'item'=> $item,
                'peg'=> $peg
            )
        );
        if(isset($request['isttd']) && $request['isttd'] == true){
            $objetoRequest = new \Illuminate\Http\Request();
            $objetoRequest ['emrfk'] = $request['emrfk'];
            $objetoRequest ['norec_emr'] = $request['emr'];
            $objetoRequest ['pegawaittd'] = $request['pegawaittd'];
            $objetoRequest ['nocm'] = $request['nocm'];
            $objetoRequest ['noregistrasi'] = $request['noregistrasi'];
            $objetoRequest ['norec_pd'] = $request['norec_pd'];
            $bsre = app('App\Http\Controllers\Bridging\BridgingBSREController')->pengajuanTTE($objetoRequest,true);
            if($bsre['status'] == 201){
                $content = $pdf->download()->getOriginalContent();
                \Storage::disk('local')->put( 'TTD_BSRE/' . $bsre['dokumen']->id . '/file' . '.pdf' , $content);
            }
          
            return $bsre;
        }

        return $pdf->stream();
        // return view('report.EMR.suratketerangandokter',compact('data','pageWidth'));
    }
