    function cetakTriaseIGD(Request $request) {
        $norec = $request['emr'];
        $kdProfile = (int) $request['kdprofile'];
        $data = DB::select(DB::raw("
        SELECT
            epd.emrdfk,
            ep.noemr,
            ed.TYPE,
            pa.namapasien,
            pa.tgllahir,
            pa.nohp,
            pa.nocm,
            ep.jeniskelamin,
            ep.umur,
            al.alamatlengkap,
            ep.noregistrasifk as noregistrasi ,
            epd.value,ep.namaruangan,pg.namalengkap as namadokter
            --case when ed.TYPE = 'datetime' then TO_CHAR(TO_TIMESTAMP(epd.value, 'YYYY-MM-DD HH24:MI:SS'),'YYYY-MM-DD HH24:MI:SS') else epd.value end as value
        FROM
            emrpasien_t AS ep
            INNER JOIN emrpasiend_t AS epd ON ep.noemr = epd.emrpasienfk
            INNER JOIN emrd_t AS ed ON epd.emrdfk = ed.ID
                INNER JOIN antrianpasiendiperiksa_t AS pd ON pd.norec = ep.norec_apd
            left JOIN pegawai_m AS pg ON pg.id = pd.objectpegawaifk
            left JOIN pasien_m as pa on ep.nocm =  pa.nocm
            left JOIN alamat_m as al on pa.id = al.nocmfk
        WHERE
            ep.norec = '$norec'
                AND ep.kdprofile = '$kdProfile' 
            AND epd.statusenabled = TRUE 
            and epd.emrfk = $request[emrfk]
        ORDER BY
            ed.nourut
            "
        ));
        foreach ($data as $z){
            if ($z->type=="datetime"){
                $z->value=date('Y-m-d H:i:s',strtotime($z->value));
            }
//            $z->value = nl2br( $z->value);
        }
        // foreach ($data as $z){
        //     if (isset($z->tgllahir) ||isset($z->tgl)){
        //         $z->tgllahir=$this->tanggal_indonesia(date('Y-m-d',strtotime($z->tgllahir)));
        //         $z->tgl=$this->tanggal_indonesia(date('Y-m-d',strtotime($z->tgl)));
        //     }
            
        // }
        $res['profile'] = Profile::where('id',$request['kdprofile'])->first();
        $res['d'] = $data;
        // return view('report.cppt-ranap-dom',compact('res','pageWidth', 'data'));
        // dd($res);
        $item =[];   
        $item2= [];      
        foreach( $res['d'] as $items){
                if($items->type  ==  "textbox" ||$items->type  ==  "textarea"  ){
                    $item[$items->emrdfk] =  $items->value;
        }
                if($items->type  ==  "datetime"){
                    $item[$items->emrdfk] = $this->tanggal_indonesia(date('Y-m-d',strtotime( $items->value))) ;
                    $item[$items->emrdfk . "time"] = date('H:i',strtotime( $items->value)) ;
                }
                if($items->type  ==  "time"){
                    $item[$items->emrdfk] = date('H:i',strtotime( $items->value));
                }
                if($items->type  ==  "date"){
                    $item[$items->emrdfk] = date('Y-m-d',strtotime( $items->value));
                }
                if($items->type  ==  "checkboxtextbox"){
                    $item[$items->emrdfk] =  $items->value;
                    $item2[$items->emrdfk] =  true;
                }
                if($items->type == "checkbox") {
                    $chekedd = false;
                    if ($items->value == '1') {
                        $chekedd = true;
                    }
                    $item[$items->emrdfk] = $chekedd;
                }
                if($items->type == "combobox") {
                    $arr = explode('~',$items->value );
                    $item[$items->emrdfk] = $arr[1];
                }
        }
        $pageWidth = 950;
        $peg = null;    
        if(isset($request['isttd']) && $request['isttd'] == true){
            $peg = DB::table('pegawai_m')->where('id',$request['pegawaittd'])->first();
            
        }
        // var_dump($data);
        // dd(array(
        //     'res' => $res,
        //     'pageWidth' => $pageWidth,
        //     'data' => $data,
        //     'item'=> $item,
        //     'peg'=> $peg
        // ));
        $pdf = PDF::loadView(
            'report.EMR.formulirtriaseigd',
            array(
                'res' => $res,
                'pageWidth' => $pageWidth,
                'data' => $data,
                'item'=> $item,
                'peg'=> $peg
            )
        );
        $pdf->setPaper('A4', 'portrait');
        if(isset($request['isttd']) && $request['isttd'] == true){
            $objetoRequest = new \Illuminate\Http\Request();
            $objetoRequest ['emrfk'] = $request['emrfk'];
            $objetoRequest ['norec_emr'] = $request['emr'];
            $objetoRequest ['pegawaittd'] = $request['pegawaittd'];
            $objetoRequest ['nocm'] = $request['nocm'];
            $objetoRequest ['noregistrasi'] = $request['noregistrasi'];
            $objetoRequest ['norec_pd'] = $request['norec_pd'];
            $bsre = app('App\Http\Controllers\Bridging\BridgingBSREController')->pengajuanTTE($objetoRequest,true);
            if($bsre['status'] == 201){
                $content = $pdf->download()->getOriginalContent();
                \Storage::disk('local')->put( 'TTD_BSRE/' . $bsre['dokumen']->id . '/file' . '.pdf' , $content);
            }
          
            return $bsre;
        }

        if (isset($request["issimpanberkas"])) {
            $pdf = PDF::loadView(
                'report.EMR.formulirtriaseigd',
                array(
                    'res' => $res,
                    'pageWidth' => $pageWidth,
                    'data' => $data,
                    'item'=> $item,
                    'peg'=> $peg,
                    'r' => $request
                )
            );
            return $this->saveDokumenKlaim($pdf, $request);
        } else {
            return $pdf->stream();
        }
    }

    public function cetakDistribusiAlat(Request $request)
    {
        $profile = (int)$request['kdprofile'];
        $norec = $request['norec'];
        $pageWidth = 950;

        // Mengambil data struk kirim
        $data = DB::table('strukkirim_t AS st')
            ->select(
                'st.norec', 
                'st.nokirim AS noorder', 
                'st.tglkirim AS tglorder',
                'ru.namaruangan AS namaruangan', 
                'pg.namalengkap AS namapengorder'
            )
            ->leftJoin('ruangan_m AS ru', 'ru.id', '=', 'st.objectruangantujuanfk')
            ->leftJoin('pegawai_m AS pg', 'pg.id', '=', 'st.objectpegawaipengirimfk')
            ->where('st.kdprofile', $profile)
            ->where('st.norec', $norec)
            ->where('st.statusenabled', true)
            ->first(); // Menggunakan first() untuk mendapatkan satu baris data saja

        // Pengecekan apakah data ditemukan sebelum mencoba mengakses propertinya
        if ($data) {
            // Mengambil detail dari tabel kirimproduk_t berdasarkan nokirimfk
            $detailOrders = DB::table('kirimproduk_t AS kp')
                ->select(
                    'prd.kdproduk',
                    'prd.namaproduk',
                    'sat.satuanstandar',
                    'kp.qtyproduk'
                )
                ->leftJoin('produk_m AS prd', 'prd.id', '=', 'kp.objectprodukfk')
                ->leftJoin('satuanstandar_m AS sat', 'sat.id', '=', 'prd.objectsatuanstandarfk')
                ->where('kp.kdprofile', $profile)
                ->where('kp.nokirimfk', $norec)
                ->get();

            // Menambahkan properti detailOrders ke dalam objek data
            $data->jmlitem = count($detailOrders);
            $data->detailsOrder = $detailOrders;
        } else {
            // Data tidak ditemukan, respons halaman tidak ditemukan
            abort(404);
        }

        // Mengembalikan respons
        return view(
            'report.cssd.report-monitoring',
            compact('data', 'pageWidth')
        );
    }

    public function cetakDaftarBarangAsset(Request $request)
    {
        $kdProfile = (int) $request['kodeprofile'];

        $data = \DB::table('registrasiaset_t as ra')
            ->leftJOIN('strukpelayanan_t as sp','sp.norec','=','ra.nostrukterimafk')
            ->leftJOIN('strukpelayanandetail_t as spd','spd.norec','=','ra.nostrukterimadetailfk')
            ->leftJOIN('produk_m as pr','pr.id','=','ra.objectprodukfk')
            ->leftJOIN('merkproduk_m as mrk', 'mrk.id', '=', 'ra.objectmerkprodukfk')
            ->leftJOIN('detailjenisproduk_m as djp','djp.id','=','pr.objectdetailjenisprodukfk')
            ->leftJOIN('jenisproduk_m as jp','jp.id','=','djp.objectjenisprodukfk')
            ->leftJOIN('kelompokproduk_m as kp','kp.id','=','jp.objectkelompokprodukfk')
            ->leftJOIN('satuanstandar_m as ss','ss.id','=','pr.objectsatuanstandarfk')
            ->leftJOIN('asalproduk_m as ap','ap.id','=','ra.objectasalprodukfk')
            // ->leftJOIN('ruangan_m as ru','ru.id','=','ra.objectruanganfk')
            ->leftJOIN('ruanganasset_m as ru1','ru1.id','=','ra.objectruanganposisicurrentfk')
            ->leftJOIN('rekanan_m as rek','rek.id','=','ra.objectsupplier')
            ->select('ra.norec','ra.noregisteraset','ra.objectprodukfk as kdproduk','pr.namaproduk','jp.jenisproduk',
                     'ru1.id as ruanganasalfk','ru1.namaruangan as namaruanganasal',
                     'ra.tglregisteraset','ra.tglstrukterima','ra.qtyprodukaset','ra.hargaperolehan','ra.tglregisteraset','ra.tglstrukterima',
                     'rek.namarekanan as namasupplier','rek.alamatlengkap as almSupplier','sp.norec as norecsp',
                     'spd.norec as norecspd','ap.asalproduk','ra.keteranganlainnya','ra.spesifikasi','ra.jenisaset','ra.judul','ra.kdbmn', 'ra.koderegisterrs', 'ra.tahunperolehan', 'pr.deskripsiproduk', 'mrk.merkproduk', 'ra.nilaisisa')
            ->where('ra.kdprofile', $kdProfile)
            ->where('ra.statusenabled', true)
            ->where('pr.statusenabled', true)
            ->when($request['tglAwal'], function($query) use ($request){
                return $query->where('ra.tglregisteraset', '>=', $request['tglAwal']);
            })
            ->when($request['tglAkhir'], function($query) use ($request){
                return $query->where('ra.tglregisteraset', '<=', $request['tglAkhir']);
            })
            ->orderBy('ra.noregisteraset')
            ->get();

        return view('report.asset.cetak-label', compact('data'));
    }

    public function cetakKartuInventarisRuangan(Request $request)
    {
        $kdProfile = (int) $request['kodeprofile'];

        $data = DB::select(
            DB::raw("
                SELECT
                    x.namaruangansekarang,

                    x.namaproduk,
                    x.merkproduk,
                    x.noseri,
                    x.norangka,
                    x.nomesin,
                    x.nobpkb,
                    x.nopolisi,
                    x.namabahanproduk,
                    x.tahunperolehan AS tahun,
                    x.kdbmn,
                    COUNT(x.idprodukfk) as jumlah,
                    array_to_string(ARRAY_AGG( x.koderegisterrs ), '-' ) AS registerasset,
                    x.hargaperolehan,
                    x.keteranganlainnya,
                    x.kondisibarangfk,
                    x.spesifikasi
                FROM
                    (
                        SELECT
                            ra.noregisteraset,
                            ru.namaruangan as namaruangansekarang,
                            ra.idprodukfk,

                            pr.namaproduk,
                            mrk.merkproduk,
                            ra.noseri,
                            ra.norangka,
                            ra.nomesin,
                            ra.nobpkb,
                            ra.nopolisi,
                            coalesce(ra.spesifikasi,'-') as spesifikasi,
                            bp.namabahanproduk,
                            ra.tahunperolehan,
                            ra.kdbmn,
                            ra.koderegisterrs,
                            ra.hargaperolehan,
                            ra.kondisibarangfk,
                            ra.keteranganlainnya,
                            coalesce(ra.keteranganlainnya,'-'),
                            cha1.kodeakun as kode1,
                            cha2.kodeakun as kode2,
                            cha3.kodeakun as kode3,
                            cha4.kodeakun as kode4,
                            cha5.kodeakun as kode5,
                            cha6.kodeakun as kode6
                        FROM
                            registrasiaset_t AS ra
                            LEFT JOIN strukpelayanan_t AS sp ON sp.norec = ra.nostrukterimafk
                            LEFT JOIN strukpelayanandetail_t AS spd ON spd.norec = ra.nostrukterimadetailfk
                            LEFT JOIN produk_m AS pr ON pr.id = ra.idprodukfk
                            LEFT JOIN merkproduk_m AS mrk ON mrk.id = ra.objectmerkprodukfk
                            LEFT JOIN detailjenisproduk_m AS djp ON djp.id = pr.objectdetailjenisprodukfk
                            LEFT JOIN jenisproduk_m AS jp ON jp.id = djp.objectjenisprodukfk
                            LEFT JOIN kelompokproduk_m AS kp ON kp.id = jp.objectkelompokprodukfk
                            LEFT JOIN satuanstandar_m AS ss ON ss.id = pr.objectsatuanstandarfk
                            LEFT JOIN asalproduk_m AS ap ON ap.id = ra.objectasalprodukfk
                            LEFT JOIN ruanganasset_m AS ru ON ru.id = ra.objectruanganposisicurrentfk
                            LEFT JOIN rekanan_m AS rek ON rek.id = ra.objectsupplier
                            LEFT JOIN bahanproduk_m AS bp ON bp.id = ra.objectbahanprodukfk
                            LEFT JOIN kondisibarang_m AS kb ON kb.id = ra.kondisibarangfk
                            INNER JOIN charkodeakunasset_m AS cha6 ON cha6.id = pr.objectprodukassetfk
                            INNER JOIN charkodeakunasset_m AS cha1 ON cha1.ID = cha6.idlevel1
                            INNER JOIN charkodeakunasset_m AS cha2 ON cha2.ID = cha6.idlevel2
                            INNER JOIN charkodeakunasset_m AS cha3 ON cha3.ID = cha6.idlevel3
                            INNER JOIN charkodeakunasset_m AS cha4 ON cha4.ID = cha6.idlevel4
                            INNER JOIN charkodeakunasset_m AS cha5 ON cha5.ID = cha6.idlevel5
                        WHERE
                            ra.kdprofile=$kdProfile
                            AND ra.objectruanganposisicurrentfk=".$request['ruangancurrenfk']."
                        ORDER BY
                            CAST(cha1.kodeakun AS DECIMAL), 
                            CAST(SPLIT_PART(cha2.kodeakun, '.', 3) AS DECIMAL),
                            CAST(SPLIT_PART(cha3.kodeakun, '.', 4) AS DECIMAL),
                            CAST(SPLIT_PART(cha4.kodeakun, '.', 5) AS DECIMAL),
                            CAST(SPLIT_PART(cha5.kodeakun, '.', 6) AS DECIMAL),
                            CAST(SPLIT_PART(cha6.kodeakun, '.', 7) AS DECIMAL),
                            ra.noregisteraset,
                            ra.koderegisterrs
                            asc 
                    ) x 
                GROUP BY
                    x.namaruangansekarang,
                    
                    x.namaproduk,
                    x.merkproduk,
                    x.noseri,
                    x.norangka,
                    x.nomesin,
                    x.nobpkb,
                    x.nopolisi,
                    x.spesifikasi,
                    x.namabahanproduk,
                    tahun,
                    x.kdbmn,
                    x.hargaperolehan,
                    x.keteranganlainnya,
                    x.kondisibarangfk,
                    x.spesifikasi,
                    x.kode1,
                    x.kode2,
                    x.kode3,
                    x.kode4,
                    x.kode5,
                    x.kode6
                ORDER BY
                    CAST(x.kode1 AS DECIMAL), 
                    CAST(SPLIT_PART(x.kode2, '.', 3) AS DECIMAL),
                    CAST(SPLIT_PART(x.kode3, '.', 4) AS DECIMAL),
                    CAST(SPLIT_PART(x.kode4, '.', 5) AS DECIMAL),
                    CAST(SPLIT_PART(x.kode5, '.', 6) AS DECIMAL),
                    CAST(SPLIT_PART(x.kode6, '.', 7) AS DECIMAL)
                    asc
            ")
        );

        $kondisibarang = DB::table('kondisibarang_m')->where('statusenabled', true)->orderBy('id')->get();

        $dataKepala = DB::table('pegawai_m')->where('id', $request['idkepala'])->first();

        $dataPenanggung = DB::table('pegawai_m')->where('id', $request['idpenanggung'])->first();

        return view('report.asset.kartu-inventaris-ruangan', compact('data', 'dataKepala', 'dataPenanggung', 'kondisibarang'));
    }


    public function cetakKIBB(Request $request)
    {
        $kdProfile = (int) $request['kdprofile'];
        
        $query = DB::select(DB::raw("
        SELECT
            ap.asalproduk,
            pr.namaproduk,
            pr.deskripsiproduk,
            mrk.merkproduk,
            bhn.namabahanproduk,
            ra.koderegisterrs,
            ra.tahunperolehan,
            ra.norangka,
            ra.nomesin,
            ra.nopolisi,
            ra.nobpkb,
            ra.hargaperolehan,
            ra.kdprofile,
            ra.keteranganlainnya,
            cha1.ID AS idcha1,
            cha1.kodeakun AS kodeakuncha1,
            cha1.urian AS uriancha1,
            cha2.ID AS idcha2,
            cha2.kodeakun AS kodeakuncha2,
            cha2.urian AS uriancha2,
            cha3.ID AS idcha3,
            cha3.kodeakun AS kodeakuncha3,
            cha3.urian AS uriancha3,
            cha4.ID AS idcha4,
            cha4.kodeakun AS kodeakuncha4,
            cha4.urian AS uriancha4,
            cha5.ID AS idcha5,
            cha5.kodeakun AS kodeakuncha5,
            cha5.urian AS uriancha5,
            cha6.ID AS idcha6,
            cha6.kodeakun AS kodeakuncha6,
            cha6.urian AS uriancha6 
        FROM
            registrasiaset_t AS ra
            INNER JOIN produk_m AS pr ON pr.ID = ra.idprodukfk
            INNER JOIN charkodeakunasset_m AS cha6 ON cha6.id = pr.objectprodukassetfk
            INNER JOIN charkodeakunasset_m AS cha1 ON cha1.ID = cha6.idlevel1
            INNER JOIN charkodeakunasset_m AS cha2 ON cha2.ID = cha6.idlevel2
            INNER JOIN charkodeakunasset_m AS cha3 ON cha3.ID = cha6.idlevel3
            INNER JOIN charkodeakunasset_m AS cha4 ON cha4.ID = cha6.idlevel4
            INNER JOIN charkodeakunasset_m AS cha5 ON cha5.ID = cha6.idlevel5
            LEFT JOIN bahanproduk_m AS bhn ON bhn.ID = ra.objectbahanprodukfk
            LEFT JOIN merkproduk_m AS mrk ON mrk.ID = ra.objectmerkprodukfk
            LEFT JOIN asalproduk_m AS ap ON ap.ID = ra.objectasalprodukfk
        WHERE
            ra.kdprofile=".$kdProfile."
            AND ra.statusenabled= TRUE
            AND ra.objectkelompokasetfk=".$request['kelompokaset']."
            AND pr.statusenabled = TRUE 
        ORDER BY
            CAST(cha1.kodeakun AS DECIMAL), 
            CAST(SPLIT_PART(cha2.kodeakun, '.', 3) AS DECIMAL),
            CAST(SPLIT_PART(cha3.kodeakun, '.', 4) AS DECIMAL),
            CAST(SPLIT_PART(cha4.kodeakun, '.', 5) AS DECIMAL),
            CAST(SPLIT_PART(cha5.kodeakun, '.', 6) AS DECIMAL),
            CAST(SPLIT_PART(cha6.kodeakun, '.', 7) AS DECIMAL),
            CAST(SPLIT_PART(ra.noregisteraset, 'AST', 2) AS DECIMAL)
             asc
        "));

        // dd($query);

        return view('report.asset.kibb', [
            'data' => $query
        ]);
    }

    public function cetakAPDBulanan(Request $request)
    {
        $kdProfile = (int) $request['kdprofile'];

        $masterdata = DB::table('auditapd_m')
            ->where('kdprofile', $kdProfile)
            ->where('statusenabled', true)
            ->get();

        $data = DB::table('auditapd_t as au')
            ->select('au.*', 'pg.namalengkap as observer', 'jp.jenispegawai as profesi', 'pr.namaaktifitas', 'ru.namaruangan')
            ->join('pegawai_m as pg', 'au.objectpegawaifk', '=', 'pg.id')
            ->join('jenispegawai_m as jp', 'au.objectjenispegawaifk', '=', 'jp.id')
            ->join('aktifitas_ppi_m as pr', DB::raw('CAST(au.jenisaktifitas AS INTEGER)'), '=', 'pr.id')
            ->join('ruangan_m as ru', 'ru.id', '=', 'au.objectruanganfk')
            ->where('au.kdprofile', $kdProfile)
            ->where('au.statusenabled', true)
            ->when($request['objectruanganfk'], function($query) use ($request) {
                return $query->where('au.objectruanganfk', $request['objectruanganfk']);
            })
            ->whereRaw('to_char(au.tanggal, \'MM-YYYY\') = ?', [$request['bulan']])
            ->where('au.isverifikasi', true)
            ->orderBy('au.tanggal', 'desc')
            ->get();
        
        $datadetail = DB::table('auditapd_t as apd')
            ->select('apddt.*')
            ->join('auditapddetail_t as apddt', 'apd.norec', '=', 'apddt.norecauditapd')
            ->where('apd.kdprofile', $kdProfile)
            ->where('apd.statusenabled', true)
            ->when($request['objectruanganfk'], function($query) use ($request) {
                return $query->where('apd.objectruanganfk', $request['objectruanganfk']);
            })
            ->whereRaw('to_char(apd.tanggal, \'MM-YYYY\') = ?', [$request['bulan']])
            ->get();

        $masterapd = array();
        $masterkesesuaian = array();
        $mastercucitangan = array();

        foreach($masterdata as $md){
            if($md->header == 'Pilihan APD'){
                array_push($masterapd, $md);
            }
            if($md->header == 'Kesesuaian'){
                array_push($masterkesesuaian, $md);
            }
            if($md->header == 'Cuci Tangan Sebelum Menggunakan APD'){
                array_push($mastercucitangan, $md);
            }
        }

        foreach($data as $item){
            $item->pilihanAPD = array();
            $item->kesesuaian = null;
            $item->cucitangan = null;

            foreach($masterdata as $md){

                foreach($datadetail as $dt){
                    if($dt->norecauditapd == $item->norec){
                        if($dt->auditapdfk == $md->id && $md->header == 'Pilihan APD'){
                            array_push($item->pilihanAPD, $md);
                        }
                        if($dt->auditapdfk == $md->id && $md->header == 'Kesesuaian'){
                            $item->kesesuaian = $md;
                        }
                        if($dt->auditapdfk == $md->id && $md->header == 'Cuci Tangan Sebelum Menggunakan APD'){
                            $item->cucitangan = $md;
                        }
                    }
                }
            }
        }

        // dd($data);

        return view('report.apd.laporan-bulanan-apd', [
            'data' => $data,
            'masterapd' => $masterapd,
            'masterkesesuaian' => $masterkesesuaian,
            'mastercucitangan' => $mastercucitangan
        ]);

        // return response()->json([
        //     'masterapd' => $masterapd,
        //     'masterkesesuaian' => $masterkesesuaian,
        //     'mastercucitangan' => $mastercucitangan
        // ]);
    }
    public function cetakAPDTahun(Request $request)
    {
        $kdProfile = (int) $request['kdprofile'];
        $tahun = $request['tahun'];

        $dataRuangan = DB::table('ruangan_m')
            ->where('kdprofile', $kdProfile)
            ->where('statusenabled', true)
            ->when($request['objectruanganfk'], function($query) use ($request) {
                return $query->where('id', $request['objectruanganfk']);
            })
            ->orderBy('namaruangan', 'asc')
            ->get();

        $hasilRuangan = [];
        foreach ($dataRuangan as $r) {
            $hasilRuangan[$r->id] = [
                'namaruangan' => $r->namaruangan,
                'statistik_bulanan' => [],
                'rata_tahunan' => 0,
                'total_audit' => 0,
                'total_sesuai' => 0
            ];
            
            for ($bulan = 1; $bulan <= 12; $bulan++) {
                $strBulan = sprintf("%02d", $bulan);
                $hasilRuangan[$r->id]['statistik_bulanan'][$strBulan] = [
                    'total' => 0,
                    'sesuai' => 0,
                    'persentase' => 0
                ];
            }
        }

        $statistikRumahSakit = [];
        for ($bulan = 1; $bulan <= 12; $bulan++) {
            $strBulan = sprintf("%02d", $bulan);
            $statistikRumahSakit[$strBulan] = [
                'total' => 0,
                'sesuai' => 0,
                'persentase' => 0
            ];
        }

        for ($bulan = 1; $bulan <= 12; $bulan++) {
            $strBulan = sprintf("%02d", $bulan);
            
          
            $dataBulanan = DB::table('auditapd_t as au')
                ->select(
                    'au.objectruanganfk',
                    DB::raw('COUNT(au.norec) as total_audits'),
                    DB::raw('SUM(CASE WHEN EXISTS (
                        SELECT 1 FROM auditapddetail_t as apddt 
                        JOIN auditapd_m as apdm ON apdm.id = apddt.auditapdfk 
                        WHERE apddt.norecauditapd = au.norec 
                        AND apdm.header = \'Kesesuaian\' 
                        AND apdm.description LIKE \'%Sesuai%\'
                    ) THEN 1 ELSE 0 END) as total_sesuai')
                )
                ->where('au.kdprofile', $kdProfile)
                ->where('au.statusenabled', true)
                ->where('au.isverifikasi', true)
                ->whereRaw('EXTRACT(MONTH FROM au.tanggal) = ?', [$bulan])
                ->whereRaw('EXTRACT(YEAR FROM au.tanggal) = ?', [$tahun])
                ->when($request['objectruanganfk'], function($query) use ($request) {
                    return $query->where('au.objectruanganfk', $request['objectruanganfk']);
                })
                ->groupBy('au.objectruanganfk')
                ->get();
            
           
            foreach ($dataBulanan as $data) {
                if (isset($hasilRuangan[$data->objectruanganfk])) {
                    $hasilRuangan[$data->objectruanganfk]['statistik_bulanan'][$strBulan]['total'] = $data->total_audits;
                    $hasilRuangan[$data->objectruanganfk]['statistik_bulanan'][$strBulan]['sesuai'] = $data->total_sesuai;
                    
                    if ($data->total_audits > 0) {
                        $persentase = round(($data->total_sesuai / $data->total_audits) * 100, 2);
                        $hasilRuangan[$data->objectruanganfk]['statistik_bulanan'][$strBulan]['persentase'] = $persentase;
                    }
              
                    $statistikRumahSakit[$strBulan]['total'] += $data->total_audits;
                    $statistikRumahSakit[$strBulan]['sesuai'] += $data->total_sesuai;

                    $hasilRuangan[$data->objectruanganfk]['total_audit'] += $data->total_audits;
                    $hasilRuangan[$data->objectruanganfk]['total_sesuai'] += $data->total_sesuai;
                }
            }
        }
        
        foreach ($hasilRuangan as $ruanganId => &$ruangan) {
            $totalPersentase = 0;
            $bulanDenganData = 0;
            
            foreach ($ruangan['statistik_bulanan'] as $bulan => $statistik) {
                if ($statistik['total'] > 0) {
                    $totalPersentase += $statistik['persentase'];
                    $bulanDenganData++;
                }
            }
            
            if ($bulanDenganData > 0) {
                $ruangan['rata_tahunan'] = round($totalPersentase / $bulanDenganData, 2);
            } else if ($ruangan['total_audit'] > 0) {
                $ruangan['rata_tahunan'] = round(($ruangan['total_sesuai'] / $ruangan['total_audit']) * 100, 2);
            }
        }
        
        foreach ($statistikRumahSakit as $bulan => &$statistik) {
            if ($statistik['total'] > 0) {
                $statistik['persentase'] = round(($statistik['sesuai'] / $statistik['total']) * 100, 2);
            }
        }

        $totalPersentaseRS = 0;
        $bulanDenganDataRS = 0;
        $totalAuditRS = 0;
        $totalSesuaiRS = 0;
        
        foreach ($statistikRumahSakit as $bulan => $statistik) {
            if ($statistik['total'] > 0) {
                $totalPersentaseRS += $statistik['persentase'];
                $bulanDenganDataRS++;
                $totalAuditRS += $statistik['total'];
                $totalSesuaiRS += $statistik['sesuai'];
            }
        }
        
        $rataRataRS = 0;
        if ($bulanDenganDataRS > 0) {
            $rataRataRS = round($totalPersentaseRS / $bulanDenganDataRS, 2);
        } else if ($totalAuditRS > 0) {
            $rataRataRS = round(($totalSesuaiRS / $totalAuditRS) * 100, 2);
        }

        foreach ($hasilRuangan as $ruanganId => $ruangan) {
            if ($ruangan['total_audit'] == 0) {
                unset($hasilRuangan[$ruanganId]);
            }
        }

        return view('report.apd.laporan-tahunan-apd', [
            'ruanganData' => $hasilRuangan,
            'statistikBulan' => $statistikRumahSakit,
            'statistikTahun' => $rataRataRS,
            'tahun' => $tahun
        ]);
    }
    

    public function cetakHygieneBulanan(Request $request)
    {
        $kdProfile = (int) $request['kdprofile'];

        $masterHygiene = DB::table('audithygiene_m')
        ->where('kdprofile', $kdProfile)
        ->where('statusenabled', true)
        ->orderBy('id')
        ->get();

        $data = DB::table('audithygiene_t as au')
        ->select('au.*', 'pg.namalengkap as observer', 'jp.jenispegawai as profesi', 'ru.namaruangan')
        ->join('pegawai_m as pg', 'au.objectpegawaifk', '=', 'pg.id')
        ->join('jenispegawai_m as jp', 'au.objectjenispegawaifk', '=', 'jp.id')
        ->join('ruangan_m as ru', 'ru.id', '=', 'au.objectruanganfk')
        ->where('au.kdprofile', $kdProfile)
        ->where('au.statusenabled', true)
        ->where('au.objectruanganfk', $request['objectruanganfk'])
        ->whereRaw('to_char(au.tanggal, \'MM-YYYY\') = ?', [$request['bulan']])
        ->orderBy('au.tanggal', 'desc')
        ->get();

        $detailHygiene = DB::table('audithygiene_t as apd')
        ->select('apddt.*')
        ->join('audithygienedetail_t as apddt', 'apd.norec', '=', 'apddt.norecaudithygiene')
        ->where('apd.kdprofile', $kdProfile)
        ->where('apd.statusenabled', true)
        ->where('apd.objectruanganfk', $request['objectruanganfk'])
        ->whereRaw('to_char(apd.tanggal, \'MM-YYYY\') = ?', [$request['bulan']])
        ->get();

        $masterSebelumKontak = array();
        $masterSebelumProsedur = array();
        $masterSetelahCairan = array();
        $masterSetelahKontak = array();
        $masterSetelahLingkungan = array();
        $masterLainLain = array();

        foreach($masterHygiene as $mhygiene){
            if($mhygiene->header == 'Sebelum kontak dengan pasien'){
                array_push($masterSebelumKontak, $mhygiene);
            }
            if($mhygiene->header == 'Sebelum melakukan prosedur bersih/tindakan aseptik'){
                array_push($masterSebelumProsedur, $mhygiene);
            }
            if($mhygiene->header == 'Setelah kontak dengan cairan tubuh pasien'){
                array_push($masterSetelahCairan, $mhygiene);
            }
            if($mhygiene->header == 'Setelah kontak dengan pasien'){
                array_push($masterSetelahKontak, $mhygiene);
            }
            if($mhygiene->header == 'Setelah kontak dengan lingkungan pasien'){
                array_push($masterSetelahLingkungan, $mhygiene);
            }
            if($mhygiene->header == 'Lain-lain'){
                array_push($masterLainLain, $mhygiene);
            }
        }

        foreach($data as $hygiene){

            $hygiene->sebelumKontak = array();
            $hygiene->sebelumProsedur = array();
            $hygiene->setelahCairan = array();
            $hygiene->setelahKontak = array();
            $hygiene->setelahLingkungan = array();
            $hygiene->lainLain = array();

            foreach($masterHygiene as $mhygiene){
                
                foreach($detailHygiene as $dthygiene){

                    if($dthygiene->norecaudithygiene == $hygiene->norec){

                        if($dthygiene->audithygienefk == $mhygiene->id && $mhygiene->header == 'Sebelum kontak dengan pasien'){
                            array_push($hygiene->sebelumKontak, $mhygiene);
                        }
                        if($dthygiene->audithygienefk == $mhygiene->id && $mhygiene->header == 'Sebelum melakukan prosedur bersih/tindakan aseptik'){
                            array_push($hygiene->sebelumProsedur, $mhygiene);
                        }
                        if($dthygiene->audithygienefk == $mhygiene->id && $mhygiene->header == 'Setelah kontak dengan cairan tubuh pasien'){
                            array_push($hygiene->setelahCairan, $mhygiene);
                        }
                        if($dthygiene->audithygienefk == $mhygiene->id && $mhygiene->header == 'Setelah kontak dengan pasien'){
                            array_push($hygiene->setelahKontak, $mhygiene);
                        }
                        if($dthygiene->audithygienefk == $mhygiene->id && $mhygiene->header == 'Setelah kontak dengan lingkungan pasien'){
                            array_push($hygiene->setelahLingkungan, $mhygiene);
                        }
                        if($dthygiene->audithygienefk == $mhygiene->id && $mhygiene->header == 'Lain-lain'){
                            array_push($hygiene->lainLain, $mhygiene);
                        }
                    }
                }
            }
        }

        return view('report.hygiene.laporan-bulanan-hygiene', [
            'data' => $data,
            'masterSebelumKontak' => $masterSebelumKontak,
            'masterSebelumProsedur' => $masterSebelumProsedur,
            'masterSetelahCairan' => $masterSetelahCairan,
            'masterSetelahKontak' => $masterSetelahKontak,
            'masterSetelahLingkungan' => $masterSetelahLingkungan,
            'masterLainLain' => $masterLainLain,
        ]);
        // return response()->json([
        //     'masterSebelumKontak' => $masterSebelumKontak,
        //     'masterSebelumProsedur' => $masterSebelumProsedur,
        //     'masterSetelahCairan' => $masterSetelahCairan,
        //     'masterSetelahKontak' => $masterSetelahKontak,
        //     'masterSetelahLingkungan' => $masterSetelahLingkungan,
        //     'masterLainLain' => $masterLainLain,
        // ]);

    }

    public function cetakJumlahAPD(Request $request)
    {
        $kdProfile = (int) $request['kdprofile'];

        $masterAPD = DB::table('auditapd_m')
            ->where('kdprofile', $kdProfile)
            ->where('statusenabled', true)
            ->orderBy('id', 'asc')
            ->get();

        $apdDetail = DB::table('auditapd_t as apd')
            ->select(DB::raw('apdm.description, COUNT(apddt.norec) as jumlah_pemakaian, MIN(ru.namaruangan) AS namaruangan, MIN(apdm.id) AS idmasterapd, MIN(apdm.description) as deskripsi, MIN(apd.tanggal) as tanggal_apd'))
            ->join('auditapddetail_t as apddt', 'apddt.norecauditapd', '=', 'apd.norec')
            ->join('auditapd_m as apdm', 'apdm.id', '=', 'apddt.auditapdfk')
            ->join('ruangan_m as ru', 'ru.id', '=', 'apd.objectruanganfk')
            ->where('apd.kdprofile', $kdProfile)
            ->where('apd.statusenabled', true)
            ->where('apd.isverifikasi', true)
            ->when($request['objectruanganfk'], function($query) use ($request) {
                return $query->where('apd.objectruanganfk', $request['objectruanganfk']);
            })
            ->whereRaw('to_char(apd.tanggal, \'MM-YYYY\') = ?', [$request['bulan']])
            ->groupBy('apdm.description')
            ->get();
        
        

        $apd = array();
        $masterkesesuaian = array();
        $mastercuci = array();

        foreach($masterAPD as $mapd){
            if($mapd->header == "Pilihan APD"){
                array_push($apd, $mapd);
            }
            if($mapd->header == "Kesesuaian"){
                array_push($masterkesesuaian, $mapd);
            }
            if($mapd->header == "Cuci Tangan Sebelum Menggunakan APD"){
                array_push($mastercuci, $mapd);
            }
        }
        
        return view('report.apd.laporan-jumlah-apd', [
            'masterAPD' => $apd,
            'masterkesesuaian' => $masterkesesuaian,
            'mastercuci' => $mastercuci,
            'jumlahAPD' => $apdDetail
        ]);
        // return response()->json([
        //         'masterAPD' => $apd,
        //         'masterkesesuaian' => $masterkesesuaian,
        //         'mastercuci' => $mastercuci,
        //         'jumlahAPD' => $apdDetail
        // ]);
    }

