    public function laporanBundleHaisHarian(Request $request)
    {
        $kdProfile = (int) $request['kdprofile'];

        $master = DB::select(DB::raw("
            select * from haisbundle_m WHERE statusenabled = true and kdprofile = 30 AND jenisbundle IN ('TINDAKAN', 'INFEKSIRUMAHSAKIT', 'HAIs') ORDER BY nourut ASC
        "));

        $data = DB::select(DB::raw("
            SELECT
                bd.norec,bd.notransaksi,bd.tglpemeriksaan,bd.petugasfk,
                pg.namalengkap, apd.objectruanganfk,ru.namaruangan, bd.isverifikasi,
                bd.jenisbundle,bd.suhu,bd.diagnosa,bd.tirahbaring,
                pm.id as idpasien, pm.namapasien, pm.tgllahir, bd.pemeriksaan, bd.terapi, bd.keterangan, bd.obatantibiotik
            FROM
                bundlehai_t bd
            INNER JOIN pasiendaftar_t pd ON pd.norec = bd.norec_pd AND pd.statusenabled = TRUE AND pd.kdprofile = 30
            INNER JOIN antrianpasiendiperiksa_t apd ON apd.norec = bd.norec_apd AND apd.statusenabled = TRUE AND apd.kdprofile = 30
            INNER JOIN pasien_m pm ON pm.id = pd.nocmfk
            LEFT JOIN kelompokpasien_m kp ON kp.id = pd.objectkelompokpasienlastfk
            LEFT JOIN ruangan_m ru ON ru.id = apd.objectruanganfk
            LEFT JOIN departemen_m dp ON dp.id = ru.objectdepartemenfk
            LEFT JOIN pegawai_m pg ON pg.id = bd.petugasfk
            WHERE
                bd.statusenabled = true
                AND bd.kdprofile = 30
                AND bd.tglpemeriksaan BETWEEN DATE_TRUNC('MONTH', timestamp '".$request['tglcetak']."') AND '".$request['tglcetak']." 23:59'
                AND ru.id = ".$request['objectruanganfk']."
            ORDER BY
                bd.tglpemeriksaan DESC
        
        "));
    
        $detail = DB::select(DB::raw("
            SELECT
                bdt.*
            FROM
                bundlehai_t bd
            INNER JOIN bundlehaidetail_t bdt ON bdt.bundlehaifk = bd.norec AND bdt.statusenabled = TRUE AND bdt.kdprofile = 30
            WHERE
                bd.statusenabled = true
                AND bd.kdprofile = 30
                AND to_char(bd.tglpemeriksaan, 'YYYY-MM-DD') BETWEEN to_char(MAKE_DATE(EXTRACT(YEAR FROM DATE '".$request['tglcetak']."')::int - 1, 4, 1), 'YYYY-MM-DD') AND '".$request['tglcetak']."'
        "));
    
        $masterTindakan = array();
        $masterInfeksi = array();
        $masterDekubitus = array();
    
        foreach($master as $ma){
            if($ma->jenisbundle == 'TINDAKAN'){
                array_push($masterTindakan, $ma);
            }
            if($ma->jenisbundle == 'INFEKSIRUMAHSAKIT'){
                array_push($masterInfeksi, $ma);
            }
            if($ma->namabundle == 'Dekubitus'){
                array_push($masterDekubitus, $ma);
            }
        }
    
        foreach($data as $dat){

            $dat->tindakan = array();
            $dat->infeksi = array();
            $dat->dekubitus = array();

            foreach($master as $ma){
                
                foreach($detail as $dtl){

                    if($dtl->bundlehaifk == $dat->norec){

                        if($dtl->bundlefk == $ma->id && $ma->jenisbundle == 'TINDAKAN'){
                            array_push($dat->tindakan, $ma);
                        }
                        if($dtl->bundlefk == $ma->id && $ma->jenisbundle == 'INFEKSIRUMAHSAKIT'){
                            array_push($dat->infeksi, $ma);
                        }
                        if($dtl->bundlefk == $ma->id && $ma->namabundle == 'Dekubitus'){
                            array_push($dat->dekubitus, $ma);
                        }
                    }
                }
            }
        }

        $ruangan = DB::select(DB::raw("
            SELECT * FROM ruangan_m WHERE statusenabled = true AND id = ".$request['objectruanganfk']."
        "));

        return view('report.hais.laporan-hais', [
            'data' => $data,
            'masterTindakan' => $masterTindakan,
            'masterInfeksi' => $masterInfeksi,
            'masterDekubitus' => $masterDekubitus,
            'ruangan' => $ruangan,
            'tanggalcetak' => $request['tglcetak']
        ]);
    }

    public function cetakRBADetailRev(Request $request)
    {
        
        $idSebelum = DB::select(DB::raw("
            SELECT
                CAST(SPLIT_PART(ka.keterangan, '-', 1) AS INTEGER) AS id_kegiatan, ka.kode
            FROM 
                keteranganbelanja_t AS kb 
            LEFT JOIN kegiatananggaran_m AS ka ON ka.id = kb.objectkegiatanfk AND ka.statusenabled = TRUE AND ka.kdprofile = 30
            WHERE kb.statusenabled = TRUE 
                AND kb.objectkegiatanfk = ".$request['subsubkegiatan']."
                AND kb.objecttahapfk = ".$request['tahap']."
        "));

        $data = DB::select(DB::raw("
            SELECT
                kb.norec AS norec_kb,
                kb.keteranganbelanja,
                kb.jml,
                kb.satuan,
                kb.hargasatuan,
                kb.subtotal,
                kb.objectasalprodukfk,
                --kb2.norec AS norec_kb_sesudah,
                --kb2.keteranganbelanja AS keteranganbelanja_sesudah,
                --kb2.jml AS jml_sesudah,
                --kb2.satuan AS satuan_sesudah,
                --kb2.hargasatuan AS hargasatuan_sesudah,
                --kb2.objectasalprodukfk AS objectasalprodukfk_sesudah,
                ka.tahun,
                ka.ID AS id_kegiatananggaran,
                ka.kode AS kode_kegiatananggaran,
                ka.keterangan,
                ka.indikatormasuk,
                ka.indikatorkeluaran,
                ka.indikatorhasil,
                ka.targetmasuk,
                ka.targetkeluaran,
                ka.targethasil,
                --ka2.indikatormasuk AS indikatormasuk_sesudah,
                --ka2.indikatorkeluaran AS indikatorkeluaran_sesudah,
                --ka2.indikatorhasil AS indikatorhasil_sesudah,
                --ka2.targetmasuk AS targetmasuk_sesudah,
                --ka2.targetkeluaran AS targetkeluaran_sesudah,
                --ka2.targethasil AS targethasil_sesudah,
                ma4.ID AS id_mataanggaran4,
                ma3.ID AS id_mataanggaran3,
                ma2.ID AS id_mataanggaran2,
                ma1.ID AS id_mataanggaran1,
                ma1.namamataanggaran AS nama_mataanggaran1,
                ma2.namamataanggaran AS nama_mataanggaran2,
                ma3.namamataanggaran AS nama_mataanggaran3,
                ma4.namamataanggaran AS nama_mataanggaran4,
                ma4.kodemataanggaran AS kode_mataanggaran4_gabung,
                CASE
                    WHEN SPLIT_PART( ma4.kodemataanggaran, '.', 5 ) = '' THEN
                        SPLIT_PART( ma4.kodemataanggaran, '.', 4 ) ELSE SPLIT_PART( ma4.kodemataanggaran, '.', 4 ) || '.' || SPLIT_PART( ma4.kodemataanggaran, '.', 5 ) 
                END AS kode_mataanggaran4,
                SPLIT_PART( ma4.kodemataanggaran, '.', 3 ) AS kode_mataanggaran3,
                SPLIT_PART( ma4.kodemataanggaran, '.', 2 ) AS kode_mataanggaran2,
                SPLIT_PART( ma4.kodemataanggaran, '.', 1 ) AS kode_mataanggaran1,
                ta.tahap 
            FROM
                keteranganbelanja_t AS kb
                INNER JOIN kegiatananggaran_m AS ka ON ka.ID = kb.objectkegiatanfk
                    AND ka.statusenabled = TRUE
                    AND ka.kdprofile = 30
                    AND ka.tahun = '".$request['tahun']."'
                INNER JOIN mataanggaran_m AS ma4 ON ma4.ID = kb.objectmataanggaranfk
                    AND ma4.statusenabled = TRUE
                    AND ma4.kdprofile = 30
                INNER JOIN mataanggaran_m AS ma3 ON ma3.kodemataanggaran ILIKE SPLIT_PART( ma4.kodemataanggaran, '.', 1 ) || '.' || SPLIT_PART( ma4.kodemataanggaran, '.', 2 ) 
                || '.' || SPLIT_PART( ma4.kodemataanggaran, '.', 3 )
                    AND ma3.statusenabled = TRUE
                    AND ma3.kdprofile = 30
                INNER JOIN mataanggaran_m AS ma2 ON ma2.kodemataanggaran ILIKE SPLIT_PART( ma3.kodemataanggaran, '.', 1 ) || '.' || SPLIT_PART( ma3.kodemataanggaran, '.', 2 )
                    AND ma2.statusenabled = TRUE
                    AND ma2.kdprofile = 30
                INNER JOIN mataanggaran_m AS ma1 ON ma1.kodemataanggaran ILIKE SPLIT_PART( ma2.kodemataanggaran, '.', 1 )
                    AND ma1.statusenabled = TRUE
                    AND ma1.kdprofile = 30
                INNER JOIN asalproduk_m AS ap ON ap.ID = kb.objectasalprodukfk
                    AND ap.statusenabled = TRUE
                    AND ap.kdprofile = 30
                INNER JOIN tahapanggaran_m AS ta ON ta.ID = kb.objecttahapfk 
                    AND ta.statusenabled = TRUE
                    AND ta.kdprofile = 30
                -- sebelum
                --LEFT JOIN keteranganbelanja_t AS kb2 ON kb2.objectmataanggaranfk = kb.objectmataanggaranfk 
                    --AND kb2.statusenabled = TRUE    
                    --AND kb2.objecttahapfk = ".$request['terhadap']."
                    --AND kb2.keteranganbelanja = kb.keteranganbelanja
                    -- AND kb2.objectkegiatanfk = ".$idSebelum[0]->id_kegiatan."
                --LEFT JOIN kegiatananggaran_m AS ka2 ON ka2.id = kb2.objectkegiatanfk
                    --AND ka2.statusenabled = TRUE
                    --AND ka2.kdprofile = 30
                    --AND ka.tahun = '".$request['tahun']."'
            WHERE
                kb.statusenabled = TRUE 
                AND kb.kdprofile = 30 
                AND kb.objecttahapfk = ".$request['tahap']." 
                AND kb.objectkegiatanfk = ".$request['subsubkegiatan']."
                --AND ka2.kode = '".$idSebelum[0]->kode."'
            ORDER BY
                SPLIT_PART( ma4.kodemataanggaran, '.', 1 ),
                SPLIT_PART( ma4.kodemataanggaran, '.', 2 ),
                CAST ( SPLIT_PART( ma4.kodemataanggaran, '.', 3 ) AS INTEGER ),
            CASE
                WHEN SPLIT_PART( ma4.kodemataanggaran, '.', 5 ) = '' THEN
                    CAST ( SPLIT_PART( ma4.kodemataanggaran, '.', 4 ) AS INTEGER ) ELSE CAST ( SPLIT_PART( ma4.kodemataanggaran, '.', 5 ) AS INTEGER ) 
                END,
                kb.nourut
        "));

        $sesudah = DB::select(DB::raw("
            SELECT 
                kb.norec AS norec_kb,
                kb.keteranganbelanja,
                kb.jml,
                kb.satuan,
                kb.hargasatuan,
                kb.subtotal,
                kb.objectasalprodukfk,
                ka.tahun,
                ka.ID AS id_kegiatananggaran,
                ka.kode AS kode_kegiatananggaran,
                ka.keterangan,
                ka.indikatormasuk,
                ka.indikatorkeluaran,
                ka.indikatorhasil,
                ka.targetmasuk,
                ka.targetkeluaran,
                ka.targethasil,
                ma4.ID AS id_mataanggaran4,
                ma3.ID AS id_mataanggaran3,
                ma2.ID AS id_mataanggaran2,
                ma1.ID AS id_mataanggaran1,
                ma1.namamataanggaran AS nama_mataanggaran1,
                ma2.namamataanggaran AS nama_mataanggaran2,
                ma3.namamataanggaran AS nama_mataanggaran3,
                ma4.namamataanggaran AS nama_mataanggaran4,
                ma4.kodemataanggaran AS kode_mataanggaran4_gabung,
                CASE WHEN SPLIT_PART( ma4.kodemataanggaran, '.', 5 ) = '' THEN
                    SPLIT_PART( ma4.kodemataanggaran, '.', 4 ) ELSE 
                    SPLIT_PART( ma4.kodemataanggaran, '.', 4 ) || '.' || SPLIT_PART( ma4.kodemataanggaran, '.', 5 ) 
                END AS kode_mataanggaran4,
                SPLIT_PART( ma4.kodemataanggaran, '.', 3 ) AS kode_mataanggaran3,
                SPLIT_PART( ma4.kodemataanggaran, '.', 2 ) AS kode_mataanggaran2,
                SPLIT_PART( ma4.kodemataanggaran, '.', 1 ) AS kode_mataanggaran1
            FROM
                keteranganbelanja_t AS kb
                INNER JOIN kegiatananggaran_m AS ka ON ka.ID = kb.objectkegiatanfk AND ka.statusenabled = TRUE
                    AND ka.kdprofile = 30
                    AND ka.tahun = '".$request['tahun']."'
                INNER JOIN mataanggaran_m AS ma4 ON ma4.ID = kb.objectmataanggaranfk
                    AND ma4.statusenabled = TRUE
                    AND ma4.kdprofile = 30
                INNER JOIN mataanggaran_m AS ma3 ON ma3.kodemataanggaran ILIKE SPLIT_PART( ma4.kodemataanggaran, '.', 1 ) || '.' || SPLIT_PART( ma4.kodemataanggaran, '.', 2 ) || '.' || SPLIT_PART( ma4.kodemataanggaran, '.', 3 )
                    AND ma3.statusenabled = TRUE
                    AND ma3.kdprofile = 30
                INNER JOIN mataanggaran_m AS ma2 ON ma2.kodemataanggaran ILIKE SPLIT_PART( ma3.kodemataanggaran, '.', 1 ) || '.' || SPLIT_PART( ma3.kodemataanggaran, '.', 2 )
                    AND ma2.statusenabled = TRUE
                    AND ma2.kdprofile = 30
                INNER JOIN mataanggaran_m AS ma1 ON ma1.kodemataanggaran ILIKE SPLIT_PART( ma2.kodemataanggaran, '.', 1 )
                    AND ma1.statusenabled = TRUE
                    AND ma1.kdprofile = 30
                INNER JOIN asalproduk_m AS ap ON ap.ID = kb.objectasalprodukfk
                    AND ap.statusenabled = TRUE
                    AND ap.kdprofile = 30
                INNER JOIN tahapanggaran_m AS ta ON ta.ID = kb.objecttahapfk 
                    AND ta.statusenabled = TRUE
                    AND ta.kdprofile = 30
            WHERE
                kb.statusenabled = TRUE 
                AND kb.kdprofile = 30 
                AND kb.objecttahapfk = ".$request['terhadap']."
                AND ka.kode = '".$idSebelum[0]->kode."'
            ORDER BY
                SPLIT_PART( ma4.kodemataanggaran, '.', 1 ),
                SPLIT_PART( ma4.kodemataanggaran, '.', 2 ),
                CAST ( SPLIT_PART( ma4.kodemataanggaran, '.', 3 ) AS INTEGER ),
                CASE WHEN SPLIT_PART( ma4.kodemataanggaran, '.', 5 ) = '' THEN
                    CAST ( SPLIT_PART( ma4.kodemataanggaran, '.', 4 ) AS INTEGER ) ELSE 
                    CAST ( SPLIT_PART( ma4.kodemataanggaran, '.', 5 ) AS INTEGER ) 
                END,
                kb.nourut
        
        "));

        foreach($data as $seb){
            $seb->jml_sesudah = 0;
            $seb->satuan_sesudah = null;
            $seb->hargasatuan_sesudah = 0;
            $seb->objectasalprodukfk_sesudah = null;
            $seb->indikatormasuk_sesudah = null;
            $seb->indikatorkeluaran_sesudah = null;
            $seb->indikatorhasil_sesudah = null;
            $seb->targetmasuk_sesudah = null;
            $seb->targetkeluaran_sesudah = null;
            $seb->targethasil_sesudah = null;
            
            foreach($sesudah as $ses){
                if($seb->kode_kegiatananggaran == $ses->kode_kegiatananggaran){
                    if($seb->kode_mataanggaran4 == $ses->kode_mataanggaran4){
                        if($seb->keteranganbelanja == $ses->keteranganbelanja){
                            $seb->jml_sesudah = $ses->jml;
                            $seb->satuan_sesudah = $ses->satuan;
                            $seb->hargasatuan_sesudah = $ses->hargasatuan;
                            $seb->objectasalprodukfk_sesudah = $ses->objectasalprodukfk;
                            
                        }
                    }

                    $seb->indikatormasuk_sesudah = $ses->indikatormasuk;
                    $seb->indikatorkeluaran_sesudah = $ses->indikatorkeluaran;
                    $seb->indikatorhasil_sesudah = $ses->indikatorhasil;
                    $seb->targetmasuk_sesudah = $ses->targetmasuk;
                    $seb->targetkeluaran_sesudah = $ses->targetkeluaran;
                    $seb->targethasil_sesudah = $ses->targethasil;
                }
            }
        }

        $program = DB::select(DB::raw("
            select dp.tahun, dp.kode kodesubsubkegiatan, dp.keterangan keterangansubsubkegiatan,
            dp0.kode kodesubkegiatan, dp0.keterangan keterangansubkegiatan,
            dp3.kode kodekegiatan, dp3.keterangan keterangankegiatan,
            dp2.kode kodeprogram, dp2.keterangan keteranganprogram,
            dp1.kode kodeurusan, dp1.keterangan keteranganurusan, 
            dp.indikatormasuk, dp.indikatorkeluaran, dp.indikatorhasil, dp.targetmasuk, dp.targetkeluaran, dp.targethasil
            from kegiatananggaran_m as dp 
            inner join keteranganbelanja_t as kb on kb.objectkegiatanfk = dp.id 
            and kb.kdprofile = 30 and kb.statusenabled = true 
            inner join kegiatananggaran_m as dp3 on dp.kode ilike dp3.kode || '%' and dp3.div = 2
            and dp3.kdprofile = 30 and dp3.statusenabled = true 
            inner join kegiatananggaran_m as dp2 on dp3.kode ilike dp2.kode || '%' and dp2.div = 1
            and dp2.kdprofile = 30 and dp2.statusenabled = true 
            inner join kegiatananggaran_m as dp1 on dp2.kode ilike dp1.kode || '%' and dp1.div = 0
            and dp1.kdprofile = 30 and dp1.statusenabled = true 
            inner join kegiatananggaran_m as dp0 on dp.kode ilike dp0.kode || '%' and dp0.div = 3
            and dp0.kdprofile = 30 and dp0.statusenabled = true 
            where dp.tahun = '".$request['tahun']."'
            and dp.id = ".$request['subsubkegiatan']."
            group by dp.tahun, dp.kode, dp.keterangan,
            dp0.kode, dp0.keterangan,
            dp3.kode, dp3.keterangan,
            dp2.kode, dp2.keterangan,
            dp1.kode, dp1.keterangan, 
            dp.indikatormasuk, dp.indikatorkeluaran, dp.indikatorhasil, dp.targetmasuk, dp.targetkeluaran, dp.targethasil
        "));

        $tanggalcetak = $this->tanggal_indonesia(date('Y-m-d',strtotime($request['tglcetak'])));        

        $asalProduk = DB::table('asalproduk_m as ap')
            ->select('ap.id','ap.asalproduk')
            ->where('ap.statusenabled',true)
            ->where('ap.isanggaran',true)
            ->orderBy('ap.asalproduk')
            ->get();
        
        
        $settingrba = DB::select(DB::raw("
            select pg.namalengkap, pg.nippns from settinganggaran_t sa
            inner join pegawai_m pg on pg.id = sa.objectkepalabludfk
            where sa.statusenabled = true
        "));

        // Fungsi untuk mengambil asal produk apa saja yang ada dalam belanja secara unique
        function cariAsal($data, $asal, $uniqueAsalNames = [], $index = 0) {
            // Base case: if index is out of bounds, return uniqueAsalNames
            if ($index >= count($data)) {
                return $uniqueAsalNames;
            }
            
            // Get the current id_asal from data
            $currentIdAsal = $data[$index]->objectasalprodukfk;
            
            // Check if this id_asal is already in uniqueAsalNames
            if (!in_array($currentIdAsal, array_column($uniqueAsalNames, 'id'))) {
                // Find the corresponding asal by id
                foreach ($asal as $item) {
                    if ($item->id == $currentIdAsal) {
                        $uniqueAsalNames[] = $item;
                        break;
                    }
                }
            }
            
            // Recursive call for the next index
            return cariAsal($data, $asal, $uniqueAsalNames, $index + 1);
        }
        
        // Call the function
        $uniqueAsalNames = cariAsal($data, $asalProduk);


        return view('report.rba.cetak-rba-sebelum-sesudah', [
            'data' => $data,
            'program' => $program,
            'tanggalcetak' => $tanggalcetak,
            'asalproduk' => $uniqueAsalNames,
            'settingrba' => $settingrba
        ]);

    }

    public function cetakLabelPilihan(Request $request)
    {
        $norec = explode(',', $request['norec']);

        $kdProfile = (int) $request['kodeprofile'];

        $data = DB::table('registrasiaset_t as ra')
            ->leftJOIN('strukpelayanan_t as sp','sp.norec','=','ra.nostrukterimafk')
            ->leftJOIN('strukpelayanandetail_t as spd','spd.norec','=','ra.nostrukterimadetailfk')
            ->leftJoin('produk_m as pr', 'pr.id', '=', 'ra.objectprodukfk')
            ->leftJOIN('merkproduk_m as mrk', 'mrk.id', '=', 'ra.objectmerkprodukfk')
            ->leftJOIN('detailjenisproduk_m as djp','djp.id','=','pr.objectdetailjenisprodukfk')
            ->leftJOIN('jenisproduk_m as jp','jp.id','=','djp.objectjenisprodukfk')
            ->leftJOIN('kelompokproduk_m as kp','kp.id','=','jp.objectkelompokprodukfk')
            ->leftJOIN('satuanstandar_m as ss','ss.id','=','pr.objectsatuanstandarfk')
            ->leftJOIN('asalproduk_m as ap','ap.id','=','ra.objectasalprodukfk')
            ->leftJOIN('ruanganasset_m as ru1','ru1.id','=','ra.objectruanganposisicurrentfk')
            ->leftJOIN('rekanan_m as rek','rek.id','=','ra.objectsupplier')
            ->select('ra.norec','ra.noregisteraset','ra.objectprodukfk as kdproduk','pr.namaproduk','jp.jenisproduk',
                     'ru1.id as ruanganasalfk','ru1.namaruangan as namaruanganasal',
                     'ra.tglregisteraset','ra.tglstrukterima','ra.qtyprodukaset','ra.hargaperolehan','ra.tglregisteraset','ra.tglstrukterima',
                     'rek.namarekanan as namasupplier','rek.alamatlengkap as almSupplier','sp.norec as norecsp',
                     'spd.norec as norecspd','ap.asalproduk','ra.keteranganlainnya','ra.spesifikasi','ra.jenisaset','ra.judul','ra.kdbmn', 'ra.koderegisterrs', 'ra.tahunperolehan', 'pr.deskripsiproduk', 'mrk.merkproduk', 'ra.nilaisisa')
            ->whereIn('ra.norec', $norec)
            ->where('ra.kdprofile', $kdProfile)
            ->where('ra.statusenabled', true)
            ->orderBy('ra.noregisteraset')
            ->get();

        return view('report.asset.cetak-label-pilihan', compact('data'));
    }

    public function cobaLapung(Request $request)
    {   

        // $nomor = DB::select(DB::raw("
        //     select 
        //         MAX(cast(split_part(pt.nopajak, '/', 1) as integer)) 
        //     from pemungutanpajak_t pt where pt.nopajak like '%' and pt.kdprofile = 30 
        // "));
        // dd($nomor[0]->max);


        // $coba = \App\Transaksi\PemungutanPajak::where('norec', '=', '56883b00-3daf-11ef-9622-adc4eae3')
        //     ->where('kdprofile', '=', 30)
        //     ->where('statusenabled', '=', true)
        //     ->first();

        // dd(empty($coba));

        $asalProduk = null;

        if($request['asalproduk'] == 18 || $request['asalproduk'] == 4){
            $asalProduk = [18,4];
        }else {
            $asalProduk = [2,15,21];
        }

        $settingRBA = DB::table('settinganggaran_t')
            ->where('statusenabled', true)
            ->where('kdprofile', 30)
            ->first();

        $dataAnggaran = DB::select(DB::raw("
            select
                -- kegiatan anggaran
                ka.id as id_kegiatan,
                ka.kode as kode_kegiatan,
                MIN(ka.keterangan) as keterangan_kegiatan,
                MIN(ka.targetmasuk) as targetmasuk_kegiatan,
                -- anak kegiatan anggaran
                ka3.id as id_kegiatan3,
                ka3.kode as kode_kegiatan3,
                MIN(ka3.keterangan) as keterangan_kegiatan3,
                ka2.id as id_kegiatan2,
                ka2.kode as kode_kegiatan2,
                MIN(ka2.keterangan) as keterangan_kegiatan2,
                ka1.id as id_kegiatan1,
                ka1.kode as kode_kegiatan1,
                MIN(ka1.keterangan) as keterangan_kegiatan1,
                -- mata anggaran
                ma.id as id_mataanggaran,
                ma.kodemataanggaran as kode_mataanggaran,
                MIN(ma.namamataanggaran) as nama_mataanggaran,
                -- anak mata anggaran
                ma3.id as id_mataanggaran3,
                ma3.kodemataanggaran as kode_mataanggaran3,
                MIN(ma3.namamataanggaran) as nama_mataanggaran3,
                ma2.id as id_mataanggaran2,
                ma2.kodemataanggaran as kode_mataanggaran2,
                MIN(ma2.namamataanggaran) as nama_mataanggaran2,
                ma1.id as id_mataanggaran1,
                ma1.kodemataanggaran as kode_mataanggaran1,
                MIN(ma1.namamataanggaran) as nama_mataanggaran1,
                ap.id as id_asalproduk,
                -- total anggaran
                SUM(kb.subtotal) as total_anggaran
            from
                keteranganbelanja_t as kb
            join asalproduk_m as ap on
                ap.id = kb.objectasalprodukfk
                and ap.statusenabled = true
            join tahapanggaran_m as ta on
                ta.id = kb.objecttahapfk
                and ta.statusenabled = true
                -- kegiatan anggaran
            join kegiatananggaran_m as ka on
                ka.id = kb.objectkegiatanfk
                and ka.statusenabled = true
            join kegiatananggaran_m as ka3 on
                ka3.kode = SPLIT_PART(ka.kode, '.', 1) || '.' || SPLIT_PART(ka.kode, '.', 2) || '.' || SPLIT_PART(ka.kode, '.', 3)  || '.' || SPLIT_PART(ka.kode, '.', 4) 
                || '.' || SPLIT_PART(ka.kode, '.', 5) || '.' || SPLIT_PART(ka.kode, '.', 6) and ka3.statusenabled = true
            join kegiatananggaran_m as ka2 on
                ka2.kode = SPLIT_PART(ka.kode, '.', 1) || '.' || SPLIT_PART(ka.kode, '.', 2) || '.' || SPLIT_PART(ka.kode, '.', 3)  || '.' || SPLIT_PART(ka.kode, '.', 4) 
                || '.' || SPLIT_PART(ka.kode, '.', 5) and ka2.statusenabled = true
            join kegiatananggaran_m as ka1 on
                ka1.kode = SPLIT_PART(ka.kode, '.', 1) || '.' || SPLIT_PART(ka.kode, '.', 2) || '.' || SPLIT_PART(ka.kode, '.', 3) and ka1.statusenabled = true
                -- mata anggaran
            join mataanggaran_m as ma on
                ma.id = kb.objectmataanggaranfk
                and ma.statusenabled = true
            join mataanggaran_m as ma3 on
                ma3.kodemataanggaran ilike SPLIT_PART(ma.kodemataanggaran, '.', 1) || '.' || SPLIT_PART(ma.kodemataanggaran, '.', 2)  
                || '.' || SPLIT_PART(ma.kodemataanggaran, '.', 3) and ma3.statusenabled = true
            join mataanggaran_m as ma2 on
                ma2.kodemataanggaran ilike SPLIT_PART(ma3.kodemataanggaran, '.', 1) || '.' || SPLIT_PART(ma3.kodemataanggaran, '.', 2)
                and ma2.statusenabled = true
            join mataanggaran_m as ma1 on
                ma1.kodemataanggaran ilike SPLIT_PART(ma2.kodemataanggaran, '.', 1) and ma1.statusenabled = true
            where
                kb.statusenabled = true
                and kb.objecttahapfk = ".$settingRBA->objecttahapaktivfk."
                and kb.objectasalprodukfk in (".implode(',', $asalProduk).")
                and ka.tahun = cast(extract(year from timestamp '".$request['tglbku']."') as VARCHAR)
            group by
                ka.id,
                ka.kode,
                ma.id,
                ma.kodemataanggaran,
                ap.id,
                -- anak kegiatan
                ka3.id,
                ka3.kode,
                ka2.id,
                ka2.kode,
                ka1.id,
                ka1.kode,
                -- anak mata anggaran
                ma3.id,
                ma3.kodemataanggaran,
                ma2.id,
                ma2.kodemataanggaran,
                ma1.id,
                ma1.kodemataanggaran
            order by
                SPLIT_PART(ka.kode, '.', 2),
                SPLIT_PART(ka.kode, '.', 3),
                cast(SPLIT_PART(ka.kode, '.', 7) as INTEGER),
                SPLIT_PART(ma.kodemataanggaran, '.', 1),
                SPLIT_PART(ma.kodemataanggaran, '.', 2),
                cast(SPLIT_PART(ma.kodemataanggaran, '.', 3) as INTEGER),
                case when SPLIT_PART(ma.kodemataanggaran, '.', 5) = '' then
                    cast(SPLIT_PART(ma.kodemataanggaran, '.', 4) as INTEGER)
                else
                    cast(SPLIT_PART(ma.kodemataanggaran, '.', 5) as INTEGER)
                end
        "));

        $dataSPJ = DB::select(DB::raw("
            select 
                ka.id as id_kegiatan,
                ka.kode  as kode_kegiatan,
                MIN(ka.keterangan) as keterangan_kegiatan,
                ma.id as id_mataanggaran,
                ma.kodemataanggaran as kode_mataanggaran,
                ma.namamataanggaran as nama_mataanggaran,
                -- anak kegiatan anggaran
                ka3.id as id_kegiatan3,
                ka3.kode as kode_kegiatan3,
                ka2.id as id_kegiatan2,
                ka2.kode as kode_kegiatan2,
                ka1.id as id_kegiatan1,
                ka1.kode as kode_kegiatan1,
                -- anak mata anggaran
                ma3.id as id_mataanggaran3,
                ma3.kodemataanggaran as kode_mataanggaran3,
                ma2.id as id_mataanggaran2,
                ma2.kodemataanggaran as kode_mataanggaran2,
                ma1.id as id_mataanggaran1,
                ma1.kodemataanggaran as kode_mataanggaran1,
                ap.id as id_asalproduk,
                SUM(case when extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
                    and bku.tglbku <= DATE_TRUNC('MONTH', timestamp '".$request['tglbku']."')
                then sr.totalbelanja else 0 end) as total_belanja_bulan_lalu,
                SUM(case when extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
                    and extract(month from bku.tglbku) = extract(month from timestamp '".$request['tglbku']."')
                then sr.totalbelanja else 0 end) as total_belanja_bulan_ini,
                SUM(sr.totalbelanja) as total_belanja
            from 
                strukrealisasi_t as sr
            JOIN realisasidetail_t AS rd ON rd.strukrealisasifk = sr.norec AND rd.statusenabled = TRUE
            JOIN keteranganbelanja_t AS kb ON kb.norec = rd.keteranganbelanjafk AND kb.statusenabled = TRUE
            JOIN bukukasumum_t as bku ON bku.norec = sr.objectbkufk and bku.statusenabled = true
            JOIN kegiatananggaran_m as ka on ka.id = sr.objectkegiatanfk and ka.statusenabled = true
            JOIN mataanggaran_m as ma on ma.id = sr.objectmataanggaranfk and ma.statusenabled = true
            JOIN asalproduk_m as ap on ap.id = sr.objectasalprodukfk and ap.statusenabled = true
            --	anak kegiatan
            JOIN kegiatananggaran_m as ka3 on
                ka3.kode = SPLIT_PART(ka.kode, '.', 1) || '.' || SPLIT_PART(ka.kode, '.', 2) || '.' || SPLIT_PART(ka.kode, '.', 3)  || '.' || SPLIT_PART(ka.kode, '.', 4) 
                || '.' || SPLIT_PART(ka.kode, '.', 5) || '.' || SPLIT_PART(ka.kode, '.', 6) and ka3.statusenabled = true
            JOIN kegiatananggaran_m as ka2 on
                ka2.kode = SPLIT_PART(ka.kode, '.', 1) || '.' || SPLIT_PART(ka.kode, '.', 2) || '.' || SPLIT_PART(ka.kode, '.', 3)  || '.' || SPLIT_PART(ka.kode, '.', 4) 
                || '.' || SPLIT_PART(ka.kode, '.', 5) and ka2.statusenabled = true
            JOIN kegiatananggaran_m as ka1 on
                ka1.kode = SPLIT_PART(ka.kode, '.', 1) || '.' || SPLIT_PART(ka.kode, '.', 2) || '.' || SPLIT_PART(ka.kode, '.', 3) and ka1.statusenabled = true
            -- anak mata anggaran
            JOIN mataanggaran_m as ma3 on
                ma3.kodemataanggaran ilike SPLIT_PART(ma.kodemataanggaran, '.', 1) || '.' || SPLIT_PART(ma.kodemataanggaran, '.', 2)  
                || '.' || SPLIT_PART(ma.kodemataanggaran, '.', 3) and ma3.statusenabled = true
            JOIN mataanggaran_m as ma2 on
                ma2.kodemataanggaran ilike SPLIT_PART(ma3.kodemataanggaran, '.', 1) || '.' || SPLIT_PART(ma3.kodemataanggaran, '.', 2)
                and ma2.statusenabled = true
            JOIN mataanggaran_m as ma1 on
                ma1.kodemataanggaran ilike SPLIT_PART(ma2.kodemataanggaran, '.', 1) and ma1.statusenabled = true
            WHERE
                sr.status = 'Sudah Diverifikasi'
                and sr.statusenabled = true
                and extract(month from bku.tglbku) <= extract(month from timestamp '".$request['tglbku']."') 
                and extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
                and ka.tahun = cast(extract(year from timestamp '".$request['tglbku']."') as VARCHAR)
                AND kb.objecttahapfk = ".$settingRBA->objecttahapaktivfk."
                And sr.objectasalprodukfk in (".implode(',', $asalProduk).")
            GROUP BY
                ka.id,
                ka.kode,
                ma.id,
                ma.kodemataanggaran,
                -- anak kegiatan
                ka3.id,
                ka3.kode,
                ka2.id,
                ka2.kode,
                ka1.id,
                ka1.kode,
                -- anak mata anggaran
                ma3.id,
                ma3.kodemataanggaran,
                ma2.id,
                ma2.kodemataanggaran,
                ma1.id,
                ma1.kodemataanggaran,
                ap.id
            ORDER BY
                SPLIT_PART(ka.kode, '.', 2),
                SPLIT_PART(ka.kode, '.', 3),
                cast(SPLIT_PART(ka.kode, '.', 7) as INTEGER),
                SPLIT_PART(ma.kodemataanggaran, '.', 1),
                SPLIT_PART(ma.kodemataanggaran, '.', 2),
                cast(SPLIT_PART(ma.kodemataanggaran, '.', 3) as INTEGER),
                case when SPLIT_PART(ma.kodemataanggaran, '.', 5) = '' then
                    cast(SPLIT_PART(ma.kodemataanggaran, '.', 4) as INTEGER)
                else
                    cast(SPLIT_PART(ma.kodemataanggaran, '.', 5) as INTEGER)
                end
        "));

        $dataJenisAnggaran = DB::table('jenisanggaran_m')
            ->where('statusenabled', true)
            ->where('kdprofile', 30)
            ->get();
        

        foreach($dataJenisAnggaran as $anggaran){
            $anggaran->anggaran = 0;
        }

        return view('report.coba-lapung2', [
            'data' => $dataAnggaran,
            'lapung' => $dataSPJ,
            'jenisAnggaran' => $dataJenisAnggaran
        ]);
    }

    public function cetakKIBC(Request $request)
    {
        $kdProfile = (int) $request['kdprofile'];
        
        $query = DB::select(DB::raw("
        SELECT
            ap.asalproduk,
            pr.namaproduk,
            pr.deskripsiproduk,
            mrk.merkproduk,
            bhn.namabahanproduk,
            ra.koderegisterrs,
            ra.tahunperolehan,
            ra.norangka,
            ra.nomesin,
            ra.nopolisi,
            ra.nobpkb,            
            CAST(ra.hargaperolehan AS DECIMAL(20)) AS hargaperolehan,
            ra.kdprofile,
            cha1.ID AS idcha1,
            cha1.kodeakun AS kodeakuncha1,
            cha1.urian AS uriancha1,
            cha2.ID AS idcha2,
            cha2.kodeakun AS kodeakuncha2,
            cha2.urian AS uriancha2,
            cha3.ID AS idcha3,
            cha3.kodeakun AS kodeakuncha3,
            cha3.urian AS uriancha3,
            cha4.ID AS idcha4,
            cha4.kodeakun AS kodeakuncha4,
            cha4.urian AS uriancha4,
            cha5.ID AS idcha5,
            cha5.kodeakun AS kodeakuncha5,
            cha5.urian AS uriancha5,
            cha6.ID AS idch6,
            cha6.kodeakun AS kodeakuncha6,
            cha6.urian AS uriancha6 ,
            md.nama as kondisibangunan,
            md2.nama as tingkat,
            md3.nama as beton,
            ra.alamatlengkap,
            ra.luaslantai,
            ra.luastanah,
            ra.luasbangunan,
            ra.keteranganlainnya,
            ra.spesifikasi
        FROM
            registrasiaset_t AS ra
            INNER JOIN charkodeakunasset_m AS cha6 ON cha6.kodeakun = ra.kdbmn
            LEFT JOIN charkodeakunasset_m AS cha1 ON cha1.ID = cha6.idlevel1
            LEFT JOIN charkodeakunasset_m AS cha2 ON cha2.ID = cha6.idlevel2
            LEFT JOIN charkodeakunasset_m AS cha3 ON cha3.ID = cha6.idlevel3
            LEFT JOIN charkodeakunasset_m AS cha4 ON cha4.ID = cha6.idlevel4
            LEFT JOIN charkodeakunasset_m AS cha5 ON cha5.ID = cha6.idlevel5
            LEFT JOIN produk_m AS pr ON pr.ID = ra.objectprodukfk
            LEFT JOIN bahanproduk_m AS bhn ON bhn.ID = ra.objectbahanprodukfk
            LEFT JOIN merkproduk_m AS mrk ON mrk.ID = ra.objectmerkprodukfk
            LEFT JOIN asalproduk_m AS ap ON ap.ID = ra.objectasalprodukfk
            LEFT JOIN masterdata_m AS md ON md.ID = ra.kondisbanguanfk
            LEFT JOIN masterdata_m AS md2 ON md2.ID = ra.tingkatfk
            LEFT JOIN masterdata_m AS md3 ON md3.ID = ra.betonfk
            
        WHERE
            ra.kdprofile=$kdProfile and ra.objectkelompokasetfk ='4'--and cha2.kodeakun in ('01.03.03','01.03.01')
        "));

        // dd($query);

        return view('report.asset.kibc', [
            'data' => $query
        ]);
    }

    public function cetakKIBD(Request $request)
    {
        $kdProfile = (int) $request['kdprofile'];
        
        $query = DB::select(DB::raw("
        SELECT
            ap.asalproduk,
            pr.namaproduk,
            pr.deskripsiproduk,
            mrk.merkproduk,
            bhn.namabahanproduk,
            ra.koderegisterrs,
            ra.tahunperolehan,
            ra.norangka,
            ra.nomesin,
            ra.nopolisi,
            ra.nobpkb,            
            CAST(ra.hargaperolehan AS DECIMAL(20)) AS hargaperolehan,
            ra.kdprofile,
            cha1.ID AS idcha1,
            cha1.kodeakun AS kodeakuncha1,
            cha1.urian AS uriancha1,
            cha2.ID AS idcha2,
            cha2.kodeakun AS kodeakuncha2,
            cha2.urian AS uriancha2,
            cha3.ID AS idcha3,
            cha3.kodeakun AS kodeakuncha3,
            cha3.urian AS uriancha3,
