            cha4.kodeakun AS kodeakuncha4,
            cha4.urian AS uriancha4,
            cha5.ID AS idcha5,
            cha5.kodeakun AS kodeakuncha5,
            cha5.urian AS uriancha5,
            cha6.ID AS idch6,
            cha6.kodeakun AS kodeakuncha6,
            cha6.urian AS uriancha6 ,
            md.nama as kondisibangunan,
            md2.nama as tingkat,
            md3.nama as beton,
            ra.alamatlengkap,
            ra.luaslantai,
            ra.luastanah,
            ra.luasbangunan,
            ra.keteranganlainnya,md4.nama as kontruksi,
            ra.spesifikasi,lb_lebar,ra.lb_panjang,ra,dtanggal,ra.dnomor
        FROM
            registrasiaset_t AS ra
            INNER JOIN charkodeakunasset_m AS cha6 ON cha6.kodeakun = ra.kdbmn
            LEFT JOIN charkodeakunasset_m AS cha1 ON cha1.ID = cha6.idlevel1
            LEFT JOIN charkodeakunasset_m AS cha2 ON cha2.ID = cha6.idlevel2
            LEFT JOIN charkodeakunasset_m AS cha3 ON cha3.ID = cha6.idlevel3
            LEFT JOIN charkodeakunasset_m AS cha4 ON cha4.ID = cha6.idlevel4
            LEFT JOIN charkodeakunasset_m AS cha5 ON cha5.ID = cha6.idlevel5
            LEFT JOIN produk_m AS pr ON pr.ID = ra.objectprodukfk
            LEFT JOIN bahanproduk_m AS bhn ON bhn.ID = ra.objectbahanprodukfk
            LEFT JOIN merkproduk_m AS mrk ON mrk.ID = ra.objectmerkprodukfk
            LEFT JOIN asalproduk_m AS ap ON ap.ID = ra.objectasalprodukfk
            LEFT JOIN masterdata_m AS md ON md.ID = ra.kondisbanguanfk
            LEFT JOIN masterdata_m AS md2 ON md2.ID = ra.tingkatfk
            LEFT JOIN masterdata_m AS md3 ON md3.ID = ra.betonfk
            LEFT JOIN masterdata_m AS md4 ON md4.ID = ra.kontruksi
            
        WHERE
            ra.kdprofile=$kdProfile and cha2.kodeakun in ('01.03.04')
        "));

        // dd($query);

        return view('report.asset.kibd', [
            'data' => $query
        ]);
    }
    public function cetakLabelPilihanPengemasan(Request $request)
    {
        $norec = explode(',', $request['norec']);

        $kdProfile = (int) $request['kodeprofile'];

        $data = \DB::table('pengemasan_t as ra')            
        ->leftJOIN('kelompokalat_m as kp','kp.id','=','ra.objectkelompoksetfk')
        ->JOIN('pegawai_m as pg','pg.id','=','ra.objectpegawaifk')       
        ->select('ra.tglpengemasan','ra.nomor', 'ra.norec','kp.namakelompokalat', 'pg.id','pg.namalengkap')     
        ->whereIn('ra.norec', $norec)
        ->where('ra.kdprofile', $kdProfile)
        ->where('ra.statusenabled', true)
        ->orderBy('ra.nomor')
        ->get();

        return view('report.asset.cetak-label-pilihan-pengemasan', compact('data'));
    }


    public function suratPasienMelarikanDiri(Request $request)
    {
        $norec = $request['emr'];
        $kdProfile = (int) $request['kdprofile'];
        $data = DB::select(DB::raw("
            SELECT
                epd.emrdfk,
                epd.emrfk,
                ep.noemr,
                ed.TYPE,
                pa.namapasien,
                pa.tgllahir,
                pa.nohp,
                pa.nocm,
                ep.jeniskelamin,
                ep.umur,
                al.alamatlengkap,
                ep.noregistrasifk as noregistrasi ,
                epd.value,ep.namaruangan,pg.namalengkap as namadokter
                --case when ed.TYPE = 'datetime' then TO_CHAR(TO_TIMESTAMP(epd.value, 'YYYY-MM-DD HH24:MI:SS'),'YYYY-MM-DD HH24:MI:SS') else epd.value end as value
            FROM
                emrpasien_t AS ep
                INNER JOIN emrpasiend_t AS epd ON ep.noemr = epd.emrpasienfk
                INNER JOIN emrd_t AS ed ON epd.emrdfk = ed.id AND ed.statusenabled = true
                INNER JOIN antrianpasiendiperiksa_t AS pd ON pd.norec = ep.norec_apd
                left JOIN pegawai_m AS pg ON pg.id = pd.objectpegawaifk
                left JOIN pasien_m as pa on ep.nocm =  pa.nocm
                left JOIN alamat_m as al on pa.id = al.nocmfk
            WHERE
                ep.norec = '$norec'
                AND ep.kdprofile = '$kdProfile' 
                AND epd.statusenabled = TRUE 
                and epd.emrfk = ".$request['emrfk']."
            ORDER BY
                ed.nourut
                "
        ));
        

        foreach ($data as $z){
            if ($z->type=="datetime"){
                $z->value=date('Y-m-d H:i:s',strtotime($z->value));
            }
        }

        $profile = Profile::where('id',$request['kdprofile'])->first();
        $res['d'] = $data;
        
        $item =[];   
        $item2= [];

        foreach( $res['d'] as $items){
            if($items->type  ==  "textbox" ||$items->type  ==  "textarea"  ){
                $item[$items->emrdfk] =  $items->value;
            }
            if($items->type  ==  "datetime"){
                $item[$items->emrdfk] = $this->tanggal_indonesia(date('Y-m-d',strtotime( $items->value))) . ', '. date('H:m', strtotime($items->value));
            }
            if($items->type  ==  "time"){
                $item[$items->emrdfk] = date('H:i',strtotime( $items->value));
            }
            if($items->type  ==  "date"){
                $item[$items->emrdfk] = $this->tanggal_indonesia(date('Y-m-d',strtotime( $items->value)));
            }
            if($items->type  ==  "checkboxtextbox"){
                $item[$items->emrdfk] =  $items->value;
                $item2[$items->emrdfk] =  true;
            }
            if($items->type == "checkbox") {
                $chekedd = false;
                if ($items->value == '1') {
                    $chekedd = true;
                }
                $item[$items->emrdfk] = $chekedd;
            }
            if($items->type == "combobox") {
                $arr = explode('~',$items->value );
                $item[$items->emrdfk] = $arr[1];
            }
        }

        // dd($item);

        $pageWidth = 950;

        $peg = DB::table('pegawai_m')
            ->where('id',$request['pegawaittd'])
            ->first();
        
        $dataSip = DB::table('masaberlakusipstr_t as mbs')
                ->select('pg.id as idpegawai', 'pg.nama', 'mbs.nosip')
                ->leftJoin('jenismasaberlakustrsip_m as jmb','jmb.id','=','mbs.jenismasaberlakufk')
                ->leftJoin('pegawai_m as pg','pg.id','=', 'mbs.pegawaifk')
                ->leftJoin('unitkerjapegawai_m as uk','uk.id','=','pg.objectunitkerjapegawaifk')
                ->leftJoin('unitkerjapegawai_m as uk2','uk2.id','=','mbs.subunitkerjafk')
                ->where('pg.statusenabled',true)
                ->where('mbs.kdprofile', $kdProfile)
                ->where('mbs.pegawaifk', $request['pegawaittd'])
                ->orderBy('mbs.berakhirstr','desc')
                ->first();  

        // if(isset($request['isttd']) && $request['isttd'] == true){
        //     $peg = DB::table('pegawai_m')->where('id',$request['pegawaittd'])->first();
            
        // }

        $cekPdf = DB::table('emr_bsre_t')
            ->where('statusenabled', true)
            ->where('noregistrasi', trim($data[0]->noregistrasi))
            ->where('nocm', $data[0]->nocm)
            ->where('nomoremr', $data[0]->noemr)
            ->where('status', true)
            ->where('emrfk', $data[0]->emrfk)
            ->get();

        if(count($cekPdf) > 0){
            $link = '/service/storage_path?path='.$cekPdf[0]->file.'&filename='.$cekPdf[0]->namafile.'&mimetype=application/pdf';
            return redirect($link);
        }

        $pdf = PDF::loadView(
            'report.EMR.suratpasienmelarikandiri-dom',
            array(
                'res' => $res,
                'pageWidth' => $pageWidth,
                'data' => $data,
                'item'=> $item,
                'peg'=> $peg,
                'profile' => $profile,
                'tte' => (isset($request['isttd']) && $request['isttd'] == true) ? 'true' : 'false',
                'sip' => $dataSip
            )
        );
        if(isset($request['isttd']) && $request['isttd'] == true){
            $objetoRequest = new \Illuminate\Http\Request();
            $objetoRequest ['emrfk'] = $request['emrfk'];
            $objetoRequest ['norec_emr'] = $request['emr'];
            $objetoRequest ['pegawaittd'] = $request['pegawaittd'];
            $objetoRequest ['nocm'] = $request['nocm'];
            $objetoRequest ['noregistrasi'] = $request['noregistrasi'];
            $objetoRequest ['norec_pd'] = $request['norec_pd'];
            $bsre = app('App\Http\Controllers\Bridging\BridgingBSREController')->pengajuanTTE($objetoRequest,true);
            if($bsre['status'] == 201){
                $content = $pdf->download()->getOriginalContent();
                \Storage::disk('local')->put( 'TTD_BSRE/' . $bsre['dokumen']->id . '/file' . '.pdf' , $content);
            }
          
            return $bsre;
        }

        return $pdf->stream();
        // return view('report.EMR.suratpasienmelarikandiri',compact('data','pageWidth', 'profile', 'item'));
    }


    public function cetakPemeriksaanNapza(Request $request)
    {   
        $norec = $request['emr'];
        $noemr = $request['noemr'];
        $kdProfile = (int) $request['kdprofile'];
        $kodeAwalSurat = $this->settingDataFixed('KodeAwalSurat', $kdProfile);
        $kodeAkhirSurat = $this->settingDataFixed('KodeAkhirSurat', $kdProfile);
        $emrfk = $request['emfk'];
        $data = DB::select(DB::raw("
            SELECT
                epd.emrdfk,
                epd.emrfk,
                ep.noemr,
                ed.TYPE,
                pa.namapasien,
                pa.tgllahir,
                pa.nohp,
                pa.nocm,
                ep.jeniskelamin,
                ep.umur,
                al.alamatlengkap,
                ep.noregistrasifk as noregistrasi,
                epd.value,ep.namaruangan,epd.tgl,
                pg.namalengkap as namadokter
            FROM
                emrpasien_t AS ep
                INNER JOIN emrpasiend_t AS epd ON ep.noemr = epd.emrpasienfk
                INNER JOIN emrd_t AS ed ON epd.emrdfk = ed.ID
                    INNER JOIN antrianpasiendiperiksa_t AS pd ON pd.norec = ep.norec_apd
                left JOIN pegawai_m AS pg ON pg.id = pd.objectpegawaifk
                left JOIN pasien_m as pa on ep.nocm =  pa.nocm
                left JOIN alamat_m as al on pa.id = al.nocmfk
            WHERE
                ep.norec = '".$request['emr']."'
                AND ep.kdprofile = ".$kdProfile." 
                AND epd.statusenabled = TRUE 
                and epd.emrfk = '".$request['emrfk']."'
            ORDER BY
                ed.nourut
        "));
        
        $profile = Profile::where('id',$request['kdprofile'])->first();

        foreach ($data as $z){
            if (isset($z->tgllahir) ||isset($z->tgl)){
                $z->tgllahir=$this->tanggal_indonesia(date('Y-m-d',strtotime($z->tgllahir)));
                $z->tgl=$this->tanggal_indonesia(date('Y-m-d',strtotime($z->tgl)));
            }
            
        }
        // $pageWidth = 950;

        $res['profile'] = Profile::where('id',$request['kdprofile'])->first();
        $res['d'] = $data;
        $item =[];   
        $item2 = [];
        
        foreach( $res['d'] as $items){
            if($items->type  ==  "textbox" ||$items->type  ==  "textarea"  ){
                $item[$items->emrdfk] =  $items->value;
            }
            if($items->type  ==  "datetime"){
                $item[$items->emrdfk] = $this->tanggal_indonesia(date('Y-m-d',strtotime( $items->value))) ;
            }
            if($items->type  ==  "time"){
                $item[$items->emrdfk] = date('H:i',strtotime( $items->value));
            }
            if($items->type  ==  "date"){
                $item[$items->emrdfk] = date('Y-m-d',strtotime( $items->value));
            }
            if($items->type  ==  "checkboxtextbox"){
                $item[$items->emrdfk] =  $items->value;
                $item2[$items->emrdfk] =  true;
            }
            if($items->type == "checkbox") {
                $chekedd = false;
                if ($items->value == '1') {
                    $chekedd = true;
                }
                $item[$items->emrdfk] = $chekedd;
            }
            if($items->type == "combobox") {
                $arr = explode('~',$items->value );
                $item[$items->emrdfk] = $arr[1];
            }
        }

        
        $pageWidth = 950;
        $peg = DB::table('pegawai_m')
            ->where('id',$request['pegawaittd'])
            ->first();
        
        $dataSip = DB::table('masaberlakusipstr_t as mbs')
                ->select('pg.id as idpegawai', 'pg.nama', 'mbs.nosip')
                ->leftJoin('jenismasaberlakustrsip_m as jmb','jmb.id','=','mbs.jenismasaberlakufk')
                ->leftJoin('pegawai_m as pg','pg.id','=', 'mbs.pegawaifk')
                ->leftJoin('unitkerjapegawai_m as uk','uk.id','=','pg.objectunitkerjapegawaifk')
                ->leftJoin('unitkerjapegawai_m as uk2','uk2.id','=','mbs.subunitkerjafk')
                ->where('pg.statusenabled',true)
                ->where('mbs.kdprofile', $kdProfile)
                ->where('mbs.pegawaifk', $request['pegawaittd'])
                ->orderBy('mbs.berakhirstr','desc')
                ->first();

        // if(isset($request['isttd']) && $request['isttd'] == true){
        //     $peg = DB::table('pegawai_m')->where('id',$request['pegawaittd'])->first();
            
        // }
        

        // cari pdf yang sudah di ttd
        $cekPdf = DB::table('emr_bsre_t')
            ->where('statusenabled', true)
            ->where('noregistrasi', trim($data[0]->noregistrasi))
            ->where('nocm', $data[0]->nocm)
            ->where('nomoremr', $data[0]->noemr)
            ->where('status', true)
            ->where('emrfk', $data[0]->emrfk)
            ->get();

        if(count($cekPdf) > 0){
            $link = '/service/storage_path?path='.$cekPdf[0]->file.'&filename='.$cekPdf[0]->namafile.'&mimetype=application/pdf';
            return redirect($link);
        }

        $pdf = PDF::loadView(
            'report.EMR.surat-pemeriksaan-napza-dom',
            array(
                'res' => $res,
                'pageWidth' => $pageWidth,
                'kodeawalsurat' => $kodeAwalSurat,
                'kodeakhirsurat' => $kodeAkhirSurat,
                'data' => $data,
                'profile' => $profile,
                'item'=> $item,
                'peg'=> $peg,
                'tte' => (isset($request['isttd']) && $request['isttd'] == true) ? 'true' : 'false',
                'sip' => $dataSip
            )
        );

        if(isset($request['isttd']) && $request['isttd'] == true){
            $objetoRequest = new \Illuminate\Http\Request();
            $objetoRequest ['emrfk'] = $request['emrfk'];
            $objetoRequest ['norec_emr'] = $request['emr'];
            $objetoRequest ['pegawaittd'] = $request['pegawaittd'];
            $objetoRequest ['nocm'] = $request['nocm'];
            $objetoRequest ['noregistrasi'] = $request['noregistrasi'];
            $objetoRequest ['norec_pd'] = $request['norec_pd'];
            $bsre = app('App\Http\Controllers\Bridging\BridgingBSREController')->pengajuanTTE($objetoRequest,true);
            if($bsre['status'] == 201){
                $content = $pdf->download()->getOriginalContent();
                \Storage::disk('local')->put( 'TTD_BSRE/' . $bsre['dokumen']->id . '/file' . '.pdf' , $content);
            }
          
            return $bsre;
        }

        return $pdf->stream();
    }

    public function cetakPerjenisAnggaranV2(Request $request)
    {

        $sesudah = DB::select(DB::raw("
            SELECT 
                ka.id, 
                ka.kode, 
                ka3.kode as kode3,
                ka2.kode as kode2,
                ka.keterangan,
                ka3.keterangan as keterangan3,
                ka2.keterangan as keterangan2,
                SUM(kb.subtotal) AS total,
                SUM(CASE WHEN ja.jenisanggaran = 'Belanja Pegawai' THEN kb.subtotal ELSE 0 END) AS belanjapegawai,
                SUM(CASE WHEN ja.jenisanggaran = 'Belanja Barang dan Jasa' THEN kb.subtotal ELSE 0 END) AS belanjabarangjasa,
                SUM(CASE WHEN ja.jenisanggaran = 'Belanja Modal Gedung' THEN kb.subtotal ELSE 0 END) AS belanjamodalgedung,
                SUM(CASE WHEN ja.jenisanggaran = 'Belanja Modal Alat dan Mesin' THEN kb.subtotal ELSE 0 END) AS belanjamodalalatmesin,
                SUM(CASE WHEN ja.jenisanggaran = 'Belanja Modal Lainnya' THEN kb.subtotal ELSE 0 END) AS belanjamodallainnya
            FROM keteranganbelanja_t kb
            JOIN transaksianggaran2024_t ta ON ta.norec = kb.objecttransaksifk AND ta.statusenabled = TRUE AND ta.kdprofile = 30
            JOIN kegiatananggaran2024_m ka ON ka.id = ta.objectkegiatanfk AND ka.statusenabled = TRUE AND ka.kdprofile = 30
            JOIN kegiatananggaran2024_m ka3 ON ka3.id = ka.headfk AND ka3.statusenabled = TRUE AND ka3.kdprofile = 30
            JOIN kegiatananggaran2024_m ka2 ON ka2.id = ka3.headfk AND ka2.statusenabled = TRUE AND ka2.kdprofile = 30
            JOIN mataanggaran_m ma ON ma.id = kb.objectmataanggaranfk AND ma.statusenabled = TRUE AND ma.kdprofile = 30 
            JOIN mataanggaran_m ma3 ON ma3.kodemataanggaran ILIKE split_part(ma.kodemataanggaran, '.', 1) || '.' || split_part(ma.kodemataanggaran, '.', 2) || '.' || split_part(ma.kodemataanggaran, '.', 3) AND ma3.statusenabled = TRUE AND ma3.kdprofile = 30
            JOIN jenisanggaran_m ja ON ja.id = ma3.objectjenisanggaranfk AND ja.statusenabled = TRUE AND ja.kdprofile = 30
            WHERE 
                kb.statusenabled = TRUE
                AND ka.kdprofile = 30
                AND ta.tahun = '".$request['tahun']."'
                AND ta.objecttahapfk = ".$request['tahapsesudah']."
            GROUP BY 
                ka.id,
                ka.kode,
                ka3.kode,
                ka2.kode,
                ka.keterangan,
                ka3.keterangan,
                ka2.keterangan
            ORDER BY 
                CAST(split_part(ka.kode, '.', 2) AS integer),
                CAST(split_part(ka.kode, '.', 3) AS integer),
                CAST(split_part(ka.kode, '.', 4) AS integer),
                CAST(split_part(ka.kode, '.', 5) AS integer),
                CAST(split_part(ka.kode, '.', 6) AS integer),
                CAST(split_part(ka.kode, '.', 7) AS integer) ASC 
        "));

        $sebelum = DB::select(DB::raw("
            SELECT 
                ka.id, 
                ka.kode, 
                ka.keterangan,
                SUM(kb.subtotal) AS total,
                SUM(CASE WHEN ja.jenisanggaran = 'Belanja Pegawai' THEN kb.subtotal ELSE 0 END) AS belanjapegawai,
                SUM(CASE WHEN ja.jenisanggaran = 'Belanja Barang dan Jasa' THEN kb.subtotal ELSE 0 END) AS belanjabarangjasa,
                SUM(CASE WHEN ja.jenisanggaran = 'Belanja Modal Gedung' THEN kb.subtotal ELSE 0 END) AS belanjamodalgedung,
                SUM(CASE WHEN ja.jenisanggaran = 'Belanja Modal Alat dan Mesin' THEN kb.subtotal ELSE 0 END) AS belanjamodalalatmesin,
                SUM(CASE WHEN ja.jenisanggaran = 'Belanja Modal Lainnya' THEN kb.subtotal ELSE 0 END) AS belanjamodallainnya
            FROM keteranganbelanja_t kb
            JOIN transaksianggaran2024_t ta ON ta.norec = kb.objecttransaksifk AND ta.statusenabled = TRUE AND ta.kdprofile = 30
            JOIN kegiatananggaran2024_m ka ON ka.id = ta.objectkegiatanfk AND ka.statusenabled = TRUE AND ka.kdprofile = 30
            JOIN kegiatananggaran2024_m ka3 ON ka3.id = ka.headfk AND ka3.statusenabled = TRUE AND ka3.kdprofile = 30
            JOIN kegiatananggaran2024_m ka2 ON ka2.id = ka3.headfk AND ka2.statusenabled = TRUE AND ka2.kdprofile = 30
            JOIN mataanggaran_m ma ON ma.id = kb.objectmataanggaranfk AND ma.statusenabled = TRUE AND ma.kdprofile = 30 
            JOIN mataanggaran_m ma3 ON ma3.kodemataanggaran ILIKE split_part(ma.kodemataanggaran, '.', 1) || '.' || split_part(ma.kodemataanggaran, '.', 2) || '.' || split_part(ma.kodemataanggaran, '.', 3) AND ma3.statusenabled = TRUE AND ma3.kdprofile = 30
            JOIN jenisanggaran_m ja ON ja.id = ma3.objectjenisanggaranfk AND ja.statusenabled = TRUE AND ja.kdprofile = 30
            WHERE 
                kb.statusenabled = TRUE
                AND ka.kdprofile = 30
                AND ta.tahun = '".$request['tahun']."'
                AND ta.objecttahapfk = ".$request['tahapsebelum']."
            GROUP BY 
                ka.id,
                ka.kode,
                ka.keterangan
            ORDER BY 
                CAST(split_part(ka.kode, '.', 2) AS integer),
                CAST(split_part(ka.kode, '.', 3) AS integer),
                CAST(split_part(ka.kode, '.', 4) AS integer),
                CAST(split_part(ka.kode, '.', 5) AS integer),
                CAST(split_part(ka.kode, '.', 6) AS integer),
                CAST(split_part(ka.kode, '.', 7) AS integer) ASC 
        "));

        $tahap = DB::select(DB::raw("
            SELECT * FROM tahapanggaran_m as ta WHERE ta.statusenabled = TRUE AND ta.kdprofile = 30 AND ta.id = ".$request['tahapsesudah']."
        "));

        // dd($sesudah);

        foreach($sesudah as $item){

            $item->total2 = 0;
            $item->belanjapegawai2 = 0;
            $item->belanjabarangjasa2 = 0;
            $item->belanjamodalgedung2 = 0;
            $item->belanjamodalalatmesin2 = 0;
            $item->belanjamodallainnya2 = 0;

            foreach($sebelum as $item2){
                if($item->kode == $item2->kode){
                    $item->total2 = $item2->total;
                    $item->belanjapegawai2 = $item2->belanjapegawai;
                    $item->belanjabarangjasa2 = $item2->belanjabarangjasa;
                    $item->belanjamodalgedung2 = $item2->belanjamodalgedung;
                    $item->belanjamodalalatmesin2 = $item2->belanjamodalalatmesin;
                    $item->belanjamodallainnya2 = $item2->belanjamodallainnya;
                }
            }
        }

        $tanggalcetak = $this->tanggal_indonesia(date('Y-m-d',strtotime($request['tglcetak'])));

        // $pdf = PDF::loadView('report.spj.cetak-jenisanggaran-sebelumsesudah-v2', array(
        //     'data' => $sesudah,
        //     'tanggalcetak' => $tanggalcetak,
        //     'tahap' => $tahap
        // ));

        $settingrba = DB::select(DB::raw("select sa.*, pg.reportdisplay as namalengkap, pg.nippns from settinganggaran_t sa
        inner join pegawai_m pg on pg.id = sa.objectkepalabludfk
        where sa.statusenabled = true"));

        return view('report.spj.cetak-jenisanggaran-sebelumsesudah-v2', [
            'data' => $sesudah,
            'tanggalcetak' => $tanggalcetak,
            'tahap' => $tahap,
            'settingrba' => $settingrba
        ]);

    }

    public function cetakCPPTNewPerTgl(Request $request)
    {
        $noregistrasi = $request['noregistrasi'];
        $tglAwal = $request['tglAwal'];
        $tglAkhir = $request['tglAkhir'];
        $kdProfile = (int) $request['kdprofile'];

        $profile = \DB::select(DB::raw("
                select * from profile_m where id = $kdProfile limit 1
            "));

        $data = DB::select(DB::raw(
            "
                select * from (SELECT
                ROW_NUMBER() OVER (PARTITION BY cp.nocppt ORDER BY cp.tglinput desc ) row_num,
                cp.norec,
                pd.noregistrasi,
                pd.tglregistrasi,
                ps.nocm,
                ps.namapasien,
                cp.noregistrasifk,
                cp.antrianpasiendiperiksafk,
                ru.namaruangan,
                pg.namalengkap,
                cp.nocppt,
                cp.s,
                cp.o,
                cp.a,
                cp.p,
                cp.intruksi,
                cp.riview,cp.tglreview,
                pg2.namalengkap AS namareview,
                cp.tglasesmen,
                cp.objectjenisdokumenfk,
                cp.objectjenispegawaifk,
                cp.s ||cp.o||cp.a||cp.a as soap ,
                jp.jenispegawai,
                to_char(ps.tgllahir, 'DD-MM-YYYY') as tgllahir,
                jk.jeniskelamin,
                ru2.namaruangan as ruanganakhir,pg3.namalengkap as namaterima,
                pg4.namalengkap as dpjpkonsulan, pg5.namalengkap as PPenunjang,
                ru3.namaruangan as ruangcppt
            FROM
                cppt_t AS cp
                INNER JOIN pasiendaftar_t AS pd ON pd.norec = cp.noregistrasifk
                INNER JOIN pasien_m AS ps ON ps.id = pd.nocmfk
                LEFT JOIN ruangan_m AS ru ON ru.id = cp.ruanganfk
                LEFT JOIN pegawai_m AS pg ON pg.id = cp.pegawaifk
                LEFT JOIN pegawai_m AS pg2 ON pg2.id = cp.pegawaireviewfk
                LEFT JOIN pegawai_m AS pg3 ON pg3.id = cp.pegawaiterimafk
                LEFT JOIN antrianpasiendiperiksa_t AS apd ON apd.norec = cp.antrianpasiendiperiksafk
                LEFT JOIN jenispegawai_m AS jp ON jp.id = cp.objectjenispegawaifk 
                inner join jeniskelamin_m as jk on jk.id = ps.objectjeniskelaminfk
                LEFT JOIN ruangan_m AS ru2 ON ru2.id = pd.objectruanganlastfk
                LEFT JOIN pegawai_m AS pg4 ON pg4.id = cp.dpjpkonsulan
                LEFT JOIN pegawai_m AS pg5 ON pg5.id = cp.perawatpenunjang
                LEFT JOIN ruangan_m AS ru3 ON ru3.id = apd.objectruanganfk
            WHERE                
                 cp.statusenabled = true 
                AND cp.noregistrasifk = '$noregistrasi' and cp.tglasesmen between  '" . $request['tglAwal'] . "' and '" . $request['tglAkhir'] . "'
            ORDER BY
                cp.tglasesmen asc) as x where row_num = '1'
                
                "
        ));

        $pageWidth = 500;

        $res['d'] = $data;
            //    dd( $res['d'] );

        return view('report.cppt-ranap-new', compact('res', 'profile', 'pageWidth'));
    }

    public function cetakCPPTNew(Request $request)
    {
        $q = $request['q'];
        $noregistrasi = ($q == 'q') ? $request['norec'] : $request['noregistrasi'];
        $kdProfile = (int) $request['kdprofile'];

        $profile = \DB::select(DB::raw("
                select * from profile_m where id =$kdProfile limit 1
            "));

        $data = DB::select(DB::raw(
            "
                select * from (SELECT
                ROW_NUMBER() OVER (PARTITION BY cp.nocppt ORDER BY cp.tglinput desc ) row_num,
                cp.norec,
                pd.noregistrasi,
                pd.tglregistrasi,
                ps.nocm,
                ps.namapasien,
                cp.noregistrasifk,
                cp.antrianpasiendiperiksafk,
                ru.namaruangan,
                pg.namalengkap,
                cp.nocppt,
                cp.s,
                cp.o,
                cp.a,
                cp.p,
                cp.intruksi,
                cp.riview,cp.tglreview,
                pg2.namalengkap AS namareview,
                cp.tglasesmen,
                cp.objectjenisdokumenfk,
                cp.objectjenispegawaifk,
                cp.s ||cp.o||cp.a|| cp.p as soap ,
                jp.jenispegawai,
                to_char(ps.tgllahir, 'DD-MM-YYYY') as tgllahir,
                jk.jeniskelamin,
                ru2.namaruangan as ruanganakhir,pg3.namalengkap as namaterima,
                pg4.namalengkap as dpjpkonsulan, pg5.namalengkap as PPenunjang,
                ru3.namaruangan as ruangcppt
            FROM
                cppt_t AS cp
                INNER JOIN pasiendaftar_t AS pd ON pd.norec = cp.noregistrasifk
                INNER JOIN pasien_m AS ps ON ps.id = pd.nocmfk
                LEFT JOIN ruangan_m AS ru ON ru.id = cp.ruanganfk
                LEFT JOIN pegawai_m AS pg ON pg.id = cp.pegawaifk
                LEFT JOIN pegawai_m AS pg2 ON pg2.id = cp.pegawaireviewfk
                LEFT JOIN pegawai_m AS pg3 ON pg3.id = cp.pegawaiterimafk
                LEFT JOIN antrianpasiendiperiksa_t AS apd ON apd.norec = cp.antrianpasiendiperiksafk
                LEFT JOIN jenispegawai_m AS jp ON jp.id = cp.objectjenispegawaifk 
                inner join jeniskelamin_m as jk on jk.id = ps.objectjeniskelaminfk
                LEFT JOIN ruangan_m AS ru2 ON ru2.id = pd.objectruanganlastfk
                LEFT JOIN pegawai_m AS pg4 ON pg4.id = cp.dpjpkonsulan
                LEFT JOIN pegawai_m AS pg5 ON pg5.id = cp.perawatpenunjang
                LEFT JOIN ruangan_m AS ru3 ON ru3.id = apd.objectruanganfk
            WHERE                
                 cp.statusenabled = true 
                AND cp.noregistrasifk = '$noregistrasi'
            ORDER BY
                cp.tglasesmen asc) as x where row_num = '1'
                     "
        ));

        $pageWidth = 500;

        $res['d'] = $data;
        // dd(json_encode($res['d']));
        return view('report.cppt-ranap-new', compact('res', 'profile', 'pageWidth'));
    }

    public function cetakSKDPSPRI(Request $request)
    {
        $kdProfile = (int)$request['kdprofile'];
        $ppkPelayanan = $this->settingDataFixed('namaPPKRujukan', $kdProfile);
        $noregistrasi = $request['noregistrasi'];
        $qbinary = base64_decode($request['qbinary']);
        $dataSurat = json_decode($qbinary);
        $tglAyeuna = date('Y-m-d H:i:s');

        $datas = DB::table("pasiendaftar_t as pd")
        ->select("pd.norec as norec_pd", "jk.jeniskelamin", "ps.tgllahir",
            DB::raw("CASE WHEN dg.kddiagnosa IS NULL THEN '-' ELSE dg.kddiagnosa END || '-' || ( CASE WHEN dg.namadiagnosa IS NULL THEN '-' ELSE dg.namadiagnosa END ) AS namadiagnosa")
        )
        ->leftjoin("pemakaianasuransi_t as pa", "pd.norec", "=", "pa.noregistrasifk")
        ->leftjoin("diagnosa_m as dg", "dg.id", "=", "pa.diagnosisfk")
        ->join("pasien_m as ps", "ps.id", "=", "pd.nocmfk")
        ->leftjoin("jeniskelamin_m as jk", "jk.id", "=", "ps.objectjeniskelaminfk")
        ->where("pd.noregistrasi", $noregistrasi)
        ->where("pd.statusenabled", true)
        ->where("pd.kdprofile", $kdProfile)
        ->first();

        if(empty($datas)) {
            echo '
            <script language="javascript">
                window.alert("Tidak ada data.");
                window.close()
            </script>';
            die;
        }

        $pageWidth = 719;

        if(isset($request["issimpanberkas"])) {
            $dataSuratlokal = DB::table("bpjsrencanakontrol_t as br")
            ->select('br.namadokter as namaDokter'
            ,'br.tglrencanakontrol as tglRencanaKontrol'
            ,'br.tglterbitkontrol as tglTerbitKontrol'
            ,'br.nama'
            ,'br.nokartu as noKartu'
            ,'br.namapolitujuan as namaPoliTujuan'
            ,'br.nosuratkontrol as noSuratKontrol'
            ,'br.jnskontrol as jnsKontrol'
            )
            ->join("pasiendaftar_t as pd", "pd.norec", "=", "br.norec_pd")
            ->where("br.statusenabled", true)
            ->where("pd.noregistrasi", $noregistrasi)
            ->first();

            if(empty($dataSuratlokal)) {
                echo '
                <script language="javascript">
                    window.alert("Tidak ada data.");
                    window.close()
                </script>';
                die;
            }

            $dataReport2 = array(
                'ppkPelayanan' => $ppkPelayanan,
                'dataSurat' => $dataSuratlokal,
                'tglAyeuna' => $tglAyeuna,
                'data' => $datas
            );

            $pdf = PDF::loadView('report.pendaftaran.skdpspri', array(
                'dataReport' => $dataReport2,
                'pageWidth' => $pageWidth,
            ));
    
            $this->saveDokumenKlaim($pdf, $request);
            return;
        }

        if(isset($request["q"])) {
            $dataSuratlokal = DB::table("bpjsrencanakontrol_t as br")
            ->select('br.namadokter as namaDokter'
            ,'br.tglrencanakontrol as tglRencanaKontrol'
            ,'br.tglterbitkontrol as tglTerbitKontrol'
            ,'br.nama'
            ,'br.nokartu as noKartu'
            ,'br.namapolitujuan as namaPoliTujuan'
            ,'br.nosuratkontrol as noSuratKontrol'
            ,'br.jnskontrol as jnsKontrol'
            )
            ->join("pasiendaftar_t as pd", "pd.norec", "=", "br.norec_pd")
            ->where("br.statusenabled", true)
            ->where("pd.noregistrasi", $noregistrasi)
            ->first();

            if(empty($dataSuratlokal)) {
                echo '
                <script language="javascript">
                    window.alert("Tidak ada data.");
                    window.close()
                </script>';
                die;
            }

            $dataReport2 = array(
                'ppkPelayanan' => $ppkPelayanan,
                'dataSurat' => $dataSuratlokal,
                'tglAyeuna' => $tglAyeuna,
                'data' => $datas
            );

            $pdf = PDF::loadView('report.pendaftaran.skdpspri', array(
                'dataReport' => $dataReport2,
                'pageWidth' => $pageWidth,
            ));

            return $pdf->stream();
        }

        $dataReport = array(
            'ppkPelayanan' => $ppkPelayanan,
            'dataSurat' => $dataSurat,
            'tglAyeuna' => $tglAyeuna,
            'data' => $datas
        );
        $pdf = PDF::loadView('report.pendaftaran.skdpspri', array(
            'dataReport' => $dataReport,
            'pageWidth' => $pageWidth,
        ));

        return $pdf->stream();
    }

    public function cetakSEPV3(Request $request)
    {
        $kdProfile = (int)$request['kdprofile'];
        $Noregistrasi = $request['noregistrasi'];
        $tglAyeuna = date('Y-m-d H:i:s');
        $ppkPelayanan = $this->settingDataFixed('namaPPKRujukan', $kdProfile);

        $registrasi = collect(DB::select("
             SELECT pa.nosep,to_char(pa.tanggalsep, 'DD-MM-YYYY HH:mm') AS tanggalsep,pa.nokepesertaan,pi.nocm,pd.noregistrasi,
                    pa.norujukan,ap.namapeserta,to_char(pi.tgllahir, 'DD-MM-YYYY') AS tgllahir,jk.jeniskelamin, 
                    rp.namaruangan,rp.kodeexternal as namapoli,pa.ppkrujukan,  
                    (CASE WHEN rp.objectdepartemenfk=16 then 'Rawat Inap' else 'Rawat Jalan' END) as jenisrawat, 
                    dg.kddiagnosa, (case when dg.namadiagnosa is null then '-' else dg.namadiagnosa end) as namadiagnosa ,  
                    ap.jenispeserta,ap.kdprovider,ap.nmprovider,kls.namakelas,pa.catatan,pa.tglcreate,rp.objectdepartemenfk,
                    CASE WHEN pa.statuskunjungan = 1 THEN 'Konsultasi dokter (pertama)'
                    WHEN pa.statuskunjungan = 2 THEN  'Kunjungan rujukan internal'
                    WHEN pa.statuskunjungan = 3 THEN 'Kunjungan Kontrol (ulangan)'
                    ELSE '' END AS kunjungan,ap.notelpmobile,pa.namadjpjpmelayanni,
                    CASE WHEN pa.flagprocedure = '0' THEN 'Prosedur tidak berkelanjutan'
                    WHEN pa.flagprocedure = '1' THEN 'Prosedur dan terapi berkelanjutan'
                    END AS procedures,kls.namakelas AS haknamakelas,
                    CASE WHEN rp.objectdepartemenfk = 18 THEN pa.polirujukannama ELSE '-' END AS polirujukannama,
                    CASE WHEN pa.penjaminlaka = '1' THEN 'Jasa Raharja PT' 
                    WHEN pa.penjaminlaka = '2' THEN 'BPJS Ketenagakerjaan'
                    WHEN pa.penjaminlaka = '3' THEN 'TASPEN PT'
                    WHEN pa.penjaminlaka = '4' THEN 'ASABRI PT'
                    ELSE '-' END AS penjaminlakalantas
             FROM pemakaianasuransi_t pa  
             LEFT JOIN asuransipasien_m ap on pa.objectasuransipasienfk= ap.id  
             LEFT JOIN pasiendaftar_t pd on pd.norec=pa.noregistrasifk  
             LEFT JOIN pasien_m pi on pi.id=pd.nocmfk  
             LEFT JOIN jeniskelamin_m jk on jk.id=pi.objectjeniskelaminfk  
             LEFT JOIN ruangan_m rp on rp.id=pd.objectruanganlastfk  
             LEFT JOIN diagnosa_m dg on pa.diagnosisfk=dg.id 
             LEFT JOIN kelas_m kls on kls.id=ap.objectkelasdijaminfk  
             where pd.noregistrasi ='$Noregistrasi' 
        "))->first();

        if(empty($registrasi)) {
            echo '
            <script language="javascript">
                window.alert("Tidak ada data.");
                window.close()
            </script>';
            die;
        }

        $qrcode = "";//base64_encode(QrCode::format('svg')->size(50)->generate($registrasi->nokepesertaan));
        $pageWidth = 719;
        $dataReport = array(
            'ppkPelayanan' => $ppkPelayanan,
            'nosep' => $registrasi->nosep,
            'tanggalsep' => $registrasi->tanggalsep,
            'nokepesertaan' => $registrasi->nokepesertaan,
            'norm' => $registrasi->nocm,
            'noregistrasi' => $registrasi->noregistrasi,
            'jenispeserta' => $registrasi->jenispeserta,
            'namapeserta' => $registrasi->namapeserta,
            'cob' => "",
            'tgllahir' => $registrasi->tgllahir,
            'jeniskelamin' => $registrasi->jeniskelamin,
            'norujukan' => $registrasi->norujukan,
            'namaruangan' => $registrasi->namaruangan,
            'namapoli' => $registrasi->namapoli,
            'ppkrujukan' => $registrasi->ppkrujukan,
            'jenisrawat' => $registrasi->jenisrawat,
            'kddiagnosa' => $registrasi->kddiagnosa,
            'namadiagnosa' => $registrasi->namadiagnosa,
            'kdprovider' => $registrasi->kdprovider,
            'nmprovider' => $registrasi->nmprovider,
            'namakelas' => $registrasi->namakelas,
            'catatan' => $registrasi->catatan,
            'tanggal' => $tglAyeuna,
            'tglcreate' => $registrasi->tglcreate,
            'kunjungan' => $registrasi->kunjungan,
            'notelpmobile' => $registrasi->notelpmobile,
            'procedures' => $registrasi->procedures,
            'polirujukannama' => $registrasi->polirujukannama,
            'namadjpjpmelayanni' => $registrasi->namadjpjpmelayanni,
            'haknamakelas' => $registrasi->haknamakelas,
            'penjaminlakalantas' => $registrasi->penjaminlakalantas,
            'objectdepartemenfk' => $registrasi->objectdepartemenfk,
        );
        $pdf = PDF::loadView('report.pendaftaran.sepv2', array(
            'dataReport' => $dataReport,
            'pageWidth' => $pageWidth,
            'qrcode' => $qrcode,
        ));

        if(isset($request["issimpanberkas"])) {
            $this->saveDokumenKlaim($pdf, $request);
            return;
        }

        return $pdf->stream();
    }

    public function saveDokumenKlaim($pdf, $request) {
        $profile = collect(DB::select("select * from profile_m where statusenabled = true"))->first();
        if (!in_array($request['iddok'], [17, 87, 88,4,28,56,58])) {
            $content = $pdf->download()->getOriginalContent();
        }
        $path = 'dokumen_klaim/'.$request['isberkasnoreg'];

        try {
            $savePath = public_path($path);
            \File::makeDirectory($savePath, 0755, true, true);
            $cleanNamaFile = str_replace(['/', '\\'], '-', $request['namafile']);
            $namafile = $cleanNamaFile.'_'.$request['isberkasnoreg'].'.pdf';
            $public_path = $savePath."/".$namafile;
            $pdf->save($public_path);
            
            $dataRegistrasi = PasienDaftar::where('noregistrasi', $request['isberkasnoreg'])->first();
            $dataInsert = array(
                "norec" => substr(Uuid::generate(), 0, 32),
                "kdprofile" => $profile->id,
                "statusenabled" => true,
                "filename" => $namafile,
                "filepath" => $path.'/'.$namafile,
                "nocmfk" => $dataRegistrasi->nocmfk,
                "noregistrasifk" => $dataRegistrasi->norec,
                "documentklaimfk" => $request['iddok'],
                "tglupload" => date('Y-m-d H:i:s'),
            );
            if(in_array($request['iddok'], [4,28,56,58])) {
                DB::table('dokklaim_t')->updateOrInsert(["filename" => $namafile, "documentklaimfk" => $request['iddok']], $dataInsert);
            } else {
                DB::table('dokklaim_t')->updateOrInsert(["filename" => $namafile], $dataInsert);
            }

            return response()->json([
                'status' => 'success',
                'message' => 'File berhasil disimpan.'
            ], 200);
        } catch (\Exception $e) {
            return response()->json([
                'status' => 'error',
                'message' => 'File gagal disimpan.',
                'error' => $e->getMessage().' - '.$e->getLine()
            ], 400);
        }
    }

