                ma3.kodemataanggaran AS kode_mataanggaran3,
                MIN(ma3.namamataanggaran) AS nama_mataanggaran3,
                ma2.kodemataanggaran AS kode_mataanggaran2,
                MIN(ma2.namamataanggaran) AS nama_mataanggaran2,
                ma1.kodemataanggaran AS kode_mataanggaran1,
                MIN(ma1.namamataanggaran) AS nama_mataanggaran1,
                SUM(case when extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
                    and bku.tglbku <= DATE_TRUNC('MONTH', timestamp '".$request['tglbku']."')
                then rd.subtotal else 0 end) as total_belanja_bulan_lalu,
                SUM(case when extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
                    and extract(month from bku.tglbku) = extract(month from timestamp '".$request['tglbku']."')
                then rd.subtotal else 0 end) as total_belanja_bulan_ini,
                SUM(
                    CASE 
                        WHEN extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
                        AND (
                            bku.tglbku <= DATE_TRUNC('MONTH', timestamp '".$request['tglbku']."')
                        OR extract(month from bku.tglbku) = extract(month from timestamp '".$request['tglbku']."')
                        )
                    THEN rd.subtotal
                    ELSE 0
                    END
                ) as total_belanja,
                SUM(case when extract(year from pb.tglpengembalian) = extract(year from timestamp '".$request['tglbku']."')
                    and pb.tglpengembalian <= DATE_TRUNC('MONTH', timestamp '".$request['tglbku']."')
                then pb.totalpengembalian else 0 end) as pengembalianbelanja_bulan_lalu,
                SUM(case when extract(year from pb.tglpengembalian) = extract(year from timestamp '".$request['tglbku']."')
                    and extract(month from pb.tglpengembalian) = extract(month from timestamp '".$request['tglbku']."')
                then pb.totalpengembalian else 0 end) as pengembalianbelanja_bulan_ini,
                coalesce(SUM(pb.totalpengembalian), 0) as totalpengembalian,
                mp.id as idmataanggaranpermen,
                ja.id as idjenisanggaran
            FROM strukrealisasi_t sr
            JOIN realisasidetail_t rd ON rd.strukrealisasifk = sr.norec AND rd.statusenabled = TRUE
            JOIN keteranganbelanja_t kb ON kb.norec = rd.keteranganbelanjafk AND kb.statusenabled = TRUE
            JOIN transaksianggaran2024_t ta ON ta.norec = kb.objecttransaksifk AND ta.statusenabled = TRUE
            --JOIN kegiatananggaran_m kalama ON kalama.id = sr.objectkegiatanfk AND kalama.statusenabled = TRUE AND kalama.kdprofile = 30 AND kalama.tahun = '".$settingRBA->tahunanggaran."'
            JOIN kegiatananggaran2024_m ka ON ka.id = ta.objectkegiatanfk AND ka.statusenabled = TRUE AND ka.kdprofile = 30
            JOIN kegiatananggaran2024_m ka3 ON ka3.id = ka.headfk
            JOIN kegiatananggaran2024_m ka2 ON ka2.id = ka3.headfk 
            JOIN kegiatananggaran2024_m ka1 on ka1.id = ka2.headfk
            JOIN mataanggaran_m ma ON ma.id = sr.objectmataanggaranfk AND ma.statusenabled = true
            JOIN mataanggaran_m ma3 ON ma3.id = ma.headfk AND ma3.statusenabled = true and ma3.kdprofile = 30
            JOIN mataanggaran_m ma2 ON ma2.id = ma3.headfk AND ma2.statusenabled = true and ma2.kdprofile = 30
            JOIN mataanggaran_m ma1 ON ma1.id = ma2.headfk AND ma1.statusenabled = true and ma1.kdprofile = 30
            JOIN asalproduk_m ap ON ap.id = sr.objectasalprodukfk AND ap.statusenabled = true and ap.kdprofile = 30
            JOIN bukukasumum_t bku ON bku.norec = sr.objectbkufk AND bku.statusenabled = TRUE AND bku.kdprofile = 30
            LEFT JOIN mataanggaranpermen_m mp ON mp.id = ma.mataanggaranpermenfk
            LEFT JOIN jenisanggaran_m ja on ja.id = ma3.objectjenisanggaranfk
            LEFT JOIN pengembalianbelanja_t pb ON pb.objectspjfk = sr.norec AND pb.statusenabled = true AND pb.objectbkufk IS NOT NULL
            WHERE 
                sr.statusenabled = TRUE
                AND sr.kdprofile = 30
                AND ta.tahun = '".$settingRBA->tahunanggaran."'
                AND sr.objectcarabayarfk = 3
                -- AND sr.objectasalprodukfk IN (".implode(',', $asalProduk).")
                ".$asalproduk_sr."
            GROUP BY
                ka.kode,
                ka3.kode,
                ka2.kode,
                ka1.kode,
                ma.kodemataanggaran,
                ma3.kodemataanggaran,
                ma2.kodemataanggaran,
                ma1.kodemataanggaran,
                mp.id,
                mp.mataanggaranpermen,
                ja.id
            ORDER BY
                COALESCE(NULLIF(SPLIT_PART(ka.kode, '.', 2), ''), '0')::INTEGER ASC,
                COALESCE(NULLIF(SPLIT_PART(ka.kode, '.', 3), ''), '0')::INTEGER ASC,
                COALESCE(NULLIF(SPLIT_PART(ka.kode, '.', 4), ''), '0')::INTEGER ASC,
                COALESCE(NULLIF(SPLIT_PART(ka.kode, '.', 5), ''), '0')::INTEGER ASC,
                COALESCE(NULLIF(SPLIT_PART(ka.kode, '.', 6), ''), '0')::INTEGER ASC,
                COALESCE(NULLIF(SPLIT_PART(ka.kode, '.', 7), ''), '0')::INTEGER ASC,
                COALESCE(NULLIF(SPLIT_PART(ma.kodemataanggaran, '.', 1), ''), '0')::INTEGER ASC,
                COALESCE(NULLIF(SPLIT_PART(ma.kodemataanggaran, '.', 2), ''), '0')::INTEGER ASC,
                COALESCE(NULLIF(SPLIT_PART(ma.kodemataanggaran, '.', 3), ''), '0')::INTEGER ASC,
                COALESCE(NULLIF(SPLIT_PART(ma.kodemataanggaran, '.', 4), ''), '0')::INTEGER ASC,
                COALESCE(NULLIF(SPLIT_PART(ma.kodemataanggaran, '.', 5), ''), '0')::INTEGER ASC,
                COALESCE(NULLIF(SPLIT_PART(ma.kodemataanggaran, '.', 6), ''), '0')::INTEGER ASC
        "));
        // dd($dataSPJLS);

        // $pajakpenerimaan = DB::select(DB::raw("
        //     SELECT
        //         jp.id,
        //         jp.namaexternal,
        //         SUM(case when extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
        //             and bku.tglbku <= DATE_TRUNC('MONTH', timestamp '".$request['tglbku']."')
        //         then bku.penerimaan else 0 end) as total_belanja_bulan_lalu,
        //         SUM(case when extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
        //             and extract(month from bku.tglbku) = extract(month from timestamp '".$request['tglbku']."')
        //         then bku.penerimaan else 0 end) as total_belanja_bulan_ini
        //     FROM pemungutanpajak_t pj
        //     JOIN jenispajak_m jp ON jp.id = pj.objectjenispphfk AND jp.statusenabled = TRUE 
        //     JOIN strukrealisasi_t sr ON sr.norec = pj.objectspjfk AND sr.statusenabled = TRUE 
        //     JOIN kegiatananggaran_m ka ON ka.id = sr.objectkegiatanfk
        //     JOIN mataanggaran_m ma ON ma.id = sr.objectmataanggaranfk
        //     JOIN asalproduk_m ap ON ap.id = sr.objectasalprodukfk
        //     JOIN bukukasumum_t bku ON bku.norec = pj.objectbkufk AND bku.statusenabled = TRUE 
        //     WHERE 
        //         pj.statusenabled = TRUE 
        //         AND sr.objectasalprodukfk = ".$request['asalproduk']."
        //     GROUP BY 
        //         jp.id,
        //         jp.namaexternal
        //     ORDER BY
        //         jp.id
        // "));


        // $pajakpengeluaran = DB::select(DB::raw("
        //     SELECT
        //         jp.id,
        //         jp.namaexternal,
        //         SUM(case when extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
        //             and bku.tglbku <= DATE_TRUNC('MONTH', timestamp '".$request['tglbku']."')
        //         then bku.pengeluaran else 0 end) as total_belanja_bulan_lalu,
        //         SUM(case when extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
        //             and extract(month from bku.tglbku) = extract(month from timestamp '".$request['tglbku']."')
        //         then bku.pengeluaran else 0 end) as total_belanja_bulan_ini
        //     FROM penyetoranpajak_t pj
        //     JOIN jenispajak_m jp ON jp.id = pj.objectjenispphfk AND jp.statusenabled = TRUE 
        //     JOIN strukrealisasi_t sr ON sr.norec = pj.objectspjfk AND sr.statusenabled = TRUE 
        //     JOIN kegiatananggaran_m ka ON ka.id = sr.objectkegiatanfk
        //     JOIN mataanggaran_m ma ON ma.id = sr.objectmataanggaranfk
        //     JOIN asalproduk_m ap ON ap.id = sr.objectasalprodukfk
        //     JOIN bukukasumum_t bku ON bku.norec = pj.objectbkufk AND bku.statusenabled = TRUE 
        //     WHERE 
        //         pj.statusenabled = TRUE 
        //         AND sr.objectasalprodukfk = ".$request['asalproduk']."
        //     GROUP BY 
        //         jp.id,
        //         jp.namaexternal
        //     ORDER BY
        //         jp.id
        // "));

        $pemungutanPajak = DB::select(DB::raw("
            SELECT
                jp.id as idjenispajak,
                jp.namaexternal,
                SUM(case when extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
                    and bku.tglbku < DATE_TRUNC('MONTH', timestamp '".$request['tglbku']."')
                then bku.penerimaan else 0 end) as penerimaan_bulan_lalu,
                SUM(case when extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
                    and extract(month from bku.tglbku) = extract(month from timestamp '".$request['tglbku']."')
                then bku.penerimaan else 0 end) as penerimaan_bulan_ini
            FROM bukukasumum_t bku 
            JOIN pemungutanpajak_t pemp ON pemp.objectbkufk = bku.norec AND pemp.statusenabled = TRUE
            LEFT JOIN jenispajak_m jp ON jp.id = pemp.objectjenispphfk AND jp.statusenabled = TRUE
            WHERE
                bku.statusenabled = TRUE
                AND EXTRACT(YEAR FROM bku.tglbku) = '".$settingRBA->tahunanggaran."'
            GROUP BY
                jp.id
            ORDER BY
                jp.id ASC
        "));

        $penyetoranPajak = DB::select(DB::raw("
            SELECT
                jp.id as idjenispajak,
                jp.namaexternal,
                SUM(case when extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
                    and bku.tglbku < DATE_TRUNC('MONTH', timestamp '".$request['tglbku']."')
                then penpd.setoran else 0 end) as pengeluaran_bulan_lalu,
                SUM(case when extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
                    and extract(month from bku.tglbku) = extract(month from timestamp '".$request['tglbku']."')
                then penpd.setoran else 0 end) as pengeluaran_bulan_ini
            FROM bukukasumum_t bku 
            JOIN penyetoranpajak_t penp ON penp.objectbkufk = bku.norec AND penp.statusenabled = TRUE
            JOIN penyetoranpajakdetail_t penpd ON penpd.objectpenyetoranpajakfk = penp.norec AND penpd.statusenabled = TRUE
            JOIN pemungutanpajak_t pemp ON pemp.norec = penpd.objectpemungutanpajakfk AND pemp.statusenabled = TRUE
            LEFT JOIN jenispajak_m jp ON jp.id = pemp.objectjenispphfk AND jp.statusenabled = TRUE
            WHERE
                bku.statusenabled = TRUE
                AND EXTRACT(YEAR FROM bku.tglbku) = '".$settingRBA->tahunanggaran."'
            GROUP BY
                jp.id
            ORDER BY
                jp.id
        "));

        $jasagiro = DB::select(DB::raw("
            SELECT 
                SUM(case when extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
                    and bku.tglbku < DATE_TRUNC('MONTH', timestamp '".$request['tglbku']."')
                then bku.penerimaan else 0 end) as jasagiro_bulan_lalu,
                SUM(case when extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
                    and extract(month from bku.tglbku) = extract(month from timestamp '".$request['tglbku']."')
                then bku.penerimaan else 0 end) as jasagiro_bulan_ini  
            FROM jasagiro_t jg
            JOIN bukukasumum_t bku ON bku.norec = jg.objectbkufk AND bku.statusenabled = TRUE
            WHERE 
                jg.kdprofile = 30 
                and jg.statusenabled = true
        "));

        $spm = DB::select(DB::raw("
            SELECT 
                SUM(case when extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
                    and bku.tglbku < DATE_TRUNC('MONTH', timestamp '".$request['tglbku']."')
                then bku.penerimaan else 0 end) as spm_bulan_lalu,
                SUM(case when extract(year from bku.tglbku) = extract(year from timestamp '".$request['tglbku']."')
                    and extract(month from bku.tglbku) = extract(month from timestamp '".$request['tglbku']."')
                then bku.penerimaan else 0 end) as spm_bulan_ini  
            FROM spm_t spm
            JOIN bukukasumum_t bku ON bku.norec = spm.objectbkufk AND bku.statusenabled = TRUE
            WHERE 
                spm.kdprofile = 30 
                and spm.statusenabled = true

        "));


        $qtahun  = '';
        if (isset($request['tglbku']) && $request['tglbku'] != "" && $request['tglbku'] != "undefined") {
            $qtahun =  " and extract(year from tglbku) = extract(year from timestamp '".$request['tglbku']."')";
        }

        $qbulan  = '';
        if (isset($request['tglbku']) && $request['tglbku'] != "" && $request['tglbku'] != "undefined") {
            $qbulan =  " and extract(month from tglbku) between 1 and extract(month from timestamp '".$request['tglbku']."')";
        }

        $uangmukakerja = DB::select(DB::raw("
            SELECT 
                SUM(x.pengeluaran) - SUM(x.penerimaan) AS uangmukakerja
            FROM
                (
                select 
                    bku.nobku,
                    to_char( bku.tglbku :: DATE, 'DD-MM-YYYY' ) tgl,
                    bku.uraianbku,
                    bku.penerimaan,
                    bku.pengeluaran,
                    0 saldo 
                FROM
                    bukukasumum_t bku 
                WHERE
                    bku.kdprofile = 30 
                    AND bku.statusenabled = TRUE
                    $qbulan             
                    $qtahun
                    AND bku.objectjenisbuktifk IN ( 3, 7 ) 
                UNION
                
                SELECT
                    bku.nobku,
                    to_char( bku.tglbku :: DATE, 'DD-MM-YYYY' ) tgl,
                    bku.uraianbku,
                    spj.jumlahdibayarverif AS penerimaan,
                    0 pengeluaran,
                    0 saldo 
                FROM
                    bukukasumum_t bku
                    INNER JOIN strukrealisasi_t spj ON bku.norec = spj.objectbkufk
                    INNER JOIN spjtopanjar_t stp ON spj.norec = stp.objectspjfk 
                    where 
                    bku.kdprofile = 30 
                    AND bku.statusenabled = TRUE            
                    $qbulan             
                    $qtahun
                    AND bku.statusenabled = TRUE 
                    AND spj.statusenabled = TRUE 
                ) AS x
        "));

        // dd($uangmukakerja);

        $tanggalcetak = $this->tanggal_indonesia(date('Y-m-d',strtotime($request['tglcetak'])));
        $tanggalbkuindo = $this->tanggal_indonesia(date('Y-m-d',strtotime($request['tglbku'])));
        return view('report.rba.cobalapungv3', [
            'setting' => $settingRBA,
            'data' => $dataAnggaran,
            'spjbku' => $dataSPJ,
            'spjls' => $dataSPJLS,
            // 'pajakpenerimaan' => $pajakpenerimaan,
            // 'pajakpengeluaran' => $pajakpengeluaran,
            'jasagiro' => $jasagiro,
            'spm' => $spm,
            'uangmukakerja' => $uangmukakerja,
            'penyetoranPajak' => $penyetoranPajak,
            'pemungutanPajak' => $pemungutanPajak,
            'tanggalcetak' => $tanggalcetak,
            'tanggalbku' => $tanggalbkuindo
            // 'pajak' => $pajak
            // 'jenisAnggaran' => $dataJenisAnggaran
        ]);
    } 

    public function suratTugasAmbulan(Request $request)
    {
        $profile = (int)$request['kdprofile'];
        $nostrukfk = $request['norec'];

        // Menggunakan parameter binding untuk keamanan
        $data = collect(DB::select(
            "SELECT
                spd.norec,
                pg.namalengkap,
                pg.nip,
                jp.id,
                jp.jenispegawai AS jabatan,
                spd.tglpelayanan,
                jka.namajeniskegiatan
            FROM
                strukpelayanandetail_t AS spd
                LEFT JOIN petugaspelayananambulan_t AS ppa ON ppa.nostrukdetailfk = spd.norec
                LEFT JOIN pegawai_m AS pg ON pg.id = ppa.objectpegawaifk
                LEFT JOIN jenispegawai_m AS jp ON jp.id = pg.objectjenispegawaifk
                LEFT JOIN jeniskegiatanambulan_m AS jka ON jka.id = spd.jeniskegiatanambulanfk::bigint
            WHERE
                spd.kdprofile = :profile
                AND spd.statusenabled = TRUE
