        //     WHERE 
        //         cap.statusenabled = TRUE
        //         AND cap.kdprofile = 30
        //         AND cap.level = 8
        //     ORDER BY cap.id ASC
        // "));

        $detailv2 = DB::select(DB::raw("
            SELECT
                cap_stsd.id as idrekening,
                cap_stsd.koderekening,
                cap_stsd.namarekening,
                stsd2.totalsetoran as totaldibayarclosing,
                cap7.id as idlevel7,
