            $detail = DB::select(DB::raw("
                SELECT 
                    sts.nosts,
                    cap.id as idrekening,
                    cap.koderekening, 
                    cap.namarekening,
                    cap7.id as idlevel7,
                    cap7.koderekening as koderekeninglevel7,
                    cap7.namarekening as namarekeninglevel7,
                    cap6.id as idlevel6,
                    cap6.koderekening as koderekeninglevel6,
                    cap6.namarekening as namarekeninglevel6,
                    cap5.id as idlevel5,
                    cap5.koderekening as koderekeninglevel5,
                    cap5.namarekening as namarekeninglevel5,
                    cap4.id as idlevel4,
                    cap4.koderekening as koderekeninglevel4,
                    cap4.namarekening as namarekeninglevel4,
                    cap3.id as idlevel3,
                    cap3.koderekening as koderekeninglevel3,
                    cap3.namarekening as namarekeninglevel3,
                    cap2.id as idlevel2,
                    cap2.koderekening as koderekeninglevel2,
                    cap2.namarekening as namarekeninglevel2,
                    cap1.id as idlevel1,
                    cap1.koderekening as koderekeninglevel1,
                    cap1.namarekening as namarekeninglevel1,
                    SUM(rkb.totalsetujui) as totaldibayarclosing
                FROM rekapklaimbpjs_t rkb
                LEFT JOIN pasiendaftar_t pd on pd.norec = rkb.norecpdfk
                LEFT JOIN ruangan_m ru on ru.id = pd.objectruanganlastfk
                LEFT JOIN kelompokpasien_m kp on kp.id = pd.objectkelompokpasienlastfk
                JOIN ststorekapklaim_t strk ON strk.objectrekapklaimfk = rkb.norec AND strk.statusenabled = TRUE 
                JOIN surattandasetoran_t sts ON sts.norec = strk.objectstsfk AND sts.statusenabled = TRUE 
                JOIN mapbkuakun_t mba 
                    ON pd.objectkelompokpasienlastfk::VARCHAR = ANY(string_to_array(mba.objectkelompokpasienfk, ','))
                    AND pd.objectruanganlastfk::VARCHAR = ANY(string_to_array(mba.objectruanganfk , ','))
                    AND mba.statusenabled = TRUE
                LEFT JOIN char_akun_pendapatan_m cap ON cap.id = mba.objectakunpendapatanfk
                LEFT JOIN char_akun_pendapatan_m cap7 ON cap7.id = cap.headfk
                LEFT JOIN char_akun_pendapatan_m cap6 ON cap6.id = cap7.headfk
                LEFT JOIN char_akun_pendapatan_m cap5 ON cap5.id = cap6.headfk
                LEFT JOIN char_akun_pendapatan_m cap4 ON cap4.id = cap5.headfk
                LEFT JOIN char_akun_pendapatan_m cap3 ON cap3.id = cap4.headfk
                LEFT JOIN char_akun_pendapatan_m cap2 ON cap2.id = cap3.headfk
                LEFT JOIN char_akun_pendapatan_m cap1 ON cap1.id = cap2.headfk
                WHERE 
                    rkb.statusenabled = TRUE 
                    AND sts.nosts = '".$request['nosts']."'
                    AND (
                        (mba.isobat IS NOT TRUE AND rkb.isobat IS NULL) 
                        OR 
                        (mba.isobat = TRUE AND rkb.isobat = TRUE)
                    )
                GROUP BY 
                    sts.nosts,
                    cap.id,
                    cap.koderekening, 
                    cap.namarekening,
                    cap7.id,
                    cap6.id,
                    cap5.id,
                    cap4.id,
                    cap3.id,
                    cap2.id,
                    cap1.id
                ORDER BY
                    split_part(cap.koderekening, '.', 3)::DECIMAL,
                    split_part(cap.koderekening, '.', 4)::DECIMAL,
                    split_part(cap.koderekening, '.', 5)::DECIMAL,
                    split_part(cap.koderekening, '.', 6)::DECIMAL,
                    split_part(cap.koderekening, '.', 7)::DECIMAL,
                    split_part(cap.koderekening, '.', 8)::DECIMAL ASC
            "));

            $data = $detail;
        }

        $sts = DB::select(DB::raw("
            SELECT * 
            FROM surattandasetoran_t sts 
            WHERE 
                sts.statusenabled = TRUE 
                AND sts.kdprofile = 30 
                AND sts.nosts = '".$request['nosts']."'  
        "));

        return view('report.spj.cetak-stsklaimv2',compact( 'data', 'sts'));
    }

    public function cetakBKUPenerimaanV2(Request $request)
    {

        $profile = DB::select("select*from profile_m where kdprofile = 30 and statusenabled = true");

        // ambil saldo awal dari saldoawal_bkubp untuk januari
        $saldoawal = DB::select(DB::raw("
            SELECT
                sabp.*
            FROM saldoawal_bkubp_t sabp
            WHERE
                sabp.statusenabled = true
                AND sabp.kdprofile = 30
                AND tahun = ".date('Y', strtotime($request['tglbku']))."
                AND bulan = 1
        "));

        $saldobulanlalu = 0;
        // jika tglbku bukan bulan januari maka saldo bulan lalu diambil dari saldo bulanjanuari
        // jika tglbku bulan januari maka ambil saldo dari entrian saldo awal
        if(date('m', strtotime($request['tglbku'])) !== '01'){

            // data bulan sebelumnya
            $bulan_sebelumnya = DB::select(DB::raw("

                SELECT
                    COALESCE(SUM(bkup.totalpenerimaan), 0) as totalpenerimaan,
                    COALESCE(SUM(bkup.totalpengeluaran), 0) as totalpengeluaran,
                    COALESCE(SUM(bkup.totalpengeluaran), 0) - COALESCE(SUM(bkup.totalpengeluaran), 0) as totalakhir
                FROM bkupenerimaanv2_t bkup
                LEFT JOIN surattandasetoran_t sts ON sts.norec = bkup.objectstsfk AND sts.statusenabled = TRUE
                LEFT JOIN char_akun_pendapatan_m cap ON cap.id = bkup.objectakunpendapatanfk AND cap.statusenabled = TRUE
                LEFT JOIN spm_t spm ON spm.norec = bkup.objectspmfk AND spm.statusenabled = TRUE
                LEFT JOIN spp_t spp on spp.norec = spm.objectsppfk AND spp.statusenabled = TRUE
                LEFT JOIN asalproduk_m ap on ap.id = spm.objectasalprodukfk and ap.statusenabled = true 
                WHERE
                    bkup.statusenabled = TRUE
                    AND bkup.kdprofile = 30
                    AND extract(year from bkup.tglbku) = ".date('Y', strtotime($request['tglbku']))."
                    AND bkup.tglbku::DATE < date_trunc('month', '".$request['tglbku']."'::DATE)
            "));

            // masukan dulu saldoawaljanuari
            if(count($saldoawal) > 0){
                $saldobulanlalu = $saldoawal[0]->saldoawal;
            }

            foreach($bulan_sebelumnya as $item){
                $saldobulanlalu += (float)$item->totalpenerimaan;
                $saldobulanlalu -= (float)$item->totalpengeluaran;
            }

        }else{
            if(count($saldoawal) > 0){
                $saldobulanlalu = $saldoawal[0]->saldoawal;
            }

        }

        // data bulan yang dipilih
        $bulan_sekarang = DB::select(DB::raw("

            SELECT
                bkup.*, sts.nosts, COALESCE(cap.koderekening, '') as norekening
            FROM bkupenerimaanv2_t bkup
            LEFT JOIN surattandasetoran_t sts ON sts.norec = bkup.objectstsfk AND sts.statusenabled = TRUE
            LEFT JOIN char_akun_pendapatan_m cap ON cap.id = bkup.objectakunpendapatanfk AND cap.statusenabled = TRUE
            LEFT JOIN spm_t spm ON spm.norec = bkup.objectspmfk AND spm.statusenabled = TRUE
            LEFT JOIN spp_t spp on spp.norec = spm.objectsppfk AND spp.statusenabled = TRUE
            LEFT JOIN asalproduk_m ap on ap.id = spm.objectasalprodukfk and ap.statusenabled = true 
            WHERE
                bkup.statusenabled = TRUE
                AND bkup.kdprofile = 30
                AND bkup.tglbku BETWEEN date_trunc('month', '".$request['tglbku']."'::DATE) AND '".$request['tglbku']."'::DATE 
        
        "));

        $saldobulansekarang = 0;
        foreach($bulan_sekarang as $item){
            $saldobulansekarang += (float)$item->totalpenerimaan;
            $saldobulansekarang -= (float)$item->totalpengeluaran;
        }

        $tglbku = date('d m Y', strtotime($request['tglbku']));
        
        setlocale(LC_ALL, 'IND');
        $bulan = strftime('%B', strtotime($request['tglbku']));
        $tglindo = $this->tanggal_indonesia($request['tglcetak']);
        
        return view('report.keuangan.cetak-bkupenerimaanv2',compact('saldobulanlalu', 'bulan_sekarang', 'saldobulansekarang', 'profile', 'tglbku', 'bulan', 'tglindo'));

    }

    public function cetakSPJBPV2(Request $request)
    {

        // data rekening
        $rekening = DB::select(DB::raw("
            SELECT 
                cap.id as idrekening,
                cap.koderekening,
                cap.namarekening,
                cap.headfk,
                cap7.id as idlevel7,
                cap7.koderekening as koderekeninglevel7,
                cap7.namarekening as namarekeninglevel7,
                cap7.headfk as headfklevel7,
                cap6.id as idlevel6,
                cap6.koderekening as koderekeninglevel6,
                cap6.namarekening as namarekeninglevel6,
                cap6.headfk as headfklevel6,
                cap5.id as idlevel5,
                cap5.koderekening as koderekeninglevel5,
                cap5.namarekening as namarekeninglevel5,
                cap5.headfk as headfklevel5,
                cap4.id as idlevel4,
                cap4.koderekening as koderekeninglevel4,
                cap4.namarekening as namarekeninglevel4,
                cap4.headfk as headfklevel4,
                cap3.id as idlevel3,
                cap3.koderekening as koderekeninglevel3,
                cap3.namarekening as namarekeninglevel3,
                cap3.headfk as headfklevel3,
                cap2.id as idlevel2,
                cap2.koderekening as koderekeninglevel2,
                cap2.namarekening as namarekeninglevel2,
                cap2.headfk as headfklevel2,
                cap1.id as idlevel1,
                cap1.koderekening as koderekeninglevel1,
                cap1.namarekening as namarekeninglevel1,
                cap1.headfk as headfklevel1
            FROM char_akun_pendapatan_m cap
            LEFT JOIN char_akun_pendapatan_m cap7 ON cap7.id = cap.headfk
            LEFT JOIN char_akun_pendapatan_m cap6 ON cap6.id = cap7.headfk
            LEFT JOIN char_akun_pendapatan_m cap5 ON cap5.id = cap6.headfk
            LEFT JOIN char_akun_pendapatan_m cap4 ON cap4.id = cap5.headfk
            LEFT JOIN char_akun_pendapatan_m cap3 ON cap3.id = cap4.headfk
            LEFT JOIN char_akun_pendapatan_m cap2 ON cap2.id = cap3.headfk
            LEFT JOIN char_akun_pendapatan_m cap1 ON cap1.id = cap2.headfk
            WHERE 
                cap.statusenabled = TRUE
                AND cap.kdprofile = 30
                AND cap.level = 8
            ORDER BY 
                cap.id asc
        "));


        // data target pendapatan
        $targetawal = DB::select(DB::raw("
            SELECT
                --rp.norec,
                --rp.keterangan,
                --rp.uraianpendapatan,
                --rp.tahun,
                --rp.objectasalprodukfk,
                SUM(rp.jumlahpendapatan) as jumlahpendapatan,
                --rp.objecturaianpendapatanfk,
                --rp.objecttahapfk,
                --ta.tahap, 
                cap.id as idrekening,
                cap.koderekening,
                cap.namarekening,
                cap7.id as idlevel7,
                cap7.koderekening as koderekeninglevel7,
                cap7.namarekening as namarekeninglevel7,
                cap7.headfk as headfklevel7,
                cap6.id as idlevel6,
                cap6.koderekening as koderekeninglevel6,
                cap6.namarekening as namarekeninglevel6,
                cap6.headfk as headfklevel6,
                cap5.id as idlevel5,
                cap5.koderekening as koderekeninglevel5,
                cap5.namarekening as namarekeninglevel5,
                cap5.headfk as headfklevel5,
                cap4.id as idlevel4,
                cap4.koderekening as koderekeninglevel4,
                cap4.namarekening as namarekeninglevel4,
                cap4.headfk as headfklevel4,
                cap3.id as idlevel3,
                cap3.koderekening as koderekeninglevel3,
                cap3.namarekening as namarekeninglevel3,
                cap3.headfk as headfklevel3,
                cap2.id as idlevel2,
                cap2.koderekening as koderekeninglevel2,
                cap2.namarekening as namarekeninglevel2,
                cap2.headfk as headfklevel2,
                cap1.id as idlevel1,
                cap1.koderekening as koderekeninglevel1,
                cap1.namarekening as namarekeninglevel1,
                cap1.headfk as headfklevel1
            FROM rincianpendapatan_t rp
            JOIN char_akun_pendapatan_m AS cap ON cap.id = rp.objecturaianpendapatanfk AND cap.statusenabled = TRUE AND cap.kdprofile = 30
            LEFT JOIN char_akun_pendapatan_m cap7 ON cap7.id = cap.headfk
            LEFT JOIN char_akun_pendapatan_m cap6 ON cap6.id = cap7.headfk
            LEFT JOIN char_akun_pendapatan_m cap5 ON cap5.id = cap6.headfk
            LEFT JOIN char_akun_pendapatan_m cap4 ON cap4.id = cap5.headfk
            LEFT JOIN char_akun_pendapatan_m cap3 ON cap3.id = cap4.headfk
            LEFT JOIN char_akun_pendapatan_m cap2 ON cap2.id = cap3.headfk
            LEFT JOIN char_akun_pendapatan_m cap1 ON cap1.id = cap2.headfk
            JOIN tahapanggaran_m AS ta ON ta.id = rp.objecttahapfk AND ta.statusenabled = true AND ta.kdprofile = 30
            JOIN asalproduk_m AS ap ON ap.id = rp.objectasalprodukfk AND ap.statusenabled = true AND ap.kdprofile = 30
            WHERE 
                rp.statusenabled = true 
                AND rp.kdprofile = 30
                AND rp.objecttahapfk = ".$request['tahapawal']."
                AND rp.tahun = '".date('Y', strtotime($request['tglbku']))."'
            GROUP BY
                cap.id,
                cap7.id,
                cap6.id,
                cap5.id,
                cap4.id,
                cap3.id,
                cap2.id,
                cap1.id
            ORDER BY
                cap.id asc
        "));

        $targetakhir = DB::select(DB::raw("
            SELECT
                --rp.norec,
                --rp.keterangan,
                --rp.uraianpendapatan,
                --rp.tahun,
                --rp.objectasalprodukfk,
                SUM(rp.jumlahpendapatan) as jumlahpendapatan,
                --rp.objecturaianpendapatanfk,
                --rp.objecttahapfk,
                --ta.tahap, 
                cap.id as idrekening,
                cap.koderekening,
                cap.namarekening,
                cap7.id as idlevel7,
                cap7.koderekening as koderekeninglevel7,
                cap7.namarekening as namarekeninglevel7,
                cap7.headfk as headfklevel7,
                cap6.id as idlevel6,
                cap6.koderekening as koderekeninglevel6,
                cap6.namarekening as namarekeninglevel6,
                cap6.headfk as headfklevel6,
                cap5.id as idlevel5,
                cap5.koderekening as koderekeninglevel5,
                cap5.namarekening as namarekeninglevel5,
                cap5.headfk as headfklevel5,
                cap4.id as idlevel4,
                cap4.koderekening as koderekeninglevel4,
                cap4.namarekening as namarekeninglevel4,
                cap4.headfk as headfklevel4,
                cap3.id as idlevel3,
                cap3.koderekening as koderekeninglevel3,
                cap3.namarekening as namarekeninglevel3,
                cap3.headfk as headfklevel3,
                cap2.id as idlevel2,
                cap2.koderekening as koderekeninglevel2,
                cap2.namarekening as namarekeninglevel2,
                cap2.headfk as headfklevel2,
                cap1.id as idlevel1,
                cap1.koderekening as koderekeninglevel1,
                cap1.namarekening as namarekeninglevel1,
                cap1.headfk as headfklevel1
            FROM rincianpendapatan_t rp
            JOIN char_akun_pendapatan_m AS cap ON cap.id = rp.objecturaianpendapatanfk AND cap.statusenabled = TRUE AND cap.kdprofile = 30
            LEFT JOIN char_akun_pendapatan_m cap7 ON cap7.id = cap.headfk
            LEFT JOIN char_akun_pendapatan_m cap6 ON cap6.id = cap7.headfk
            LEFT JOIN char_akun_pendapatan_m cap5 ON cap5.id = cap6.headfk
            LEFT JOIN char_akun_pendapatan_m cap4 ON cap4.id = cap5.headfk
            LEFT JOIN char_akun_pendapatan_m cap3 ON cap3.id = cap4.headfk
            LEFT JOIN char_akun_pendapatan_m cap2 ON cap2.id = cap3.headfk
            LEFT JOIN char_akun_pendapatan_m cap1 ON cap1.id = cap2.headfk
            JOIN tahapanggaran_m AS ta ON ta.id = rp.objecttahapfk AND ta.statusenabled = true AND ta.kdprofile = 30
            JOIN asalproduk_m AS ap ON ap.id = rp.objectasalprodukfk AND ap.statusenabled = true AND ap.kdprofile = 30
            WHERE 
                rp.statusenabled = true 
                AND rp.kdprofile = 30
                AND rp.objecttahapfk = ".$request['tahapakhir']."
                AND rp.tahun = '".date('Y', strtotime($request['tglbku']))."'
            GROUP BY
                cap.id,
                cap7.id,
                cap6.id,
                cap5.id,
                cap4.id,
                cap3.id,
                cap2.id,
                cap1.id
            ORDER BY
                cap.id asc
        "));


        // data sts dan dan spm yang sudah dibkukan
        $data = DB::select(DB::raw("
        
            SELECT
                bkup.nobku, 
                bkup.tglbku,
                CASE WHEN extract(year from bkup.tglbku) = extract(year from timestamp '".$request['tglbku']."')
                    and bkup.tglbku <= DATE_TRUNC('MONTH', timestamp '".$request['tglbku']."')
                THEN stsd.totalsetoran else 0 end as total_bku_bulan_lalu,
                CASE WHEN extract(year from bkup.tglbku) = extract(year from timestamp '".$request['tglbku']."')
                    and extract(month from bkup.tglbku) = extract(month from timestamp '".$request['tglbku']."')
                THEN stsd.totalsetoran else 0 end as total_bku_bulan_ini,
                sts.nosts,
                stsd.totalsetoran AS totalsetoransts, 
                ap.asalproduk,
                cap.id AS idrekening,
                cap.namarekening, 
                cap.koderekening, 
                cap7.id as idlevel7,
                cap7.koderekening as koderekeninglevel7,
                cap7.namarekening as namarekeninglevel7,
                cap7.headfk as headfklevel7,
                cap6.id as idlevel6,
                cap6.koderekening as koderekeninglevel6,
                cap6.namarekening as namarekeninglevel6,
                cap6.headfk as headfklevel6,
                cap5.id as idlevel5,
                cap5.koderekening as koderekeninglevel5,
                cap5.namarekening as namarekeninglevel5,
                cap5.headfk as headfklevel5,
                cap4.id as idlevel4,
                cap4.koderekening as koderekeninglevel4,
                cap4.namarekening as namarekeninglevel4,
                cap4.headfk as headfklevel4,
                cap3.id as idlevel3,
                cap3.koderekening as koderekeninglevel3,
                cap3.namarekening as namarekeninglevel3,
                cap3.headfk as headfklevel3,
                cap2.id as idlevel2,
                cap2.koderekening as koderekeninglevel2,
                cap2.namarekening as namarekeninglevel2,
                cap2.headfk as headfklevel2,
                cap1.id as idlevel1,
                cap1.koderekening as koderekeninglevel1,
                cap1.namarekening as namarekeninglevel1,
                cap1.headfk as headfklevel1
            FROM bkupenerimaanv2_t bkup
            JOIN surattandasetoran_t sts ON sts.norec = bkup.objectstsfk AND sts.statusenabled = TRUE
            JOIN surattandasetorandetailv2_t stsd ON stsd.objectstsfk = sts.nosts AND sts.statusenabled = TRUE 
            LEFT JOIN asalproduk_m ap on ap.id = bkup.objectasalprodukfk AND ap.statusenabled = TRUE 
            LEFT JOIN char_akun_pendapatan_m cap ON cap.id = stsd.objectakunpendapatanfk AND cap.statusenabled = TRUE
            LEFT JOIN char_akun_pendapatan_m cap7 ON cap7.id = cap.headfk
            LEFT JOIN char_akun_pendapatan_m cap6 ON cap6.id = cap7.headfk
            LEFT JOIN char_akun_pendapatan_m cap5 ON cap5.id = cap6.headfk
            LEFT JOIN char_akun_pendapatan_m cap4 ON cap4.id = cap5.headfk
            LEFT JOIN char_akun_pendapatan_m cap3 ON cap3.id = cap4.headfk
            LEFT JOIN char_akun_pendapatan_m cap2 ON cap2.id = cap3.headfk
            LEFT JOIN char_akun_pendapatan_m cap1 ON cap1.id = cap2.headfk 
            WHERE
                bkup.statusenabled = TRUE
                AND bkup.kdprofile = 30

        "));

        $settingrba = DB::table('settinganggaran_t')->where('statusenabled', true)->where('kdprofile', 30)->first();

        setlocale(LC_ALL, 'IND');
        $bulan = strftime('%B', strtotime($request['tglbku']));
        $tglindo = strftime('%d %B %Y', strtotime($request['tglcetak']));

        return view('report.keuangan.cetak-spjbpv2',compact('rekening', 'targetawal', 'targetakhir', 'data', 'bulan', 'settingrba', 'tglindo'));

    }

    public function cetakTargetPendapatanBP(Request $request)
