        }else{
            $tahun = "and ta.tahun = '".$setting[0]->tahunanggaran."'";
        }

        $tahap = '';
        if (isset($request['tahap']) && $request['tahap'] != "" && $request['tahap'] != "undefined") {
            $tahap = "and ta.objecttahapfk = '".$request['tahap']."'";
        }
        
        $subsubkegiatan = '';
