            when kodemataanggaran ilike 'I.A.%' then 1
            when kodemataanggaran ilike 'I.B.%' then 2
            when kodemataanggaran ilike 'II.%' then 3
            when kodemataanggaran ilike 'III.%' then 4
          end as urut1,
          case 
