                    and extract(month from bkup.tglbku) = 3
                THEN stsd.totalsetoran else 0 end as maret,
                CASE WHEN extract(year from bkup.tglbku) = '".$request['tahun']."'
                    and extract(month from bkup.tglbku) = 4
