                THEN stsd.totalsetoran else 0 end as mei,
                CASE WHEN extract(year from bkup.tglbku) = '".$request['tahun']."'
                    and extract(month from bkup.tglbku) = 6
                THEN stsd.totalsetoran else 0 end as juni,
                CASE WHEN extract(year from bkup.tglbku) = '".$request['tahun']."'
                    and extract(month from bkup.tglbku) = 7
                THEN stsd.totalsetoran else 0 end as juli,
                CASE WHEN extract(year from bkup.tglbku) = '".$request['tahun']."'
                    and extract(month from bkup.tglbku) = 8
                THEN stsd.totalsetoran else 0 end as agustus,
                CASE WHEN extract(year from bkup.tglbku) = '".$request['tahun']."'
                    and extract(month from bkup.tglbku) = 9
                THEN stsd.totalsetoran else 0 end as september,
                CASE WHEN extract(year from bkup.tglbku) = '".$request['tahun']."'
                    and extract(month from bkup.tglbku) = 10
                THEN stsd.totalsetoran else 0 end as oktober,
                CASE WHEN extract(year from bkup.tglbku) = '".$request['tahun']."'
                    and extract(month from bkup.tglbku) = 11
                THEN stsd.totalsetoran else 0 end as november,
                CASE WHEN extract(year from bkup.tglbku) = '".$request['tahun']."'
                    and extract(month from bkup.tglbku) = 12
                THEN stsd.totalsetoran else 0 end as desember,
                sts.nosts,
                stsd.totalsetoran AS totalsetoransts, 
                ap.asalproduk,
                cap.id AS idrekening,
                cap.namarekening, 
                cap.koderekening, 
                cap7.id as idlevel7,
                cap7.koderekening as koderekeninglevel7,
                cap7.namarekening as namarekeninglevel7,
                cap7.headfk as headfklevel7,
                cap6.id as idlevel6,
                cap6.koderekening as koderekeninglevel6,
                cap6.namarekening as namarekeninglevel6,
                cap6.headfk as headfklevel6,
                cap5.id as idlevel5,
                cap5.koderekening as koderekeninglevel5,
                cap5.namarekening as namarekeninglevel5,
                cap5.headfk as headfklevel5,
                cap4.id as idlevel4,
                cap4.koderekening as koderekeninglevel4,
                cap4.namarekening as namarekeninglevel4,
                cap4.headfk as headfklevel4,
                cap3.id as idlevel3,
                cap3.koderekening as koderekeninglevel3,
                cap3.namarekening as namarekeninglevel3,
                cap3.headfk as headfklevel3,
                cap2.id as idlevel2,
                cap2.koderekening as koderekeninglevel2,
                cap2.namarekening as namarekeninglevel2,
                cap2.headfk as headfklevel2,
                cap1.id as idlevel1,
                cap1.koderekening as koderekeninglevel1,
                cap1.namarekening as namarekeninglevel1,
                cap1.headfk as headfklevel1
            FROM bkupenerimaanv2_t bkup
            JOIN surattandasetoran_t sts ON sts.norec = bkup.objectstsfk AND sts.statusenabled = TRUE
            JOIN surattandasetorandetailv2_t stsd ON stsd.objectstsfk = sts.nosts AND sts.statusenabled = TRUE 
            LEFT JOIN asalproduk_m ap on ap.id = bkup.objectasalprodukfk AND ap.statusenabled = TRUE 
            LEFT JOIN char_akun_pendapatan_m cap ON cap.id = stsd.objectakunpendapatanfk AND cap.statusenabled = TRUE
            LEFT JOIN char_akun_pendapatan_m cap7 ON cap7.id = cap.headfk
            LEFT JOIN char_akun_pendapatan_m cap6 ON cap6.id = cap7.headfk
            LEFT JOIN char_akun_pendapatan_m cap5 ON cap5.id = cap6.headfk
            LEFT JOIN char_akun_pendapatan_m cap4 ON cap4.id = cap5.headfk
            LEFT JOIN char_akun_pendapatan_m cap3 ON cap3.id = cap4.headfk
            LEFT JOIN char_akun_pendapatan_m cap2 ON cap2.id = cap3.headfk
            LEFT JOIN char_akun_pendapatan_m cap1 ON cap1.id = cap2.headfk 
            WHERE
                bkup.statusenabled = TRUE
                AND bkup.kdprofile = 30
                AND extract(year from bkup.tglbku) = '".$request['tahun']."'
        "));

        $settingrba = DB::table('settinganggaran_t')->where('statusenabled', true)->where('kdprofile', 30)->first();

        setlocale(LC_ALL, 'IND');
        $bulan = strftime('%B', strtotime($request['tglbku']));
        $tglindo = strftime('%d %B %Y', strtotime($request['tglcetak']));
        $tahun = $request['tahun'];

        return view('report.spj.cetak-spj-bulanan-bp',compact('rekening', 'target', 'data', 'bulan', 'settingrba', 'tglindo', 'tahun'));

    }

    public function cetakSTSManualV2(Request $request)
    {
        $nosts = $request['nosts'];

        $data = DB::select(DB::raw("
            SELECT
                cap_stsd.id as idrekening,
                cap_stsd.koderekening,
                cap_stsd.namarekening,
                SUM(stsd2.totalsetoran) as totaldibayarclosing,
                cap7.id as idlevel7,
                cap7.koderekening as koderekeninglevel7,
                cap7.namarekening as namarekeninglevel7,
                cap6.id as idlevel6,
                cap6.koderekening as koderekeninglevel6,
                cap6.namarekening as namarekeninglevel6,
                cap5.id as idlevel5,
                cap5.koderekening as koderekeninglevel5,
                cap5.namarekening as namarekeninglevel5,
                cap4.id as idlevel4,
                cap4.koderekening as koderekeninglevel4,
                cap4.namarekening as namarekeninglevel4,
                cap3.id as idlevel3,
                cap3.koderekening as koderekeninglevel3,
                cap3.namarekening as namarekeninglevel3,
                cap2.id as idlevel2,
                cap2.koderekening as koderekeninglevel2,
                cap2.namarekening as namarekeninglevel2,
                cap1.id as idlevel1,
                cap1.koderekening as koderekeninglevel1,
                cap1.namarekening as namarekeninglevel1
            FROM surattandasetorandetailv2_t stsd2
            JOIN char_akun_pendapatan_m cap_stsd ON cap_stsd.id = stsd2.objectakunpendapatanfk AND cap_stsd.statusenabled = TRUE AND cap_stsd.kdprofile = 30
            LEFT JOIN char_akun_pendapatan_m cap7 ON cap7.id = cap_stsd.headfk
            LEFT JOIN char_akun_pendapatan_m cap6 ON cap6.id = cap7.headfk
            LEFT JOIN char_akun_pendapatan_m cap5 ON cap5.id = cap6.headfk
            LEFT JOIN char_akun_pendapatan_m cap4 ON cap4.id = cap5.headfk
            LEFT JOIN char_akun_pendapatan_m cap3 ON cap3.id = cap4.headfk
            LEFT JOIN char_akun_pendapatan_m cap2 ON cap2.id = cap3.headfk
            LEFT JOIN char_akun_pendapatan_m cap1 ON cap1.id = cap2.headfk
            WHERE
                stsd2.objectstsfk = '".$nosts."'
                AND stsd2.statusenabled = TRUE
                AND stsd2.kdprofile = 30
            GROUP BY
                cap_stsd.id, cap_stsd.koderekening, cap_stsd.namarekening,
                cap7.id, cap7.koderekening, cap7.namarekening,
                cap6.id, cap6.koderekening, cap6.namarekening,
                cap5.id, cap5.koderekening, cap5.namarekening,
                cap4.id, cap4.koderekening, cap4.namarekening,
                cap3.id, cap3.koderekening, cap3.namarekening,
                cap2.id, cap2.koderekening, cap2.namarekening,
                cap1.id, cap1.koderekening, cap1.namarekening
            ORDER BY
                cap_stsd.koderekening ASC
        "));

        $sts = DB::select(DB::raw("
            SELECT
                sts.nosts,
                sts.totalsetoran,
                sts.tglpenerimaan,
                sts.keterangan
            FROM surattandasetoran_t sts
            WHERE
                sts.statusenabled = TRUE
                AND sts.kdprofile = 30
                AND sts.nosts = '".$request['nosts']."'
            LIMIT 1
        "));

        return view('report.keuangan.cetak-sts-manualv2', compact('data', 'sts'));
    }
    public function laporanBundleHaisBulanan(Request $request)
    {
        $kdProfile = (int) $request['kdprofile'];

        $master = DB::select(DB::raw("
            select * from haisbundle_m WHERE statusenabled = true and kdprofile = 30 AND jenisbundle IN ('TINDAKAN', 'INFEKSIRUMAHSAKIT', 'HAIs') ORDER BY nourut ASC
        "));

        $data = DB::select(DB::raw("
            SELECT
                bd.norec,bd.notransaksi,bd.tglpemeriksaan,bd.petugasfk,
                pg.namalengkap, apd.objectruanganfk,ru.namaruangan, bd.isverifikasi,
                bd.jenisbundle,bd.suhu,bd.diagnosa,bd.tirahbaring,
                pm.id as idpasien, pm.namapasien, pm.tgllahir, bd.pemeriksaan, bd.terapi, bd.keterangan, bd.obatantibiotik
            FROM
                bundlehai_t bd
            INNER JOIN pasiendaftar_t pd ON pd.norec = bd.norec_pd AND pd.statusenabled = TRUE AND pd.kdprofile = 30
            INNER JOIN antrianpasiendiperiksa_t apd ON apd.norec = bd.norec_apd AND apd.statusenabled = TRUE AND apd.kdprofile = 30
            INNER JOIN pasien_m pm ON pm.id = pd.nocmfk
            LEFT JOIN kelompokpasien_m kp ON kp.id = pd.objectkelompokpasienlastfk
            LEFT JOIN ruangan_m ru ON ru.id = apd.objectruanganfk
            LEFT JOIN departemen_m dp ON dp.id = ru.objectdepartemenfk
            LEFT JOIN pegawai_m pg ON pg.id = bd.petugasfk
            WHERE
                bd.statusenabled = true
                AND bd.kdprofile = 30
                AND bd.tglpemeriksaan BETWEEN DATE_TRUNC('MONTH', timestamp '".$request['tglcetak']."') AND '".$request['tglcetak']." 23:59'
                AND ru.id = ".$request['objectruanganfk']."
            ORDER BY
                bd.tglpemeriksaan DESC
        
        "));
    
        $detail = DB::select(DB::raw("

            SELECT
                bdt.*
            FROM
                bundlehai_t bd
            INNER JOIN bundlehaidetail_t bdt ON bdt.bundlehaifk = bd.norec AND bdt.statusenabled = TRUE AND bdt.kdprofile = 30
            WHERE
                bd.statusenabled = true
                AND bd.kdprofile = 30
                AND to_char(bd.tglpemeriksaan, 'YYYY-MM-DD') BETWEEN to_char(MAKE_DATE(EXTRACT(YEAR FROM DATE '".$request['tglcetak']."')::int - 1, 4, 1), 'YYYY-MM-DD') AND '".$request['tglcetak']."'
        "));
    
        $masterTindakan = array();
        $masterInfeksi = array();
        $masterHAIs = array();
    
        foreach($master as $ma){
            if($ma->jenisbundle == 'TINDAKAN'){
                array_push($masterTindakan, $ma);
            }
            if($ma->jenisbundle == 'INFEKSIRUMAHSAKIT'){
                array_push($masterInfeksi, $ma);
            }
            if($ma->jenisbundle == 'HAIs'){
                array_push($masterHAIs, $ma);
            }
        }
    
        foreach($data as $dat){

            $dat->tindakan = array();
            $dat->infeksi = array();
            $dat->hais = array();

            foreach($master as $ma){
                
                foreach($detail as $dtl){

                    if($dtl->bundlehaifk == $dat->norec){

                        if($dtl->bundlefk == $ma->id && $ma->jenisbundle == 'TINDAKAN'){
                            array_push($dat->tindakan, $ma);
                        }
                        if($dtl->bundlefk == $ma->id && $ma->jenisbundle == 'INFEKSIRUMAHSAKIT'){
                            array_push($dat->infeksi, $ma);
                        }
                        if($dtl->bundlefk == $ma->id && $ma->jenisbundle == 'HAIs'){
                            array_push($dat->hais, $ma);
                        }
                    }
                }
            }
        }

        $ruangan = DB::select(DB::raw("
            SELECT * FROM ruangan_m WHERE statusenabled = true AND id = ".$request['objectruanganfk']."
        "));

        return view('report.hais.laporan-hais-bulanan', [
            'data' => $data,
            'masterTindakan' => $masterTindakan,
            'masterInfeksi' => $masterInfeksi,
            'masterHAIs' => $masterHAIs,
            'ruangan' => $ruangan,
            'tanggalcetak' => $request['tglcetak']
        ]);
    }

    public function getCetakSPPSPJ(Request $request)
    {
        $setting = \DB::table('settinganggaran_t as st')
            ->join('pegawai_m as pg','pg.id','=','st.objectkepalabludfk')
            ->join('pegawai_m as bend', 'bend.id', '=', 'st.objectbendpengeluaran')
            ->join('tahapanggaran_m as ta','ta.id','=','st.objecttahapaktivfk')
            ->select('st.*','pg.namalengkap', 'pg.nip as nipkuasa', 'ta.tahap', 'ta.id as idtahap', 'pg.id as idpegawai', 'bend.namalengkap as namabendahara', 'bend.nip as nipbendahara')
            ->where('st.kdprofile', 30)
            ->where('st.statusenabled', true)
            ->orderBy('st.tahunanggaran')
            ->get();

        $data = DB::select(DB::raw("

            SELECT
                sppspm.norec AS norecsppspm,
                sppspm.nomorspp,
                sppspm.nomorspm,
                sppspm.tanggal AS tglsppspm,
                sr.norec AS norecspj,
                sr.norealisasi AS nospj,
                sr.tglrealisasi AS tglspj,
                sr.totalbelanja AS totalspj,
                subsub.kode AS kodesubsub,
                subsub.keterangan AS keterangansubsub,
                sub.kode AS kodesub,
                sub.keterangan AS keterangansub,
                ma.kodemataanggaran,
                ma.namamataanggaran,
                pptk.namalengkap,
                pptk.nip as nippptk
            FROM sppspmspj_t sppspm
            JOIN strukrealisasi_t sr ON sr.norec = sppspm.objectspjfk AND sr.statusenabled = TRUE
            JOIN realisasidetail_t rd ON rd.strukrealisasifk = sr.norec AND rd.statusenabled = TRUE
            JOIN keteranganbelanja_t kb ON kb.norec = rd.keteranganbelanjafk AND kb.statusenabled = TRUE
            JOIN transaksianggaran2024_t ta ON ta.norec = kb.objecttransaksifk AND ta.statusenabled = TRUE
            JOIN pegawai_m pptk ON pptk.id = ta.objectpptkfk AND pptk.statusenabled = TRUE
            JOIN kegiatananggaran2024_m subsub ON subsub.id = sr.objectkegiatanfk AND subsub.statusenabled = TRUE
            JOIN kegiatananggaran2024_m sub ON sub.id = subsub.headfk AND sub.statusenabled = TRUE
            JOIN mataanggaran_m ma ON ma.id = sr.objectmataanggaranfk AND ma.statusenabled = TRUE
            WHERE
                sppspm.statusenabled = TRUE 
                AND ta.tahun = '".$setting[0]->tahunanggaran."'
                AND sr.norec = '".$request['norecspj']."'
            GROUP BY
                sppspm.norec,
                sr.norec,
                subsub.id,
                sub.id,
                ma.id,
                pptk.id
            ORDER BY
                sppspm.tanggal DESC;
        "));

        $anggaran = DB::select(DB::raw("

            SELECT
                SUM(kb.subtotal) AS totalanggaran
            FROM keteranganbelanja_t kb
            JOIN transaksianggaran2024_t ta ON ta.norec = kb.objecttransaksifk AND ta.statusenabled = TRUE
            JOIN kegiatananggaran2024_m ka ON ka.id = ta.objectkegiatanfk AND ka.statusenabled = TRUE
            JOIN mataanggaran_m ma ON ma.id = kb.objectmataanggaranfk AND ma.statusenabled = TRUE
            WHERE
                kb.statusenabled = TRUE 
                AND ta.tahun = '".$setting[0]->tahunanggaran."'
                AND ta.objecttahapfk = ".$setting[0]->objecttahapaktivfk."
                AND kb.objectasalprodukfk = 18
        
        "));

        $terbilang = isset($anggaran) ? $this->terbilang($anggaran[0]->totalanggaran) : '';
        $terbilangSPJ = isset($data) ? $this->terbilang($data[0]->totalspj) : '';

        return view('report.keuangan.cetak-sppspj', [
            'data' => $data,
            'setting' => $setting,
            'tglindo' => isset($data) ? $this->tanggal_indonesia($data[0]->tglspj) : '',
            'tgldasarpengeluaran' => isset($setting) ? $this->tanggal_indonesia($setting[0]->tanggaldasarpengeluaran) : null,
            'anggaran' => $anggaran,
            'terbilang' => $terbilang,
            'terbilangSPJ' => $terbilangSPJ
        ]);
    }

    public function getCetakSPMSPJ(Request $request)
    {
        $setting = \DB::table('settinganggaran_t as st')
            ->join('pegawai_m as pg','pg.id','=','st.objectkepalabludfk')
            ->join('pegawai_m as bend', 'bend.id', '=', 'st.objectbendpengeluaran')
            ->join('tahapanggaran_m as ta','ta.id','=','st.objecttahapaktivfk')
            ->select('st.*','pg.namalengkap', 'pg.nip as nipkuasa', 'ta.tahap', 'ta.id as idtahap', 'pg.id as idpegawai', 'bend.namalengkap as namabendahara', 'bend.nip as nipbendahara')
            ->where('st.kdprofile', 30)
            ->where('st.statusenabled', true)
            ->orderBy('st.tahunanggaran')
            ->get();

        $data = DB::select(DB::raw("

            SELECT
                sppspm.norec AS norecsppspm,
                sppspm.nomorspp,
                sppspm.nomorspm,
                sppspm.tanggal AS tglsppspm,
                sr.norec AS norecspj,
                sr.norealisasi AS nospj,
                sr.tglrealisasi AS tglspj,
                sr.totalbelanja AS totalspj,
                subsub.kode AS kodesubsub,
                subsub.keterangan AS keterangansubsub,
                sub.kode AS kodesub,
                sub.keterangan AS keterangansub,
                ma.kodemataanggaran,
                ma.namamataanggaran,
                pptk.namalengkap,
                pptk.nip as nippptk,
                rk.namarekanan,
                rk.bankrekeningnomor as norekrekenan,
                rk.bankrekeningatasnama as namarekrekanan,
                rk.bankrekeningnama,
                rk.npwp as npwprekanan
            FROM sppspmspj_t sppspm
            JOIN strukrealisasi_t sr ON sr.norec = sppspm.objectspjfk AND sr.statusenabled = TRUE
            JOIN realisasidetail_t rd ON rd.strukrealisasifk = sr.norec AND rd.statusenabled = TRUE
            JOIN keteranganbelanja_t kb ON kb.norec = rd.keteranganbelanjafk AND kb.statusenabled = TRUE
            JOIN transaksianggaran2024_t ta ON ta.norec = kb.objecttransaksifk AND ta.statusenabled = TRUE
            JOIN pegawai_m pptk ON pptk.id = ta.objectpptkfk AND pptk.statusenabled = TRUE
            JOIN kegiatananggaran2024_m subsub ON subsub.id = sr.objectkegiatanfk AND subsub.statusenabled = TRUE
            JOIN kegiatananggaran2024_m sub ON sub.id = subsub.headfk AND sub.statusenabled = TRUE
            JOIN mataanggaran_m ma ON ma.id = sr.objectmataanggaranfk AND ma.statusenabled = TRUE
            LEFT JOIN rekanan_m rk ON rk.id = sr.rekananfk AND rk.statusenabled = TRUE
            WHERE
                sppspm.statusenabled = TRUE 
                AND ta.tahun = '".$setting[0]->tahunanggaran."'
                AND sr.norec = '".$request['norecspj']."'
            GROUP BY
                sppspm.norec,
                sr.norec,
                subsub.id,
                sub.id,
                ma.id,
                pptk.id,
                rk.id
            ORDER BY
                sppspm.tanggal DESC;
        "));

        $anggaran = DB::select(DB::raw("

            SELECT
                SUM(kb.subtotal) AS totalanggaran
            FROM keteranganbelanja_t kb
            JOIN transaksianggaran2024_t ta ON ta.norec = kb.objecttransaksifk AND ta.statusenabled = TRUE
            JOIN kegiatananggaran2024_m ka ON ka.id = ta.objectkegiatanfk AND ka.statusenabled = TRUE
            JOIN mataanggaran_m ma ON ma.id = kb.objectmataanggaranfk AND ma.statusenabled = TRUE
            WHERE
                kb.statusenabled = TRUE 
                AND ta.tahun = '".$setting[0]->tahunanggaran."'
                AND ta.objecttahapfk = ".$setting[0]->objecttahapaktivfk."
                AND kb.objectasalprodukfk = 18
        
        "));

        $pajak = DB::select(DB::raw("

            SELECT
                pp.objectbkufk,
                pp.nopajak nopajakpp,
                pp.uraianpajak,
                sr.norealisasi,
                string_agg ( DISTINCT rd.uraian, ',' ) uraian,
                sr.tglverif tglrealisasi,
                jp.reportspm,
                CASE WHEN pp.pph IS NOT NULL THEN pp.pph ELSE pp.ppn END AS jumlah,
                CASE WHEN pp.idbillpph IS NOT NULL THEN pp.idbillpph ELSE pp.idbillppn END AS idbill 
            FROM strukrealisasi_t sr
            INNER JOIN realisasidetail_t rd ON rd.strukrealisasifk = sr.norec AND rd.statusenabled = TRUE AND rd.kdprofile = 30
            JOIN pemungutanpajak_t pp ON pp.objectspjfk = sr.norec AND pp.statusenabled = TRUE AND pp.kdprofile = 30
            LEFT JOIN jenispajak_m jp ON jp.ID = pp.objectjenispphfk AND jp.statusenabled = TRUE AND jp.kdprofile = 30
            WHERE
                sr.statusenabled = TRUE
                AND sr.norec = '".$request['norecspj']."'
                AND sr.kdprofile = 30
            GROUP BY
                pp.norec,
                jp.reportspm,
                sr.norealisasi,
                sr.tglverif,
                pp.pph

        "));

        $terbilang = isset($anggaran) ? $this->terbilang($anggaran[0]->totalanggaran) : '';
        $terbilangSPJ = isset($data) ? $this->terbilang($data[0]->totalspj) : '';

        return view('report.keuangan.cetak-spmspj', [
            'data' => $data,
            'setting' => $setting,
            'tglindo' => isset($data) ? $this->tanggal_indonesia($data[0]->tglspj) : '',
            'tglsppspmindo' => isset($data) ? $this->tanggal_indonesia($data[0]->tglsppspm) : '',
            'tgldasarpengeluaran' => isset($setting) ? $this->tanggal_indonesia($setting[0]->tanggaldasarpengeluaran) : null,
            'anggaran' => $anggaran,
            'terbilang' => $terbilang,
            'terbilangSPJ' => $terbilangSPJ,
            'pajak' => $pajak,
        ]);
    }

