    public function CetakCuti(Request $request)
    {
        $res['profile'] = Profile::where('id',$request['kdprofile'])->first();
        // dd($res);

        // $uuid = 'b0923bc0-b574-11f0-8ae4-8f177a5c';
        $data =\DB::table('planningpegawaistatus_t as pps')
            ->leftJoin('pegawai_m as pg','pg.id','=','pps.objectpegawaifk')
            ->leftJoin('sdm_jeniscuti_m as jc','jc.id','=','pps.objectstatuspegawaiplanfk')
            ->leftJoin('jabatan_m as jb','jb.id','=','pg.objectjabatanstrukturalfk')
            ->leftJoin('unitkerja_m as ukp','ukp.id','=','pg.objectunitkerjafk')
            ->select( 'pps.norec','pps.noplanning','pps.tglpengajuan','pps.objectpegawaifk','pps.objectstatuspegawaiplanfk',
                'pps.deskripsistatuspegawaiplan as desk','pps.keterangan','pg.namalengkap','pg.nip','jc.name as statuspermohonan',
                'jb.namajabatan','ukp.unitkerja','pps.approvalstatus','pps.totalcuti')
            ->where('pps.kdprofile', $request['kdprofile'])
            ->where('pps.statusenabled',true)
            ->whereNull('pps.totalcuti')
            ->where('pps.noplanning', $request['noplanning'])
            ->orderBy('pps.tglpengajuan');

        $data = $data->get();
        $data2 =[];

        foreach ($data as $item){
            $norec= $item->norec;
            $details = DB::select(DB::raw("select *,to_char(tgl, 'Day') as day from listtanggalcuti_t where objectplanningpegawaistatusfk='$norec' and to_char(tgl, 'Day') <> 'Sunday   '"));
            $tglVerif = [];
            foreach ($details as $itmde){
                if( $itmde-> approvalstatus == 1 && $itmde->day != "Sunday   "){
                    $tglVerif [] = array(
                        'norec' => $itmde->norec,
                        'tgl' => $itmde->tgl,
                        'day' => $itmde->day,
                        'approvalstatus' => $itmde->approvalstatus,
                        'objectplanningpegawaistatusfk' => $itmde->objectplanningpegawaistatusfk
                    );
                }

            }

            $data2 [] =  array(
                'norec' => $item->norec,
                'noplanning' => $item->noplanning,
                'tglpengajuan' => $item->tglpengajuan,
                'objectpegawaifk' => $item->objectpegawaifk,
                'objectstatuspegawaiplanfk' => $item->objectstatuspegawaiplanfk,
                'desk' => $item->desk,
                'keterangan' => $item->keterangan,
                'namalengkap' => $item->namalengkap,
                'nip' => $item->nip,
                'statuspermohonan' => $item->statuspermohonan,
                'namajabatan' => $item->namajabatan,
                'unitkerja' => $item->unitkerja,
                'approvalstatus' => $item->approvalstatus,
                'totalcuti' => $item->totalcuti,
                'listtanggal' => $details,
                'listtanggalapprove' => $tglVerif,

            );
        }
        $firstData = $data2[0];
        $dates = collect($firstData['listtanggal'])->pluck('tgl')->sort()->values();

        $startDate = \Carbon\Carbon::parse($dates->first())->format('Y-m-d');
        $endDate   = \Carbon\Carbon::parse($dates->last())->format('Y-m-d');
        $tanggal_pengajuan = \Carbon\Carbon::parse($firstData['tglpengajuan'])->format('Y-m-d');

        $totalDays = $dates->count();

        $qrcode = base64_encode(QrCode::format('svg')->size(60)->generate($firstData['norec']));

        $pdf = PDF::loadView(
            'report.sdm.cetak-cuti',
            array(
                'res' => $res,
                'qrcode'=> $qrcode,
                'data' => $data2,
                'firstData'  => $firstData, 
                'noplanning' => $request['noplanning'],
                'tanggal_pengajuan' => $tanggal_pengajuan,
                'startDate' => $startDate,
                'endDate' => $endDate,
                'totalDays' => $totalDays,
            )
        )->setPaper('A4', 'portrait');

        return $pdf->stream();
    }


    public function cetakIdentitasPasien(Request $request)
    {
        $nocm = $request->get('nocm');
        $kdProfile = (int)$request->get('kdprofile');

        $profile = collect(DB::select("
            select * from profile_m where statusenabled=true limit 1
        "))->first();

        $data = collect(DB::select("
            SELECT 
                pm.id,
                pm.nocm,
                pm.namapasien,
                pm.tempatlahir,
                pm.tgllahir,
                COALESCE(sp.statusperkawinan, '-') AS statusperkawinan,
                COALESCE(ag.agama, '-') AS agama,
                COALESCE(pk.pekerjaan, '-') AS pekerjaan,
                alm.alamatlengkap,
                alm.namadesakelurahan,
                alm.kecamatan,
                alm.kotakabupaten,
                prop.namapropinsi,
                alm.kodepos,
                pm.alamatktr,
                COALESCE(pm.notelepon, '-') AS notelepon,
                COALESCE(pm.noidentitas, '-') AS noidentitas,
                COALESCE(gd.golongandarah, '-') AS golongandarah,
                COALESCE(pen.pendidikan, '-') AS pendidikan,
                COALESCE(pm.noasuransilain, '-') AS noasuransilain,
                COALESCE(pm.nobpjs, '-') AS nobpjs,
                jk.jeniskelamin,
                pm.penanggungjawab,
                pm.hubungankeluargapj,
                pm.pekerjaanpenangggungjawab,
                pm.ktppenanggungjawab,
                pm.alamatrmh,
                kp.kelompokpasien AS carabayar,
                pm.foto
            FROM pasien_m AS pm
            LEFT JOIN statusperkawinan_m AS sp ON sp.id = pm.objectstatusperkawinanfk
            LEFT JOIN agama_m AS ag ON ag.id = pm.objectagamafk
            LEFT JOIN pekerjaan_m AS pk ON pk.id = pm.objectpekerjaanfk
            LEFT JOIN pendidikan_m AS pen ON pen.id = pm.objectpendidikanfk
            LEFT JOIN alamat_m AS alm ON alm.nocmfk = pm.id
            LEFT JOIN propinsi_m AS prop ON prop.id = alm.objectpropinsifk
            LEFT JOIN golongandarah_m AS gd ON gd.id = pm.objectgolongandarahfk
            LEFT JOIN jeniskelamin_m AS jk ON jk.id = pm.objectjeniskelaminfk
            LEFT JOIN (
                SELECT DISTINCT ON (nocmfk) nocmfk, objectkelompokpasienlastfk 
                FROM pasiendaftar_t 
                WHERE statusenabled = true 
                ORDER BY nocmfk, tglregistrasi DESC
            ) pd ON pd.nocmfk = pm.id
            LEFT JOIN kelompokpasien_m AS kp ON kp.id = pd.objectkelompokpasienlastfk
            WHERE pm.nocm = :nocm
            LIMIT 1
        ", ['nocm' => $nocm]))->first();

        if (empty($data)) {
            return "Pasien dengan No. RM $nocm tidak ditemukan.";
        }

        $ageStr = '-';
        if ($data && $data->tgllahir) {
            $birthDate = new \DateTime($data->tgllahir);
            $today = new \DateTime();
            $diff = $today->diff($birthDate);
            $ageStr = $diff->y . ' thn ' . $diff->m . ' bln ' . $diff->d . ' hari';
        }

        $fotoData = null;
        if ($data && isset($data->foto) && $data->foto !== null) {
            $rawFoto = $data->foto;

            // Handle PostgreSQL bytea stream resource
            if (is_resource($rawFoto)) {
                $rawFoto = stream_get_contents($rawFoto);
            }

            if (is_string($rawFoto) && strlen($rawFoto) > 0) {
                // Case 1: Already a full data URI (e.g. "data:image/jpeg;base64,/9j/...")
                if (substr($rawFoto, 0, 5) === 'data:') {
                    $fotoData = $rawFoto;
                }
                // Case 2: Already a base64 string (e.g. "/9j/4AAQSkZJRgAB...")
                // Base64 chars: A-Z a-z 0-9 + / =
                // JPEG base64 always starts with /9j/
                else if (preg_match('/^[A-Za-z0-9+\/]+=*$/', trim($rawFoto)) && base64_decode($rawFoto, true) !== false) {
                    $fotoData = 'data:image/jpeg;base64,' . trim($rawFoto);
                }
                // Case 3: PostgreSQL hex format \x...
                else if (substr($rawFoto, 0, 2) === '\\x') {
                    $fotoData = 'data:image/jpeg;base64,' . base64_encode(pack('H*', substr($rawFoto, 2)));
                }
                // Case 4: Pure hex string (only 0-9 a-f)
                else if (preg_match('/^[0-9a-fA-F]+$/', $rawFoto)) {
                    $fotoData = 'data:image/jpeg;base64,' . base64_encode(pack('H*', $rawFoto));
                }
                // Case 5: Raw binary data
                else {
                    $fotoData = 'data:image/jpeg;base64,' . base64_encode($rawFoto);
                }
            }
        }

        // Temporarily bypass GD warning for interlaced PNGs
        set_error_handler(function($errno, $errstr, $errfile, $errline) {
            if (strpos($errstr, 'imagecreatefrompng') !== false || strpos($errstr, 'libpng') !== false) {
                return true; // Silence warning, do not let Laravel throw an exception
            }
            return false; // Fall back to default error handler
        });

        try {
            $pdf = PDF::loadView('report.pendaftaran.cetak-identitas-pasien', array(
                'data' => $data,
                'profile' => $profile,
                'ageStr' => $ageStr,
                'fotoData' => $fotoData
            ));

            $response = $pdf->stream();
        } finally {
            restore_error_handler();
        }

        return $response;
    }

    public function CetakMPP(Request $request)
    {
        $noemr = $request['noemr'];
        $kdProfile = (int) $request['kdprofile'];
        $emrfk = $request['emrfk'];
        $main = \DB::select(DB::raw("SELECT id, type from emrd_t where emrfk = $emrfk and statusenabled = true and kdprofile = $kdProfile order by id
        "));
        $data = \DB::select(DB::raw("SELECT ed.id,epd.value, ed.type
                FROM emrpasien_t ep
                        INNER JOIN emrpasiend_t epd ON ep.noemr = epd.emrpasienfk
                        INNER JOIN emrd_t ed ON ed.ID = epd.emrdfk 
                        INNER JOIN pegawai_m pg on pg.id = epd.pegawaifk
                    WHERE ep.kdprofile = $kdProfile AND ep.statusenabled = TRUE 
                        AND ep.noemr ILIKE '$noemr' 
                        AND ed.statusenabled = TRUE 
                        AND ep.emrfk = $emrfk 
                        AND ed.emrfk = $emrfk
                ORDER BY ed.ID ASC"));
        $detail = [];
        $id=0;
        $value="";
        foreach ($main as $m) {
        $id=0;
        $value="";
            foreach ($data as $d) {
                if ($m->id == $d->id) {
                    $id = $m->id;
                    if ($d->type == 'datetime') {
                        $value=$this->tanggal_indonesia(date('Y-m-d',strtotime($d->value)));
                    }else{
                        $value =$d->value;
                    }
                    break;
                }else {
                    $id = $m->id;
                    $value = "";
                }
                
            }

            $detail[]= array(
                "id"=> $id,
                "value"=>$value,
                "type"=> $m->type
            );
        }

        $pasien = \DB::table('emrpasien_t as ep')
            ->select('ps.namapasien','ep.nocm','jk.jeniskelamin','ps.tgllahir','ep.namaruangan','ep.noregistrasifk')
            ->join('pasien_m as ps','ps.nocm','=','ep.nocm')
            ->leftJoin('jeniskelamin_m as jk','jk.id','=','ps.objectjeniskelaminfk')
            ->where('ep.noemr', $noemr)
            ->where('ep.kdprofile', $kdProfile)
            ->first();

        $profile = \DB::table('profile_m')->where('id', $kdProfile)->first();

        $pageWidth = 950;
        return view('report.EMR.formulir-mpp', compact('detail','pageWidth','pasien','profile'));
    }

     public function cetakPengkajianGeriatriKomprehensif(Request $request)
    {
        $norec = $request['emr'];
        $kdProfile = (int) $request['kdprofile'];
        if ($kdProfile <= 0) {
            $kdProfile = 30;
        }
        $emrfk = isset($request['emrfk']) ? (int)$request['emrfk'] : 3000921;
        // Support dua mode: emr = norec UUID, atau noemr = noemr string (MR.../...)
        $noemrParam = isset($request['noemr']) ? trim($request['noemr']) : '';
        $norecParam  = isset($request['emr'])  ? trim($request['emr'])  : '';

        // Tentukan kondisi WHERE berdasarkan parameter yang tersedia
        if (!empty($noemrParam) && $noemrParam !== '-') {
            $whereEmr = "ep.noemr = '$noemrParam'";
        } else {
            $whereEmr = "ep.norec = '$norecParam'";
        }

        $data = DB::select(DB::raw("
        SELECT
            split_part(epd.value, '~', 2) as split,
            epd.emrdfk,
            ep.noemr,
            ed.TYPE,
            pa.namapasien,
            pa.namaibu,
            pa.namaayah,
            pa.tgllahir,
            pa.nohp,
            pa.nocm,
            ep.jeniskelamin,
            ep.umur,
            al.alamatlengkap,
            ep.noregistrasifk as noregistrasi ,
            epd.value,ep.namaruangan,pg.namalengkap as namadokter
        FROM
            emrpasien_t AS ep
            INNER JOIN emrpasiend_t AS epd ON ep.noemr = epd.emrpasienfk
            INNER JOIN emrd_t AS ed ON epd.emrdfk = ed.ID
            INNER JOIN antrianpasiendiperiksa_t AS pd ON pd.norec = ep.norec_apd
            left JOIN pegawai_m AS pg ON pg.id = pd.objectpegawaifk
            left JOIN pasien_m as pa on ep.nocm =  pa.nocm
            left JOIN alamat_m as al on pa.id = al.nocmfk
        WHERE
            $whereEmr
            AND ep.kdprofile = '$kdProfile' 
            AND epd.statusenabled = TRUE 
            and epd.emrfk = $emrfk
        ORDER BY
            ed.nourut
            "
        ));
        foreach ($data as $z){
            if ($z->type=="datetime"){
                $z->value=date('Y-m-d H:i:s',strtotime($z->value));
            }
        }
        $res['profile'] = Profile::where('id', $kdProfile)->first();
        if (!$res['profile']) {
            $res['profile'] = Profile::where('id', 30)->first();
        }
        if (!$res['profile']) {
            $res['profile'] = new \stdClass();
            $res['profile']->baris1 = 'RS JIWA GRHASIA';
            $res['profile']->baris2 = 'Daerah Istimewa Yogyakarta';
            $res['profile']->namalengkap = 'RS JIWA GRHASIA';
            $res['profile']->fixedphone = '-';
            $res['profile']->website = '-';
            $res['profile']->alamatemail = '-';
        }
        $res['d'] = $data;
        $item =[];   
        $item2= [];      
        foreach( $res['d'] as $items){
            if($items->type  ==  "textbox" ||$items->type  ==  "textarea" ||$items->type  ==  "textarea2" ||$items->type  ==  "textarea3" || $items->type == "radio" || $items->type == "numeric" ){
                $item[$items->emrdfk] =  $items->value;
            }
            if($items->type  ==  "datetime"){
                $item[$items->emrdfk] = $this->tanggal_indonesia(date('Y-m-d',strtotime( $items->value))) ;
            }
            if($items->type  ==  "time"){
                $item[$items->emrdfk] = date('H:i',strtotime( $items->value));
            }
            if($items->type  ==  "date"){
                $item[$items->emrdfk] = date('Y-m-d',strtotime( $items->value));
            }
            if($items->type  ==  "checkboxtextbox"){
                $item[$items->emrdfk] =  $items->value;
                $item2[$items->emrdfk] =  true;
            }
            if($items->type == "checkbox" || $items->type == "checkbox2" || $items->type == "checkbox12" || $items->type == "mna") {
                $chekedd = false;
                if ($items->value == '1' || $items->value == 'true' || $items->value == 't') {
                    $chekedd = true;
                }
                $item[$items->emrdfk] = $chekedd;
            }
            if($items->type == "combobox") {
                $arr = explode('~',$items->value );
                $item[$items->emrdfk] = isset($arr[1]) ? $arr[1] : $items->value;
            }
        }
        $pageWidth = 950;
        $pdf = PDF::loadView(
            'report.EMR.pengkajian-geriatri-komprehensif',
            array(
                'res' => $res,
                'pageWidth' => $pageWidth,
                'data' => $data,
                'item'=> $item
            )
        );
        return $pdf->stream();
    }

    public function cetakEmrPublik(Request $request)
    {
        if ($request->has('token')) {
            $token = $request->input('token');
            $parts = explode('.', $token);
            if (count($parts) === 2) {
                $payload = $parts[0];
                $signature = $parts[1];
                $secretKey = env('APP_KEY', 'some-random-fallback-key-123!');
                $expectedSignature = hash_hmac('sha256', $payload, $secretKey);
                
                if (hash_equals($expectedSignature, $signature)) {
                    $decoded = base64_decode($payload);
                    $dataParts = explode('|', $decoded);
                    if (count($dataParts) === 5) {
                        $emrNorec = $dataParts[0];
                        $emrfk = (int)$dataParts[1];
                        $blade = $dataParts[2];
                        $expires = (int)$dataParts[3];
                        $kdProfile = (int)$dataParts[4];
                        
                        if (time() > $expires) {
                            return response('<html><head><title>Link Kedaluwarsa</title></head><body style="font-family:sans-serif; text-align:center; padding:50px;"><h1 style="color:#e74c3c;">Link Telah Kedaluwarsa</h1><p>Maaf, link akses dokumen edukasi ini sudah tidak berlaku lagi (melebihi batas waktu 7 hari).</p></body></html>', 403);
                        }
                        
                        $request->merge([
                            'emr' => $emrNorec,
                            'emrfk' => $emrfk,
                            'blade' => $blade,
                            'kdprofile' => $kdProfile
                        ]);

                        // Dapatkan pegawaittd secara otomatis berdasarkan pembuat EMR
                        $emrInfo = \DB::table('emrpasien_t')
                            ->where('norec', $emrNorec)
                            ->where('kdprofile', $kdProfile)
                            ->first();
                        if ($emrInfo && !empty($emrInfo->pegawaifk)) {
                            $request->merge(['pegawaittd' => $emrInfo->pegawaifk]);
                        }

                        // Blade generik (fred-diabetes-dom, fred-hipertensi-dom, dll) tetap pakai CetakSuratMan.
                        $dedicatedBlades = [
                            'rujukan-edukasi-psikiatri'                                      => 'cetakRujukanEdukasiPsikiatri',
                            'rujukan-edukasi-pasien-dengan-komorbid-epilepsi'                 => 'cetakRujukanEdukasiPasienGangguanJiwaDenganKomorbidEpilepsi',
                            'rujukan-edukasi-pasien-dengan-komorbid-sindrome-geriatri-low-intake' => 'cetakRujukanEdukasiPasienGangguanJiwaDenganKomorbidSindromeGeriatriLowIntake',
                            'rujukan-edukasi-pasien-dengan-komorbid-tuberculosis'             => 'cetakRujukanEdukasiPasienGangguanJiwaDenganKomorbidTuberculosis',
                            'rujukan-edukasi-pasien'                                          => 'cetakRujukanEdukasiPasien',
                        ];

                        if (isset($dedicatedBlades[$blade])) {
                            // Ambil norec_apd dan data pasien dari DB agar dedicated endpoint punya semua param
                            $emrExtra = \DB::table('emrpasien_t as ep')
                                ->select('ep.umur', 'ep.jeniskelamin', 'ep.noregistrasifk',
                                         'apd.norec as norec_apd', 'pd.noregistrasi')
                                ->join('antrianpasiendiperiksa_t as apd', 'apd.norec', '=', 'ep.norec_apd')
                                ->join('pasiendaftar_t as pd', 'pd.norec', '=', 'apd.noregistrasifk')
                                ->where('ep.norec', $emrNorec)
                                ->where('ep.kdprofile', $kdProfile)
                                ->first();

                            if ($emrExtra) {
                                $request->merge([
                                    'norec_apd'   => $emrExtra->norec_apd,
                                    'noregistrasi' => $emrExtra->noregistrasi,
                                    'umur'         => $emrExtra->umur,
                                    'jeniskelamin' => $emrExtra->jeniskelamin,
                                ]);
                            }

                            $method = $dedicatedBlades[$blade];
                            return $this->$method($request);
                        }

                        return $this->CetakSuratMan($request);
                    } else {
                        return response('<h1>Link Tidak Valid (Payload tidak cocok)</h1>', 403);
                    }
                } else {
                    return response('<h1>Link Tidak Valid (Tanda tangan digital tidak cocok)</h1>', 403);
                }
            } else {
                return response('<h1>Link Tidak Valid (Format token salah)</h1>', 403);
            }
        } else {
            return response('<h1>Akses Ditolak</h1><p>Akses memerlukan token valid.</p>', 403);
        }
    }

    public function cetakResumeV3Publik(Request $r)
